window.ATLAS_I18N_LOR={"01IO012":["İkiz Disiplin","Bir dost birime bu tur +3|+0 veya +0|+3 verirsin.","","''Değişimden korkma. Sana kendini sorgulatır, sınırlarını zorlatır. En iyi öğretmenimiz değişimdir.''\n- Karma","Büyü",[],["Ionia"],"YAYGIN"],"01IO015":["Yasuo","Sen bir düşmanı Sersemlettiğinde ya da Geri Gönderdiğinde ona 2 hasar veririm.","5+ birimi Sersemlettiğinde ya da Geri Gönderdiğinde.","''Ölüm de rüzgâr gibi...''","Birim",[],["Ionia"],"Şampiyon"],"01IO020":["Maskelerin Muhafızı","Çağrıldığımda diğer dost birimlere bu tur +1|+0 verirsin.","","''Bugünden itibaren hayatın disipline, idmana, alçakgönüllülüğe ve dengeye adanacak. Bugün Kinkou olacaksın.''","Birim",[],["Ionia"],"YAYGIN"],"01IO045":["Baharın Habercisi","Destekle: Desteklediğim dost birim bu tur Can Çalma alır.","","''Kış hükmünü sürerken duyduk\nKarlı topraktaki ayak seslerini.\nArdından yapraklar, asmalar yeşerdi\nVe orman, yeni mevsim için yeniden giyindi.''\n - Shon-Xan şiiri","Birim",[],["Ionia"],"YAYGIN"],"01IO008":["Yordle Kılıç Ustası","Sen bir birimi Sersemlettiğinde ya da Geri Gönderdiğinde ben +2|+0 kazanırım.","","''Ha, bana 'sevimli' diyorsun demek? 'Pofuduk', öyle mi? Bak bakalım BU 'sevimli' miymiş!''","Birim",["YORDLE"],["Ionia"],"ENDER"],"01IO040":["Kinkou Yaşamkılıcı","","","''Burada bir zamanlar okullarımız, evlerimiz, tapınaklarımız vardı. Şimdi bu gölgelerle dolu harabeler arasında sürünüyoruz. Zed'in tarikatı bu kutsal yeri lekeledi. Eminim pişman olacaklar.''","Birim",[],["Ionia"],"YAYGIN"],"01IO041":["Karma","Tur Sonu: Elinde bölgelerine ait rasgele bir büyü oluşur.","Aydınlandığında.","''Tefekkürle zihnimizi odaklayarak her engeli aşacak bir yol bulabiliriz.''","Birim",[],["Ionia"],"Şampiyon"],"01IO011":["Geri Gönder","Bir dost birimi Geri Gönderirsin.","","Akıllı savaşçı, dirayetli olduğu kadar kendine hâkimdir de. Başarıyla geri çekilmek, yaşayıp tekrar savaşabilmek demektir.","Büyü",[],["Ionia"],"YAYGIN"],"01IO009":["Zed","Saldır: Benim niteliklerime sahip, saldıran bir Canlı Gölge çağırırsın.","Kendimin veya dost Canlı Gölge kartlarının rakibin Nexus'una iki kez vurduğunu gördüğümde.","''Denge aptalların efendisidir. Gölgeler bana gerçek gücün ne olduğunu gösterdi.''","Birim",[],["Ionia"],"Şampiyon"],"01IO014":["Yeşilkırlı İhtiyar","Çağrıldığımda elindeki dost birimlere +1|+1 kazandırırsın.","","Ionia'nın bilgeliği yazılı olarak özetlenmiş olsa da kadim yazmalara can veren şey Ionia'nın büyük saygı gören ihtiyarlarının anlattığı hikâyelerde ve öğretilerindedir.","Birim",[],["Ionia"],"YAYGIN"],"01IO005":["Atik Poro","","","''Bana deli diyeceksiniz ama son hatırladığım... tüylü bir şeylere dokunma hissiydi...?''\n- Navori Eşkıyası","Birim",["PORO"],["Ionia"],"YAYGIN"],"01IO044":["Navori Casusu","Beni oynamak için bir dost birimi Geri Gönderirsin.","","''Hadi, çabuk kaçalım buradan! Adımı boş ver. Yolda açıklayacağım, söz veriyorum...''","Birim",[],["Ionia"],"YAYGIN"],"01IO023":["Murassa Koruyucu","Oyna: Elindeki bir dost birime +3|+3 kazandırırsın.","","''Savaş dönemlerinde, köylüler Güz Vadisi'nin kadim koruyucusunu bulurdu. Koruyucu gönlünü alabilenlere savaşın gidişatını değiştirecek lütuflarda bulunurdu.''\n- İlk Diyar Menkıbesi","Birim",[],["Ionia"],"ENDER"],"01IO029":["Yeşeren Tohumlar","Elindeki dost birimlere +1|+0 kazandırırsın.","","''Bunlar sadece tohum değil çocuklar. Bunlar toprağın mirası, geleceğimizin bereket dolu olacağının vaadi.''\n- Karma","Büyü",[],["Ionia"],"ENDER"],"01IO003":["Ölüm İşareti","Bir dost birimin Hayali tesirini kaldırıp onu bir düşman birime kazandırırsın.","","''Ben karanlıktaki hançerim.''\n- Zed","Büyü",[],["Ionia"],"ENDER"],"01IO047":["Gölge Yangını","Savaştaki TÜM takipçilere Hayali tesiri kazandırırsın.","","Sihir akışlarının dengesi bozulursa, büyük bir şiddetle ruhlar âleminden fani âleme fışkırırlar. Bunun sonuçları genellikle dudak uçuklatır.","Büyü",[],["Ionia"],"DESTANSI"],"01IO026":["İlham Veren Hoca","Oyna: Elindeki bir dost birime +1|+0 kazandırırsın.","","''Bu vücudu geliştirmek yıllarımı aldı! Günlerimi yorulmak nedir bilmeden kuş gözleyerek, bulutları bir şeylere benzeterek ve şekerli çörek araklayarak geçirdim! Hayatımı bu işe vakfettim!''","Birim",[],["Ionia"],"YAYGIN"],"01IO024":["Şafak ve Alacakaranlık","Bir dost birimin 2 adet birebir ve Hayali kopyasını çağırırsın.","","''Shen iki dünyanın dertleri arasında kalmış bir adam. İkisine de çare olamayacak. Ben kendimi sadece Ionia'ya adadım.''\n- Zed","Büyü",[],["Ionia"],"ENDER"],"01IO028":["Pullu Kapanbağa","Oyna: +3|+0 ya da +0|+3 kazanırım.","","Yeşilkır'ın en yaşlı sakinlerinden biri. Çevre koşullarına sürekli uyum sağlayarak zamana kafa tutmayı başarmış.","Birim",["SÜRÜNGEN"],["Ionia"],"YAYGIN"],"01IO057":["Gölge İnfazcı","Çağrıldığımda 1 kart çekersin.","","Zarafetle süzülür\nSessiz adımlarla karanlıkta\nBıraktığı tek iz pençeleri.","Birim",[],["Ionia"],"YAYGIN"],"01IO032":["Shen","Destekle: Desteklediğim dost birim bu tur Bariyer alır.","Dost birimlerin 5 kez Bariyer kazandığını gördüğümde.","''Ruhlar âlemi ve fani âlem, birbirini sıkıca tutan iki el gibi iç içedir...'' ","Birim",[],["Ionia"],"Şampiyon"],"01IO013":["Gölge Canavar","","","''Güç için neleri feda ederdin? Dönüşüm, içtiğin bir antla başlar ve verebileceğin her şeyi elinden aldıktan sonra biter.''\n- Zed","Birim",[],["Ionia"],"YAYGIN"],"01IO018":["Fırla","Bir dost birime bu tur +1|+0 ve İlk Saldırı verirsin.","","Savaş da bir yarıştır, iki kişi ilk kim kimin canını alacak diye yarışır.","Büyü",[],["Ionia"],"YAYGIN"],"01IO056":["Rüzgâr Avcısı, Yone","Oyna: 2 düşmanı Sersemletirsin.","","''Küçüklüğümde kardeşime 'Rüzgâr kaçar mı, kovalar mı?' diye sordum. Şimdi o adaletten kaçıyor, ben de onu kovalıyorum.''","Birim",[],["Ionia"],"ENDER"],"01IO016":["Meltem Bilgesi","Oyna: Elindeki Meltem Bilgesi olmayan bir kartın birebir kopyasını oluşturursun.","","'Savaşçı kaybettiklerine ağlarken ihtiyar onu teselli etmiş: 'Gök bilgesini bul. Bu dünyadan yitmiş ama hatıralarda hâlâ yaşayan şeyleri sadece o geri getirebilir.''\n- İlk Diyar Menkıbesi","Birim",["KUŞ"],["Ionia"],"ENDER"],"01IO036":["Yeşilkır Gözcüleri","Vuruş: Elindeki en pahalı birimin bedeli 1 azalır.","","''Devriyeler, bize doğru bir... hayır... İKİ tane, kürklü, devasa yaratık yaklaşıyor! Destek isti... Haa. Bir dakika. Dürbünü yine ters tutmuşum.''","Birim",["YORDLE"],["Ionia"],"YAYGIN"],"01IO033":["Minah Tezayak","Oyna: 3 düşmanı Geri Gönderirsin.","","''Biz çayırda koştururken önümüze aniden bir ÇOCUK atladı! BAM BAM BAM bir koydu! Nefesimiz tıkandı yemin ederim!'' - Navori Eşkıyası","Birim",[],["Ionia"],"DESTANSI"],"01IO001":["Yenilenme Ayini","Bir dost birimi ya da Nexus'unu 4 iyileştirirsin. 1 kart çekersin.","","''Bedenin bütünlüğü ancak zihnin aydınlanmasıyla sağlanır.''\n- Karma","Büyü",[],["Ionia"],"ENDER"],"01IO010":["Birlikten Kuvvet Doğar","2 dost birimin yerini değiştirirsin. Onlara bu tur Bariyer verirsin.","","''Dengeyi koruyarak ilerliyorum.''\n- Shen","Büyü",[],["Ionia"],"ENDER"],"01IO022":["Hayalet","Bir dost birime bu tur Sıyrılgan verirsin.","","''Kendini belli etme. Görevin bitene kadar da dönme.''\n- Zed","Büyü",[],["Ionia"],"YAYGIN"],"01IO021":["Yavru Yelyolcusu","Çağrıldığımda diğer dost birimlere bu tur +2|+2 verirsin.","","''Bahar ilk Ionia'nın yamaçlarına gelir. Yeni yeni güçlenen kanatların çırpılışı, ülkeyi bu mevsimin hafif meltemleriyle yıkar.''\n- İlk Diyar Menkıbesi","Birim",[],["Ionia"],"DESTANSI"],"01IO054":["Çağların İçgörüsü","Elinde bölgelerine ait rasgele bir büyü daha oluşur.\nAydınlanmış: 1 yerine 2 büyü oluşur.","","''Ümidiniz gölgelenirse sakın unutmayın, yalnız değilsiniz. Geçmiş hep bizimle. O, binlerce geleceği gördü ve hepsinin getireceği umudu içinde saklıyor.\"\n- Karma","Büyü",[],["Ionia"],"ENDER"],"01IO027":["Sessiz Gölge Kâhini","Nexus Vuruşu: Elinde bir kopyam oluşur.","","''Bedene güvenilmez. Dayanıksızdır. Işıkla gölge arasındaki sınır kadar narindir.''","Birim",[],["Ionia"],"DESTANSI"],"01IO031":["Bulutiçen","Anlık büyülerin ve Odaklama büyülerinin bedeli 1 azalır.","","Şarkıları köylerden işitilirdi. Gökten dalga dalga inip yamaçlarda yankılanan, uzun, pes ses dalgalarıydı. Her biri ikindi bulutları kadar değişken ve tuhaftı.","Birim",[],["Ionia"],"ENDER"],"01IO002":["Ionia'nın İstenci","Bir birimi Geri Gönderirsin.","","İşgalciler Ionia topraklarına ilk ayak bastıklarında, halkı savaşta yenmenin yeterli olmayacağını fark ettiler.","Büyü",[],["Ionia"],"YAYGIN"],"01IO017":["Navorili Hızlıbıçak","Çağrıldığımda bu tur Sıyrılgan alırım.","","''Merak etme, ben onu keklik gibi avlarım. Beni buradan çıkar yeter, o zaman ganimeti bölüşürüz, hatta sana fazla fazla ödeme yaparım!''","Birim",["YORDLE"],["Ionia"],"YAYGIN"],"01IO042":["İdman Yapan Öğrenci","Başka bir dost birim çağırdığında, bana bu tur +1|+1 verirsin.","","''Şekilli hareketler yaptığımda görecek kimse yoksa dövüşmenin anlamı ne?''","Birim",[],["Ionia"],"YAYGIN"],"01IO006":["Yeşilkırlı İkili","Başka bir dost birim çağırdığında, bana bu tur +1|+0 verirsin.","","''Hop, dallara dikkat! Sola git, SOLA!''\n''SEN beni taşırken senin istediğin yere gideriz kürk yumağı. Şimdi benim dediğim olacak!''","Birim",[],["Ionia"],"ENDER"],"01IO050":["Kinkou Rehber","Sadakat: Destenden bedeli 1 olan bir dost birim çağırırsın.","","Nereye giderse gitsin, dostlarının peşinden gelebileceği şekilde gider.","Birim",[],["Ionia"],"ENDER"],"01IO048":["Yusari","","","''Tarikatın bizi topraklarımızdan attı. Gücünü kanıtladın Zed usta. Şimdi de izin ver, ben de senin öğretilerini almaya layık olduğumu kanıtlayayım.''","Birim",[],["Ionia"],"ENDER"],"01IO007":["Ren Gölgekılıç","Vur: Elinde bir Gölge Canavar oluşur.","","''İster kaç ister savaş ister korkuyla saklan. Hiçbiri fayda etmeyecek. Gölgeler seni almaya geldi.''","Birim",[],["Ionia"],"DESTANSI"],"01IO053":["Aydınlık Savaşçısı","Aydınlanmış: +4|+4 alırım.","","''Savaşı en bayağı içgüdülerimiz besler. Ama içgüdülerin güven, sabır ve tefekkür gibi en yüksek erdemlerimiz üstünde hiçbir etkisi yoktur.''","Birim",[],["Ionia"],"YAYGIN"],"01IO004":["Can İksiri","Bir dost birimi ya da Nexus'unu 3 iyileştirirsin.","","Her kuşağın, bölgenin ve ailenin kendine özgü şifalı tarifleri olur. Tabii bazıları diğerlerinden çok daha etkilidir.","Büyü",[],["Ionia"],"YAYGIN"],"01IO049":["Yadsıma","Hızlı bir büyüyü, Yavaş bir büyüyü ya da bir Yeteneği durdurursun.","","Hayır.","Büyü",[],["Ionia"],"ENDER"],"01IO052":["Navori Haydudu","Çağrıldığımda benim niteliklerime sahip bir Navori Eşkıyası çağırırsın.","","''Gezgin bir müzisyendim, te buradan Placidium'a kadar her köyde tanınırdım. Sonra Noxus'lular geldi. Şimdi çaldığım üç kuruşla geçiniyorum. Anacığım haklıymış, şifacı olmalıymışım...''","Birim",[],["Ionia"],"YAYGIN"],"01IO030":["Arşejderi","","","''Gökyüzünden bir tokat yedik sanki. Büklüm büklüm bulutlar ve sert rüzgârlar tugayımızı dümdüz etti. Takip etmeye çalıştık ama rüzgâra kim yetişebilir?''\n- Lejyon Generali","Birim",["EJDER"],["Ionia"],"DESTANSI"],"01IO019":["Yeşilkırlı Muhafız","Bir dost birim Bariyer aldığında +2|+0 kazanırım.","","''Bu kır, sakinlerini korur. Ama sen, sen buralı değilsin.''","Birim",[],["Ionia"],"YAYGIN"],"01IO046":["Çelik Fırtına","Saldıran bir düşmanı Sersemletirsin.","","''Hasagi!''\n- Yasuo","Büyü",["ELEMENTAL"],["Ionia"],"ENDER"],"01IO037":["Ruh Sığınağı","Bir dost birime bu tur Bariyer ve Can Çalma verirsin.","","''Bu silah eskiden babamındı. Bir zamanlar kendimde bulamadığım gücü sana verir umarım.''\n- Shen","Büyü",[],["Ionia"],"YAYGIN"],"01IO043":["Nehirbüken","Vuruş: Bir büyü çekersin.","","''Biz İlk Diyar'ın mağrur evlatlarıyız. Onun sihri ülkemizde nasıl ırmaklar gibi akıyorsa vastaya kanımızda da öyle akar.''","Birim",[],["Ionia"],"ENDER"],"01IO038":["Münzevi Keşiş","Oyna: Diğer tüm dost birimleri Geri Gönderirsin.","","''Reflekslerimle ve içgüdülerimle baş başa kalmak istiyorum.''","Birim",[],["Ionia"],"ENDER"],"01IO039":["Gölge Geçişi","Bir dost birimi Geri Gönderirsin ve yerine bir Canlı Gölge çağırırsın.","","Karşında acaba gözlerinle gördüğünü sandığın düşman mı var? Yoksa bu gölgelerin bir oyunu mu?","Büyü",[],["Ionia"],"YAYGIN"],"01IO055":["Ki Koruması","Elindeki bir dost birime Bariyer kazandırırsın. 1 kart çekersin.","","''Dengeyi koruyanlar, sırtlarını Kinkou'nun korumasına yaslayabilir.''\n- Shen","Büyü",[],["Ionia"],"YAYGIN"],"01NX020":["Draven","Çağrıldığımda ya da Vuruş yaptığımda: Elinde bir Dönen Balta oluşur.","Toplam 2+ Dönen Balta ile vurduğumda.","''İmza istiyorsan sıraya gireceksin birader.''","Birim",[],["Noxus"],"Şampiyon"],"01NX006":["Vladimir","Oyna: İstediğin sayıda dost birime 1 hasar vererek bir düşmana o sayıya denk hasar verirsin.","5+ dost birimin hasar alıp sağ kaldığında.","Hain. Zalim. Soğuk. Anlayışı keskin. İlginç. Nazik.\nKarşı konulmaz...","Birim",[],["Noxus"],"Şampiyon"],"01NX004":["Eleyici Darbe","Güç değeri 3 ya da daha az olan bir birimi öldürürsün.","","Herkes ölür. Ama zayıflar daha çabuk ölür.","Büyü",[],["Noxus"],"ENDER"],"01NX048":["Kızıl Küratör","Hasar alıp sağ kalırsam elinde rasgele bir Kızıl birim oluşur.","","''Görüştüğümüze çok sevindim!'' ''Lanet olsun ki çok meşgulüz.'' ''Elbette! Bu balo kaçmazdı.'' ''Sipariş ettiğim takım sanırım üstüme olmayacak.'' ''Işıltınız yeter hanımlar. Sen geliyor musun Kye?''","Birim",[],["Noxus"],"YAYGIN"],"01NX038":["Darius","","Rakibin Nexus'unun başlangıçtakinin yarısı ya da daha azı kadar Canı kaldığını gördüğümde.","''İradesi çelik gibi, gücü devlerinkine denk. Trifaria Lejyonu'na daha uygun bir general olamaz.''\n- Swain","Birim",[],["Noxus"],"Şampiyon"],"01NX023":["Eklembacaklı Ordusu","Çağrıldığımda, diğer dost Örümcekler +2|+0 kazanır.","","Ona ait olman için sana bir kere bakması yeter. Onlara ait olman için seni bir kere ısırmaları yeter.","Birim",["ÖRÜMCEK"],["Noxus"],"ENDER"],"01NX013":["Bitirici Manevra","Bir düşmanı Sersemletirsin. Tüm dost birimlere bu tur +2|+0 verirsin.","","''Her ahmak, düşmanının üstüne onunkinden kat kat kalabalık bir güçle yürüyebilir. Asıl deha, bunu son ana kadar gizleyebilmek.''\n- Swain","Büyü",[],["Noxus"],"ENDER"],"01NX046":["Eklembacaklı Gözcü","Oyna: Bir düşmanı Sersemletirsin.","","''Ah, âdeta esiri oldum! O upuzun bacakları, insanı uyuşturacak kadar tatlı sesi ve gül kırmızısı gözleri yok mu... Üstelik bu akşam benimle yemek yemeyi kabul etti!''\n- Bahtsız Soylu","Birim",["ÖRÜMCEK"],["Noxus"],"YAYGIN"],"01NX047":["Kan Nakli","Bir dost birime 1 hasar, bir diğerine bu tur +2|+2 verirsin.","","''Bir alışveriş yapacağız canım. Sen vereceksin, ben alacağım.'' - Vladimir","Büyü",[],["Noxus"],"YAYGIN"],"01NX040":["Lejyon Sabotajcısı","Saldır: Rakibin Nexus'una 1 hasar verirsin.","","''Kalkan Kırıcılarımız insanları ortadan ikiye yarabilir. Ama işlerin daha... göze çarpmadan halledilmesi gerektiğinde kullanabileceğimiz yetenekli askerlerimiz de var.''\n- Swain","Birim",[],["Noxus"],"YAYGIN"],"01NX025":["Kardeşlik Bağı","2 dost birime +2|+0 kazandırırsın.","","''Savaşta kurulan bağ akrabalık bağı kadar sağlamdır. Ne de olsa ikisi de kanla kurulur.''\n- Deneyimli Lejyoner","Büyü",[],["Noxus"],"YAYGIN"],"01NX055":["Ev Örümceği","Çağrıldığımda bir Yavru Örümcek çağırırsın.","","''Örümceklerim misafire bayılır. Ne yazık ki misafirlerim onları hiç sevmiyor.''\n- Elise","Birim",["ÖRÜMCEK"],["Noxus"],"YAYGIN"],"01NX030":["Kızıl Talebe","Hasar alıp sağ kalırsam rakibin Nexus'una 1 hasar veririm.","","''Üstelik son görüşmemizin üstünden bu kadar az vakit geçmişken!'' ''Ne giymeyi düşünüyorsunuz?'' ''Kavalyen olmayı çok ama çok isterim.'' ''Ne, pişti mi olalım yani?''","Birim",[],["Noxus"],"ENDER"],"01NX007":["Arena Savaşı Yorumcusu","Saldır: Saldıran diğer dost birimlere bu tur +1|+0 verirsin.","","Coşkuyla kükredi. Arenanın kalbi bir anlığına onunkiyle birlikte attı. Seyirci kalabalığının heyecanı iki dudağının arasındaydı.","Birim",[],["Noxus"],"ENDER"],"01NX021":["Lejyon Yağmacısı","Saldır: Her yerdeki dost Lejyon Yağmacısı kartlarına +1|+1 kazandırırsın.","","Trifaria Lejyonu'nun peşinden, arkasında bıraktığı zayıfları ve yaralıları avlayan fırsatçı haydutlar gelir.","Birim",[],["Noxus"],"YAYGIN"],"01NX009":["Taraftarın Sevgilisi","Çağrıldığımda, sahip olduğun diğer her dost birim için +1|+1 kazanırım.","","Bazı hesapçılar karizmatik olduğu için sevilir, bazıları da çok teknik dövüştüğü için. Vessid'de bunların ikisi de yok ama hasmını toprakta bir kan lekesine çevirmekte kimse ondan daha hızlı değil.","Birim",[],["Noxus"],"ENDER"],"01NX011":["Ölüm Pervanesi","Savaşan bir dost birim, savaşan bir düşmana vurur.","","''İşim acayip iyi ya.''\n- Draven","Büyü",[],["Noxus"],"YAYGIN"],"01NX053":["Hesaplaşma","Güç değeri 5+ olan bir dost birimin varsa, Güç değeri 4 ya da daha az olan tüm birimleri öldürürsün.","","''HESAPLAŞMAYA HAZIR MIYIIIIIIIIIIIIIZZZZZ?''\n- Arena Savaşı Yorumcusu","Büyü",[],["Noxus"],"DESTANSI"],"01NX054":["Tehditkâr Kükreme","Güç değeri 4 ya da daha az olan tüm düşmanları Sersemletirsin.","","''Derin bir nefes alıyoor... Yoksa o mu geliyor? Evet sayın seyirciler, gerçekten de Yıldırım'ın meşhur savaş narası geldi! Korkudan tir tir titriyoruz, Yıldırım!''\n- Arena Savaşı Yorumcusu","Büyü",[],["Noxus"],"ENDER"],"01NX029":["Deneyimli Lejyoner","Başka bir dost birim hasar alıp sağ kaldığında ona +1|+0 kazandırırsın.","","Savaştan ölümün eşiğinde döndü. Canını, sevgili eşinin ihtimamı ve eczacının hazırladığı merhemler kurtardı. Savaşacak yaşı geçtiğinde bile Noxus, uzmanlığına danışmak için masraftan kaçınmadı.","Birim",[],["Noxus"],"DESTANSI"],"01NX014":["Ustura Shiraza","Nexus'a çifte hasar veririm.","","''NE DEMİŞ? O adamın kafasında beyin yerine tuğla var tuğla. Ama omuzlarına diyecek yok doğrusu...''","Birim",[],["Noxus"],"DESTANSI"],"01NX042":["Katarina","Çağrıldığımda elinde Geçici bir Bıçak Sırtı oluşur.","Bir vuruş yaptığımda. Seviye atladığımda beni Geri Gönderirsin.","''Demacia'lılara nişan alma çalışması yapalım da duyularımız keskinleşsin.''","Birim",[],["Noxus"],"Şampiyon"],"01NX051":["Yüzbaşı Farron","Çağrıldığımda elinde 2 Biçen Balta oluşur.","","Benn Farron'a gençliğinde Zaun'un Kuyu'sunun derinliklerinde dengesiz, kabul edilemez bir toplum düşmanı dediler. Noxus ordusunun safları onu kucakladı ve ödüllendirdi. Artık durdurulamaz.","Birim",[],["Noxus"],"DESTANSI"],"01NX012":["Lejyon İhtiyat Birliği","","","Askerlere savaş meydanındaki cüretkârlıklarından dolayı saygı duyulan Noxus'ta, ihtiyat birliği görevine verilmek ceza olarak görülür.","Birim",[],["Noxus"],"YAYGIN"],"01NX043":["Bıçak Sırtı","Herhangi bir şeye 1 hasar verirsin.","","''Doğru ellerdeki bir bıçak her şeyi ama her şeyi kesebilir.''\n- Katarina","Büyü",[],["Noxus"],"YAYGIN"],"01NX037":["Lejyon Bombacısı","Son Nefes: Rakibin Nexus'una 1 hasar verirsin.","","Her Noxus'luya, imparatorluğa hizmet ederek geçen bir yaşamın en yararlısı olduğu öğretilir. Ama bu öğretiye Lejyon'un el bombacıları kadar gösterişli şekilde uyan çok az kişi vardır.","Birim",[],["Noxus"],"YAYGIN"],"01NX010":["Lejyon Generali","Çağrıldığımda, bu oyunda Sersemlettiğin ya da Geri Gönderdiğin her birim için +1|+1 kazanırım.","","Tüm Noxus'lular üç Kuvvet İlkesi'ni bilir. Fakat orduda yükselmek isteyen askerler bunların üçünde de ustalaşmalıdır.","Birim",[],["Noxus"],"YAYGIN"],"01NX017":["Lejyon Davulcusu","Destekle: Desteklediğim dost birim bu tur İlk Saldırı alır.","","O davuluna vurdukça Lejyon imparatorluğun dört köşesine dağılıyor. Onları hiçbir şey durduramaz. Asla durduramadı.","Birim",[],["Noxus"],"YAYGIN"],"01NX003":["Arena Bahisçisi","Tur Başı: En düşük bedelli kartını atıp 1 kart çekersin.","","''...bir tek Shiraza'nın, bir de o Ionia'lı çocuğun hayatta kalacağına para yatır. Tek kolu yok ama ölü de değil ya? O kolla hayata daha sıkı tutunur şimdi. Tabii bahsi ikiye de katlayabilirsin...''","Birim",["YORDLE"],["Noxus"],"ENDER"],"01NX039":["İleri Görüşlülük","Oynandığında ya da atıldığında dost birimlere +1|+0 kazandırırsın.","","''Geleceği göremeyenlerin onu yaşamaya hakkı yoktur.''\n- Jericho Swain","Büyü",[],["Noxus"],"ENDER"],"01NX041":["Trifaria Kalkan Kırıcısı","","","''Kuşatmaya tahammül edecek sabrım yok. Kalkan Kırıcıları gönderin.''\n- Darius","Birim",[],["Noxus"],"YAYGIN"],"01NX036":["Minotor Hesapçı","Tur Başı: En Güçsüz düşmanı Sersemletirsin.","","''Kimin sana ne yanlış yaptığı umurumda değil. Kozunu arenada paylaşmak istiyorsan para peşin, kırmızı meşin. Acıklı hikâyeler anlattın diye indirim yapmıyorum.''","Birim",[],["Noxus"],"ENDER"],"01NX044":["Koçbaşı","Saldır: +4|+0 kazanırım.","","''Kapılarını açmayı reddediyorlar komutanım. Darius'la konuşmak istediler ama iki günlük yolda. Süvarileri gönderelim mi?''\n''Yoo, gerek olmayacak.''","Birim",[],["Noxus"],"DESTANSI"],"01NX005":["Kızıl Aristokrat","Oyna: Bir dost birime 1 hasar verirsin ve +1|+0 ile Aban kazandırırsın.","","''Davetiye bulabildiniz mi?'' ''Ah, bir de benimkileri görsen. Bütün gece nasıl tahammül edeceğim bilmiyorum.'' ''Israr etme şekerim, babam beni vasiyetinden çıkarır. Aynı elbiseyi giysek?''","Birim",[],["Noxus"],"YAYGIN"],"01NX016":["Trifaria Lejyoner Adayı","Çağrıldığımda başka bir dost Noxus birimine sahipsen +2|+0 kazanırım.","","''Bu unvanı ancak baltan savaşmaktan köreldiğinde, postallarının içi vıcık vıcık kanla dolduğunda kazanırsın.''\n- Deneyimli Lejyoner","Birim",[],["Noxus"],"YAYGIN"],"01NX019":["Kuvvet","Bir dost birime bu tur +3|+0 ve Aban verirsin.","","''İncelikli iş yapmanın önemi abartılıyor dediğimde iltifat olarak söylemiyorum. Gereksiz bir olay.''\n- Darius","Büyü",[],["Noxus"],"YAYGIN"],"01NX015":["Bi'tanesi","","","Hepsini çok seviyor. Ama bunu birazcık daha fazla seviyor.","Birim",["ÖRÜMCEK"],["Noxus"],"YAYGIN"],"01NX050":["Ölüm Çiçeği","Savaşan TÜM birimlere 1 hasar verirsin.","","''Benimle dans et!''\n- Katarina","Büyü",[],["Noxus"],"ENDER"],"01NX056":["Shunpo","Bir düşmana 2 hasar verirsin, ardından Silahlanırsın.","","Bıçağı görebiliyorsan artık çok geçtir.","Büyü",[],["Noxus"],"YAYGIN"],"01NX033":["Lejyoner Seçme Uzmanı","Çağrıldığımda Güç değeri 5+ olan her dost birimin için 1 kart çekersin.","","''Trifaria Lejyonu'na katılmaya layık olanları seçebilmek için çok bilgili ve acımasız bir göz gerekir. Bizimki kurtla kuzuyu bir günlük yoldan ayırt edebilir.''\n- Lejyon Generali","Birim",[],["Noxus"],"ENDER"],"01NX052":["Kana Kan","Dost bir takipçiye 1 hasar verirsin. Takipçi ölmezse, elinde bir kopyası oluşur.","","Kan büyücüleri ilk derslerinde ortalığı muhakkak berbat ederler.","Büyü",[],["Noxus"],"YAYGIN"],"01NX045":["Acımasız Hesapçı","","","''Şimdi sıra PENÇE'de! Geçen sefer Psikopat Beşli'ye kan banyosu yaptırdı, artık Psikopat Üçlü oldular! Evvvett, bugünün kurbanı için bahisleri alayım! Bire dört veriyor!''\n- Arena Bahisçisi Karl","Birim",[],["Noxus"],"ENDER"],"01NX031":["Şöhret Heveslisi Lejyoner","","","Trifaria Lejyonu'nda yer edinmek çoğu için yeterlidir ama herkese yetmeyebilir.","Birim",[],["Noxus"],"ENDER"],"01NX002":["Biçen Balta","Rakibin Nexus'una 4 hasar verirsin.","","''Bazen bir suru yıkmak için taktiksel deha gerekir. Bazen de daha sert vurmak gerekir.''\n- Darius","Büyü",[],["Noxus"],"ENDER"],"01NX008":["Basilisk Süvarisi","Sadakat: +1|+1 ve Aban kazanırım.","","Bu birimde atlar da var ama binmek için değil. Binekleri tadına bayıldığı için.","Birim",[],["Noxus"],"ENDER"],"01NX034":["Sevgi Dolu Poro","","","''Noxus'ta zayıf... zayıflığa yer y... BİRİ ŞUNU ÜSTÜMDEN ALSIN BAK ÇOK FENA OLACAK!''\n- Darius","Birim",["PORO"],["Noxus"],"YAYGIN"],"01NX035":["Draven'ın En Büyük Hayranı","Çağrıldığımda elinde ya da oyunda Draven yoksa destenin en üstüne gelir.","","''İmza istiyorsan sı... sıraya gireceksin birader.''","Birim",[],["Noxus"],"YAYGIN"],"01NX026":["Gözü Kara Lejyoner","","","''Pervasızlık bir kusurdur. Ama Lejyon tarafından dizginlenirse yararlı bir araç haline gelir.''\n- Swain","Birim",[],["Noxus"],"YAYGIN"],"01NX027":["Hiddet Karışımı","Bir dost birime bu tur +3|+0 verirsin.","","''Uzattığın el geri çevrilirse yumruk ne güne duruyor?''\n- Noxus aforizması","Büyü",[],["Noxus"],"YAYGIN"],"01NX022":["Noxus Giyotini","Hasar almış bir birimi öldürüp elinde Geçici bir Noxus Giyotini oluşturursun.","","Darius'un merhametten anladığı, acısız öldüren bir darbedir.","Büyü",[],["Noxus"],"ENDER"],"01NX032":["Kızıl Provokatör","Çağrıldığımda tüm diğer dost birimlere 1 hasar verirsin.","","''Ne kadar itiraz etsem de götüreceksiniz zaten. Mecburen geliyorum.''","Birim",[],["Noxus"],"ENDER"],"01NX024":["Pazu Kato","Destekle: Desteklediğim dost birim bu tur +3|+0 ve Aban alır.","","''Shiraza çok iyi bir kız arkadaş... Yani çok iyi bir kız. Kesinlikle çıkmıyoruz. Ama çıkıyor olsak kendisine yıldönümümüzü kutladığımı iletirdim. Başka soru yanıtlamayacağım, teşekkürler.''","Birim",[],["Noxus"],"DESTANSI"],"01NX049":["Kurnazlık","Bir düşmanı Sersemletirsin.","","''Düşmanına kendini asabileceği kadar uzun bir urgan hediye etmek daha kolaydır.''\n- LeBlanc","Büyü",[],["Noxus"],"YAYGIN"],"01DE031":["Şafak Vaizleri","Tur Sonu: Bu tur bir dost birim öldüyse, diğer dost birimlere +1|+1 kazandırırsın.","","''Kötülük şimdilik üstün gelmiş olabilir fakat nihai galip o olmayacak. Kaybettiklerimizi hatırlayın. Onların anısı sizin zırhınız olsun!''","Birim",[],["Demacia"],"DESTANSI"],"01DE022":["Lucian","","4+ dost birimin ya da dost bir Senna'nın öldüğünü gördüğümde.","''Yanımda sen olduğun sürece bana bir şey olmaz Senna.''","Birim",[],["Demacia"],"Şampiyon"],"01DE019":["Seferberlik","Elindeki dost birimlerin bedeli 1 azalır.","","''Eli ayağı tutan her Demacia'lının iki haftada tarlasını bırakıp cephede savaşabilir hale gelmesini bekleriz.''\n- Garen","Büyü",[],["Demacia"],"ENDER"],"01DE042":["Lux","","Toplamda 6+ manalık büyü oynadığını gördüğümde. Seviye atladığımda elinde bir Son Parıltı oluşur.","''Bende başkalarından farklı bir şey olduğunu her zaman biliyordum. İçimde bir ışık vardı sanki. O ışığın ne olduğundan emin değilim ama mutlaka öğrenmeliyim!'' ","Birim",[],["Demacia"],"Şampiyon"],"01DE010":["Çevikkanat Mızrakçısı","Son Nefes: Elinde rasgele bir Seçkin kart oluşur.","","''Canını bir gümüşkanata emanet edip havada göğüs göğse çarpışmak hem cesur bir yürek hem de çok sağlam sinirler ister.''\n- Garen","Birim",["SEÇKİN","KUŞ"],["Demacia"],"ENDER"],"01DE020":["Yılmaz Öncü Savunmacısı","","","''O yaratıklar neydi, kimdi bilmiyorduk. Ama yanımızda silah arkadaşlarımızın olduğunu biliyorduk, bu da bize yetti.''","Birim",["SEÇKİN"],["Demacia"],"YAYGIN"],"01DE034":["Savaş Demircisi","Seçkin bir birim çağırdığında ona +1|+1 kazandırırsın.","","Zafere giden yol demirci ocağından başlar.","Birim",[],["Demacia"],"ENDER"],"01DE002":["Tianna Crownguard","Çağrıldığımda Silahlanırsın.","","''Ailemiz bu ülke için kanını döktü. Üç beş ışık oyunu yapacağım diye aile şerefimizi ayaklar altına alamazsın.''","Birim",[],["Demacia"],"DESTANSI"],"01DE012":["Garen","Çağrıldığımda diğer dost birimlere bu tur +1|+1 verirsin.","İki vuruş yaptığımda.","Askerin görevi idman yapmak ve dayanıklı olmaktır. En büyük tehlike karşısında bile vazgeçmeyeceğiz.","Birim",["SEÇKİN"],["Demacia"],"Şampiyon"],"01DE017":["Bir Başına","Tam olarak 1 dost birimin varsa, ona +3|+3 kazandırırsın.","","Herkes başarısız olduğunda, zafer yolunu açmak gerçek kahramanlara düşer.","Büyü",[],["Demacia"],"ENDER"],"01DE045":["Fiora","","2 düşman öldürdüğümde.","''Arenalardan turnuvalara, idmanlardan savaş meydanına kadar her yerde kendime layık rakipler ararım. En iyi kılıç ustası olduğumu kendime kanıtlamadan durmayacağım.''","Birim",[],["Demacia"],"Şampiyon"],"01DE052":["Aydınkalkan Müdafaacıları","Çağrıldığımda ya da Saldır: Dost birimlere bu tur Bariyer verirsin.","","''Bu müdafaa dizilişi, taktiklerimizin temelini oluşturur. Her askerin hem kendi kalkanına hem de yoldaşlarınınkine güvenmesini gerektirir. Onlar ayakta durdukça ülkemiz de duracaktır.''\n- Garen","Birim",[],["Demacia"],"DESTANSI"],"01DE021":["Amansız Takip","Silahlanırsın.",""," ''Herkes korkularıyla yüzleşmeli. Şanslıymışsın, ben buradayım.''\n- Lucian\n","Büyü",[],["Demacia"],"YAYGIN"],"01DE025":["Tutukla","Bir dost birim, bir birimi Zapt Eder.","","''Biz kanunuz, sen halksın. Bize itaat edeceksin. Ötesi yok.''\n- İknacı Sihir Avcısı","Büyü",[],["Demacia"],"YAYGIN"],"01DE007":["Yargı","Savaşan bir dost birim, tüm savaşan düşmanlara vurur.","","Adalet daima yerini bulur.","Büyü",[],["Demacia"],"DESTANSI"],"01DE055":["Laurent Düellocu","Oyna: Elindeki bir dost birime Rakipçeker kazandırırsın.","","''Pahalı bir kılıç satın almış züppenin tekine benziyordu. Meğer o kılıcı kullanmayı çok iyi biliyormuş. Rövanş isterdim ama aksanı öyle komikti ki adını anlamadım.''\n- Demacia'lı asteğmen","Birim",[],["Demacia"],"YAYGIN"],"01DE048":["Galeyancı Sihir Avcısı","Bu oyunda bedeli 6+ olan bir büyü oynadığında +2|+2 kazanırım.","","''Çağlar önce Rün Savaşlarının dizginsiz büyüleri Runeterra'yı kasıp kavurmuştu. Teşkilatımız, hem içeride hem dışarıda büyüyü yok ederek krallığımızı korumak için kuruldu.''\n- Sihir Avcısı El Kitabı","Birim",[],["Demacia"],"ENDER"],"01DE001":["Yılmaz Öncü Sancakçısı","Sadakat: Diğer dost birimlere +1|+1 kazandırırsın.","","''Sancağımızın önemini iyi kavra. Onu kralımız, ailelerimiz, yurttaşlarımız için dalgalandırırız. Demacia'ya duyduğumuz sarsılmaz inancın ta kendisidir. Gururumuzun nişanesidir.''\n- Tianna Crownguard ","Birim",["SEÇKİN"],["Demacia"],"ENDER"],"01DE043":["Ordu Aşçıları","Destekle: Desteklediğim dost birim bu tur +1|+1 alır.","","Demacia ordusundaki kimseyi hafife almamak lazım.","Birim",[],["Demacia"],"YAYGIN"],"01DE049":["Yiğit Poro","","","''Yeni er, en iyi askerlerimizinkine denk bir cesaret ve dayanıklılık gösterdi. Bir gün Yılmaz Öncülere katılabilecek mi? Herkesten daha... ufak tefek ama göreceğiz.''\n- Yılmaz Öncü Çavuşu","Birim",["PORO"],["Demacia"],"YAYGIN"],"01DE053":["Züppe Laurent","Vuruş: Elinde bölgelerine ait başka bir rasgele Rakipçeker takipçi oluşur.","","''...Yok artık.''\n- Fiora","Birim",[],["Demacia"],"DESTANSI"],"01DE033":["Anma","Bu tur ölmüş olan her dost birim için bedelim 1 azalır. Bedeli 5 olan rasgele bir Demacia'lı takipçi çağırırsın.","","''Bugün, bizden öncekilerin canına kıyan adaletsizliklere karşı duracağız. Yoldaşlarımızın yaptığı fedakârlık boşa gitmeyecek.''\n- Aydınlık Muhafız","Büyü",[],["Demacia"],"ENDER"],"01DE044":["Pekişen Cesaret","Bir dost birimi tamamen iyileştirirsin, sonra Güç ve Can değerlerini ikiye katlarsın.","","Demacia'da, bir düşman askerinin iki katı güçlü olmak boş övünmeden ibaret değildir.","Büyü",[],["Demacia"],"ENDER"],"01DE024":["Koleksiyoncu Sihir Avcısı","Son Nefes: Elinde Demacia dışındaki bir bölgeye ait, bedeli 6+ olan rasgele bir büyü oluşur.","","''Büyülü eşyaların yadsınamaz bir çekiciliği vardır. Fakat bunları uzmanlarımızın maharetli ellerine bırakıp iyi niyetli ama bilgisiz halkımızdan uzak tutmak en iyisidir.''\n- Sihir Avcısı El Kitabı","Birim",[],["Demacia"],"YAYGIN"],"01DE004":["Gümüşkanat Öncüsü","Oyna: Birebir kopyamı çağırırsın.","","Bulutlardan gümüş yıldırımlar gibi inerek hızla ve isabetle hedeflerini buldular. Sonra belirdikleri kadar büyük bir hızla ortadan kayboldular. ","Birim",["SEÇKİN","KUŞ"],["Demacia"],"YAYGIN"],"01DE011":["Laurent Çömezi","","","''NE yaptı dedin? Pierre de Guillard'ın paha biçilmez, çifte dengeli süvari kılıcını ona sadece eğitimde kullanacağım dedi diye emanet etmiştim!'' - Laurent Silahtar","Birim",[],["Demacia"],"YAYGIN"],"01DE047":["Devir Teslim","Bir Yılmaz Öncü çağırırsın.","","Yılmaz Öncülerin üniformaları, aralarına yeni katılan erlerin görevlerinin ağırlığını ve gururunu hissedebilmesi için bir askerden diğerine geçer.","Büyü",[],["Demacia"],"YAYGIN"],"01DE046":["Yılmaz Öncü Gözcüsü","","","Ortalığın sessiz olması güvenli olduğu anlamına gelmez.","Birim",["SEÇKİN"],["Demacia"],"YAYGIN"],"01DE050":["Arıt","Bir takipçiyi Susturursun.","","''Petrisitten yapılma Bozmühür'ünüz sihre karşı en büyük korumanız, sorumluluklarımızın simgesi ve otoritenizin göstergesidir. Hak ettiği saygıyı gösterin.''\n- Sihir Avcısı El Kitabı","Büyü",[],["Demacia"],"YAYGIN"],"01DE040":["İknacı Sihir Avcısı","Bu oyunda bedeli 6+ olan bir büyü oynadığında +1|+1 ve Rakipçeker kazanırım.","","''Demacia'lılar! Güvenliğinizi sağlamak benim için onurdur. Ama bizim de koşulsuz desteğinize ihtiyacımız var çünkü güvenli surlarımızın ardında bile aramızda büyücüler gizleniyor!''\n","Birim",[],["Demacia"],"ENDER"],"01DE036":["Yılmaz Öncü Eri","Seçkin bir birim çağırdığında bedelim 1 azalır.","","''Tanıştığım herkes, çıktığım her yolculuk bana yeni bir şey öğretti. Ama öğrendikçe ve güçlendikçe, gidecek daha çok yolum olduğunu fark ettim.'' - Yılmaz Öncü Eri Cithria\n","Birim",["SEÇKİN"],["Demacia"],"YAYGIN"],"01DE037":["Karşı Hamle","Bir dost birime bu tur +3|+0 ve Bariyer verirsin.","","''Doğru tahmin etmişim, poro gibi dövüşüyormuşsun!''\n- Fiora","Büyü",[],["Demacia"],"ENDER"],"01DE014":["Takviye Birlik","2 Yılmaz Öncü çağırırsın, sonra Seçkin dost birimlere +1|+1 kazandırırsın.","","''Hasımlarımız birimize vurmanın hepimize vurmak anlamına geldiğini bilirler.''\n- Öncülerin Yasası","Büyü",[],["Demacia"],"ENDER"],"01DE015":["Aydınlık Muhafız","Çağrıldığımda bu tur bir dost birim ölmüşse Can Çalma ve Dayanıklılık kazanırım.","","''Soğuk, ölü eller yoldaşlarını tutup aşağı çekti. Sadece o ayakta kaldı. Işıklı bir adalet timsaliydi, kılıcı savrulurken hayatını kaybeden askerlerin adını söylüyordu sanki.''\n- Demacia'lı asteğmen","Birim",[],["Demacia"],"ENDER"],"01DE003":["Laurent Silahtar","Oyna: Bir dost birime +2|+2 kazandırırsın.","","''Evet, çok güzeller. Ama her kaliteli enstrüman gibi onlar da gerçek güzelliklerini ancak ustaların elinde açığa vurur.'' ","Birim",[],["Demacia"],"ENDER"],"01DE026":["Teke Tek Çatışma","Bir dost birim ve bir düşman birim birbirine vurur.","","''Sen sus, kılıçlarımız konuşsun.''\n- Fiora","Büyü",[],["Demacia"],"YAYGIN"],"01DE032":["Prizmatik Bariyer","Bir dost birime bu tur Bariyer verirsin.","","''Dünya farklı olanlara sırtını dönebiliyor. Farklılıkların kişiyi zayıf kıldığını söyleyenler var ama aslında bizi güçlü ve merhametli yapıyorlar. En karanlık zamanlarda bile arkandayım!''\n- Lux","Büyü",[],["Demacia"],"YAYGIN"],"01DE027":["Gardını Al","Dost birimlere bu tur Rakipçeker verirsin.","","''Demacia'da bir Laurent'tan kılıç dersi almayı reddebilecek veya bu dersten sağ çıkabilecek kimse yok.''\n- Fiora","Büyü",[],["Demacia"],"ENDER"],"01DE006":["Yılmaz Öncü Çavuşu","Çağrıldığımda elinde bir Demacia İçin! oluşur.","","''Sabahtan akşama kadar eğitimlerde başımızda duruyor. Savaşa ilk atılan o. Çelik kadar sert, kaya gibi sağlam. Daha iyi bir önder bulunamaz.''\n- Demacia'lı asteğmen","Birim",["SEÇKİN"],["Demacia"],"ENDER"],"01DE038":["Işık Muhafızı, Senna","Dost bir Lucian ilk defa öldüğünde +1|+1 ve Çifte Saldırı kazanırım.","","''Biz Muhafızlar, bitmez tükenmez hortlak ordularıyla insan diyarı arasındaki ilk savunma hattıyız. Savaşa ilk biz gireriz, ağır saldırırız ve yoldaşlarımızın canı tehlikedeyse bir adım bile geri atmayız.''","Birim",[],["Demacia"],"ENDER"],"01DE041":["Sırt Sırta","2 dost birime bu tur +3|+3 verirsin.","","''Arkamı kolla, dalıyorum!''\n''Hadi ya? Ben de tam aynı şeyi diyecektim.''\n- Doğu Taburu'ndan Lorn ve Dax","Büyü",[],["Demacia"],"ENDER"],"01DE035":["Demacia İçin!","Dost birimlere bu tur +3|+3 verirsin.","","''Burası bizim yuvamız, bunlar ailemiz, silah arkadaşlarımız. Burası gururumuz, onurumuz, bileğimizdeki güç. Bugün onun varlığını korumak için savaşırken hep bir ağızdan adını haykıracağız: DEMACIA!''\n- Yılmaz Öncü Çavuşu","Büyü",[],["Demacia"],"ENDER"],"01DE018":["Aydınlık Saldırı","Bir dost birime bu tur +1|+1 verirsin.","","''Yaşayan ölüler yarına çıkmayacakmış gibi savaşır. Biz, gerçekten de çıkmamalarını sağlayacağız.''\n- Lucian","Büyü",[],["Demacia"],"YAYGIN"],"01DE009":["Aydınkalkan Koruyucusu","Oyna: Bir dost birime bu tur Bariyer verirsin.","","''Ülkemizdeki refahın kaynağı, her bir askerimizin canının altından da kıymetli olmasıdır.''\n- Kral Jarvan III","Birim",[],["Demacia"],"YAYGIN"],"01DE039":["Bulutçayırlı Cithria","","","''Annem geceleri yatmadan önce bir yandan kılıcını bileyler, bir yandan da Demacia'nın kahramanlarının öykülerini anlatırdı. Rüyalarıma girerdi. Bugün de benim öyküm başlayacak!''","Birim",["SEÇKİN"],["Demacia"],"YAYGIN"],"01DE056":["Yılmaz Öncü Başkılıç","Saldır: +2|+2 kazanırım.","","Savaş narası atıldı, ayaklarım toprağı eşmeye başladı bile. Kaderimin belirlenmesi için hanımımın emrini bekliyorum, sonra onun isteğini gerçek kılacağım.","Birim",["SEÇKİN"],["Demacia"],"YAYGIN"],"01DE029":["Çeviktüy İz Sürücü","Başka bir dost birimi çağırdığında Rakipçeker kazanırım.","","Gümüşkanat kartallarının akrabası olan bu kuşlar, hem kuzenleri kadar yırtıcıdırlar hem de onlara kıyasla ne kadar ufak olduklarının hiç farkında değilmiş gibi davranırlar.","Birim",["KUŞ"],["Demacia"],"YAYGIN"],"01DE028":["Yılmaz Öncü Süvarisi","","","Öncülerin uygun adım yürümek için ne savaş davuluna ne de müziğe ihtiyacı vardı. At toynaklarının toprakta çıkardığı düzenli, devamlı sesler yeterliydi.","Birim",["SEÇKİN"],["Demacia"],"YAYGIN"],"01DE013":["Zincir Yelek","Bir dost birime Dayanıklılık kazandırırsın.","","Demacia Çeliği üstün sağlamlığıyla dünyanın her yerinde nam salmıştır. Bu metali dövmek için hem kuvvetli hem de namuslu bir demirci gerekir.","Büyü",[],["Demacia"],"YAYGIN"],"01DE023":["Soruşturmacı Sihir Avcısı","Bu oyunda bedeli 6+ olan bir büyü oynadığında elinde bir Tutukla oluşur.","","''Kusura bakmayın, bölüyorum ama bizimle işbirliği yapmanız gerekiyor. Kulağımıza bazı 'olağandışı olaylar' yaşandığı geldi...''","Birim",[],["Demacia"],"YAYGIN"],"01DE051":["Korkusuz Cithria","Saldır: Saldıran diğer dost birimlere bu tur +1|+1 ve Korkunç verirsin.","","''Masallar, efsaneler benim için hikâye değil, beni çağıran gerçek birer serüvendi. Bulutçayır'dan kendi maceramı bulmaya çıktım, bir değil birçok macera buldum. Üstelik bunlar daha başlangıç.''\n","Birim",["SEÇKİN"],["Demacia"],"DESTANSI"],"01DE054":["Yılmaz Öncü İntikamcısı","Çağrıldığımda bu tur bir dost birim öldüyse bir birim çekersin.","","''Kaybettiklerimiz her savaş narasında, kılıçlarımızın her savruluşunda, kalkanlarımızın her çarpışmasında anılacak. Bugün, muzaffer olacağız!''","Birim",["SEÇKİN"],["Demacia"],"YAYGIN"],"01DE030":["Gümüşkanat Dalıcısı","","","Kalenin burçlarından bir ok yağmuru taşıyordu ama bir tanesi bile gökyüzünde hızla yön değiştiren o gümüşi noktaya değmiyordu. ","Birim",["KUŞ"],["Demacia"],"YAYGIN"],"01PZ040":["Jinx","","Elinin boş olduğunu gördüğümde.","''N'oldu kız Kılçık?''\n''Endişeliyim Jinx. Ne zaman sıkılsan...''\n''...bir şeyleri havaya uçurmak istiyorum! Sağ ol Kılçık, süper fikir!''","Birim",[],["Piltover ve Zaun"],"Şampiyon"],"01PZ008":["Teemo","Nexus Vuruşu: Rakibin destesindeki rasgele kartlara 5 adet Zehirli Pofkep Mantarı koyarsın.","Sen 15+ Zehirli Pofkep Mantarı koyduğunda.","''Bandle İzcisi Andı Madde 154: Bilinmezden asla korkma! Madde 276: Orman sakinleri dostumuzdur! Madde 354: Tüylü bir şeyse sevmekte sakınca olmayabilir ama sakın yeme! Madde 417...''","Birim",["YORDLE"],["Bandle Şehri","Piltover ve Zaun"],"Şampiyon"],"01PZ056":["Heimerdinger","Bir büyü oynadığında, elinde bedeli büyününkine denk, Geçici bir Taret oluşur. Bu taretin bedeli 0 olur.","Toplam Güç değeri 12+ olan dost Teknolojik birimler çağırdığını gördüğümde.","''Deli mucit mi? Pöh, ben bal gibi de 'biraz dağınık ve kendine has ama aklı son derece yerinde' bir mucidim! Terbiyesizlik.''","Birim",["YORDLE"],["Bandle Şehri","Piltover ve Zaun"],"Şampiyon"],"01PZ013":["Modifiyeli Mucit","Oyna: Elindeki tüm kartları atarsın. 3 kart çekersin. Bir düşmana 3 hasar verirsin.","","Hayallerinin peşinden koşarken ellerini kaybetti ama yılmadı. Onu hiçbir şey durduramazdı.","Birim",[],["Piltover ve Zaun"],"DESTANSI"],"01PZ007":["Elektrikli Gösteri Topu","Destekle: Destende, desteklenen dost birimin 4 kopyası oluşur.","","Topların gürlemesi, gösteriyi görmek için can atan kalabalıkları meydana çekti. Sonra haftalarca saçlarından konfeti ayıkladılar.","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ018":["Okulun Dâhisi","","","Nasıl mı nişan alıyor? Bak bu çok güzel bir soru.","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ019":["Hevesli Çırak","Çağrıldığımda 2 büyü manan dolar.","","Herkes Piltover'ın ilerlemesine hemen katkıda bulunamaz. Bazılarını biraz yönlendirmek gerekir, mesela icatlara yanlış gözle bakanları...","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ025":["Pofkep Mantarı Satıcısı","Bir büyü oynadığında, rakibin destesine 3 tane Zehirli Pofkep Mantarı koyarsın.","","''Bunlar nasıl?''\n''Birinci kalite! Hepsiyle bizzat konuşarak topladım.''\n''Tamam, sar o zaman... Ne dedin sen?''\n''Hıı! Bu evlenecekmiş mesela!''\n''Kaç tane yedin?''\n''Nişanlısı midyeymiş!''","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ048":["Corina Veraza","Oyna: Destenin en üstündeki 5 kartın Kökünü Kazırsın. Kökünü kazıdığın kartlar arasındaki her büyü için tüm düşmanlara ve rakibin Nexus'una 1 hasar verirsin.","","''Dar görüşlü Piltover'lıların kafası bir tek çarklara, metale basar. Bitkilerimin her sapındaki, yaprağındaki, hücresindeki sanatı anlayamazlar. Sonları hak ettikleri gibi zarafetsiz olacak.''","Birim",[],["Piltover ve Zaun"],"DESTANSI"],"01PZ028":["Anlık Çözüm","Oynandığında ya da atıldığında bir Hurda Yengeç çağırır.","","Genç mucidin sadece birkaç parça hurdası ve çok az zamanı kalmıştı. Sonra aklına çok farklı bir ilham kaynağı geldi: uzak bir ormanda, nehir kıyısında gördüğü yampiri yampiri yürüyen bir canlı.","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ050":["Büyü Gücü Yükselişi","Bir dost birime bu tur +4|+0 ve İlk Saldırı verirsin.","","''Işık yaymaya başladığında biraz da gıdıklıyor. Normaldir herhalde... değil mi?''\n- Ezreal","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ054":["Acemi İnfilakçı","Saldır: Rakibin Nexus'una 2 hasar verirsin.","","''Bir şey olmayacağından emin misin?''\n''Değilim.''\n''Eminim demen gerekirdi!''\n''Sormaman gerekirdi.''","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ030":["Şaibeli Tip","Oyna: Bir takipçi seçersin. Onun birebir kopyasına dönüşürüm.","","''Merhaba, ben de sizin gibi Kimya Baronuyum!''","Birim",["YORDLE"],["Piltover ve Zaun"],"ENDER"],"01PZ017":["Kullanılmış Fıçı Satıcısı","Çağrıldığımda 2 Asit Fıçısı çağırırsın.","","''Seni Ziel mi yolladı? Ben ona dedim, onda ne varsa onundur! Daha önce görmediğim bir şeyin parasını nasıl iade edeyim? Ama işe bak ki elime bir parti yeni fıçı geçti, onları vereyim isterse...''","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ038":["Kuyu Suyu Tarayıcı","Oyna: Bir kart atarsın, bir kart çekersin.","","Kuyu'da hiçbir şey harcanmaz.","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ036":["Ezreal","Nexus Vuruşu: Elinde Geçici bir Gizemli Atış oluşur.","Sen düşmanları 8+ kere hedeflediğinde.","''Gözlük? Tamam. Atkı? Tamam. Her işlevini tabii ki çok iyi anladığım büyülü eldiven? Tamam olmaz mı, o da tamam!''","Birim",[],["Piltover ve Zaun"],"Şampiyon"],"01PZ035":["Jae Medarda","Ben hedef alındığımda 1 kart çekersin.","","Piltover'lı saygın Medarda ailesinin servetinin vârisi olan Jae, aile işlerini yönetmektense define peşinde koşuyor. Bu da babasının tepesini feci attırıyor tabii.","Birim",[],["Piltover ve Zaun"],"DESTANSI"],"01PZ010":["Mantar Bulutu","Rakibin destesine 5 tane Zehirli Pofkep Mantarı koyarsın.","","Önce pofkep mantarının şapkası pof diye patlar. Sonra yakıcı, sakatlayıcı bir acı talihsiz kurbanı esir eder. Son olarak, uzaklardan bir kıkırdama duyulur.","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ045":["Zaun'lu Sokak Çocuğu","Oyna: Bir kart atarsın, bir kart çekersin.","","''Bu kuyu süprüntüleri birbirine hiç mi destek olmaz?''\n''Kendilerine acımaktan vakit bulamıyorlardır.''\n''Ne ayıp. Aaa... Cüzdanım nerede?''","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ002":["Leş Barın Sahibi","Çağrıldığımda, bu oyunda çağırdığın her Leş Barın Sahibi için elinde rasgele bir kart oluşur.","","''Aynen, Kuyu nasıl 'birazcık' kokuyorsa, bu da 'birazcık' çarpıyor işte. Kusacaksan kova şarkıcının orda.''","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ004":["İsabet Dalgası","Bir düşman birime ya da rakibin Nexus'una 3 hasar, bir diğerine 2 hasar, bir diğerine 1 hasar verirsin.","","''Yetenekliysen, şansa ihtiyacın olmaz.''\n- Ezreal","Büyü",[],["Piltover ve Zaun"],"DESTANSI"],"01PZ020":["Korkusuz Poro","","","İlk uçuşunu kazara yaptı. Yalanırken, yanlışlıkla bir Gelişim Günü topunun içine girdi. Artık Piltover'ın en sevilen simalarından. Kalabalığın hayranlık dolu bakışları arasında göklerde süzülüyor.","Birim",["PORO"],["Piltover ve Zaun"],"YAYGIN"],"01PZ046":["Sahte Kopyalar","Elinden bir kart seçersin. Destende bu kartın 4 adet birebir kopyası oluşur.","","Taklit hırsızlığın en övücü biçimi.","Büyü",[],["Piltover ve Zaun"],"ENDER"],"01PZ052":["Gizemli Atış","Herhangi bir şeye 2 hasar verirsin.","","''Hedefi asla ıskalamam. Ara sıra uyarı ateşi açtığım oluyor tabii...''\n- Ezreal","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ033":["Mükemmırrlık Peşinde","Bu oyunda 20 yeni kart oynadıysan Kediyamet çağırırsın.","","''Von Yipp'in projesinde çalışan herkes kandırılmış meğer. Ortaya çıkardığımız felaketten, nasıl korkunç bir gücü serbest bıraktığımızdan haberimiz yoktu.''\n- Piltover'lı proje mühendisi","Büyü",[],["Piltover ve Zaun"],"DESTANSI"],"01PZ005":["Hextech Dönüştürücü","Bir takipçiyi başka bir takipçinin birebir kopyasına dönüştürürsün.","","''KİLO VERMEK İSTİYORUM DEDİN.''\n''SEN DE BENİ YORDLE'A ÇEVİRDİN ÖYLE Mİ?''\n''AĞIRLIĞIN AZALDI İŞTE.''\n''YORDLE OLDUM BE!''","Büyü",[],["Piltover ve Zaun"],"ENDER"],"01PZ021":["Midenstokke'ların Adamları","Nexus Vuruşu: Birebir kopyamı çağırırsın.","","''Bay Berz, sizi bulduğumuzda kasanın İÇİNDE, üstünüz altın dişlilerle kaplanmış halde, kırık kapıyı tutarak uyuyordunuz.''\n''Ben değildim diyom yaa, benzetmişsinizdir.''\n''Kapı hâlâ elinizde.''\n''Kanıtlayın.''","Birim",[],["Piltover ve Zaun"],"ENDER"],"01PZ031":["Statikk Şok","Bir düşman birime ya da rakibin Nexus'una 1 hasar ve bir diğerine 1 hasar verirsin.\nBir kart çekersin.","","''Ark deşarjını işte böyle keşfettik. Halefim böyle bir olgunun varlığını elbette ortaya atmıştı ama ne kadar uzağa ulaşabileceğini hesaplamamış. Zavallıcık...''\n- Heimerdinger","Büyü",[],["Piltover ve Zaun"],"ENDER"],"01PZ059":["Altın Ezicibot","","","EZ. ÖLDÜR. YOK ET. TEKRAR ET.","Birim",["TEKNOLOJİK"],["Piltover ve Zaun"],"YAYGIN"],"01PZ001":["Ara Tara","Oynamak için 2 taneye kadar kart atarsın. Attığın her kart için 1 kart çekersin.","","''Abiii! BEŞ FEDAİYLE BİR DE GOLEM Mİ YOLLAMIŞLAR? Tamam tamam dur tam buna uyguuun... bi' şeyiiim... olacaktııııııııı...''\n- Jinx","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ057":["Yengeçler Buluşması","2 Hurda Yengeç çağırırsın.","","Bir zamanlar aşılmaz bir kara parçasının ayırdığı bu iki kendi halinde yaratık, sonunda Kuyu'nun ılık sularında bir araya geldi.","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ027":["Termojenik Işın","Oynamak için tüm mananı harcarsın. Bir birime bu kadar hasar verirsin.","","''Hem zamanımız hem paramız tükendi. Işın ise çalışıyor çalışmasına da enerji tüketimini düzene sokamadık.''\n- Zaun'lu deneyci","Büyü",[],["Piltover ve Zaun"],"ENDER"],"01PZ055":["Akıllı Akademisyen","Sen bir kart çektiğinde bu tur +1|+0 alırım.","","Bütün büyük icatların ilk kıvılcımını hayal gücü çaktırır. Ama kıvılcımı yangına dönüştüren araştırmadır.","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ014":["Lisanssız İcat","Bir Yasadışı İcat çağırırsın.","","''Yaşadıkları tersliklerin haddi hesabı yok: patlamaların sarsıntıları, çatlaklardan yükselen leş kokulu dumanlar. Bu salaklardan biri bir gün şehri yıkacak.''\n- Piltover'lı hayırsever","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ034":["Toplayıcı Kuyu Çocuğu","Sadakat: Elinde bir Kuyu Haritası oluşur. Bu tur bedeli 0 olur.","","Zaun'lu çocuklar hemen eski madencilik tünellerini ve Yollar'ın daha derin seviyelerini keşfetmeye başladı. Karşılarına inanılmaz bir dünya ve çok ilginç arkadaşlar çıktı.\n","Birim",[],["Piltover ve Zaun"],"ENDER"],"01PZ003":["Montaj Robotu","Sen bir büyü oynadığında +1|+1 kazanırım.","","''Ahmağın teki bile makine yapabilir. Ama mekanik bir zihne GERÇEK gelişim eklemek için büyük beceri gerekir. O bürokratlar akılları başlarına gelince ayaklarıma kapanacak...'' - Klas Henwick","Birim",[],["Piltover ve Zaun"],"ENDER"],"01PZ044":["Zaun'lu Gitarist","Oyna: Tüm düşmanlara 1 hasar verirsin.","","''...solosu armonik minör gama indikten sonra arpejlenerek (evet böyle bir kelime var) ara kıtaya transpoze oluyor. Neyse, dinleseniz bile anlayamazsınız zaten.''\n- Max Bliff, Kuyusözlük yazarı","Birim",[],["Piltover ve Zaun"],"ENDER"],"01PZ029":["Saygın Hayırsever","Oyna: Bölgelerine ait bir destansı kart Cisimlendirirsin.","","''O zamanlar öfkeli bir adamdım. Paraya ve şöhrete, rakiplerimi mahvederek kavuştum. Şimdi servetimi hayır işlerine harcıyorum. Umarım yaşlılığımın pişmanlığı, kötülüklerimi affettirir.''","Birim",[],["Piltover ve Zaun"],"ENDER"],"01PZ051":["Maytapçı","Tüm büyülerin ve yeteneklerin fazladan 1 hasar verir.","","''Patladı mı tam patlasın istiyorsun demek. Doğru yere geldin o zaman!''","Birim",[],["Piltover ve Zaun"],"ENDER"],"01PZ023":["Profesör von Yipp","Bedeli 1 olan bir dost birimi çağırdığında ona +2|+2 kazandırırsın.","","''Bugün komiteye en yeni icadımı tanıtacağım. Saygıdeğer meslektaşımın gösterdiği üzere...''","Birim",["KEDİ"],["Piltover ve Zaun"],"ENDER"],"01PZ024":["Dengesiz Elektrik Mühendisi","Bu oyunda bedeli 6+ olan bir büyü oynadığında +4|+0 ve İlk Saldırı kazanırım.","","İsim: Klas Henwick, Yaş: 51, Lisans Türü: Sınıf 2 Koşullu, Lisans Durumu: İptal Edildi, Yorum: Lab. patlaması sonrası üretimi azaltma uyarılarına kulak asmadı (DOS. 13X764NM). GİRMESİ YASAK.","Birim",[],["Piltover ve Zaun"],"ENDER"],"01PZ049":["Gelişim Günü!","3 kart çekersin. Çektiğin kartların bedeli 1 azalır.","","GELİŞİM GÜNÜ!\nKutlamalar GÜNEŞ KAPISI MEYDANI'nda!\nHEXTECH HARİKALARINI görün!\nKORKUSUZ PORO'yu hayretle seyredin!\nGELECEĞİN İNSANI, GÜNÜMÜZÜ anlatıyor!\nGiriş ÜCRETSİZ! \nPiltover'lı çocuklar davetlimiz!","Büyü",[],["Piltover ve Zaun"],"DESTANSI"],"01PZ006":["Meydan Muhafızı","Bu oyunda oynadığın her büyü için bedelim 1 azalır.","","İtaat etmek için 20 saniyen var.","Birim",[],["Piltover ve Zaun"],"ENDER"],"01PZ053":["Gömpeç Öbeği","Çağrıldığımda elinde bir Mantar Bulutu oluşur.","","''Bak yeminle! Öbek olup sinsi sinsi geziyorlar. Deli gibi görünüyorlar ama kimse anlamıyor! Ama ben anladım! Büyük planları var! Planları! Pofkep mantarı. Peynir... şerbeti. Ne diyordum?''\n- Pofkep Mantarı Satıcısı","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ012":["Alevli Patlangaç!","Atıldığımda beni tekrar çağırırsın.","","''PATLANGAÇ, TUT!''\n- Jinx","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ039":["Ay Çok Heyecanlı!","Oynamak için 1 kart atarsın. Herhangi bir şeye 3 hasar verirsin.","","''SAVULUUUN! Yok yok, SAVULMAYIIIIN!''\n- Jinx","Büyü",[],["Piltover ve Zaun"],"ENDER"],"01PZ016":["Ani İlham","Elinde bölgelerine ait, bedeli 6+ olan rasgele bir büyü oluşur.\nBüyü manan dolar.","","Bir imparatorluk kurmak için bir anlık aydınlanma yeter.","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ058":["İri Kıyım Gömpeç","Çağrıldığımda elinde 2 Mantar Bulutu oluşur.","","''Koc-caman bir tane gördüm! At kadar büyüktü! Kayacıl kadar kurnazdı! Bak o gömpeç başımıza iş açacak ha. Boşuna öbeğin kraliçesi olmamış!''\n- Pofkep Mantarı Satıcısı","Birim",["YORDLE"],["Piltover ve Zaun"],"ENDER"],"01PZ009":["Amatör Uçman","","","''Kişiye özel uçan makineler boş hayalden başka bir şey değil. Hatta çırağımı son yaptığım prototipi çöpe atmaya yolladım. Sahi, nerede o?''\n- Piltover'lı mühendis","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ042":["Gözüpek Denizci","Destekle: Desteklediğim dost birim bu tur Sıyrılgan alır.","","Piltover'lılar bilinmeyeni Gelişim Şehri'nde güven içinde araştırma ve icat yaparak keşfetme taraftarı. Ama bir avuç maceracı çok daha büyük bir bilinmezliği, yani dünyayı keşfetmek için yola düşüyor.","Birim",[],["Piltover ve Zaun"],"ENDER"],"01PZ026":["Kuyu Haritası","Bir dost birime Sıyrılgan kazandırırsın.","","''Piltoşlar her şeyi bildiklerini sanır ama haritaları sadece bizim onlara anlattığımız yerleri gösterir. Bilgiyi yerlilerden alacaksın. Parası neyse de vereceksin.''\n- Kuyu Çocuğu Ajuna Lem","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"01PZ043":["Zaun'lu Yankesici","Nexus Vuruşu: Elinde, rakibin destesindeki rasgele bir büyünün birebir kopyası oluşur.","","Gelişim Şehri'nin alt katlarına atılanların, birbirinin işini bitireceği umuluyordu. Ama onlar birlik oldu ve kendilerine yeni bir yurt kurdular: Zaun. Çok güzel olmayabilirdi ama evleriydi.","Birim",[],["Piltover ve Zaun"],"ENDER"],"01PZ047":["Asit Fıçısı","Son Nefes: HER BİR Nexus'a 1 hasar verirsin.","","''Üstüne tulum giy derdim emme aşağısı gömpeç yuvası gibi nem içinde ya. Hee, eldiven tak ama. Yannız dikkat et balçık üstüne sıçramasın, sıçrarsa da mühüm bi' şeyine gelmesin.''\n- Zaun'lu ustabaşı Ziel","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"01FR024":["Anivia","Saldır: Tüm düşmanlara ve rakibin Nexus'una 1 hasar verirsin.\nSon Nefes: Yumurtanivia haline dönüşerek dirilirim.","Aydınlandığında.","''Beni bu topraklar var etti, onları korumak da bana düşer. Nöbetimi ne zaman ne savaşlar ne de ölümün kendisi sona erdirebilir.''","Birim",["KUŞ"],["Freljord"],"Şampiyon"],"01FR039":["Tryndamere","","Ölecek kadar hasar alırsam, ölmek yerine Seviye Atlarım.","''Amacın uğruna canını verme, yaşa.''","Birim",[],["Freljord"],"Şampiyon"],"01FR006":["Buzdoğanların Mirası","Bir dost birime ve onun her yerdeki dost kopyalarına +2|+2 kazandırırsın.","","''Biz bir avuç Buzdoğan'ın kanına Freljord'un sihri karışmış. Atalarımız kadim bir kötülüğü mühürleyip hapsetmiş. Şimdi biz bir avuç Buzdoğan o dönmesin diye nöbetteyiz.''\n- Muhafız Gregor","Büyü",[],["Freljord"],"YAYGIN"],"01FR022":["Kehanet Şahini","Çağrıldığımda destenin en üstündeki 2 dost birim +1|+1 kazanır.","","''Yağmacılarımız üç kere Avarosaların kapılarına dayandılar, üçünde de atışa hazır yaylarla karşılandılar. Saldırılarımızdan nasıl bir hileyle haberdar oluyorlar?''\n- Gazi Soylu Steffen","Birim",["KUŞ"],["Freljord"],"YAYGIN"],"01FR042":["Donduran Rüzgârlar","2 düşmana Buz Tutturursun.","","''Kendi topraklarımda bana meydan mı okuyorsun? Hazırlıksızsın, küçüğüm.''\n- Anivia","Büyü",["ELEMENTAL"],["Freljord"],"ENDER"],"01FR009":["Braum","İlk kez hasar alıp sağ kaldığımda bir Kudretli Poro çağırırsın.","Toplam 10+ hasar alıp sağ kaldığımda.","''Baba, Braum'la kapısının masalını anlat!''\n''Ya da düşüp dağı ikiye yarmasını anlat!''\n''Aa, hanı gözü dönmüş yetiden kurtarmasının hikâyesini anlat asıl!''","Birim",[],["Freljord"],"Şampiyon"],"01FR018":["Buz Dişli Kurt","Vuruş: Güç değeri 0 olan bir birime vurursam onu öldürürsün.","","Kuzeyin yırtıcıları, en kolay avın kışın ısırıcı soğuğuyla sakatlanmış av olduğunu çok iyi bilir.","Birim",["KÖPEK"],["Freljord"],"ENDER"],"01FR036":["Avarosa Okçusu","Oyna: Bir düşmana 1 hasar verirsin.","","Freljord'da ya avlanırsın ya da açlıktan ölürsün.","Birim",[],["Freljord"],"YAYGIN"],"01FR045":["Gazi Soylu Steffen","Hasar alıp sağ kalırsam +3|+0 kazanırım.","","''Kışın Pençesi'ne olan andımı Sejuani'nin vücudumda açtığı ilk yarayla mühürledim. Ondan sonraki her yara izimi onun hizmetinde aldım.''","Birim",[],["Freljord"],"YAYGIN"],"01FR008":["Yalnız Poro","Çağrıldığımda elinde bedeli 1 olan rasgele bir Poro daha oluşur.","","''Ömrüm Freljord'da geçti, yine bu ufaklığın halinden daha yürek dondurucu bir şey görmedim.''\n- Poro Çobanı","Birim",["PORO"],["Freljord"],"YAYGIN"],"01FR055":["Parçala","Bir düşmanın Güç değeri 0 ise ona 4 hasar verirsin. Değilse Buz Tutturursun.","","''Kış bu topraklara ayak basınca güçlüleri küçük düşürür, zayıfları ise alır götürür.''\n- Gazi Soylu Steffen","Büyü",["ELEMENTAL"],["Freljord"],"YAYGIN"],"01FR038":["Ashe","Saldır: En Güçlü düşmana Buz Tutturursun.","5+ düşmanın Güç değerini 0'a düşürdüğünde. Seviye atladığımda destenin en üstünde bir Kristal Ok oluşur.","''Yurduma baktığımda sadece şimdiki halini değil, nasıl olabileceğini de görebiliyorum. Sadece benim halkıma değil, barış isteyen herkese açık, bereketli bir yer olabilir birleşmiş Freljord.''","Birim",[],["Freljord"],"Şampiyon"],"01FR029":["Yardıma Koş","Bir şampiyon çekersin.","","''Yağmacılar yaklaşıyor! Alarm verin, ateşleri yakın! Çağırabileceğimiz bütün yardımı çağırmalıyız!''\n- Avarosa Gözcüsü","Büyü",[],["Freljord"],"ENDER"],"01FR035":["Çömez Yağmacı","Hasar alıp sağ kalırsam +3|+0 kazanırım.","","''Avarosalar bebelerini zayıf, savaşa hazırlıksız, ihtiyarlayarak ölsünler diye yetiştiriyor. Bizimkilerse savaş ateşlerinin içine doğuyor.''\n- Pençe Anası Vrynna","Birim",[],["Freljord"],"YAYGIN"],"01FR020":["Çığ","TÜM birimlere 2 hasar verirsin.","","Her çığ, yerinde durmayı reddeden bir çakıltaşıyla başlar.","Büyü",["ELEMENTAL"],["Freljord"],"ENDER"],"01FR014":["Yavru Yeti","Son Nefes: Destende 2 Hiddetli Yeti oluşur.","","''O kadar minik ve şirindi ki! Büyüyüp... işte... yeti olacağına inanmak çok zordu.''\n- Avarosa Avcı","Birim",["YETİ"],["Freljord"],"YAYGIN"],"01FR049":["Sinsi Kurt","Çağrıldığımda, rakibin bir Kar Tavşanı çağırır.","","''Tavşandan kurt olmaz.''\n- Kışın Pençesi atasözü","Birim",["KÖPEK"],["Freljord"],"YAYGIN"],"01FR037":["Avarosa Binicileri","Sadakat: Destenin en üstündeki dost birime +3|+3 ve Aban kazandırırsın.","","Destek birlikleri bayırı tırmanırken Biniciler başlarını eğerek savaş anasını selamladılar. Çünkü Avarosa'nın ete kemiğe bürünmüş hali olan kraliçeleri Ashe onlara barış umudu getiriyordu.","Birim",[],["Freljord"],"ENDER"],"01FR026":["Lider Yabanpençe","","","Savaş atı kadar güçlü, kedi kadar huysuz.","Birim",["KEDİ"],["Freljord"],"YAYGIN"],"01FR030":["Silah Kıran","Can değeri 3 veya daha az olan bir düşmana Buz Tutturursun.","","''Soğuk mu? Güleyim bari! Umarım yürekleriniz, o yazlık çelikten silahlarınızdan daha sağlamdır!''\n- Braum","Büyü",["ELEMENTAL"],["Freljord"],"YAYGIN"],"01FR013":["Pençe Anası Vrynna","Hasar alıp sağ kalırsam +3|+0 kazanırım.","","''Ashe'in döküntüleriyle aynı ateşin başına oturacağıma soğuktan titreye titreye ölürüm. Ama istedikleri ısınmaksa fazlasıyla ısınacaklar.''","Birim",[],["Freljord"],"DESTANSI"],"01FR019":["Kışın Soluğu","Güç değeri 0 olan tüm düşmanları öldürürsün, sonra tüm düşman birimlere Buz Tutturursun.","","Freljord'u işgal edenlerin karşısına çıkan ilk ve son düşman Kış Ana'dır. Onun yeminlileri, merhametsiz rüzgâr ve yakıcı soğuktur.","Büyü",["ELEMENTAL"],["Freljord"],"DESTANSI"],"01FR041":["Avarosa Köy Muhafızı ","Çağrıldığımda destendeki dost birimlere +1|+1 kazandırırsın.","","''Tek bayrak altında birçok kabile! Belki bir gün bütün Freljord omuz omuza savaşır.''","Birim",[],["Freljord"],"DESTANSI"],"01FR025":["Poro Çobanı","Çağrıldığımda bir Poroya Tanıklık ettiysen bir Poro çekersin.","","Sürüye iki şey gerekir: Sevgi ve birlikte olmak. Gerisi fasa fisodur.\n","Birim",[],["Freljord"],"ENDER"],"01FR054":["Gazi Yağmacı","","","''Zayıflar biriktirir, güçlüler alır. Küçük Avarosalar hangisi olduklarını öğrenecekler!''","Birim",[],["Freljord"],"ENDER"],"01FR021":["Kabilesiz Tarkaz","Saldır: Savaşan TÜM birimlere 1 hasar verirsin.","","''Tarkaz çoğu kişiden daha yiğitçe ve iyi savaştı. Yenilgiyi de iyi karşıladı bence... Yani karşıladı sayılır.''\n- Tryndamere","Birim",[],["Freljord"],"DESTANSI"],"01FR043":["Yumağın Kalbi","Oyna: Poro takipçilerini bir araya getirip Poro Yumağı kartına dönüştürürsün ve onların niteliklerini ve faydalı tesirlerini kazandırırsın.","","''Tamam, bir tane daha anlatacağım ama sus yoksa annem duyar!''\n''Bir zamanlar, Avarosa'nın köyüne akıncılar saldırmış. Çok az askeri varmış. Tam yenilecekken bir poro gelip ona yardım etmeyi önermiş...''","Birim",["PORO"],["Freljord"],"ENDER"],"01FR033":["Kader Taşları","Tur Başı: Bu tur fazladan bir mana taşı alırsın.","","''Bu kadim höyükler bize, bu vahşi topraklara göğüs germiş sayısız kavim arasında sadece en yenisi olduğumuzu hatırlatsın.''\n- Ashe","Birim",[],["Freljord"],"YAYGIN"],"01FR011":["Donukvadi Okçusu","Oyna: Bir düşmana Buz Tutturursun.","","Avarosalar mevsimleri sert geçen, karlı topraklarıyla gurur duyar. Keskin gözlü savaşçıları bu gururu bir adım daha ileri taşır. ","Birim",[],["Freljord"],"YAYGIN"],"01FR050":["Babacan Hancı","Oyna: Bir dost birimi ya da Nexus'unu 3 iyileştirirsin.","","''Güzel mekân değil mi? Adı Sarhoş Baykuş! Kemiklerini ısıtacak çeşit çeşit yiyeceğimiz, içeceğimiz var. Gir gir, donacaksın!''","Birim",[],["Freljord"],"YAYGIN"],"01FR052":["Gezen Kadın","Oyna: Oyunda ve ellerde bulunan, Güç değeri 4 ya da daha az olan TÜM birimlerin Kökünü Kazırsın.","","''Molozların arasından çıktığımda, etrafımdaki topraklarda bir yanık yarasının izini gördüm. Yoldaşlarımdan geriye külleri kalmıştı. Ürkütücü bir figür ufka doğru uzaklaşıyordu...''\n- Gezgin Bjerg","Birim",[],["Freljord"],"DESTANSI"],"01FR016":["Poro Kurabiyesi","Her yerdeki dost Porolara +1|+1 kazandırırsın.","","''Hapır hupur yerler, sonra biraz daha ver diye dilleri bir karış dışarıda, baharda kırkılmış elnükler gibi sevinçle sana bakarlar. Hayır diyebiliyorsan de!''\n- Avarosa kurabiyeci","Büyü",[],["Freljord"],"YAYGIN"],"01FR005":["Savaş Gazabı","Bir dost birime +8|+4 kazandırırsın.","","''Biraz... öfkeliymişim diyorlar.''\n- Tryndamere","Büyü",[],["Freljord"],"ENDER"],"01FR023":["Savaş Anasının Çağrısı","Destenin en üstündeki dost birimi hem şimdi hem de HER Tur Başında çağırırsın.","","Bir gün Freljord'da başka hiçbir şeye benzemeyen bir çağrı duyulacak. O gün herkes bu çağrıya yanıt verecek çünkü kadim düşmanlarımızın gelişini haber veriyor olacak.","Büyü",[],["Freljord"],"DESTANSI"],"01FR047":["Yabanıl Şaman","Aydınlanmış: +4|+4 alırım.","","''Hayvan gibi kükremeyi öğrenen, çok geçmeden ana dilini unutur.''\n- Anivia","Birim",[],["Freljord"],"YAYGIN"],"01FR056":["Ayaz Yeti","Çağrıldığımda, Can değeri 3 veya daha az olan düşmanlara Buz Tutturursun.","","''AaaaaaaAAaaaAaaaaah!''\n- Gezgin Bjerg","Birim",["YETİ"],["Freljord"],"ENDER"],"01FR027":["Erkek Elnük","","","Avarosa masallarında, hayatta tek istediği güneşli bir çayır ve çekişe çekişe tartışmak olan ''Elnük Amca'' adlı inatçı bir ihtiyardan bahsedilir.","Birim",["ELNÜK"],["Freljord"],"YAYGIN"],"01FR057":["Sürü Psikolojisi","Dost birimlere bu tur +2|+2 ve Aban verirsin.","","Gecenin sessizliğinde bir uluma yankılandı. Sonra bir daha, bir daha. Dakika geçmeden sürü bir ağızdan ulumaya başlamıştı. Gözü dönmüş seslerle kan istiyorlardı.","Büyü",[],["Freljord"],"ENDER"],"01FR004":["Sağlamlık Karışımı","Bir dost birime bu tur +0|+2 verirsin.","","''Hava berbat ha? Hiç merak etme, Baykuş'da öyle bir içki yapıyoruz ki yeni doğan bebeğin göğsünde kıl bitirir. İliklerine kadar ısınırsın şimdi.''\n- Babacan Hancı","Büyü",[],["Freljord"],"YAYGIN"],"01FR048":["Avarosa Tuzakçısı","Çağrıldığımda, destenin en üstündeki 3 kart arasında bir Hiddetli Yeti oluşur.","","''Bütün hafta hiçbir şey tutamadım! Ya hayvanlar akıllandı ya da bir şey onları korkutup kaçırdı...''","Birim",[],["Freljord"],"YAYGIN"],"01FR017":["Elnük Sürüsü","Oyna: Destenin en üstündeki 6 kart arasındaki tüm elnükleri çağırırsın. Kalanları destene geri koyarsın.","","''Avarosalar elnük gibidir. Savaş görmemişlerin bile kolayca devirdiği bön bakışlı ot yiyicilerdir. Sadece kalabalık olduklarından hayatta kalırlar.''\n- Pençe Anası Vrynna","Birim",["ELNÜK"],["Freljord"],"YAYGIN"],"01FR046":["Yüreklendirme","Hasar almış bir dost birime +3|+3 kazandırırsın.","","''...Braum'un yaraları çok derinmiş ama o başını geriye atıp kahkahalarla gülmüş. Çünkü biliyormuş ki ancak zor zamanlarda kahraman olunurmuş!''\n- Braum'un Hikâyesi","Büyü",[],["Freljord"],"ENDER"],"01FR012":["Antik Dönüştürücü","Boş bir mana taşı kazanırsın ve Nexus'un 3 iyileşir.","","Efsanevi bir iyileştirme gücüne sahip, pırıl pırıl bir mücevher olan çağlar taşının parlaklığıyla ne yakut ne de safir yarışabilir.","Büyü",[],["Freljord"],"YAYGIN"],"01FR040":["Buzdiş Şamanı","Tur Başı: En Güçlü düşmana Buz Tutturursun.","","''Vahşi doğayla bir olmak için soğuktan saklanmamak, kendimizi o vahşiliğe kaptırmak gerek.''","Birim",[],["Freljord"],"ENDER"],"01FR031":["Kadim Yeti","Tur Sonu: Bedelim 1 azalır.","","''O ses de neydi? Hapşırık sesi gibiydi. Buz dağları... hapşırır mı?''\n- Gezgin Bjerg","Birim",["YETİ"],["Freljord"],"ENDER"],"01FR053":["Kudretli Poro","","","''Bizim Uzunboynuz'un gözü, Poro Kralı'nı niyeti bozuk bir yabanpençeden korurken ziyan olmuş. Neticede mühim olan yumruğunun değil yüreğinin sağlamlığı.''\n- Poro Çobanı","Birim",["PORO"],["Freljord"],"YAYGIN"],"01FR010":["Yeminli Andı","2 dost birime +0|+3 kazandırırsın.","","''Kalbinin ocağında ateş, savaşta sana kalkan olacağım. Bizi ve soyumuzu korumak için kolum güçlü olsun, yaşamımız bu andı mühürleyen kanlarımız gibi hep birlikte aksın.''\n- Tryndamere","Büyü",[],["Freljord"],"ENDER"],"01FR001":["Ani Donduruş","Bir düşmana Buz Tutturursun.","","Soğuk uyarmaksızın bastırır ve en güçlü savaşçıyı bile çaresiz bırakır.","Büyü",["ELEMENTAL"],["Freljord"],"ENDER"],"01FR032":["Yıldızgöz Kâhin","Bir büyü oynadığında, destenin en üstündeki dost birim +1|+1 kazanır.","","''Onlara yaklaşan rüzgârı duymaları için keskin kulaklar, yağacak karda koşmaları için çevik ayaklar ve kışın perdesinin ötesini görmeleri için keskin gözler ihsan et.''","Birim",[],["Freljord"],"ENDER"],"01FR051":["Yeti Masalı","Tahtanda bir Yeti varsa Hiddetli Yeti çağırırsın. Yoksa çağırmazsın, destenin en üstünde oluşturursun.","","''...Onun da kocamaan bir ağzı, böyle sivri sivri dişleri, kaya gibi yumrukları, hüd-det-li bakan gözleri varmış ve KÜKREYİNCE AĞAÇLAR SALLANMIŞ! Bjerg amca söyledi.'' - Küçük Ingvar","Büyü",[],["Freljord"],"YAYGIN"],"01FR034":["Sebatkârlar","Çağrıldığımda, ölmüş olan her dost birim için +1|+1 kazanırım.","","''Aaah ah, bu ihtiyar Bjerg neler çekti... En kuzeyde yoldaşlarını kaybetti, aylar sonra saçma sapan sayıklayarak döndü. Şimdi varsa yoksa dev canavarlarmış, koca pençelermiş... Yazık.''\n- Babacan Hancı","Birim",[],["Freljord"],"ENDER"],"01FR007":["Ödü Kopmuş Bjerg","Çağrıldığımda Güç değeri 5+ olan bir birim çekersin.","","''B-bakın ne diyorum size, dev gibi bir şeydi diyorum, DEEEV!''","Birim",[],["Freljord"],"YAYGIN"],"01FR003":["Avarosa Gözcüsü","Son Nefes: 1 kart çekersin.","","''Gençliğimde kendime uzak savaş meydanlarında yer aradım. Meğerse yerim memleketimmiş, kendi soyumun yanıymış. Artık gözlerimi, onları korumak için kullanıyorum.''","Birim",[],["Freljord"],"YAYGIN"],"01SI038":["Şakacı Hortlak","Başka bir dost birim öldüğünde rakibin Nexus'una 1 hasar verirsin.","","Yaptığı en büyük kötülük küçük bir kızın çığlıklarına koşan askerleri öldürmek değil, hayatta kalanları kendi kızlarının yardım isteklerine kulak tıkadıklarından kuşkulandırmaktı.","Birim",[],["Gölge Adalar"],"ENDER"],"01SI049":["Öte Dünyaya Bakış","Bir dost birimi öldürerek 2 kart çekersin.","","''Hataya düştüm. Bu beyaz kefenin ardına bakmamamız gerekirmiş meğer. Gizlediği bilgiler her neyse bedeli ödenemeyecek kadar büyük.''\n- Yılmaz Öncü Müfettişi Arie Wrence","Büyü",[],["Gölge Adalar"],"YAYGIN"],"01SI053":["Elise","Saldır: Saldıran bir Yavru Örümcek çağırırsın.","Tur Başı: 3+ Örümcek'in daha varsa.","Bir zamanlar Noxus'un güçlü bir ailesinin lideri olan Elise'in Gölge Adalar'la olan bağlantısı ona doğadışı bir gençlik ve güzellik sağlıyor. Tek bedeli, kurban olarak sunulacak birkaç talihsiz ruh!","Birim",["ÖRÜMCEK"],["Gölge Adalar"],"Şampiyon"],"01SI057":["Kadim Krokolit","Beni oynamak için 2 dost birimi öldürürsün.","","''Koy kafese, pam pam pam... \nEsir oldu hepsi, bırakmam...\nKoyarım kafese, hiç çıkarmam! Yoksa...\nİstediğimde hiç bulamam...''","Birim",["SÜRÜNGEN"],["Gölge Adalar"],"ENDER"],"01SI023":["Ruhların Çobanı","Hayali bir dost birim çağırdığında ona +1|+1 kazandırırsın.","","Yolunda yalnız olmadığını bir tek ölüler bilirdi. Öte dünyaya giden yolda rehberlik ettiği sayısız yoldaşı bir onlar görürdü.","Birim",[],["Gölge Adalar"],"YAYGIN"],"01SI010":["Gölgelerin Hücumu","2 Hayalet Süvari çağırırsın.","","Son anlarına kadar sadakatle yaşadılar, sadakatle öldüler.","Büyü",[],["Gölge Adalar"],"YAYGIN"],"01SI042":["Hecarim","Saldır: Saldıran 2 Hayalet Süvari çağırırsın.","Sen 7+ Hayali dost birimle saldırdığında.","Duyduğun gök gürültüsü değil, Savaşın Gölgesi'nin toynak sesleri.","Birim",[],["Gölge Adalar"],"Şampiyon"],"01SI027":["Taze Kurbanlar","Bu tur 3+ dost birim öldüyse Zehirçene çağırırsın.","","''Zehir dişli ilahının önünde diz çök. Hatta daha iyisi, önünde can ver.''\n- Elise","Büyü",[],["Gölge Adalar"],"ENDER"],"01SI048":["Lanetli Bekçi","Son Nefes: Bir Kaçak Ucube çağırırsın.","","Delilik ve zaman çok kötü bir ikilidir.","Birim",[],["Gölge Adalar"],"YAYGIN"],"01SI018":["Dert Kâtibi","Çağrıldığımda elinde bu oyunda ölen bir dost birimin kopyası oluşur.","","''...Fakat yazarımız Affet'in... Aafet'in... Yok ya, öyle değildi... Öff, yine mürekkep döküldü! Fakat yazarımız... Aman be!''","Birim",[],["Gölge Adalar"],"YAYGIN"],"01SI030":["Kalista","","3+ dost birimin öldüğünü gördüğümde.","Yaşarken bir generaldi, bir kahramandı, masumların koruyucusuydu. Ama canı bedeninden ayrılınca geride sadece alacağı öcün ateşi kaldı ve ölemeyen bir intikam ruhuna dönüştü.","Birim",[],["Gölge Adalar"],"Şampiyon"],"01SI035":["Katliamcı Rhasa","Oyna: Bu tur bir dost birim öldüyse, En Güçsüz 2 düşmanı öldürürsün.","","''Bize... efsanelere geçecek bir yolculuk olacak dediler... Demacia'yı... koruyacaktık... Büyük umutlarla açıldık... Ama bütün o... canlar... boşuna verildi...''\n- Demacia'lı asker Arie Wrence","Birim",[],["Gölge Adalar"],"DESTANSI"],"01SI005":["Gûlyengeç","Bu oyunda ölmüş olan her dost birim için bedelim 1 azalır.","","Artık çoktan unutulmuş bir krallıkta yük hayvanı olarak kullanılan bu canavar, şimdilerde eski savaş meydanlarında gezinip kabuğuna metal parçaları, ruhuna ölü ruhlar katıyor.","Birim",[],["Gölge Adalar"],"ENDER"],"01SI037":["Uğursuz Poro","","","Çok daha kötü ölümler var sonuçta.","Birim",["PORO"],["Gölge Adalar"],"YAYGIN"],"01SI052":["Thresh","","6+ birimin öldüğünü gördüğümde.","''Şangır şungur, zincirler sürünüyor, Gardiyan geliyor,\nŞangır şungur, saklanmak boş, yerini çok iyi biliyor...''","Birim",[],["Gölge Adalar"],"Şampiyon"],"01SI033":["Komutan Ledros","Oyna: Rakibin Nexus'una, onun canının yarısı kadar hasar verirsin. Sayı üste yuvarlanır.\nSon Nefes: Eline geri dönerim.","","Geçen yıllar hatıraları eritip tükettikçe çoğu hayalet kimliğini unuttu gitti. Ama çektiği azap, Ledros'u geçmişe zincirledi. Bazı şeylere zaman bile ilaç olamaz.","Birim",[],["Gölge Adalar"],"DESTANSI"],"01SI003":["Harrowing","Bu oyunda ölmüş olan dost birimlerden En Güçlü 6 tanesini diriltirsin ve onlara Hayali tesiri kazandırırsın.","","Kimi geceler, dalga dalga kabaran aç ruhlar Kara Sis'le birlikte yayılır. Sis onları denizin öte yakasına taşır. Yaşayanlarla beslenir, aldıkları canlarla büyüyen karanlığı koyulaştırırlar.","Büyü",[],["Gölge Adalar"],"DESTANSI"],"01SI041":["Ölemeyenler","Son Nefes: Bir sonraki Tur Başında dirilirim ve öldüğüm her sefer için +1|+1 kazanırım.","","İhtiyar şehit, silah arkadaşlarını ölüme götürüşünü hatırladı. Ama nedenini unutalı yıllar olmuştu...","Birim",[],["Gölge Adalar"],"DESTANSI"],"01SI045":["Ruh Em","Bir dost birime 4 Sömürü hasarı verirsin.","","''Seni öldüren beni güçlendirir.''\n- Thresh","Büyü",[],["Gölge Adalar"],"YAYGIN"],"01SI036":["Gezinen Bacaklar","Bu tur bir dost birim öldüyse 2 Yavru Örümcek çağırırsın.","","Koluna bir şey sürünmüş gibi hissediyorsun ya? Bir de o sürünen şey derinin altında geziniyormuş gibi hissettiğini düşün.","Büyü",[],["Gölge Adalar"],"YAYGIN"],"01SI051":["Harcanmış Dâhi","Başka bir dost birim öldüğünde ya da Son Nefes: Büyü manan dolar.","","Bestesini kusursuz hale getirmek için gece gündüz çalışıyordu. Sonra bir anda içinden karanlık bir sessizlik esip geçti. Herkes çığlık çığlığa canını kurtarmaya çalışırken o hiçbir şey fark etmedi.","Birim",[],["Gölge Adalar"],"ENDER"],"01SI012":["Dalgın Balıkçı","Oyna: Elindeki bir dost birime Hayali tesiri kazandırırsın ve bedelini 1 azaltırsın.","","Yazık oldu adamcağıza...","Birim",[],["Gölge Adalar"],"YAYGIN"],"01SI031":["Demir Haberci","Saldır: Sahip olduğun her Hayali dost birim için +1|+0 kazanırım.","","Yaşarken olduğu gibi ölümden sonra da sapkın, kötücül emirler veriyor ve Hecarim'in sadık şövalyeleri ölümden sonra da yaşarken yaptıkları gibi emre uyup katliama gidiyor.","Birim",[],["Gölge Adalar"],"ENDER"],"01SI034":["Kara Kargı","Bu tur bir dost birim öldüyse bir birime 4 hasar verirsin.","","''Mızrağımız mazlumlara ağlıyor!''\n- Kalista","Büyü",[],["Gölge Adalar"],"YAYGIN"],"01SI043":["Bahtsız Soylu","Son Nefes: Bir Yavru Örümcek çağırırsın.","","''Le-leydi Elise? Neredesiniz?''","Birim",[],["Gölge Adalar"],"YAYGIN"],"01SI009":["Çakırkeyif Ruhlar","Destekle: Desteklediğim dost birim +2|+0 ve Hayali tesiri kazanır.","","Kimileri Afet'in sonuçlarına bakıp yol açtığı yıkımı ve sefaleti görüyor, kimi de şişesindeki balığı.","Birim",[],["Gölge Adalar"],"YAYGIN"],"01SI007":["Hayaletli Madalyon","3 Serbest Kalmış Ruh çağırırsın.","","Bu antik, büyülü eşyalara hem onları ele geçirme hırsındaki yaşayanlar hem de ellerinde kalmasını isteyen ölüler büyük değer veriyor.","Büyü",[],["Gölge Adalar"],"YAYGIN"],"01SI056":["İstilacı Örümcek","Çağrıldığımda, bu tur diğer dost Örümcekler +1|+0, düşmanlar ise -1|-0 alır.","","''Bir dakikadan kısa sürede insan boyu bir ağ örebilirler. Görmek ister misin?''\n- Elise","Birim",["ÖRÜMCEK"],["Gölge Adalar"],"ENDER"],"01SI001":["İntikam","Bir birimi öldürürsün.","","İhanete uğrayanlar son nefeslerini verirken Kalista'nın adını anarak, mızrağıyla intikamlarını almasını umarlar.","Büyü",[],["Gölge Adalar"],"YAYGIN"],"01SI019":["Hücre","Bu tur çağrılan her düşmana 3 hasar verirsin.","","''Kimse kaçamaz.''\n- Thresh","Büyü",[],["Gölge Adalar"],"ENDER"],"01SI011":["Doymaz Kasap","Beni oynamak için bir dost birimi öldürürsün.","","Bana ne yediğini söyle, sana kim olduğunu söyleyeyim.","Birim",[],["Gölge Adalar"],"YAYGIN"],"01SI014":["Ruh Sisi","Çağrıldığımda her yerdeki diğer dost Ruh Sisi kartlarına +1|+0 kazandırırsın.","","Gölge Adalar'ın bu hayaletleri kimliklerinden uzun zaman önce arınarak saf, doymak bilmez bir açlığa dönüşmüşler.","Birim",[],["Gölge Adalar"],"YAYGIN"],"01SI022":["Adaların Damgası","Bir dost birime +2|+2 ve Hayali kazandırırsın.","","Güç, ama ne pahasına?","Büyü",[],["Gölge Adalar"],"YAYGIN"],"01SI006":["Musallat","Rakibin bir takipçisini bu tur için çalarsın. (Zaten 6 dost birimin ya da Yer kartın varsa oynayamazsın.)","","Uyandığında kamp hiç olmadığı kadar sessizdi, elleri ıslak ıslak parlayan bir kızıllıkla kaplıydı. ","Büyü",[],["Gölge Adalar"],"ENDER"],"01SI028":["Ruh Parçası","Bir dost birimin birebir kopyasını çağırırsın. Kopya Hayali ve 1|1 olur.","","''Zavallının kimliğini öğrenmek için cesedi kaldırıp suyun dışına çıkardım. Elimi omzuna koyduğunda döndü ve yüzü göründü. Benim yüzümdü.''\n- Demacia'lı asker Arie Wrence","Büyü",[],["Gölge Adalar"],"ENDER"],"01SI025":["Hunharlık","Bir dost birimi öldürerek herhangi bir şeye kartın Güç değeri kadar hasar verirsin.","","Ölümün ne olduğunu anlayamayanlar için öldürmenin hiçbir anlamı yoktur.","Büyü",[],["Gölge Adalar"],"ENDER"],"01SI046":["Sis'in Çağrısı","Bu tur ölen rasgele bir dost birimi diriltirsin.","","''Sis, ruhu bedenden ayırıp yaşamı çirkin bir parodisine dönüştürür. Yaşadığım topraklara neler yaptığını gördüm. Buna son vermek için o lanetli adalara gideceğim.''\n- Yılmaz Öncü müfettişi Arie Wrence","Büyü",[],["Gölge Adalar"],"YAYGIN"],"01SI050":["Ordunun Doğumu","3 Yavru Örümcek çağırırsın, sonra dost Örümceklere +1|+0 kazandırırsın.","","Yumurtadan ilk çıktıklarında çok aç oluyorlar.","Büyü",[],["Gölge Adalar"],"ENDER"],"01SI016":["İfritçağıran","Sadakat: Bir Ruh Sisi çağırırsın.","","Sessizce ortaya çıkıyor. Ardından getirdiği dehşeti ise gözden kaçırmak imkânsız.","Birim",[],["Gölge Adalar"],"ENDER"],"01SI021":["Köpekbalığı Arabası","Son Nefes: Hayali bir dost birimin sonraki saldırısında dirilir ve saldırırım.","","''Ne görmüş dedin? Anlıyorum. Delilik çok acımasızdır, eczacı dostum. En azından diğerleri azıcık da olsa mantıklıydı.''\n- Demacia'lı Hekim","Birim",[],["Gölge Adalar"],"ENDER"],"01SI032":["Afet Tarihçisi","Oyna: Bir dost birimi öldürüp diriltirsin.","","Bir zamanlar, ünlü bir âlim olan babası tozlu el yazmalarını okurken onun yanında otururdu. Babası bir gün mesleğini devralacağını umuyordu. Ama böyle devralacağını düşünmemişti.","Birim",[],["Gölge Adalar"],"YAYGIN"],"01SI058":["Hayalet Temyizci","Oyna: Bir dost birimi öldürüp bedeli ondan 2 fazla olan rasgele bir takipçi çağırırsın.","","Ruhlar, sesinizi sesime katın! Birlikte sonu gelmeyecek bir karanlık çağıralım!","Birim",[],["Gölge Adalar"],"ENDER"],"01SI054":["Hortlağın Pençesi","Bir birime 3 Sömürü hasarı verirsin.","","Ölüler yaşayanların dünyasının durmaksızın atan nabzını susturmaktan başka bir şey istemez.","Büyü",[],["Gölge Adalar"],"YAYGIN"],"01SI044":["Hortlak Ana","Oyna: Elindeki bir dost birimi seçersin. Onun birebir kopyasını çağırırsın. Kopya Hayali olur.","","Afet, yoluna çıkan her şeyi çürütüp yozlaştırdı. İyiler zalim oldu. Cesurlar gaddar oldu. Mantığın yerini garez aldı.","Birim",[],["Gölge Adalar"],"DESTANSI"],"01SI039":["Eklembacaklı Dehşet","","","Kimi habis hortlaklar adanın canlılarından ilham alarak tanıdık hayvanları kâbus yaratıklarına dönüştürüyor.","Birim",["ÖRÜMCEK"],["Gölge Adalar"],"YAYGIN"],"01SI020":["Ruh Közcüsü","Çağrıldığımda ölmüş olan En Güçlü dost şampiyon dirilir.","","Tükenmeye yüz tutmuş bir mum, yerine yakılacak olanı aydınlatmaktan başka neye yarar?","Birim",[],["Gölge Adalar"],"ENDER"],"01SI029":["Çürüten Çığlık","Tüm düşmanlara 1 hasar verirsin. Nexus'unu 3 iyileştirirsin.","","Bizi öldüren onları güçlendiriyor.","Büyü",[],["Gölge Adalar"],"YAYGIN"],"01SI004":["Kara Suların Belası","","","Kimileri Afet'ten kaçmak için dalgaların kucağına atıldı. Çürütücü etkinin suya yayılamayacağını düşünüyorlardı. Yanılıyorlardı.","Birim",[],["Gölge Adalar"],"YAYGIN"],"01SI026":["Gardiyan'ın Avı","Son Nefes: Elinde bedeli 3 ya da daha az olan, Son Nefes'e sahip başka bir rasgele takipçi oluşur.","","Nefesini tutabildiği kadar tutarak gardiyanın kendisini fark etmeden geçip gitmesini umdu. Bu kovalamacanın, Thresh'in çok keyif aldığı işkencelerin daha başlangıcı olduğunu bilmiyordu...","Birim",[],["Gölge Adalar"],"YAYGIN"],"01SI040":["Habis Ziyafet","Bir birime 1 Sömürü hasarı verirsin ve bir Yavru Örümcek çağırırsın.","","''Le-leydim! Örümceklere bu kadar... düşkün olduğunuzu bilmiyordum. Çağırsanız da üstüme tırmanmasalar olur mu? Le-leydi Elise? Lütfen!''\n- Bahtsız Soylu Lord Sassen","Büyü",[],["Gölge Adalar"],"YAYGIN"],"01SI015":["Afet","TÜM birimleri öldürürsün.","","Sevgi kadar saf bir duygunun bu denli acımasız ve kaçınılmaz bir şeye yol açtığına inanmak çok zor. ","Büyü",[],["Gölge Adalar"],"DESTANSI"],"01SI055":["Ruhiçen","","","''Gemilerimiz o hayaletli kıyılara yaklaştıkça düşünmeye koyuldum: Bu kâbus yaratıkları o çorak topraklarda mı ortaya çıkmıştı? Hiç gerçekten yaşamışlar mıydı?''\n- Demacia'lı asker Arie Wrence","Birim",[],["Gölge Adalar"],"ENDER"],"01SI047":["Solan Hatıralar","Bir takipçi seçersin. Elinde Hayali bir kopyası oluşur.","","Bir an teninde dans eden gün ışığı damlalarını, ağzına attığı sulu çiyçileklerini, kırların şarkısını taşıyan meltemin başının üstünden geçişini anımsadı. Sonra... hepsini unuttu.","Büyü",[],["Gölge Adalar"],"ENDER"],"02PZ001":["Denizmırnavı","Çağrıldığımda 1 kart çekersin.\nSonra, bu oyunda en az 10 başka yeni kart oynadıysan +4|+0 kazanırım.","","O sırıtık insanlardan kaçmasına hiçbir şey engel olamazdı. Azıcık sudan mı korkacaktı?","Birim",["KEDİ"],["Piltover ve Zaun"],"DESTANSI"],"02PZ010":["Deneyimli Müfettiş","Çağrıldığımda TÜM oyuncular 1 kart çeker.","","Kimi polis memurları vakaları halletmek için içgüdülerine, kimileri muhbirlerine güvenir. Ama Memur J.S. Harknor'un güçlü yönü çalışkanlık ve evrak tutmaktır. Bol bol evrak tutmak...","Birim",["YORDLE"],["Piltover ve Zaun"],"YAYGIN"],"02PZ006":["Yakaladım!","Çekildiğimde bedelim bu tur 2 azalır.\nBir birime 3 hasar verirsin.","","''Şu kelepçeleri dener misiniz Bay Berz?''\n''Benim çıkarım ne?''\n''Sizde kalabilirler.''\n''...Peki madem.''\n''Tutuklusun! Alın bunu.''","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"02PZ004":["Duvar Delen","Bir dost birime bu tur +2|+0 verirsin.\nElinde Geçici bir Duvar Delen oluşur.","","''Burada yumruklar konuşur.''\n- Vi","Büyü",[],["Piltover ve Zaun"],"ENDER"],"02PZ007":["Açıkgöz Müfettiş","Bedeli 2 olan bir kart oynadığında, 1 kart çekersin ve ona Geçici kazandırırsın.","","''Tüm dedektifler tepki verir ama iyi bir dedektif olacakları önceden kestirir, örnek bir dedektifse olayın önüne geçer.''\n- Muhafızın El Kitabı","Birim",[],["Piltover ve Zaun"],"ENDER"],"02PZ002":["Baş Mekanist Zevi","Bir kart çektiğinde ona Geçici kazandırırsın ve elinde birebir kopyası oluşur.","","Beş yaşındayken, dünyanın ilk çok frekanslı sonik bıçağını yaptı. Pek pratik değildi (çoğunlukla sandviç kesmekte kullanıyordu) ama bu sayede muhafızların seçkin Teçhizat Birimi'ne katıldı.","Birim",[],["Piltover ve Zaun"],"DESTANSI"],"02PZ008":["Vi","Oyunda veya elindeyken başka kart oynadığında +1|+0 kazanırım (en fazla +8|+0).","Tek seferde 10+ hasarlık vuruş yaptığımda.","''Fedai Vi! Lütfen halkı düşünün! Çevreye verdiğiniz hasarı düşünün! AÇILACAK TAZMİNAT DAVALARINI DÜŞÜNÜN!''\n- Açıkgöz Müfettiş","Birim",[],["Piltover ve Zaun"],"Şampiyon"],"02PZ009":["Kanıtlardan Bir İz","Elinde bölgelerine ait, bedeli 2 olan rasgele bir kart oluşur. Bedeli bu tur 2 azalır.","","''Böylece,'' dedi Memur Harknor, ''araştırmamızın bizi getirdiği yer...''","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"02PZ003":["Lacileri Çek","Çekildiğimde bedelim bu tur 2 azalır.\nBir dost birimin niteliklerini 4|4'e çıkarırsın.","","''Limanda sorun çıkmış! Al bunları, selamımı da söylersin.'' \n- Baş Mekanist Zevi","Büyü",[],["Piltover ve Zaun"],"ENDER"],"02PZ005":["Devriyeciler","Çekildiğimde bedelim bu tur 1 azalır.","","Memur Mir'in koşu tekniği diğer fedailer arasında alay konusuydu. Memur Mir bunun nedenini anlamıyordu.","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"02BW040":["Çarpanbağa","","","''EN GİÇLÜ YÜNÜM SIRA DAN İNSAN'LARI YÖNİTEBİLMEK AYRCA KALEMİM KUVETLİ DİR'' \n- Kuma karalanmış bir not","Birim",[],["Bilgewater"],"YAYGIN"],"02BW057":["Kaypak Dalga Binicisi","","","''Şu mercan kayalarında çok acayip şeyler gördüm Kaptan. O kaz kafalı herif portakalların içine bir şey mi şey mi karıştırıyor acaba?''\n- Gemi Astsubayı","Birim",[],["Bilgewater"],"YAYGIN"],"02BW041":["Derinlerdeki Canavar","","","''Canavardan korkma derler,\nFırtınasından sağ çıkar kimi\nAma ya pruvaları kıranlar\nÇekenler suyun altına gemicileri?''\n- Bir Bilgewater hanında tavan kirişine kazınmış bir yazı","Birim",["DENİZ CANAVARI"],["Bilgewater"],"YAYGIN"],"02BW013":["Sinsi Katil","","","''...sonra bu gerzek bana, 'Belinin kıvrımı denizdeki dalga gibi aynı,' dedi. Ben de ona, 'Yalakalığı kes, yoksa ben senin dilini keserim,' dedim.''","Birim",[],["Bilgewater"],"YAYGIN"],"02BW034":["Maymun İdolü","Tur Başı: Bana 2 hasar verirsin ve bir Barut Maymunu çağırırsın.","","''Bu... hatıra. Mürettebat bunu eski, kaçık bir rakibimden yürüttü. Ahmak 'kadim, gizemli güçler'den bahsedip dururdu, söyledikleri gerçeğe çok uzak değilmiş meğer.''\n- Miss Fortune","Birim",[],["Bilgewater"],"ENDER"],"02BW056":["Derinliklerin Doymaz Ağzı","Oyna: Canı benden az olan bir düşmanın Kökünü Kazırsın.","","''Yelken açmıştım daha dün\nBilgewater Limanı'ndan\nSonra çıktı karşıma derinlerden\nKanat Kulaklı Batık Hanım...'' \n- ''Kanat Kulaklı Batık Hanım'' türküsünden","Birim",["DENİZ CANAVARI"],["Bilgewater"],"DESTANSI"],"02BW060":["Attığını Vuran Korsan","Dost birimler saldırdığında rakibin Nexus'una 1 hasar verirsin.","","''Kısa olmak savaşta şaşırtıcı bir avantaj sağlıyor. Aşağı bakmak kimsenin aklına gelmiyormuş meğerse!''","Birim",["YORDLE"],["Bilgewater"],"YAYGIN"],"02BW011":["Üçkâğıtçı Yordle","Sadakat: 1 kart Aşırırsın ve elinde bir Uyarı Atışı oluşur.","","''Sana bir dost olarak yardım etmek istedim. Duruşunu, bakışını, kılıcının parlayışını pek gözüm tuttu. Kılıcın hakikaten çok güzelmiş yalnız.''","Birim",["YORDLE"],["Bilgewater"],"ENDER"],"02BW030":["Enkaz İstifçisi","Çağrıldığımda 2 kartı Denize Atarsın ve destende 2 Hazine oluşur.","","''Bu aralar eminim denizin altında, üstünden çok hazine vardır. O olmasa toplamak kolay olurdu da...''\n- Testere Kasap","Birim",["DENİZ CANAVARI"],["Bilgewater"],"DESTANSI"],"02BW019":["Baloncuk Ayı","","","Yılan Adalar'ın mercan kayalıklarından geçen bereketli sihir akıntıları, su altının olağandışı sakinlerini besler.","Birim",[],["Bilgewater"],"YAYGIN"],"02BW007":["Atılgan Kumarbaz","Beni oynamak için 2 kart atarsın.\nSaldır: 2 kart çekersin ve onlara Geçici kazandırırsın.","","''Genelde kolay iş. Masalar gırtlak patlatarak şarkı söylemekten oyuna bakmayan enayilerle dolu. Benim için hava hoş. Para paradır, onların cebinde duracağına benimkinde dursun.''","Birim",[],["Bilgewater"],"ENDER"],"02BW014":["Mercan Kayalığı Canlıları","Çağrıldığımda elinde bölgelerine ait, bedeli 1 olan rasgele bir büyü oluşur.","","Çoğu sığ suda bir sürü deniz canlısı yaşar ama hiçbiri Çivit Yol'un mercan kayalıklarıyla boy ölçüşemez. Çivit Yol harikalarla dolu, sanki bu dünyaya ait olmayan bir yerdir.","Birim",[],["Bilgewater"],"ENDER"],"02BW055":["Kalpsiz Tayfabaşı","Yağma: Bedeli 1 olan her yerdeki dost birimler +1|+0 kazanır.","","O ateş edince, kancacıların hızlı davranması gerekir. Suya yayılan kan bir sürü misafir getirir... Hiçbiri de hoş gelmez.","Birim",[],["Bilgewater"],"DESTANSI"],"02BW017":["Narenciye Taşıyıcısı","Yağma: Dost birimleri ve Nexus'unu 3 iyileştirirsin, ardından Silahlanırsın.","","''Denizciler kendilerini çok sert sanıyor. Hep bir hırlama, gırlama. Aferin, çok güzel. Ama yine de portakal yemek lazım! Dişleri sağlamlaştırır, cildi güzelleştirir. Yemeyenin cesedini suya atarlar.''","Birim",[],["Bilgewater"],"ENDER"],"02BW038":["Çarpan Püsküryüzgeç","Çağrıldığımda destenden bedeli 3 ya da daha düşük olan bir büyü çekersin.","","Zap bir keresinde Çivit Yol'u üç dakika dolmadan turladı. Üstelik sonlara doğru Karakanat'ın parçalanmış gövdesinden kaçınmak zorunda kaldı. O gün akıntılar İNANILMAZDI.","Birim",[],["Bilgewater"],"DESTANSI"],"02BW021":["Usturapul Avcısı","Oyna: Bir düşmana Kırılganlık kazandırırsın.","","''Duydum ki hedefini bulmak için kilometrelerce yüzer, bulunca da asla kaçırmazmış. İnsan mı balık mı bilmiyorum ama bu suları bizden iyi tanıdığı kesin.''\n- Testere Kasap","Birim",[],["Bilgewater"],"ENDER"],"02BW035":["Şerif Lariette Rose","Çağrıldığımda tüm düşmanlara Kırılganlık kazandırırsın.","","Bilgewater'da kanun olmayabilir ama şehrin hareketli duvarları arasında adaleti kendilerince uygulamaktan korkmayan bir avuç cesur kişi de vardır.","Birim",[],["Bilgewater"],"DESTANSI"],"02BW058":["Testere Kasap","Yağma: +1|+1 kazanırım.","","Paslı Kancalar'a katılmak kanlı bir olaydır. Gemicilerin hem denizciliği hem savaşmayı hem kasaplığı iyi bilmesi gerekir. En sevimsiz adaylar tüm bu becerilerini tek savaşta kanıtlar.","Birim",[],["Bilgewater"],"YAYGIN"],"02BW028":["Girdap Rex","Yağma: Rasgele hedef alınan düşmanların üzerinde 7 kere Top Salvosu oynarsın.","","''Geç tayfayı, geç enkazları\nSavaş çoktan bitti\nYangın işlerini bitirdi, Girdap Rex kaptanı yedi\nGemilerinin sadece iskeleti kaldı.'' \n- ''Eve Dönüyorum Sally'' şarkısından","Birim",[],["Bilgewater"],"DESTANSI"],"02BW037":["Derinlerin Gözü","Nexus Vuruşu: 1 kart çekersin.","","''Heyamola dediler, yelken açtılar\nNashramae'ye iş görmeye\nAma Doğa Ana'nın tersi döndü, kimi öldü\nKimi de gitti her şeyi gören gözü ziyarete!'' \n- ''Her Şeyi Gören Göz'' şarkısından","Birim",["DENİZ CANAVARI"],["Bilgewater"],"ENDER"],"02BW008":["Gemi Astsubayı","Oyna: Bir Barut Fıçısı ya da bedeli 1 olan rasgele bir takipçi çağırırsın.","","Tembel bir denizciyi en hızlı hareketlendiren şeyin yanık bir fitil olduğunu iyi biliyordu.","Birim",["YORDLE"],["Bilgewater"],"ENDER"],"02BW047":["Çamur Tarayıcıları","Çağrıldığımda 3 kartı Denize Atarsın.","","Denize açılmaya uygun teçhizatı çöpe çevirmek de bir yetenek. Ve bu yetenekten onlarda bol bol var.","Birim",[],["Bilgewater"],"YAYGIN"],"02BW004":["Dehşet Yolu Tayfası","Çağrıldığımda bir Barut Fıçısı çağırırsın.","","''Sabah sabah tayfaları uyanık, topları hazırken mi savaşalım? Bu gece onlara sessizce bir hediye bırakırız, olur biter...''","Birim",[],["Bilgewater"],"YAYGIN"],"02BW002":["Dehşet Yolu","Çağrıldığımda Gangplank kartını çekersin.\nTüm büyülerinin, yeteneklerinin ve dost birimlerinin verdiği hasar ikiye katlanır.","","''Edin vedanızı, indirin yelkenlerinizi\nDehşet Yolu geliyor.\nDerindir deniz, dibi mezarlarla doludur,\nÇünkü Dehşet Yolu geliyor!'' \n- ''Dehşet Yolu Geliyor'' adlı şarkıdan","Birim",[],["Bilgewater"],"DESTANSI"],"02BW016":["Kumarbot","Çağrıldığımda ya da Tur Başı: Önceki tur çektiğin her kart için bana +0|+1 kazandırırsın, sonra niteliklerimi karıştırırsın.","","Prototiplerden biri üç bomba geldiğinde patlıyormuş. Bu ''özellik'' sonraki modellerden kaldırılmış.","Birim",[],["Bilgewater"],"ENDER"],"02BW027":["Av Filosu","Çağrıldığımda, rakibin bir Altın Narval çağırır.","","Dalgaların altında parıldayan altın değil, gümüş de değil, Katliam Filosu kaptanının zeki düşmanının boynuzu.","Birim",[],["Bilgewater"],"YAYGIN"],"02BW050":["Usta Solocu","Yağma: Elindeki ve destendeki dost birimlerin bedeli 2 azalır.","","''Bizimle müzik yolculuğuna çıkın! Runeterra'nın her yerinden ezgiler dinleyin! Ama unutmayın, giriş ücretli, bahşişe de hayır demeyiz!''\n- Gösteri tellalı","Birim",[],["Bilgewater"],"ENDER"],"02BW015":["Sirene","Çağrıldığımda Miss Fortune kartını çekersin.\nBen saldırırken tüm büyülerin ve yeteneklerin fazladan 1 hasar verir.","","Sirene'yi başka gemilerle karıştırmak olanaksız. İnci beyazı geniş yelkenleri ve pırıl pırıl cilalı ahşap oymalarıyla en az dümenindeki kaptan kadar güzel.","Birim",[],["Bilgewater"],"DESTANSI"],"02BW010":["Yağmacı Poro","Yağma: 2 rasgele tesir kazanırım.","","''Resmi, Ödül Tahtası'nda herkesinkinden uzun süredir asılı. Açgözlü, acımasız, istediğini elde etmek için her şeyi yapacak bir şeytan. Daha fenası, bir de sevimli ki!''\n- Gangplank","Birim",["PORO"],["Bilgewater"],"YAYGIN"],"02BW009":["Bilardo Sansarı","Çağrıldığımda, sonraki Tur Başında 1 kart çekersin ve ona Geçici kazandırırsın.","","''Ben anlamıyom valla ya. Hepsini anında üterim ama sonuncusu... bir türlü yatmadı birader. Neyse, benim günüm değilmiş.''\n- Atılgan Kumarbaz","Birim",[],["Bilgewater"],"YAYGIN"],"02BW005":["Kiralık Katil","Çağrıldığımda En Güçlü düşmana Kırılganlık kazandırırsın.","","''Bu senin resmin mi? Öf, ilandakinden bile çirkinmişsin be! Umarım işime yararsın da...''","Birim",[],["Bilgewater"],"YAYGIN"],"02BW039":["Jaull Avcıları","Çağrıldığımda elinde rasgele bir Deniz Canavarı oluşur.","","Definenin cazibesi sayısız mürettebatı sığ suların ötesine çeker. Bu zavallılar okyanusun ne kadar korkunç olduğunu çok geçmeden öğrenir ve bu yüzden pek azı geri döner.","Birim",[],["Bilgewater"],"ENDER"],"02BW006":["Esrarengiz İllüzyonist","Oyna: Bir dost birimi, bedeli 5 olan rasgele bir takipçiye dönüştürürsün.","","''Marvolio? Ellerim... Ellerim nerede?''\n''Şimdi bakınız ellerinizi yine meydana çıkaracağım. Tadaa! Öhöm. TA DAAA!''\n''MARVOLIO ELLERİM NEREDE DEDİM SANA!''\n''Eveeet, gösterimiz bu kadardı, teşekkürler!''","Birim",[],["Bilgewater"],"ENDER"],"02BW036":["Altın Narval","","","Efsanelere göre boynuzlu, beyaz bir balina Sakallı Hanım'ın bir şeyini çalmış. Sakallı Hanım ceza olarak sonsuza kadar açgözlüler peşine düşsün diye onu pırıl pırıl altınla kaplamış.","Birim",[],["Bilgewater"],"YAYGIN"],"02BW033":["Karaborsa Tüccarı","Bir düşman kartı çektiğinde bedeli 1 azalır.\nYağma: 1 kart Aşırırsın.","","''Ne istiyorsan hepsi var! Hatta 'özel stok' bile var. Yalnız unutma, benden almadın.''","Birim",[],["Bilgewater"],"ENDER"],"02BW032":["Gangplank","Çağrıldığımda bir Barut Fıçısı çağırırsın.","Rakibin Nexus'una 5+ farklı turda hasar verdiğinde.","''Çok bakma, baktığını fark eder. Hakkında kötü söz de etme, Bilgewater'ın tüm fısıltılarını duyar. Hah, geliyor. Başını eğ. Yere bak.''\n- Dehşet Yolu tayfası","Birim",[],["Bilgewater"],"Şampiyon"],"02BW022":["Miss Fortune","Dost birimler saldırdığında, savaştaki tüm düşmanlara ve rakibin Nexus'una 1 hasar verirsin.","4 kere saldırdığını gördüğümde.","''Miss Fortune mu? Bana burada 'Kaptan' diyeceksin.''","Birim",[],["Bilgewater"],"Şampiyon"],"02BW046":["Fizz","Sen bir büyü oynadığında beni hedefleyen tüm düşman büyüleri ve yetenekleri durur ve bana bu tur Sıyrılgan verirsin.","6+ büyü oynadığında.","Bilgewater'ın efsanevi karakterleri arasında en hercaisi Fizz. Kimi denizciler kıyıya vurmuş bir sürü paramparça gemi yüzünden onu suçlarken...","Birim",["YORDLE"],["Bandle Şehri","Bilgewater"],"Şampiyon"],"02BW026":["Twisted Fate","Oyna: Bir Kader Kartı oynarsın.","9 kart çektiğini gördüğümde.","''Şimdi ellerimi seyret, kartları say ve ucunu kaçırmamaya çalış. Bir de unutma...''","Birim",[],["Bilgewater"],"Şampiyon"],"02BW053":["Nautilus","","Derin olduğunda. Seviye atladığımda, bedeli 4+ olan Denize Atılmış dost birimler destene kopyalanır.","''Hınç'ı koca bir çıpa batırdı. Finn'i de boğdu bu arada. Geride bir avuç tayfa kaldık. Gece de oluyor. Hava soğuyor. Özür dilerim anacığım. Haklıymışsın. Dev gerçekmiş.'' \n- Bulunmuş bir not","Birim",[],["Bilgewater"],"Şampiyon"],"02BW061":["Gizli Aslar","Çekildiğimde bedelim bu tur 1 azalır.\nBir dost birime +2|+1 kazandırırsın.","","''Şansı bir kere yakaladın mı devam ettirmek gerek.'' \n- Twisted Fate","Büyü",[],["Bilgewater"],"YAYGIN"],"02BW024":["Çifte Bela","1 manalık 2 rasgele takipçi çağırırsın.","","''Hişt Gav, şu bizim aradığımız herif değil mi? Arkadaş bulmuş.''\n''Yanındaki... köpekbalığı adam mı Baz?''\n''Olsun, daha çok altın verirler. Hadi!'' \n- Baz ve Gav, acemi ödül avcıları","Büyü",[],["Bilgewater"],"ENDER"],"02BW003":["Göz Korkut","Yağma: HERHANGİ BİR takipçiyi eline Geri Gönderirsin.","","''Artık bize çalışacaksın!''\n- Gemi Astsubayı","Büyü",[],["Bilgewater"],"ENDER"],"02BW025":["Denizin Dişleri","Bir düşmana Kırılganlık kazandırırsın ve Uzundiş çağırırsın.","","''Köpekbalığı!''\n- Fizz","Büyü",[],["Bilgewater"],"YAYGIN"],"02BW012":["Barut Getirin!","2 Barut Fıçısı çağırırsın.","","''Fıçı!''\n- Gangplank","Büyü",[],["Bilgewater"],"YAYGIN"],"02BW018":["Çakaralmaz","Herhangi bir şeye 1 hasar verirsin.\nHasar alan ölürse, rakibin Nexus'una 1 hasar verirsin.","","Gangplank'in kendi usulünce yaptığı meditasyon hep kısa sürer ve kanlı biter.","Büyü",[],["Bilgewater"],"YAYGIN"],"02BW048":["Hapisten Kaçış","Bedeli 1 olan rasgele bir takipçi çağırırsın.","","''Ne dersin Baz? Pek güçlü değil gibi.''\n''Emin misin Gav? Hapishaneden kaçmış...''\n''O zaman güçlü değil akıllıdır. Hadi!'' \n- Baz ve Gav, acemi ödül avcıları","Büyü",[],["Bilgewater"],"YAYGIN"],"02BW043":["Bir Kart Seç","Oynamak için elindeki bir kartı destene koyarsın.\nSonraki Tur Başında 2 kart çekersin ve onlara Geçici kazandırırsın.","","''Şansım kendi eserim.''\n- Twisted Fate","Büyü",[],["Bilgewater"],"ENDER"],"02BW051":["Oyunbaz Düzenbaz","Saldıran bir dost birimi çatışmadan çıkarırsın ve Silahlanırsın.","","''Bir kulaç öndeyim!''\n- Fizz","Büyü",[],["Bilgewater"],"ENDER"],"02BW054":["Gelgit","Bir düşmanı Sersemletirsin.\nSende Nautilus varsa, sersemleyen birim rakibin destesine konur.","","''Onları dibe çek...''\n- Nautilus","Büyü",[],["Bilgewater"],"ENDER"],"02BW042":["Zihin Birleşimi","Bu tur dost birimlerin Güç ve Can değerleri bu oyunda oynadığın diğer büyülerin sayısına eşitlenecek şekilde artar.","","Bilgewater'ın çevresindeki akıntılardan ve gelgitten, gücü ve aniden yön değiştirmesi yüzünden haklı olarak korkulur. Ama bu suların altındaki gerçek gücü hiçbir denizci bilmez.","Büyü",[],["Bilgewater"],"DESTANSI"],"02BW059":["Saçma Atışı","3 kartı Denize Atarsın. Bir birime 7 hasar verirsin.","","''Düşman gemisini batırdıysa, değer.''\n- Bilgewater deyişi","Büyü",[],["Bilgewater"],"ENDER"],"02BW023":["Derinliklerin Çağrısı","Her yerdeki dost Deniz Canavarlarının bedeli 1 azalır.\nBir Deniz Canavarı çekersin.","","Denizciler fısıldayarak denizin karışıp kaynayacağı, dalgalardan adı ağza alınamayacak dehşetlerin yükseleceği günlerden bahseder...","Büyü",[],["Bilgewater"],"ENDER"],"02BW031":["Çifte Vuruş","Bir düşmana 2 hasar verirsin.\nHasar alan ölürse, rakibin Nexus'una 4 hasar verirsin.","","''Ben hep ilk ateş ederim.''\n- Miss Fortune","Büyü",[],["Bilgewater"],"ENDER"],"02BW029":["Hurda","2 kartı Denize Atarsın. 2 kart çekersin.","","Suda yüzen eşyalar yüzeyde fazla kalmaz. Gemideki yerini hak eden her denizci kıymetli yüklerle gereksiz ıvır zıvırı hızla ayırt etmeyi bilir.","Büyü",[],["Bilgewater"],"YAYGIN"],"02BW049":["Çalıntı Mallar","1 kart Aşırırsın.\nYağma: 1 kart daha Aşırırsın.","","Senin malın benim malım, benim malım... yine benim malım.","Büyü",[],["Bilgewater"],"YAYGIN"],"02BW001":["Bu Bir Uyarıdır","Bir düşmana bu tur Kırılganlık verirsin. Bu tur ölürse 1 kart çekersin.","","''Suratını asma, ayağına çabuk ol evlat! Kaptan sallandığını görürse seni yelken direğine çeker, martılara yem eder. Hadi, fırla!''\n- Dehşet Yolu tayfası","Büyü",[],["Bilgewater"],"YAYGIN"],"02BW063":["El Çabukluğu","Yağma: Rakibin elinden şampiyon olmayan rasgele bir kart çekersin.","","''Kart oyunu şans işi değil, insanları tanıma işi. Karşında oturanın kendisinden şüphe etmesini sağlarsan, cüzdanını sana eliyle vermiş kadar olur.''\n- Twisted Fate","Büyü",[],["Bilgewater"],"ENDER"],"02BW045":["Kurşun Yağmuru","Rasgele hedeflenmiş üç farklı düşmana ya da rakibin Nexus'una 1 hasar verirsin.","","''Silahlar konuşsun!''\n- Miss Fortune","Büyü",[],["Bilgewater"],"YAYGIN"],"02BW020":["Uyarı Atışı","Rakibin Nexus'una 1 hasar verirsin.","","''Sen de bizimle ateş edeceksin evlat! Yaylım ateşi ne demek bilmiyor musun?''\n- Gemi Astsubayı","Büyü",[],["Bilgewater"],"YAYGIN"],"02BW044":["Safra At","4 kartı Denize Atarsın.","","''Ağırlığını taşımaya değmezse atın gitsin. Aynı şey sizin için de geçerli. İşinizin başınıza hadi!''\n- Gemi Astsubayı","Büyü",[],["Bilgewater"],"ENDER"],"02BW062":["Ada Dümencisi","Çağrıldığımda 1 manalık rasgele bir takipçi çağırıp ona Öncü tesiri kazandırırsın.","","''Işığı kaldır Yılan Ana'dan\nDalgalardan, bulutlara\nGri gözleri apaçık gökyüzünün,\nBakışının yansıması sakin\nGülümser huzurla...''\n- Nagakabouros'a dua","Birim",[],["Bilgewater"],"ENDER"],"02FR009":["Kurt Süvarisi","Yağma: Boş bir mana taşı alırsın.","","Kışın Pençesi'nin genç binicilerine, silah tutabildikleri an bir kurt yavrusu verilir. Yetiştirilme şekilleri sadece savaş odaklıdır. Kurt kapıp parçalamayı, binicisi yağmalayıp çalmayı öğrenir.","Birim",[],["Freljord"],"YAYGIN"],"02FR004":["Soğuk Karşılama","Bir düşmana bu tur Buz Tutturursun ve Kırılganlık verirsin.","","''Bu sıcakkanlılar Freljord'da bir gün bile dayanamaz!'' \n- Sejuani","Büyü",["ELEMENTAL"],["Freljord"],"ENDER"],"02FR002":["Sejuani","Oyna: Bir düşmana bu tur Buz Tutturursun ve Kırılganlık verirsin.","Rakibin Nexus'una 5+ farklı turda hasar verdiğinde.","Sejuani'nin Gerçek Buz'dan gürzü çok güçlü olsa da asıl silah kendisi. Freljord'un yakıcı soğuğunda dövülüp dondurucu iklimde sınanarak güçlenmiş.","Birim",[],["Freljord"],"Şampiyon"],"02FR001":["Köz Kız","Tur Başı: HER ŞEYE 1 hasar verirsin.","","''Verimli tarlalarını sürerler\nHer zayıf gibi tohum ekerler.\nBiz çoğunu tutuştururuz\nKışın Pençesi ne isterse elde eder!'' \n- Kışın Pençesi çocuk tekerlemesi","Birim",[],["Freljord"],"ENDER"],"02FR005":["Ursin Ruhgezgini","Yağma: Taşpençe Ursin kartına dönüşürüm.","","Ursinler yollarına insan olarak başlarlar ama güçlü ruh Volibear'in bahşettiği yabanıl, devasa gücü elde etmek için sıradan ölümlü yaşamlarını bir kenara bırakırlar.","Birim",[],["Freljord"],"YAYGIN"],"02FR010":["Paylaşılan Ganimet","Destenin en üstündeki 3 birime +1|+1 kazandırırsın.\nYağma: Bunlardan bir tanesini çekersin.","","''Paylaşmak güzeldir.''\n- İnsafsız Yağmacı","Büyü",[],["Freljord"],"ENDER"],"02FR008":["Yağmacı Gemisi","Çağrıldığımda Sejuani kartını çekersin.\nYağma: Destendeki dost birimlerin Güç ve Can değerlerini ikiye katlarsın.","","''İlkbahar ekin ekecek kadar sıcak havayla beraber yağmacı gemilerini de getirir ve başta bol olan tahıllar azalmaya başlar.''\n- Avarosa Köy Muhafızı","Birim",[],["Freljord"],"DESTANSI"],"02FR007":["Kuzeyin Hiddeti","Bir dost birime bu tur +3|+4 verirsin.","","''İçindeki canavarı kucakla!''\n- Sejuani","Büyü",[],["Freljord"],"YAYGIN"],"02FR006":["İnsafsız Yağmacı","","","Kışın Pençesi'nin Freljord'da dengi yoktur. Bu acımasız akıncıların ne kadar vahşi olduğunu herkes bilir. Gözlerini kan bürüdüğünde yapılabilecek tek şey hızlı bir ölüm için dua etmektir.","Birim",[],["Freljord"],"YAYGIN"],"02FR003":["Aurora Porealis","Elinde rasgele 2 Poro ve 2 Poro Kurabiyesi oluşur.","","''Poroya bakıp dilek tutarsan\nVe gece göğe bakarsan\nGörürsün yıldızlar arasında\nParlayan bir kurabiye.''\n- Küçük Ingvar","Büyü",[],["Freljord"],"DESTANSI"],"02NX001":["Canavar Azmanı","Çağrıldığımda Swain kartını çekersin.\nTur Başı: Rakibin Nexus'una iki defa 1 hasar verirsin.","","Ionia'lılar onu ufukta gördüklerinde canavar olduğunu sandılar. Haksız sayılmazlardı. Noxus gemi mühendisliğinin son harikası olan bu çelik savaş gemisi dehşet verici bir şey.","Birim",[],["Noxus"],"DESTANSI"],"02NX007":["Swain","Nexus Vuruşu: Rakibin Nexus'una 3 hasar verirsin.","Çatışma dışı 14+ hasar verdiğinde.","''Fanilerin anlayamayacağı bir güç, bana çoğu kişinin göremediklerini görme gücü verdi. Herkesi korkutan karanlığın derinliklerine bakıyorum.''","Birim",[],["Noxus"],"Şampiyon"],"02NX006":["Şehiryıkan","Tur Başı: Rakibin Nexus'una 1 hasar verirsin.","","İhtiyarın sesi şaşılacak kadar sakindi. ''Bir şeyi açıklamanı rica edeceğim,'' dedi. ''Taş toplayıp daha yüksek duvar yapmanın anlamı ne? Noxus'lular o taşları her seferinde geri fırlatıyor.''","Birim",[],["Noxus"],"ENDER"],"02NX002":["Aurok Işılboynuz","Saldır: Hasar almış tüm düşmanları Sersemletirsin.","","''Kuşaklar boyu baskı altında tutulduk. Gerçek özgürlüğün ne olduğunu Noxus topraklarımızı ele geçirene kadar anlamadık. Bu yüzden imparatorluk için savaşıyorum.''","Birim",[],["Noxus"],"DESTANSI"],"02NX009":["Kuzgun Sürüsü","Hasar almış ya da Sersemlemiş bir birime 4 hasar verirsin.","","Dinle. İşitiyor musun? Çırpılan binlerce kanadın gümbürtüsü yankılanıyor.","Büyü",[],["Noxus"],"ENDER"],"02NX004":["İmparatorluk İmhacısı","Oyna: Bir dost birime 1 hasar vererek rakibin Nexus'una 2 hasar verirsin.","","''Patlamaya kadar hızlı ve sessiz.''","Birim",[],["Noxus"],"YAYGIN"],"02NX003":["Noxus Şevki","Bir dost birime 3 hasar vererek herhangi bir şeye 3 hasar verirsin.","","''Bedeli neyse ödenmeli.''\n- Jericho Swain","Büyü",[],["Noxus"],"YAYGIN"],"02NX010":["Zırhlı Fül Süvarisi","Güç değeri 4 ya da daha az olan düşmanlar bana hasar veremez.","","''Savaş canavarı harekete geçince durdurmanın imkânı yok. En iyisi yolundan çekilmek.''\n- Basilisk Süvarisi","Birim",[],["Noxus"],"ENDER"],"02NX008":["Ölümün Eli","Bir düşmana 2 hasar, rakibin Nexus'una 1 hasar verirsin.","","''Şerefinle ölmeye çalış.''\n- Swain","Büyü",[],["Noxus"],"YAYGIN"],"02NX005":["Demir Balista","","","''Elinde doğru araçlar varsa kuşatma kolay iştir. Şehiryıkanlar düşmanı dışarı kaçırır, balistalar da işlerini bitirir.'' \n- Kuşatma Mühendisi","Birim",[],["Noxus"],"YAYGIN"],"02DE003":["Sadık Porsukayı","","","Hayvan sahibine benzer derler ya, doğru.","Birim",[],["Demacia"],"YAYGIN"],"02DE008":["Kocaboynuz Yoldaş","","","Acemi bir kolcu yoldaşlarıyla ormanda aylar geçirerek geyiğinin her hareketini tahmin etmeyi öğrenir. Sabırlı olmalıdır ama bir kere bağ kurdular mı aralarına hiçbir şey giremez.","Birim",[],["Demacia"],"YAYGIN"],"02DE004":["Yeşildiş Kolcusu","","","''Bu ormanı ve içine sığınan herkesi korumaya ant içtim.''","Birim",["SEÇKİN"],["Demacia"],"YAYGIN"],"02DE006":["Quinn","Çağrıldığımda Valor çağırırsın.","4 kere saldırdığını gördüğümde.","''Bizim Quinn hep korkusuz bir kolcu şövalye olmuştur. Valor da yanında ya da gökyüzündeyken, ikisini hiçbir şey durduramaz.''\n- Genevieve Ağaçyürek, kolcu şövalye","Birim",[],["Demacia"],"Şampiyon"],"02DE009":["Ak Saçlı Kolcu","Son Nefes: Bir Sadık Porsukayı çağırırsın.","","Bertrand kariyerine Bandle İzcisi olarak başladı. Bütün izci rozetlerini kazandı. ''Güler Yüzlülük'' hariç.","Birim",["YORDLE"],["Demacia"],"ENDER"],"02DE005":["Direngen Ruh","Bir dost birime ''Hasar alamam ya da ölemem'' özelliği kazandırırsın.","","Kolcu yaralı bacağının acısına aldırmadan bir kere daha doğrulup kılıcını kaldırdı. Onu ayakta tutan sadece kendisinin değil, Demacia'nın da azmiydi.","Büyü",[],["Demacia"],"DESTANSI"],"02DE002":["Kör Eden Saldırı","Valor çağırırsın.","","''Saçımı kaptı! SAÇIMI KAPTI!''\n- Lejyon Yağmacısı","Büyü",[],["Demacia"],"ENDER"],"02DE010":["Genevieve Ağaçyürek","Çağrıldığımda diğer dost birimlere bu tur +1|+1 verirsin.","","Demacia kolcularını savaşırken görmek ilham vericidir. İnsanla hayvan yan yana, tek yürek olarak büyük bir kararlılıkla savaşır ve birbirlerinden asla ayrılmazlar.","Birim",[],["Demacia"],"DESTANSI"],"02DE007":["Kolcu Azmi","Dost birimlere bu tur Dayanıklılık verirsin.","","''Düşman yaklaştığında korkuyu kalbinize sokmayın. Ağaçlar bizi koruyacak.''\n- Yeşildiş Kolcusu","Büyü",[],["Demacia"],"ENDER"],"02DE001":["Düzenli Saldırı","Bir düşman seçersin. 2 dost birim sırayla ona vurur.","","''Peşimden, birlikte!''\n- Yeşildiş Kolcusu","Büyü",[],["Demacia"],"YAYGIN"],"02SI005":["Öz Büyüsü","3 kartı Denize Atarsın.\nDost birimleri 3 iyileştirirsin.","","''Bu adalar temizlenecek.''\n- Maokai","Büyü",[],["Gölge Adalar"],"ENDER"],"02SI010":["Ölügonca Gezgini","Çağrıldığımda 3 kartı Denize Atarsın.","","''Dev treant bana... gösterdi. Bu, gezdiği... hayat dağıtıyor... akıl almaz... burası. Adının Kutlu Adalar olması boşuna değil!'' - Bulunmuş bir günlükten","Birim",[],["Gölge Adalar"],"YAYGIN"],"02SI008":["Maokai","Her tur ilk defa başka bir dost birim çağırdığında, 2 kartı Denize Atarsın ve bir Fide çağırırsın.","25+ birimin öldüğünde ya da kartın Denize Atıldığında.","Bu lanetli topraklar Maokai'yi yıldırmayacaktı. Treant'ın bağlılığı o kadar derin, öfkesiyse o kadar şiddetliydi ki hiçbir şey önünde duramazdı.","Birim",[],["Gölge Adalar"],"Şampiyon"],"02SI007":["Dikenli Kurbağa","Son Nefes: 2 kartı Denize Atarsın ve Nexus'unu 2 iyileştirirsin.","","''...inanılmaz bir tür... çocukken bulduğum yaratığın aynısı... bile yaşlanmamış! Acaba... sonraki şehre mi? Belki bu harika canlılar sonsuza dek yaşıyordur!''\n- Bulunmuş bir günlükten","Birim",[],["Gölge Adalar"],"YAYGIN"],"02SI003":["Dalgaların Dehşeti","Dost Deniz Canavarları Korkunç alır.\nSaldır: Düşmanlara bu tur -2|-0 verirsin.","","Tehlikeyi çok geç fark ettiler. Dev yaratık koca ağzını açıp onlara doğru hızla yüzdü. Sonsuz diş gemilerini parçalarken avcıların elinden sadece ölümü beklemek geldi.","Birim",["DENİZ CANAVARI"],["Gölge Adalar"],"DESTANSI"],"02SI001":["Yokkayran Koleksiyoncusu","Başka bir dost birim öldüğünde rakibin Nexus'una 1 Sömürü hasarı verirsin.","","''Bugün Niven'a rastlad... Yeni sandalcıymış! Bizi sandalıyla... götürdü. Sesi çok... Önce... yemeğe çağırmayı düşünüyorum.'' - Bulunmuş bir günlükten","Birim",[],["Gölge Adalar"],"ENDER"],"02SI002":["Heybetli Isırmaşık","Bir takipçi oynadığında, onu öldürüp bir Heybetli Isırmaşık çağırırsın.","","''Bugün... inanılmaz bir... daha karşılaştık... çocuklar korktu... ama tehlikeli değil... Elimize sürün... hemen güvendi. Onlara daha çok orman çileği toplamalıyım!''\n- Bulunmuş bir günlükten","Birim",[],["Gölge Adalar"],"DESTANSI"],"02SI004":["Marazlı Bakıcı","Oyna: Bir dost birimi öldürerek 2 Fide çağırırsın.","","''Her yürek köklerin büyüyebileceği bir bahçedir!''","Birim",[],["Gölge Adalar"],"ENDER"],"02SI006":["Kabuk Canavarı","İlk defa bir dost birim öldüğünde +2|+2 kazanırım.","","Gölge Adalar'ın yaratıkları duygusallığı uzun zaman önce bir kenara bıraktı. Sonuçta beslenmek zorundalar.","Birim",[],["Gölge Adalar"],"YAYGIN"],"02SI009":["Fide Atışı","Sonraki Tur Başında 1 adet Fide çağırırsın.","","''Hihiiiiii!''\n- Fide","Büyü",[],["Gölge Adalar"],"YAYGIN"],"02IO008":["Ses Dalgası","Bir dost birime bu tur Rakipçeker verirsin.\nElinde Geçici bir Titreşim Darbesi oluşur.","","''Kendine hâkim olursan...''\n- Lee Sin","Büyü",[],["Ionia"],"YAYGIN"],"02IO002":["Ejderin Pulları","Çağrıldığımda elinde bir Ejderin Koruması oluşur.","","''Öğrenci şefkatli olmalıdır çünkü İlk Diyar'a da Ejder şefkat göstermiş, ona sıcaklık ve yaşam bahşetmiştir.''\n- Ejder Öğretileri","Birim",[],["Ionia"],"YAYGIN"],"02IO006":["Lee Sin","Bir büyü oynadığında bu tur Rakipçeker alırım.\nBir büyü daha oynarsan, bu tur Bariyer alırım.","8+ büyü oynadığında.","''Ejder çabasına değenlere yardım eder. Yorgunlara takat verir. Hastaları teselli eder. Kaybolanlara ışık verir. Çalkantılı ruhlara ise denge...''","Birim",[],["Ionia"],"Şampiyon"],"02IO004":["Ejderin Boynuzları","","","''Öğrenci tüm gücüyle çaba göstermelidir çünkü Ejder toprağı dalgaların altından çekip çıkararak bize yuva olacak bir ülke yapmıştır.''\n- Ejder Öğretileri","Birim",[],["Ionia"],"YAYGIN"],"02IO003":["Ejderin Gözü","Tur Başı: Akış: Bir Ejder Yavrusu çağırırsın.","","''Öğrencinin zihni berrak olmalıdır çünkü Ejder, güneşi göğümüzde baştan başa çekerek bizlere dünyayı gösterir.''\n- Ejder Öğretileri","Birim",[],["Ionia"],"DESTANSI"],"02IO001":["Ejderin Pençeleri","Ben elindeyken, bir turda 2 büyü oynadığında beni çağırırsın.","","''Öğrenci çok dikkatli dinlemelidir çünkü ilk sesleri Ejder, kükremesiyle yapmış ve genç ruhlarımıza sihri bahşetmiştir.''\n- Ejder Öğretileri","Birim",[],["Ionia"],"YAYGIN"],"02IO005":["Avuç Darbesi","Bir düşmanı Sersemleterek bir Ejderin Kuyruğu çağırırsın.","","''Ne gittiğimi gördün ne dönüşümü göreceksin.''\n- Ejderin Kuyruğu","Büyü",[],["Ionia"],"ENDER"],"02IO010":["Geri Çekil","Bir dost birimi Geri Göndererek elinde Geçici bir Dön oluşturursun.","","Ionia sahillerine çıkan ilk Noxus'lular karşılarında zayıf ve hazırlıksız bir düşman buldular. Sayısız kişi katledildi ama ufak bir kısmı kaçıp güvenliğe ulaşmayı başardı...","Büyü",[],["Ionia"],"ENDER"],"02IO007":["Ejderhanın Gazabı","Bir dost birim, bir düşmana tekme atarak önce düşmana, sonra rakibin Nexus'una vuruş yapmış olur.\nDüşman sağ kalırsa onu Geri Gönderirsin","","''Ejder serbest kalmalı; yoksa beni için için tüketecek.''\n- Lee Sin","Büyü",[],["Ionia"],"DESTANSI"],"02IO009":["Derin Meditasyon","Akış: Bedelim 2 azalır.\nBaşka 2 büyü çekersin.","","Meditasyon bitişi olmayan bir yolculuk, sadece kaybolarak takip edilebilen bir yoldur.","Büyü",[],["Ionia"],"ENDER"],"03NX019":["Zayıfları Avla","Rakibin elindeki En Güçsüz takipçiyi atar.","","''Zayıflara bu dünyada yer yok. Her gün daha çok eziyet çekiyorlar, cendereye daha çok sıkışıyorlar. Ben ölüm değil, merhamet dağıtıyorum.''\n- İz Sürücü Arrel","Büyü",[],["Noxus"],"ENDER"],"03NX022":["Yabani Pençeler","Bir dost birim bir düşmana vurur. Aban tesiri varsa, artan hasarı rakibin Nexus'u alır.","","''Ooo, yaban adamı bugün her zamankinden de yabani! O pençelere sakın yaklaşmayın ha!''\n- Arena Savaşı Yorumcusu","Büyü",[],["Noxus"],"DESTANSI"],"03NX007":["Riven","Çağrıldığımda saldırı hakkı sendeyse ya da saldırı hakkı sana geçtiğinde, Yeniden Döversin.","Sürgün Kılıcı'nı oluşturduğunda.","''Eski kimliğimden kaçmayacağım. Kırdıklarımı tamir etmeye söz verdim...''","Birim",[],["Noxus"],"Şampiyon"],"03NX006":["Silah Kabzası","Bir dost birime bu tur +2|+0 verirsin. Yeniden Döversin.","","''Düşmanını tanımak için önce silahını tanımalısın. Nasıl hareket ettiğini, nasıl düşündüğünü, ne zaman saldıracağını silahı gösterir. Sahibinin eksiksiz bir açıklamasıdır.''\n- İz Sürücü Arrel","Büyü",[],["Noxus"],"YAYGIN"],"03NX002":["İz Sürücü Arrel","Tur Sonu: Bu tur benim üzerimde bir büyü oynadıysan, En Güçsüz düşmana vururum.","","''Saklan, buluruz.\nNefes al, duyarız.\nKaç, öldürürüz.''","Birim",[],["Noxus"],"DESTANSI"],"03NX018":["Derdest Et","Bir düşmanı Sersemletirsin.\nSende bir Darius varsa, Silahlanırsın.","","''Bu işi bizzat ben çözeceğim.''\n- Darius","Büyü",[],["Noxus"],"ENDER"],"03NX009":["Haşin Süvari","","","''Başka bir askerin peşinde olmak gibisi yok. İzini sürmek için onun gibi düşünüp hissetmelisin. Yakalamak için onun senden korktuğu gibi sen de ondan korkmalısın. Çok az kişinin tadacağı ama benim hepsinden çok sevdiğim bir bağ.''","Birim",[],["Noxus"],"YAYGIN"],"03NX017":["Basilisk Kan Avcısı","Oyna: Bir dost birime ve bir düşmana 4 kere 1 hasar verirsin.","","Basilisk eğitmenleri, savaştan önce bu hayvanları aç bırakır. Serbest kaldıklarında dost düşman ayırt etmezler ve söz geçirmenin imkânı olmaz.","Birim",["SÜRÜNGEN"],["Noxus"],"DESTANSI"],"03NX015":["Hayatta Kalma Becerisi","Dost birimlerin Canı bu tur 1'in altına düşemez.\nAtıldığında, En Güçlü dost birimin Canı bu tur 1'in altına düşemez.","","''Ejderanlar kokuyu aldı. Onu bulacaklar. Biz de işi bitireceğiz. Başka yolu yok.''\n- İz Sürücü Arrel","Büyü",[],["Noxus"],"ENDER"],"03NX014":["Bilenmiş Azim","Bir dost birime bu tur +3|+2 verirsin.","","''Erath silahları tamir etsin, hayvanlara baksın, zıkkımlanın diye size yemek pişirsin zaten, başka ne işe yarar değil mi?''\n- Savaş Uşağı Erath","Büyü",[],["Noxus"],"YAYGIN"],"03NX003":["Savaş Uşağı","Son Nefes: Yeniden Döversin.","","''Avcıların dediği gibi, yüz gün yüz gece gittik. Ayaklarım yüz yerinden su topladı, kahvaltıma yüz böcek düştü, yüz kere 'intikam'mış, 'kılıç'mış bunları dinledim. Ağzımın payını da yüz kereden fazla verdiler, söylemeden duramam...'' ","Birim",[],["Noxus"],"YAYGIN"],"03NX001":["Ründokuyan","Çağrıldığımda Yeniden Döversin.","","''Çoğu silahlar kaba saba aletlerdir. Onları kullananlara da öylesi yakışır. Ama rün büyüsü yedirilmiş bir silah, çelikten çok daha ötesidir.''","Birim",[],["Noxus"],"YAYGIN"],"03NX005":["Gaddar Avcı","Çağrıldığımda bu tur İlk Saldırı alırım.","","''Bulduk seni. Dövüşmeden gelmeyeceğini BİLİYORDUK. Ya da umuyorduk.''","Birim",[],["Noxus"],"ENDER"],"03BW006":["Hep Kazanan Jack","Tur Başı: Elinde bir Balıkların Yanına oluşur.","","Jack, boks ringinde geçirdiği yıllardan kıymetli dersler aldı. Düşmanının kanı akıyorsa korkabiliyordu da. Sessiz, sert bakışların gücünü öğrendi. Bir de kontrolsüz şiddetin gücünü.","Birim",[],["Bilgewater"],"DESTANSI"],"03BW010":["Mükellef Sofra","Bir dost birim, diğer bir dost birimi Zapt Eder ve zapt ettiği dost birimin niteliklerini kazanır.","","''İçeri buyur dostum. Buyur ki tüm istediklerin mütemadiyen senin olsun.''\n- Tahm Kench","Büyü",[],["Bilgewater"],"YAYGIN"],"03BW005":["Batık Yatırım","Bir birim ya da Yer kartını destesine koyarsın.","","''Sana istediğini tamı tamına verdim arkadaşım. Ama sonsuza dek sende kalacak demedim.''\n- Tahm Kench","Büyü",[],["Bilgewater"],"ENDER"],"03BW004":["Tahm Kench","Çağrıldığımda ya da Tur Başı: Elinde bir Tadımlık oluşur.","3+ birim Zapt Ettiğimde. Seviye atladığımda, Zapt Ettiğim düşmanların Kökünü Kazırım, dost birimleri ise serbest bırakırım.","''Yüzündeki o ifadeyi iyi bilirim dostum. Elindeki kartlar hak ettiğin asıl kartlar değil gibi bakıyorsun. Hayattan kâm almak istiyorsun, değil mi? Gel açlığını doyurayım, sana hak ettiğin her şeyi tattırayım. Adını şuracığa, şu kâğıda karalayıversen yeter dostum. Ondan sonra hayatını doya doya yaşayacaksın.''","Birim",[],["Bilgewater"],"Şampiyon"],"03BW002":["Keyif Kertenkelesi","Tur Başı: Bana 2 hasar verirsin.","","''İnsanlar aptaldır aptal! Ver sıcak oturak, soğuk içecek, dökülürler tüm sırlarını bir güler yüze. Leonard da güler yüzlüdür ha!''\n- Madam Kurbella","Birim",[],["Bilgewater"],"YAYGIN"],"03BW014":["Maymunluk","Bir Barut Maymunu çağırırsın.\nYağma: Sonraki Tur Başı bir daha çağırırsın.","","''Sevimli ha? SEVİMLİ HA? Her yere giriyorlar, deniz tutmuş bir haberciden daha çok pislik çıkarıyorlar, BİR SANİYE DE SUSMUYORLAR. GEMİYE MAYMUN FALAN ALMAK YASAK, O KADAR.''\n- Gemi Astsubayı","Büyü",[],["Bilgewater"],"YAYGIN"],"03BW007":["Bokstapot","Oyna: Bana 3 hasar verirsin.","","''Şimdi kar'şim bizim Pablo tabii son zamanlarda biraz kurudu kaldı tabii (heh). İyi dayak yedi herif. Ama ondan başka sekizde sekiz yapabilen kim var?''\n- İskele Babası","Birim",[],["Bilgewater"],"YAYGIN"],"03BW016":["Patlama Gemisi","Bir birime 1 hasar verirsin.\nVerdiğin hasar kadar Barut Fıçısı çağırırsın.","","''İlki patlamadan bizim delikanlı Gerent alarm verdi. Pruvamız sallandı, flok yelkeni alev aldı ama Karakanat batmadı. Bitti sandık ama Gerent'in baktığı yere bakınca ne göreyim? Barut dolu bir sürü filika üstümüze geliyor!''\n- Karakanat'tan\nsağ kurtulan denizci","Büyü",[],["Bilgewater"],"ENDER"],"03BW001":["Katliam Limanı","Tur Başı: 1 kartı Denize Atarsın. Derin olduysan beni yok edip rasgele bir Deniz Canavarı çağırırsın.","","Bilgewater yerlileri her gün Katliam Limanı'nda gezinerek avcıların denizin derinliklerinde yakaladığı dehşetengiz canavarlara bakar. Canavarlar genellikle ölü olur. Genellikle...","Yer",[],["Bilgewater"],"DESTANSI"],"03BW015":["Morarık Moruk","Oyna: Bana 2 hasar verirsin.","","''ŞU ZİLİ ÇALIN DA HÜRMETSİZ ZIPÇIKTIYA UNVANLARIMI NASI' ALDIĞIMI GÖSTEREYİM LEN! OĞLUM BANA 'SEKİZYUMRUK PABLO' DERLER! 'KAFA KIRAN KRAKEN' DERLER! 'DOKUNAÇLI DEHŞET' DERLER! BİRAZDAN ELİM UF OLDU DİYE AĞLAYARAK ANANIN YANINA KAÇACAKSIN!''\n- Bokstapot","Birim",[],["Bilgewater"],"YAYGIN"],"03BW003":["İskele Babası","Oyna: Tüm diğer dost birimlere 1 hasar verirsin ve hasar verdiğin her dost birim için +1|+0 kazanırım.","","Nüfuz sahibi olmak için genellikle şiddete başvurmak gerekir... ama bu kadar da su sıçratılmaz be kardeşim.","Birim",[],["Bilgewater"],"ENDER"],"03BW017":["Tombiş Balonbalığı","Bu oyunda oynadığın her büyü için bedelim 1 azalır.\nÇağrıldığımda, elinde bölgelerine ait 1 manalık rasgele bir büyü oluşur.","","''Dik duy bakim çayyak! Göyevin dümşman hatlayının aykasına sızıp patlatabildiyin kaday balon patlatmak! Göydüyün HEY şeyi bize AN-LA-TI-CAN-SIN! Anlaşıydı mı?''\n- Amiyal Shelly, Çarpanbağa","Birim",[],["Bilgewater"],"DESTANSI"],"03BW008":["Madam Kurbella","Oyna: Bana ve bir dost birime 1 hasar verip 1 kart çekersin.","","'İhtiyar Kurbiş'in bir iki falsosu olmuş tabii. Vaktiyle buralı bir iki kişiyi öldürmüş. Ama olsun, böylece daha gerçekçi bir hali oluyor.''\n- Keyif Kertenkelesi","Birim",[],["Bilgewater"],"YAYGIN"],"03BW020":["Barut Curcunası","Bu oyunda Yağma'yı etkinleştirdiğin her sefer için bir Barut Maymunu çağırırsın.","","''Bu kurum yumakları iyidir ya. Bak sana bir tüyo vereyim; havai fişek gibidirler. Yani düşmanının barut stoğunu dağıtırsan, maymunlar gerisini halleder.''\n- Miss Fortune","Büyü",[],["Bilgewater"],"DESTANSI"],"03BW009":["Tartakla","Bir dost birime 2 hasar vererek 2 düşmana Kırılganlık kazandırırsın.","","''O 'yedek fıçıları' nereden bulduğunu söyle bence Slim kardeşim. Yoksa o dilini Jimbo'ya veririm, halat çekmece oynamaya başlar. Kazanan da sen olmazsın söyleyeyim.''\n- İskele Babası","Büyü",[],["Bilgewater"],"ENDER"],"03DE010":["Büyük Meydan","Bir dost birim çağrıldığında ona bu tur +1|+1 ve Rakipçeker verirsin.","","Tianna toplanmış asker kalabalığını inceledi. Duyulan tek ses, sancağın rüzgârda dalgalanışıydı. Kısa bir baş hareketiyle onayını gösterdi, sonra sancağı bir narayla kaldırdı. ''Kimler Demacia uğruna savaşmaya hazır?'' Askerlerin bağırışları, yeri göğü inletti. ","Yer",[],["Demacia"],"DESTANSI"],"03FR009":["Sonsuz Uçurum","Tur Başı: Elinde, destende ya da oyunda olmayan rasgele bir 2. seviye şampiyon elinde oluşur.","","Kahramanlar bu köprüye, dünya ötesinden gelen çağrılara kulak vererek ulaşır. Ezici soğuğundan ve paramparça taşlarından kurtulabilenler, bitiminde ya ölümü görür ya da zaferi.","Yer",[],["Freljord"],"DESTANSI"],"03MT005":["Ayrılan Yollar","Bir Yer kartı çeker ya da yok edersin.","","Targon'un sağı solu belli olmaz. Yıkılmaz denenler bel verir, yıkılmışlar yeniden ayaklanır.","Büyü",[],["Targon"],"YAYGIN"],"03SI009":["Helia Mahzenleri","Tur Başı: En pahalı dost birimini öldürebiliyorsan öldürerek, destenden bedeli ondan 1 fazla olan başka bir kart çağırırsın.","","Talihsiz ruhları bu sefil yere çekmek için sonsuz yaşam ve bitmez tükenmez zenginlik vaatlerinden daha iyisi olamaz.","Yer",[],["Gölge Adalar"],"DESTANSI"],"03IO006":["Hirana Manastırı","Tur Başı: Elinde bir Himaye oluşur.","","Dengelerini bulmak ve moral toplamak isteyenler için Ionia dağlarında kimi sığınaklar gizlidir.","Yer",[],["Ionia"],"DESTANSI"],"03NX013":["Yak Yık","Hasar almış bir birimi öldürür ya da Yer kartını yok edersin.","","''Ejderanlar kokuyu aldı. Onu bulacaklar. Biz de işi bitireceğiz. Başka yolu yok.''\n- İz Sürücü Arrel","Büyü",[],["Noxus"],"YAYGIN"],"03NX004":["Noxkraya Arenası","Tur Sonu: En Güçlü dost biriminle En Güçsüz düşman birbirine vurur.","","''Sellaam Hesaplaşma fanatikleri! Arenayı KASIP KAVURACAK bir ATEŞ ÇEMBERİ gecesine hazzır mısınııız? Eyvah, Minik Trik'in şansı bu gece ona gülmüyor! Kafa kesen, kelle koparan, kapı gibi DEV GRANAK'ın karşısına çıkacak! Sağlıkçılar, yerinizi alın, bu savaş kısa sürecek!''\n- Arena Savaşı Yorumcusu","Yer",[],["Noxus"],"DESTANSI"],"03DE004":["Yüzbaşı Arrika","Oyna: Bir birimi ya da Yer kartını Zapt Edersin.","","Çocukluğunda memleketi yerle bir olan Arrika, Noxus'un yıkıcılığını gözleriyle gördü. Orduya katıldığında Noxus bayrağını Demacia topraklarında bir daha asla dalgalandırmayacağına ve hiçbir çocuğu yetim bırakmayacağına yemin etti.","Birim",["SEÇKİN"],["Demacia"],"ENDER"],"03IO005":["Evin Dönüşü","Önce bir dost birimi ya da Yer kartını Geri Gönderirsin, sonra bir düşman birimi ya da Yer kartını Geri Gönderirsin.","","''Trevoorrr, geri dönnnn...''\n- Trevor'un evi","Büyü",[],["Ionia"],"YAYGIN"],"03MT052":["Yıldız Pınarı","Tur Sonu: Hasar almış dost birimleri 1 iyileştirirsin. Ardından, dost birimleri 22+ iyileştirdiğini gördüysem oyunu kazanırsın.","","''Kutsal suyun akışından,\nDerin havuzlara, şifalı sulara\nGör parlayan suların ışığını,\nDinle nehrin şarkısını,\nKristal dağın doruğunda.''\n- Ottrani şiiri","Yer",[],["Targon"],"DESTANSI"],"03MT064":["Targon'un Doruğu","Tur Başı: TÜM oyuncuların elindeki rasgele birer kartın bedeli bu tur 0'a düşer.","","Semavi Âlem'e açılan kapının önünde Targon'un kristal muhafızı durur. Onun huzurunda umut, kuşku, korku var olamaz. Sınavları tüm fani kaygıları alıp götürür, tırmanıcının ruhunun özü neyse apaçık ortaya çıkarır. Tırmanıcı buna göre yargılanır çünkü en yüce yargıç bu muhafızdır. ","Yer",[],["Targon"],"DESTANSI"],"03SI008":["Ufalan","Bir birimi öldürmek ya da Yer kartını yok etmek için bir dost birimi öldürürsün.","","Bu lanetli adalarda hiçbir şey uzun sürmez. Her şeyin sonu gelir.","Büyü",[],["Gölge Adalar"],"ENDER"],"03PZ001":["Piltover Üniversitesi","Tur Başı: Elindeki tüm kartları atarsın. Elinde 3 rasgele kart oluşur ve onlara Geçici kazandırırsın.","","Profesör Cecil B. Heimerdinger icatları sayesinde ünlü olmuştu ama onu Piltover'ın en parlak zihinlerine müthiş bir canlılıkla anlattığı dersler ve sonunun nasıl geleceği belli olmayan deneyleri kazıdı.","Yer",[],["Piltover ve Zaun"],"DESTANSI"],"03FR003":["Bakan Ölüm","Oyna: TÜM Yer kartlarının Kökünü Kazırsın ya da TÜM diğer birimlere 3 hasar verirsin.","","''Eşyamızı toplayacak, kimseyi uyaracak vaktimiz olmadı. Ormana kaçıp evlerimizi yıkmasını seyredebildik sadece.''\n- Avarosa Köy Muhafızı","Birim",[],["Freljord"],"ENDER"],"03MT026":["Gün Mızrağı Rahvun","Şafak: Elinde rasgele bir Şafak kartı oluşur.\nBizim için her zaman Gündüz'dür.","","''İnancınızdan şaşmazsanız ışığımız asla sönmez\nRa-Horaklar!''","Birim",[],["Targon"],"ENDER"],"03MT067":["Kristal Dağ Keçisi","Oyna: Bir dost birime Aban kazandırırsın.","","Targon'a çıkmayı düşünenler, dağın hayvanlarıyla dost olmalı. Targon'un tehlikeli yamaçlarını daha iyi tanıyan, buzlu yollarında daha hızlı ilerleyebilen başka varlık yoktur.","Birim",[],["Targon"],"YAYGIN"],"03MT084":["Yıldızyapan","Bedeli 7+ olan bir Semavi karta Yakarırsın, ardından bir dost birimi ya da Nexus'unu 5 iyileştirirsin.","","''Yıldızlara bak. Talihin varsa ben de sana bakarım.''\n- Aurelion Sol","Büyü",[],["Targon"],"YAYGIN"],"03MT221":["Sivri Dişler","Oyna: Bedeli 3 ya da daha az olan bir Semavi karta Yakarırsın.","","''Ay Ana, bana yol göster,\nGökyüzünü yırt aç,\nÖte âlemi göster.''\n- Lunari duası","Birim",[],["Targon"],"DESTANSI"],"03MT093":["Uçarı Yıldız","Bu tur saldırmış ya da Sersemlemiş olan bir düşmana 5 hasar verirsin.","","''DuBUFFFŞŞŞŞ!''\n- Zoe","Büyü",[],["Targon"],"YAYGIN"],"03MT073":["Lunari Akşamgetiren","Çağrıldığımda elinde bir Akşamçiçeği Tozu oluşur.","","''Akşamçiçekleri sadece geceleri, o da dolunay varsa açar. Lunariler olarak gurur duyduğumuz bir simge. Tozunu hasat etmeyi sadece biz bildiğimizden, yüzyıllardır kullanıyoruz.''","Birim",[],["Targon"],"YAYGIN"],"03MT002":["Gök Yıkılırken","Sahip olduğun her dost Ejder ya da Semavi birim için bedelim 2 azalır. Tüm düşmanlara 15 hasar verirsin.","","''Sonunda o zaman gelip çattığında Runeterra ibretlik olacak. Belki yanık cesedini sonsuza kadar yanımda taşırım. Oyuncak gibi. Cansız, değersiz bir oyuncak gibi. Bilemiyorum. Ayrıntılı düşünmedim.''\n- Aurelion Sol","Büyü",[],["Targon"],"DESTANSI"],"03MT217":["Aphelios","Akşam: Seçtiğin bir Ay Silahı elinde oluşur.\nHer tur ilk defa başka 2 kart oynadığında, Ay Silahın yoksa Geçiş Yaptığın silah elinde oluşur.","4+ Ay Silahı oynadığında.","''Her çatışmada, Solarilere saygıya layık olduğumuzu gösteriyoruz. Onlara ayın ışığının güneşlerininkiyle eşit olduğunu öğrettik, bilmedikleri şeyleri yabana atmamayı öğrettik. Daha alacakları çok ders olduğunu da...''\n- Lunari Karanlıksöyleyen","Birim",[],["Targon"],"Şampiyon"],"03MT044":["Güneş Muhafızı","Şafak'ta veya başka bir Şafak etkinleştirdiğinde: Bana +1|+1 kazandırırsın.","","''Işık saçan muhafız! Gazabın öğlen güneşi gibi kavurur. Gel de bu mukaddes yere izinsiz gelenlere cezalarını ver.''\n- Güneş Muhafızı'nın üzerine kazılı yazı","Birim",[],["Targon"],"DESTANSI"],"03MT056":["Diana","Akşam olduğunda ya da başka bir Akşam etkinleştirdiğinde: Bu tur Rakipçeker alırım.","Akşam'ı 4+ kere etkinleştirdiğinde.","Aralarında durup savaşa hazırlandı. Mavilere ve gümüşe bürünmüştü. Işık saçıyordu. Gözleri yıldız gibi parlıyordu. Ay doğup onu ışığıyla yıkarken, oradaki tüm Lunariler gözlerini kapayarak içlerinden onun güvende olmasını dileyip şükürlerini sundular.","Birim",[],["Targon"],"Şampiyon"],"03MT020":["Işıltılı Gökboynuz","Oyna: Bir dost birimi ve Nexus'unu 3 iyileştirirsin.","","''Gökyüzünde ilerleyen şu yıldızı görüyor musun? İşte o yetişkin bir gökboynuz. Yavrular gökyüzüne dönecek kadar büyüyene dek şifa büyülerini bize ödünç verir. Yetişkin gökboynuzlarsa güçlerini kendileri kullanır. Gökboynuz görüp ne olduğunu anlamak uğurludur derler. Gökboynuzlara bakmaksa daha bile uğurludur.''\n- Yıldız Bakıcısı Lidari","Birim",[],["Targon"],"YAYGIN"],"03MT091":["Çok Havalı Yıldız Haritası","Bedeli 3 ya da daha az olan bir Semavi karta Yakarırsın.","","''Bu ÇOK parlak yıldızlara da... 'Göksel Atlama İpi' adını taktım! Yoksa baş aşağı çizilmiş bir gülen yüze mi benziyorlar?''\n- Zoe","Büyü",[],["Targon"],"ENDER"],"03MT047":["Ay Gölgesi Cygnus","Akşam: Bir dost birime bu tur Sıyrılgan verirsin.","","Lunariler geceyi ve sağlayacağı korumayı bekledi. Yolları bomboş görünüyordu ama Cygnus, Solari kampının hemen ileride olduğunu biliyordu. Bir işaretiyle herkes arkasında tek sıra oldu.","Birim",[],["Targon"],"DESTANSI"],"03MT094":["Lunari Gölgegezen","Akşam: Sıyrılgan kazanırım.","","''Gözlerimizi semaya, güneşe, hanımımızın ışı... Bir dakika. O... O da ne?''\n- Solari Rahip","Birim",[],["Targon"],"YAYGIN"],"03MT036":["Targon'un Lütfu","Bir dost birime +3|+3 kazandırırsın.","","''Targon'un lütfu bizimle.''\n- Taric","Büyü",[],["Targon"],"ENDER"],"03MT092":["Dağ Keçisi","Vuruş: Elinde bir Mücevher oluşur.","","Targon Dağı'nın keçileri, sıradan akrabalarından çok daha tehlikeli. Tos attıklarında mücevherden boynuzları kırılıyor ve parçalar çarptıkları yere saplanıyor. ","Birim",[],["Targon"],"ENDER"],"03MT060":["Sağlam Sırtlı Koruyucu","Tur Başı: Nexus'unu 3 iyileştirirsin. Bana, iyileştirdiğin miktar kadar hasar verirsin.","","''Targon yollarını en iyi ben bilirim. O yüzden en... eee... dikbaşlı gökboynuzlar bana kalıyor. Neyse ki onları ben kolluyorum!'' ","Birim",[],["Targon"],"DESTANSI"],"03MT001":["Hınzır Kakımkanatlar","Oyna: Güç değeri 2 ya da daha az olan düşmanları Sersemletirsin.","","Dağın billur sessizliğinde birden düşen buzların tıngırtısı ve onların çok yukarısından da yolcuların... kıkırdama sesleri olduğuna yemin edebileceği bir şeyler duyuldu.","Birim",[],["Targon"],"YAYGIN"],"03MT055":["Soraka","Destekle: Beni ve desteklediğim dost birimi 4 iyileştirirsin.","Hasar görmüş dost birimleri 4+ defa iyileştirdiğinde.","''Şifa vermek temelinde özverili bir hareket. Kimseden güç almana gerek olmaz, kendileri seve seve verirler. Birine şefkat gösterdiğinde pırıl pırıl parladığını göreceksin.''","Birim",[],["Targon"],"Şampiyon"],"03MT048":["Hediye Veren","Çağrıldığımda elinde bir Mücevher oluşur.","","''Bu mücevherleri Muhafız kutsamış diyorlar. Onları takarsan ruhen yanında olur.''","Birim",[],["Targon"],"YAYGIN"],"03MT082":["Sabah Işığı","Dost birimlere bu tur +1|+1 verirsin.\nBir dost birimin Şafak'ını etkinleştirirsin.","","''Gün doğumunda kalkacağız! Işığın içine ilerleyeceğiz!''\n- Leona","Büyü",[],["Targon"],"ENDER"],"03MT058":["Taric","Destekle: Bana ve desteklediğim dost birime bu tur Dayanıklı verirsin. Bu tur senin oynadığın, sadece beni hedef almış olan son büyü o dost birime kopyalanır. (Tekrar kopyalanamaz.)","Dost birimleri 7+ kere hedeflediğini ya da Desteklediğini gördüğümde.","''Taric'in iyiliği ve anlayışlılığı onu tanıyan herkese ilham veriyor. Onları, en soğuk gecelerde bile kendi içlerindeki sıcaklıkla ısınmaya teşvik ediyor.''\n- Dağ Kâhini","Birim",[],["Targon"],"Şampiyon"],"03MT062":["Kikirdek Pırıltı Uzmanı","Oyna: Semavi bir karta Tanıklık etmişsen, bir dost birime +1|+1 ve Büyü Kalkanı kazandırırsın.","","''...ışıltıböcekleri aynı yere dökülüp sonra yine uçan yıldız tozları gibi çok aşırı süper güzeller dün akşam gördüm neyse şimdi çok acıktım sonra da ışıltıböceği yine TAAAA yıldızlara kadar uçunca...''","Birim",[],["Targon"],"ENDER"],"03MT040":["Işıltıböceği","","","''Umut uçtukça yükselen ve asla yakalanmaması gereken narin bir şeydir.''\n- Lunari Rahibe","Birim",[],["Targon"],"YAYGIN"],"03MT086":["Göğe Bakan Ressam","Oyna: 1 kart atarak bedeli 3 ya da daha az olan bir Semavi karta Yakarırsın.","","''Bak en sevdiğim bu. Adı 'Bilinç Durumundaki Psişenin Metafizik Kimliği'. Ama kafanı şöööyle çevirince iki kaşığa benziyor.''","Birim",[],["Targon"],"ENDER"],"03MT016":["Ürkmüş Kozmik Fil","","","''Yaa, koca fil kaydeş küçük geçitten geçmek istemiyoy muymuş? Olur, geçme... HAHAHA kandırdım HADİ GİDİYORUZ HOOOPPAAA!''\n- Zoe","Birim",[],["Targon"],"YAYGIN"],"03MT054":["Leona","Şafak: En Güçlü düşmanı Sersemletirsin.","Şafak'ı 5+ kere etkinleştirdiğinde.","Aralarında durup savaşa hazırlandı. Kızıllara ve altına bürünmüştü. Işık saçıyordu. Gözleri kor gibi parlıyordu. Doğan güneş başını bir haleyle taçlandırırken, oradaki tüm Solariler gözlerini yere indirdi. Utançtan değil, ışıklı liderlerine saygılarından.","Birim",[],["Targon"],"Şampiyon"],"03MT220":["Çatallanan Yol","Akşam: Bir düşmanı Sersemletirsin. Sersemlettiğin bir takipçiyse, onu bir sonraki Tur Başında yine Sersemletirsin.","","''Ay Ana, çöktü akşamımız,\nİzin ver bize zarar verenleri durduralım,\nVe onlara pişmanlığı öğretelim.''\n- Lunari duası","Birim",[],["Targon"],"ENDER"],"03MT021":["Sonsuz Zihinbölen","Oyna: 2 düşman seçersin.\nTur Başı: Onları Sersemletirsin.","","Bu yaratığın gözlerine bakan yolcular öyle derin bilgiler edinir, öyle müthiş bir içgörüye ulaşırlarmış ki zihinleri un ufak olurmuş.","Birim",["EJDER"],["Targon"],"DESTANSI"],"03MT006":["Inviolus Vox","Her tur, Hiddet tesirine sahip bir dost birim bir düşmanı ilk öldürdüğünde elinde rasgele bir Ejder takipçi oluşur.","","''Göklere bakın, onları benim gördüğüm gibi görün! Önce işaretleri gelir. Geceleri ışık saçarlar. Sonra öfkeleri gelir. Gündüzleri yakarlar. Göreceksiniz! Hepimiz göreceğiz!''\n- Ejderlerin Habercisi","Birim",["EJDER"],["Targon"],"DESTANSI"],"03MT015":["Sonsuzluğa Bakış","Yakarırsın.","","Sema başının üzerinde yıldızlarla aydınlanmış siyah bir nakış gibi uzanıyor. Enginliğinin karşısında küçücük ve sönük kalıyorsun. Önce nereye bakacaksın?","Büyü",[],["Targon"],"YAYGIN"],"03MT013":["Ay Işığı İlleti","Bu tur 2 düşman birimi Susturursun.\nAkşam: Bu birimler bu tur karşılayamaz.","","''Ay ışığına alışık olmayanlar onunla görmeyi öğrenmelidir, yoksa hiçbir şey göremez olurlar.''\n- Diana","Büyü",[],["Targon"],"YAYGIN"],"03MT009":["Zoe","Nexus Vuruşu: Elinde bir Çok Havalı Yıldız Haritası oluşur. Zaten varsa, bedeli 1 azalır.","Farklı adı olan 10 kart oynadığını gördüğümde.","''Merhabaaa n'apıyosun? Neeee KART OYUNU MU BU? Ben de oynayabilir miyim? Hı? Zaten senin oyununun mu içindeyim? Hehe, ne saçma boyut ya...''","Birim",[],["Targon"],"Şampiyon"],"03MT087":["Aurelion Sol","Oyna: Bedeli 7 ya da daha fazla olan bir Semavi karta Yakarırsın.\nTur Başı: Elinde rasgele bir Semavi kart oluşur.","Tur Sonu: Dost birimlerin Güç değeri 20+ olduğunda.","''Benim hakkımda ne yazdığın umurumda mı sanıyorsun vasat insan! Beni yakışıklı olarak anlat yeter. Bir de haşmetli. Bir de çok, çok zeki. Bunları doğru imlayla yazmayı biliyor musun?''","Birim",["EJDER"],["Targon"],"Şampiyon"],"03MT019":["Kristal Siper","Bir dost birime +1|+1 ve Büyü Kalkanı kazandırırsın.","","''Dağı gururlandır.''\n- Taric","Büyü",[],["Targon"],"YAYGIN"],"03MT214":["Uçuş","Nexus Vuruşu: 1 kart çekersin ve beni destenin en üstündeki 3 kartın arasına koyarsın.","","''Ay Ana, bana itikat ver,\nİçimi Uçuş'un güveniyle doldur,\nBeni doğru yollara çıkar.''\n- Lunari duası","Birim",["KUŞ"],["Targon"],"ENDER"],"03MT071":["Gezgin Tyari","Destekle: Desteklediğim dost birim +0|+2 kazanır.","","Seyahat eden, yolun getirdiklerine açık olmalı. Yol insanı istemese de değiştirir. Seyahat eden yanında yeni bir şey götürür... ve eski kendisinin bir kısmını geride bırakır. ","Birim",[],["Targon"],"YAYGIN"],"03MT008":["Dilek","Hasar almış dost birimleri tamamen iyileştirirsin.","","''Hayat bul!''\n- Soraka","Büyü",[],["Targon"],"ENDER"],"03MT023":["Güneş Patlaması","Bir birime 6 hasar verirsin.\nŞafak: Bunun yerine bu tur o birimi Susturursun ve ona 6 hasar verirsin.","","Güneşinki gibi dimdik bakışların altında pek az şey sağ kalabilir.","Büyü",[],["Targon"],"ENDER"],"03MT045":["Astral Koruma","Bir dost birimi 4 iyileştirip ona +0|+4 kazandırırsın.","","''Bizi yendiğini mi sandın? Hah! Daha yeni başlıyoruz.''\n- Sağlam Sırtlı Koruyucu","Büyü",[],["Targon"],"YAYGIN"],"03MT080":["Pınar Bekçisi","Çağrıldığımda elinde bir Pınarın Hediyeleri oluşur.","","''Ben genellikle pınarlarla ilgilenirim ama çoban olarak başlıca sorumluluğum sürüm. Bazen önceliklerin uyuşmadığı oluyor.''","Birim",[],["Targon"],"YAYGIN"],"03MT042":["Büyü Hırsızı","Bu oyunda oynanmış bir düşman büyüsü Cisimlenir.","","''Yaa ne güzel yaptıııııııııııııııııınnn! Ama tabii ben yapsam çok daha güzel olurdu. Neysehoşçakalgörüşürüzbaybay!''\n- Zoe","Büyü",[],["Targon"],"ENDER"],"03MT057":["Solari Gündöven","Şafak: Bana bu tur Can Çalma verirsin.","","Odaya ışık dolarken Gündöven odağını bozmadı. Büyülü Solari eşyasıyla, güneşin pırıl pırıl ışığını toplayıp silahı için bir tılsım haline getirdi.","Birim",[],["Targon"],"YAYGIN"],"03MT041":["Taşların Bilgesi","Destekle: Desteklediğim dost birim +2|+2 kazanır.\nSon Nefes: Elinde 3 Mücevher oluşur.","","''Söylediklerinden bir şey anladın mı?''\n''Tek kelime anlamadım. Ama iyi birine benziyordu.''\n- Emir ve Haley, Dağın Konukları","Birim",["YORDLE"],["Targon"],"DESTANSI"],"03MT027":["Ufuk Kılıcı","Bir dost birime +1|+2 kazandırırsın. Ona bu tur Aban verirsin.\nŞafak: Bir Ufuk Kılıcı çekersin.","","''Güneşin gücüyle efsunlan!''\n- Solari Rahibi","Büyü",[],["Targon"],"YAYGIN"],"03MT096":["Solari Rahibe","Şafak: Bedeli 4, 5 ya da 6 olan bir Semavi karta Yakarırsın.","","Solariler de diğer Targon'lular gibi yıldızların rehberliğine güvenir çünkü en büyük saygıyı gösterdikleri güneş de bir yıldızdır.","Birim",[],["Targon"],"ENDER"],"03MT028":["Solari Kalkancısı","Şafak: Bana bu tur +0|+4 verirsin.","","''Gece gelmemekle ahmaklık ettin.'' Kalkancı dikleşti. ''Silahlarını bırakıp karşı koymadan gel.''\nLunari ses çıkarmadan çömeldi, kıvrık kılıçlarını bir daha kaldırdı. \nÖyle olsun. \nSolari de hazırlandı. Doğan güneşin ışıklarını yansıtmak için kalkanını kaldırdı. ","Birim",[],["Targon"],"YAYGIN"],"03MT089":["Hilal Muhafızı","Akşam: +2|+0 kazanırım.","","''Çilekeş muhafız, dolunayın şefkatli dokunuşu gücünü yerine getirsin. Uyan da bizleri, bu kutsal yere izinsiz ayak basmak isteyenlerden koru.''\n- Hilal Muhafızı'nın üzerine kazılı yazı","Birim",[],["Targon"],"ENDER"],"03MT051":["Rehber Dokunuş","Bir dost birimi ya da Nexus'unu 2 iyileştirirsin. 1 kart çekersin.","","Gökboynuzlar en çok mutlu oldukları zaman ışık saçar.","Büyü",[],["Targon"],"YAYGIN"],"03MT003":["Ejderin Yumurtaları","2 farklı Ejder çekersin ya da dost Ejderlere +1|+1 ve Aban kazandırırsın.","","''Bağırışları, boğazı şiş kedi sesi gibidir. Duyarsanız derhal kaçıp en yakın muhafızı bulun. Anladınız mı? Ejder yumurtasının olduğu yerde ejder de olur.''\n- Targon'lu toplayıcı","Büyü",[],["Targon"],"ENDER"],"03MT098":["Güneş Zindeliği","Bir dost birime +0|+2 kazandırırsın.","","''Kalkanımız azmimizdir! Kararlılığımız, ışığa güvenimizdendir!''\n- Solari Kalkancısı","Büyü",[],["Targon"],"YAYGIN"],"03MT215":["Öte Âlemden Hediyeler","Seçtiğin bir Ay Silahı elinde oluşur.","","''Uzat elini, Aphelios.''\n- Alune","Büyü",[],["Targon"],"YAYGIN"],"03MT063":["Aydüşleyen","Oyna: Yakarırsın.\nAkşam: Seçtiğin kartın bedeli 1 azalır.","","''Bak, bu gece gökte ne çok arkadaşımız var! Şu en parlak yıldızı görüyor musun? O Ulak'ın gözü, bize bakıyor! Şuradaki daha sönük küme de, bulutların arkasına saklanan Hilebaz! Şu da... ŞŞT, KULUN! Pati atamazsın onlara!''","Birim",[],["Targon"],"YAYGIN"],"03MT100":["Göktutulması Ejderi","Şafak: Oynayacağın bir sonraki Ejderin ya da Semavi birimin bedeli 2 azalır.\nAkşam: Elinde rasgele bir Ejder ve Semavi takipçi oluşur.","","Ejder pulu (Göktutulması Ejderi, Drako obskuratus)\nNotlar: Pulun inanılmaz optik özellikleri var. Direkt günışığını kuvvetle yansıtıyor.\nEk: GECELERİ DE PARLIYOR!\n- Yumurta Araştırmacısı Anden Mayne'in notlarından","Birim",["EJDER"],["Targon"],"ENDER"],"03MT076":["Dağ Kâhini","Semavi kartlarının bedeli 1 azalır.\nSadakat: Yakarırsın.","","''Yıldızlardan, kılavuzluklarından öğrenecek çok şey var. Onlar bizim değişmezimiz, yolumuzu onlarla çizeriz.''","Birim",[],["Targon"],"ENDER"],"03MT029":["Yıldız Çobanı","Hasar almış bir dost birimi iyileştirdiğinde +2|+0 kazanırım.","","''Bir gece gökyüzünde, arkasında izler bırakarak koşan bir gökboynuz gördüm. O zamandan beri severim. Bu kadar çoğuyla tanışacağım hiç aklıma gelmezdi!''","Birim",[],["Targon"],"ENDER"],"03MT219":["Saklı Tapınak","Her tur ilk defa 2 başka kart daha oynadığında 2 mana doldurursun ve En Güçlü dost birime +1|+0 kazandırırsın.","","Alune kardeşi Aphelios'la buradan, Ruhlar Âlemi'nden iletişim kurar. Sessiz suikastçıya teselli edici sözler söyleyen ve âlemleri ayıran perdenin ardından uzanıp ona haklı yargısını dağıtacağı silahları veren Alune'dir.","Yer",[],["Targon"],"ENDER"],"03MT079":["Yıldızların Haşarısı","Bir Semavi karta Tanıklık edersen, bedelim 2 azalır.","","''Büyükler ne sıkıcı ya. Burada kafa dengi bir tek Zoe'yle onun arkadaşları var. Onlardan çok şey öğreniyorum tamam mı? O salak rahibe kadından hiç öğrenmiyorum. ÖFFFF ne sıkıcı!''","Birim",[],["Targon"],"YAYGIN"],"03MT007":["Yavru Gökboynuz","","","''Tüm kanatlı hayvan yavruları gibi, genç gökboynuzların da yuvadan uçması gerek. Bu bakımdan gece göğündeki tüm diğer yıldızlara benziyorlar çünkü kolayca kayıp düşebiliyorlar. Neyse ki öyle bir durumda onları biz tutup, hazır olduklarında göğe geri yolluyoruz.''\n- Yıldız Bakıcısı Lidari","Birim",[],["Targon"],"YAYGIN"],"03MT038":["Akyalaz Koruyucusu","","","Daha küçük, daha dost canlısı ejderlerle ilk defa Targon'lu çocuklar arkadaş oldu. Kendileri de yavru olan bu yaratıklar belki de çocukların masum merakını sezerek onlara saldırmak yerine onları korumayı tercih ettiler. ","Birim",["EJDER"],["Targon"],"YAYGIN"],"03MT014":["Ejderlerin Habercisi","Dost Ejderlerin bedeli 1 azalır.","","Bulutlar ejderlerin muazzam bedenlerine dolandı. Sağır edici çığlıkları gökyüzünü inletti. Haberci neyin yaklaştığını biliyordu. Ama korkmuyor, aksine kaderin kucağına atılacağına seviniyordu.","Birim",[],["Targon"],"ENDER"],"03MT110":["Yolumdan Çekilin","Oyunun geri kalanı boyunca, dost birimlere verilen Bariyer dışındaki ''bu tur'' güçlendirmeleri kalıcı olur. 1 kart çekersin.","","''Bilirsin, söylediğim her şeyde ciddiyim\nGeldiğimi görünce, yolumdan çekilin\nDiz çöktürmeye geldim, diz çöktürmeye geldim\nGeri döndüm, artık daha iyiyim ve buradan gitmeyeceğim.''\n- Kai'Sa, ''THE BADDEST''","Büyü",[],["Targon"],"DESTANSI"],"03MT017":["Ulak'ın Mührü","Destende 5 Ulak oluşur.","","''Zaman geçer, gökler döner. Yılan çekilir, gökteki yerini Ulak alır. Bolluk mevsimi başlar...''\n- Lunari Rahibe","Büyü",[],["Targon"],"ENDER"],"03MT025":["Dağın Parçaları","Elin Mücevher kartlarıyla dolar.","","''Mücevherleri ışığa tutarsan parlarlar. Aynı fanilerin yaşamları gibi hepsinin içinde birer ateş vardır.''\n- Taric","Büyü",[],["Targon"],"DESTANSI"],"03MT216":["Gök Gölgeleri","Çağrıldığımda bir Akşam kartına Tanıklık ettiysen 2 büyü manan dolar.","","''Ay Ana, unutturma bana,\nYerde tek dursam da,\nÇocuklarının yukarıda dans ettiğini,\nVe yalnız olmadığımı.''\n- Lunari duası","Birim",[],["Targon"],"YAYGIN"],"03MT012":["Zirve Yargıcı","Bu oyunda dost birimleri hedeflediğin ya da desteklediğin her sefer için bedelim 1 azalır.","","Dağın son sınavı Yargıç'tır. Dağa tırmanan kişinin başarılarının ötesine geçip ruhunu görebilen sadece odur.","Birim",[],["Targon"],"DESTANSI"],"03MT085":["Sükûnet","Bu tur bir birimi Susturursun.","","''Huzur bulacaklar.''\n- Soraka","Büyü",[],["Targon"],"ENDER"],"03MT081":["Dağın Konukları","Destekle: Desteklediğim dost birim +2|+2 kazanır. Bu dost birimin Destekle tesiri varsa, onun desteklediği dost birim de +2|+2 kazanır ve desteklenen her dost birim sırayla kazanmaya devam eder.","","Targon Dağı'na çıkma cesareti gösteren herkesin kendine göre bir sebebi var. Bazıları kendini birilerine kanıtlamak için çıkıyor, bazıları kendilerine bir şey kanıtlamak için.","Birim",[],["Targon"],"DESTANSI"],"03MT030":["Yıldız Gözcüsü","Hasar almış bir dost birimi iyileştirdiğinde ona bu tur Sıyrılgan verirsin.","","''Yıldızların bizimle geçirdiği günler sayılıdır. Bakımları bittiğinde onları ani bir yıldız ışığı patlamasıyla göğe geri yollarım... o sırada toynakları her yerime çarpar.''","Birim",[],["Targon"],"ENDER"],"03MT088":["Solari Asker","Şafak: Bana bu tur +1|+1 verirsin.","","Güneşin sıcacık ışığı altında sapkının hücresinin önünde nöbet tuttu. Nazik nazik yakarmasına kulak asmadı. Sonunda acı bir sessizlik çöktü.","Birim",[],["Targon"],"YAYGIN"],"03MT033":["Rumul Dede","Oyna: 2 dost birime +0|+4 kazandırırsın.","","''Zil seslerini duyuyor musun Osu? Büyükbaba dönmüş!''\n- Yıldız Çobanı Illi","Birim",[],["Targon"],"ENDER"],"03MT035":["Solgun Kamer","Bir dost birime bu tur +1|+1 verirsin.\nAkşam: 1 kart çekersin.","","''Gecenin örtüsünde, solgun ayın koruyuculuğu altında.''\n- Diana","Büyü",[],["Targon"],"YAYGIN"],"03MT075":["Lunari Rahibe","Akşam: Yakarırsın.","","''Ey uçsuz bucaksız gökte sayısız seyyah gibi gezen yıldızlar! Bir an yanımızda dinlenin, bize gördüklerinizi anlatın.''\n- Akşam Şarkıları'ndan","Birim",[],["Targon"],"ENDER"],"03MT218":["Yıldız Kemiği","Bir Semavi karta Tanıklık ettiysen, destende bir Ulak oluşur ve her yerdeki Semavi dost birimlere +1|+1 kazandırırsın.","","''Oynasın Ulak göklerde,\nVe neşesiyle,\nYıldızları yaksın.''\n- Lunari duası","Büyü",[],["Targon"],"DESTANSI"],"03MT074":["Hınzır Uyku Baloncuğu","Bir düşmanı Sersemletirsin. Elinde Geçici bir Uçarı Yıldız oluşur.","","''Hadi öğlen uykusuna! Bir ışıltıböceği, iki ışıltıböceği, üç... aaordakideneymişnegüzel!''\n- Zoe","Büyü",[],["Targon"],"ENDER"],"03MT072":["Aç Ejder","","","Targon Dağı'na tırmananları sayısız güçlük bekler. Sonu gelmeyen tırmanış gibi kimileri, onların güçlerini ve ruhlarını yavaş yavaş tüketir. Bazılarıysa çok daha hızlı gerçekleşir.","Birim",["EJDER"],["Targon"],"YAYGIN"],"03MT039":["Porobek","","","Uzayda kıkırdamalarını kimse duyamaz.","Birim",["PORO"],["Targon"],"YAYGIN"],"03PZ019":["Yamalı Porobot","Elindeyken her tur değişen rasgele bir tesirim olur. Çağrıldığımda bu tesiri kazanırım.","","Gerçeği kadar yumuş değil ama onun kadar sevimli.","Birim",["PORO"],["Piltover ve Zaun"],"ENDER"],"03PZ005":["Balistikbot","Tur Başı: Elinde bir Ateşleme oluşur.","","''Denek geriye sadece zihninin kalmasını isteyerek, 'Bütün kinlerimi orada tutuyorum,' diye ekledi.''\n- Eklentici notları, giriş 1011","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"03PZ004":["Ölüm Işını - Sürüm 1","Bir birime 1 hasar verirsin. Destenin en üstündeki 3 kartın arasında bir Ölüm Işını - Sürüm 2 oluşur.","","''Bugün, ışık enerjisinin yoğunlaştırılarak güçlü bir ışın haline getirilebileceğini başarıyla sergiledim. Doğru geliştirmeler yapılırsa bu ışın benzersiz hassasiyette bir gereç haline gelebilir ama daha çok işi var.''\n- Viktor'un tasarım notlarından","Büyü",[],["Piltover ve Zaun"],"ENDER"],"03PZ003":["Viktor","Çağrıldığımda ya da Tur Başı: Elinde bir Sihir Çekirdeği Güçlendirmesi oluşur.","Oluşturulmuş 7+ kart oynadığında.","''Zaun, çok trajediler yaşadın. Artık değişim zamanı geldi. Bütün büyük ilerlemeler gibi bu da senin kendi içinden başlamalı.''","Birim",[],["Piltover ve Zaun"],"Şampiyon"],"03PZ010":["Mekanik Taklitçi","Saldır: Dost birimlerin üzerindeki tüm tesirleri kazanırım.","","''Sana benziyorum ama senden daha iyiyim.''","Birim",[],["Piltover ve Zaun"],"DESTANSI"],"03PZ022":["Tüm Gücümüzle","Tüm dost birimlerin Güç ve Can değerlerini, Güç ya da Can değerleri en yüksek olan dost biriminkine yükseltirsin.\nTüm dost birimler, dost birim tesirlerini kazanır.","","'Biliyorum, biliyorum\nDahasını istiyorsun\nHazırsan başlayalım\nTüm gücümüzü kullanalım.''\n- Seraphine, ''MORE''","Büyü",[],["Piltover ve Zaun"],"DESTANSI"],"03PZ014":["Planlı Buluşlar","Elinde bir Eklenti Meraklısı, Balistikbot ya da Miyavdroid oluşur ve ona +1|+1 kazandırırsın.","","''İnsanı hayvani temel güdülerinden ayıran rasyonalite ve seçimleridir.''\n- Viktor","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"03PZ013":["Kademeli Gelişim","Bir takipçi seçersin. Elinde +1|+1 bir kopyası oluşur.","","''Kendini geliştirmek, kahramanın da baş kötünün de kendin olduğun bir oyun. Zorluk çekersin. Kazandığını bile sanabilirsin. Ama sonunda, yolunu kesenin yine kendin olduğunu görürsün.''\n- Mekanik Taklitçi","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"03PZ025":["Zorlama Testi","Elindeki tüm kartların Geçici tesirini kaldırırsın. Ben atıldığımda, 1 Geçici kart çekersin.","","''Çok da zor bir olay değil ya. İskelette çelik yerine kendi icadım olan daha sağlam bir alaşım kullandım ve kısa devreleri önlemek için devreleri menteşelerden uzaklaştırdım. Gayet kolaydı.''\n- Baş Mekanist Zevi","Büyü",[],["Piltover ve Zaun"],"ENDER"],"03PZ012":["Eklenti Meraklısı","","","''Olley be, yeni koluma bak! Hep bunlardan istemişimdir. Sırada ne var? Bacak yerine manyetik tekerlek mi? Elektrokemer mi? METALDEN DİŞ mi? Yok ya vazgeçtim, yüzümü ellemeyin. Yüzüm iyi.''","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"03PZ020":["Sihir Çekirdeği Dökümhanesi","Tur Başı: Tüm oyuncular 1 kart çeker.","","''Yöntemlerim hakkında ne isterlerse desinler, gelişimi yadsıyamazlar! Bilgimin ışığı, cehaletin karanlığını fener gibi aydınlatıyor!''\n- Viktor","Yer",[],["Piltover ve Zaun"],"ENDER"],"03PZ002":["Miyavdroid","","","''Piltover akademik camiasıyla senelerce pençeleştim. İcatlarıma 'fazla tehlikeli' dediler, ben de 'fazla sevimli'ymişim! Benimle aynı emelleri paylaşan en az bir kişinin bulunduğunu bildiğim Zaun'a miyavlar olsun!''","Birim",["KEDİ"],["Piltover ve Zaun"],"ENDER"],"03PZ011":["Artçı Şok","Bir birime 3 hasar verirsin ya da bir Yer kartını yok edersin.","","''Bu ışık, Piltover'a ilerleyişimizde bize rehber olacak. Evrimin ihtişamının önünde hiçbir şey duramayacak!''\n- Viktor","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"03PZ017":["Üç Işınlı İmkânsızalatör","Bir birime 1 hasar verirsin. 1 manalık rasgele bir takipçi çağırırsın. Ben elindeyken 3 manalık bir kart oynadığında, ikisini de 1 arttırırsın.","","''...ve üç deyince, biiir, 'kii, ÜÇ! Aa. Aaa, yine mi kestirilemez bir sonuç çıktı?''\n- Heimerdinger","Büyü",[],["Piltover ve Zaun"],"DESTANSI"],"03PZ018":["Poro Topu","Oynamak için 1 kart atarsın.\nElinde 2 Korkusuz Poro oluşur.","","İki tüylü siluet hayranlıkla bakan kalabalığın tepesinde bir yay çizdi. Arkalarında bir puf bulutu ve hafif bir kurabiye kokusu bıraktılar.","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"03SI004":["Peşinde Bir Gölge","Destenin en üstündeki 4 kartın arasından bir takipçi seçersin.\nKalanları destene geri koyarsın. Elinde çektiğin takipçinin birebir Hayali bir kopyası oluşur.","","''Gidin... Etraflarını sarın...''\n- Nocturne","Büyü",[],["Gölge Adalar"],"ENDER"],"03SI001":["Hepgölge Musallatı","Akşam: Elinde bir kopyam oluşur.","","''Önce sadece bir çift göz gördüm ve gölgeler arasından tıkırtı gibi bir ses geldi. Arkama her baktığımda çoğaldılar. Öfkelendiler. Diş'i görür görmez koşmaya başladım.''\n- Balina Dişi'li Yağmacı","Birim",[],["Gölge Adalar"],"DESTANSI"],"03SI018":["Lanetli Açlık","Son Nefes tesiri olan bir dost birimi öldürüp yerine destenden bedeli 1 fazla olan bir takipçi çağırırsın.","","''Mamanız hazııııır!''\n- Doymaz Kasap","Büyü",[],["Gölge Adalar"],"ENDER"],"03SI012":["Vakitsiz Ölüm","Bu tur çağrılmış ama oynanmamış tüm birimlerin Kökünü Kazırsın.","","''Ölüm Demacia'da da var elbette. Sevdiklerimizi aldığına şahit oluyor, bir gün bizim de başımıza geleceğini biliyoruz. Ama bu adalarda... ölümün neredeyse tadını alabiliyorum. Nefes alırken ciğerlerime doluyor, fısıltıları kulaklarımda. Soyut bir kavram değil. Yanımda oturuyor. Şu anda. Ve hepimizi alacak.''\n- Tarihçi Jens Tommen'in notlarından","Büyü",[],["Gölge Adalar"],"ENDER"],"03SI014":["Kuşatan Gölgeler","Destendeki ve elindeki TÜM dost birimler +2|+2 ve Hayali kazanır.","","''Gölge Adalar'ın kâbuslarıyla hepimizi hem zihnen hem bedenen bitireceğinden, deliliğin sonsuza dek hüküm süreceğinden korkuyorum.''\n- Tarihçi Jens Tommen'in notlarından","Büyü",[],["Gölge Adalar"],"DESTANSI"],"03SI016":["Durmayacağız","Bir birime 1 Sömürü hasarı verirsin.\nDestende Durmayacağız kartının 2 kopyası oluşur. Bunun gerçekleştiği her üç seferde bir, her yerdeki tüm kopyalarım Valizini Toplaman Lazım kartına dönüşür.","","''Durmayacağız istediğimizi elde edene kadar\nDurmayacağız, iş başındayız\nBiz POP/STAR'ız, artık sadece kazanmak var\nKimse bizi alt edemeyecek...''\n- Evelynn, ''POP/STARS''","Büyü",[],["Gölge Adalar"],"DESTANSI"],"03SI007":["Karanlık Örtüsü","Bu tur çağırdığın bir sonraki dost birim, bu tur için +1|+0 ve Büyü Kalkanı alır.","","''Diş'ten çıktın mı onları hissetmeye başlarsın. Ensene parmak uçları yapışmış gibi olur. Üstlerine yürürsün, kımıldamazlar bile. Ne kılıcımdan korkuyorlar ne meşalemden. Dehşetli şeyler.''\n- Balina Dişi yağmacısı","Büyü",[],["Gölge Adalar"],"YAYGIN"],"03SI005":["Nocturne","Akşam: Bir düşmana Kırılganlık kazandırırsın ve düşmanlara bu tur -1|-0 verirsin.","5+ Akşam'lı veya Korkunç dost birimle saldırdığında.","''Yeterince ruh yerinden sarsılırsa dünyamıza geçiyorlarmış. Bu canavarı kendi âlemine sadece umut gönderebilir... ama umut burada çok zaman önce, bir kraliçenin son nefesi ve bir kralın ebedi çığlığıyla ölmüş.''\n- Tarihçi Jens Tommen'in notlarından","Birim",[],["Gölge Adalar"],"Şampiyon"],"03SI006":["Çöküş Canavarı","Akşam: Rakibin Nexus'una 2 sömürü hasarı verirsin.","","Yolcular her geçen gece biraz daha yoruluyordu. Uykuları huzursuz, rüyaları gerçek gibiydi. Uyku artık onları dinlendirmiyor, aksine iliklerindeki canı emiyordu.","Birim",[],["Gölge Adalar"],"YAYGIN"],"03SI015":["Laftan Anlamaz Hayalet","Son Nefes: Rakibinin destesinde 2 kopyam oluşur.","","Gölge Adalar ruhlarının çoğu ölümün bağrından kopup gelmiş, dehşet verici yaratıklardır. Ufak bir kısmı ise... sadece... çok ama çok sinir bozucudur.","Birim",[],["Gölge Adalar"],"YAYGIN"],"03SI003":["Gözcü Ürkuş","Akşam: Bu tur +2|+0 ve Korkunç alırım.","","Gün gecenin zifiri karanlığına karışırken buranın gölgeleri uyanır, gözler ve bekler.","Birim",["KUŞ"],["Gölge Adalar"],"YAYGIN"],"03SI002":["Tarifsiz Dehşet","Herhangi bir şeye 1 Sömürü hasarı verirsin.\nAkşam: Elinde rasgele bir Akşam kartı oluşur.","","''Her geçen gün hevesimi biraz daha azaltıyor, beni burayı bulmaya zorlayan gayret azalıyor. Balina Dişi hayatla bağı kesilmiş, bezgin insanlarla dolu. Kaldıkça onlar gibi olacağım diye korkuyorum.''\n- Tarihçi Jens Tommen'in notlarından","Büyü",[],["Gölge Adalar"],"YAYGIN"],"03SI010":["Karanlığın Süvarileri","Akşam: Bu oyunda Akşam'ı etkinleştirdiğimiz her sefer için +1|+0 kazanırım.","","Güneş her battığında gecenin simsiyah kanatları açılıp günün son umutlarını da karartır.","Birim",[],["Gölge Adalar"],"ENDER"],"03SI013":["Kabaran Sisler","Bir Ruh Sisi çağırırsın.","","Sis ruhları fani gözlere görünmeden boyutlar arasında dolaşır, aniden ortaya çıkar, karşılaştıkları herkese sefalet getirirler.","Büyü",[],["Gölge Adalar"],"YAYGIN"],"03IO025":["Yumruk Fırtınası","Bir dost birime +1|+0 ve İlk Saldırı kazandırırsın. Zaten varsa, Çifte Saldırı kazandırırsın.","","''Sık sık vur, hızlı vur, sert vur.''\n- Ejderin Boynuzları","Büyü",[],["Ionia"],"ENDER"],"03IO017":["Pix!","Destekle: Desteklediğim dost birim bu tur +2|+1 alır.","","''Pix şahane, hem küçük hem havalı hem candan daha ne,\nEn sevdiği şey nane, haydi gel gidelim... hhhmırmırmrmane!''\n- Lulu","Birim",["PERİ"],["Ionia"],"YAYGIN"],"03IO008":["Kapris","Bir takipçiyi bu tur için 1|1'lik bir Sincap olacak şekilde dönüştürürsün ve Susturursun.","","''Şekeribus!''\n- Lulu","Büyü",[],["Ionia"],"YAYGIN"],"03IO001":["Çiçek Çocuk","Desteklendiğimde +2|+0 kazanırım.","","Herkes büyülü dost istiyor ama kimse ne büyük sorumluluk olduğunu bilmiyor. Dengeli beslemek, gezdirmeye çıkarmak... tuvalet eğitimi vermek lazım. Çok iş, çok.","Birim",["PERİ"],["Ionia"],"YAYGIN"],"03IO019":["Tek İstek","Bir dost birim seçersin. Tüm diğer birimleri ve Yer kartlarını Geri Gönderirsin.","","''Yolumda bir başımayım.''\n- Münzevi Keşiş","Büyü",[],["Ionia"],"DESTANSI"],"03IO002":["Lulu","Destekle: Desteklediğim dost birim bu tur 4|4'e kadar çıkar.","Dost birimler 3+ defa Desteklendiğinde.","''Merak etme Pix, Kayran'dan çıkıp BÜTÜN HER ŞEYİ şekeribuslayacağız! Hazır mısın?''","Birim",["YORDLE"],["Bandle Şehri","Ionia"],"Şampiyon"],"03IO011":["Kaslı Sincap","Vuruş: Güç değerim ikiye katlanır.","","Bu vücudun sırrı, günde dört kere içtiği meşe palamudu tozu.","Birim",["PERİ"],["Ionia"],"ENDER"],"03IO009":["Patlıcanavar","","","Enerji ve Besin Öğeleri: Enerji: 104 kJ (25 kcal) Karbonhidrat: 5,88 gr, Şeker: 3,53 gr, Lif: 3 gr, Yağ: 0,18 gr. Protein: 0,98 gr, Su: 92 gr...","Birim",["PERİ"],["Ionia"],"YAYGIN"],"03IO003":["Peri Kılavuz","Oyna: Bir dost birime Sıyrılgan kazandırırsın.","","''Şşt! Buradan! Yürüyen ağaç evden sonra tam sağ yapıp konuşan çiçeklerin yanından dümdüz devam etmemiz lazım. Lu, beni dinliyor musun? Lu? Lu! LULU! Yemek. Verme. Şunlara. Verme.''","Birim",["YORDLE"],["Ionia"],"ENDER"],"03IO007":["Trevor Horpiştoto","Destekle: Desteklediğim dost birimin niteliklerine sahip ve saldıran bir Homurperi oluşur.","","Sana hayallerini gerçekleştir dedik, kadim ve büyülü bir ormanda uyur-uçarken rüyanın arasında mırıldandığın büyülerle hepsini gerçek dünyaya getir demedik.","Birim",["YORDLE"],["Ionia"],"DESTANSI"],"03IO010":["Küçük Cadı","Destekle: Desteklediğim dost birim bu tur İlk Saldırı ve +1|+0 alır.","","Sör Ribery Montague evinden mühim bir görevi tamamlamayı ya da meşhur bir haneden bir iyilik koparmayı umarak çıkmıştı. Ama kader yolunu bir Bandle ormanına düşürdü. Orada küçük Bri onu hemen kurbağaya çevirip yanında gezdirmeye başladı. Zavallı Rib!","Birim",[],["Ionia"],"YAYGIN"],"03IO020":["Yapmabebo!","Bedeli 3 ya da daha az olan Hızlı ya da Yavaş bir büyüyü durdurursun.","","''Ay sakın öyle yapma şapşik pofimişko! Karıncaylanların canını yakarsın!''\n- Lulu","Büyü",[],["Ionia"],"ENDER"],"03IO022":["Hadi Gel Al","Bir dost birimi Geri Göndererek birebir Hayali bir kopyasını çağırırsın. Bedeli bu tur 0 olur.","","''Dahası\nBiliyorum bende var\nE hadi gel al,\nBelli ki sana lazım dahası.''\n- Akali, ''MORE''","Büyü",[],["Ionia"],"DESTANSI"],"03IO018":["Tüylü Bakıcı","Desteklendiğimde bu tur +0|+3 alırım.\nDestekle: Desteklediğim dost birim bu tur +3|+0 alır.","","Mor periler pek tatlı, küçük varlıklardır. Onları gören herkes koruyup kollamak ister... yani hemen hemen herkes.","Birim",["YORDLE"],["Ionia"],"ENDER"],"03DE008":["Ejder Müdafaası Teğmeni","Çağrıldığımda, bir Ejdere Tanıklık ettiysen Rakipçeker kazanırım.","","''Çitduvar'da silah arkadaşlarımı kaybettiğimde, azmimi de yitirdim sanmıştım. Ama eski asker savaş görünce hemen kendine gelirmiş meğer.''","Birim",[],["Demacia"],"YAYGIN"],"03DE001":["Karşısına Dikil","Bir dost birime Rakipçeker kazandırırsın.\nDost birim bir Ejderse, 1 kart çekersin.","","''Hiçbiri elimizden kaçamayacak!''\n- Shyvana","Büyü",[],["Demacia"],"YAYGIN"],"03DE015":["Taştan Baskılayıcı","TÜM büyülerin bedeli 1 artar.","","Biçimsiz ve kaba saba bir taş bloku, heykeltıraşın hünerli ellerinde çabucak başka bir hal alır. Eserler işte bu anda gerçekten can bulmaya başlar.","Birim",[],["Demacia"],"ENDER"],"03DE006":["Carlayan Ejder","","","Neredeyse her canlı yavrusunu ölümüne savunur ama tehditlerle ejderler kadar iyi başa çıkabileni azdır.","Birim",["EJDER"],["Demacia"],"YAYGIN"],"03DE025":["Lav Nefes","Hiddet tesiri olan bir dost birim, En Güçsüz 2 düşmana sırayla vurur.","","Demacia'lılar bir ejderin hiddetini yüzyıllar boyu sadece efsanelerde duydular. Çitduvar bunu değiştirdi.","Büyü",["ELEMENTAL"],["Demacia"],"ENDER"],"03DE002":["Baştan Başa Saldırı","Bir dost birim ve bir düşman birim birbirine vurur. Ardından, dost birim bir Ejderse, 5 iyileşir.","","Ejderle şövalye yara bere içinde, nefes nefese ayrıldıklarında ejder daha da canlanmış gibiydi. Kan kokusu almıştı. Daha çoğunu dökmek istiyordu.","Büyü",[],["Demacia"],"ENDER"],"03DE011":["Shyvana","Saldır: Bana bu tur +1|+1 verirsin.","Dost Ejderler 16+ hasar verdiğinde.","''Bir yandan, doğası itibariyle en büyük düşmanımız. Türü çağlar boyu Demacia'ya azap çektirdi. Öte yandan prensimiz ona büyük güven duyuyor. Kararlı bir asker ve değerli bir müttefik gibi davranıyor. Tek umudum, ona duyduğumuz güvene ihanet etmemesi.''\n- Teğmen Jerik'in Çitduvar hakkında yazdıklarından bir sayfa","Birim",["EJDER"],["Demacia"],"Şampiyon"],"03DE003":["Ejder Müdafaası Gözcüsü","Çağrıldığımda, bir Ejdere Tanıklık ettiysen Silahlanırsın.","","''Ta uzakta, görüyor musun? Yoksa...''\n''Öyle galiba.''\n''Nasıl emin olabildin?''\n''Başka hiçbir şeye benzemezler. Kulaklarını tıka. Feci gürültü çıkacak.''\n- Anden ve Yessenia","Birim",[],["Demacia"],"ENDER"],"03DE013":["Gözleyen Anne Ejder","","","''Aman dikkat askerler! Dikkatlice yürür ve yuvayı bozmazsak, anne ejder savunmada kalır. Ama tepesini daha da attırırsak... arkanıza bakmadan kaçın.''\n-Yumurta Araştırmacısı Anden Mayne","Birim",["EJDER"],["Demacia"],"YAYGIN"],"03DE005":["Yumurta Araştırmacısı","Çağrıldığımda elinde rasgele bir Ejder oluşur.","","Ejder Yumurtası (Carlayan Ejder, Drakonis dırdırıkus) \nLokasyon: Araştırmacı Anden Mayne keşif gezisinde buldu. \nNotlar: Kuluçka süresi bilinmiyor. Kuluçkası devam ettirildi. Kabuğun içinde hareket gözlemlendi. Isıya, ışığa, çekice tepki veriyor. İnceleme sonuçları belirsiz. \n- Yumurta Araştırmacısı Anden Mayne'in notlarından","Birim",[],["Demacia"],"YAYGIN"],"03DE007":["Şeytani Kadregrin","Çağrıldığımda, her yerdeki tüm diğer dost Ejderler +4|+4 kazanır.","","Demacia'ya aniden bir sürü ejder saldırınca, Shyvana bu işte Şeytani Kadregrin'in parmağı olduğunu hemen anladı. Onun cüretinden ve güçlü alevlerinden yüz bulan diğer ejderler Demacia'ya korku salmaya başlamıştı. ","Birim",["EJDER"],["Demacia"],"DESTANSI"],"03DE012":["Can Verenler İçin","Seçkin bir birim çağırdığında bedelim 1 azalır.\nBu tur ölmüş olan her dost birim için bir Yılmaz Öncü çağırırsın.","","''Bir asker ölürse, yerine diğeri geçecek. Sancağımız asla inmeyecek.''\n- Garen","Büyü",[],["Demacia"],"DESTANSI"],"03DE014":["Keskin Görüş","Bir dost birime bu tur +1|+2 ve Keskin Görüş verirsin.","","Demacia'nın surlarını aşma cüretini gösterenler, karşılarında onları def etmeye hazır, dişten tırnağa silahlı bir bölük bulur.","Büyü",[],["Demacia"],"YAYGIN"],"03FR020":["Yarahane","Bir dost birim hasar alıp sağ kaldığında ona +1|+0 ve Dayanıklı kazandırırsın.","","Kışın Pençesi'nin kutlu bulduğu pek çok yer var ama en büyüklerinden biri Yarahane. Akınlarda hasar alınca savaşçılar ve yakınları için toplanma salonları yapılmış savaş gemilerinden oluşuyor. Bu gemiler onları yapan kabilenin dayanıklılığını ve her koşula uyum sağlamasını temsil ediyor.","Yer",[],["Freljord"],"DESTANSI"],"03FR007":["Toplayıcı Trol","Çağrıldığımda 8+ bedelli bir karta Tanıklık etmişsen, +3|+0 kazanırım.","","İz sürücü kara gizlenmiş, soğuk havaya insan teri ve duman kokusu yayan bir kumaş parçasının yanına çömeldi.\nKumaşı çekince, ucundan fırtınalı göğün altında donuk donuk duran bir tılsım sarktığını gördü. Avarosa işiydi. ","Birim",[],["Freljord"],"YAYGIN"],"03FR004":["Canlandıran Kükreme","Elinden bir birim seçip gösterirsin. Nexus'unu bu birimin Güç değeri kadar iyileştirirsin.\nAydınlanmış: Birimin bedeli 0 olur.","","''Yetişkin trollerin postu kalındır. Kemikleri sağlamdır, çabuk kaynar. Yılmak nedir bilmez, korkunç düşmanlardır. Hemen kellelerini alın, yoksa iyileşip yine karşınıza çıkarlar.''\n- Avarosa Okçusu","Büyü",[],["Freljord"],"ENDER"],"03FR017":["Eskilerin Kâhini","Oyna: 8+ bedelli bir karta Tanıklık etmişsen, dost bir birime Aban ve Yenilenme kazandırırsın.","","Derler ki Eskiler'in türküleri çok az trole öğretilirmiş ve bilenler atalarının isimlerini yâd ederek kardeşlerine olağanüstü güç kazandırabilirmiş.","Birim",[],["Freljord"],"ENDER"],"03FR006":["Trundle","Çağrıldığımda elinde bir Buz Sütunu oluşur.","Buz Sütunu oynadığını gördüğümde.","Geçidin iki yanındaki meşaleler teker teker yandı. Manzara, keskin gölgelerle aydınlandı. Düzinelerce, belki yüzlerce trol gelmişti. Hepsi kocaman, vahşi ve ölümcüldü.\nTrundle Kemiktitreten'i omzuna koyup, ''Bir kere daha soruyorum,'' diye hırıldadı. ''Teslim olacak mısınız, kafanızı mı kırayım?''","Birim",[],["Freljord"],"Şampiyon"],"03FR008":["Buz Depremi ","Bu tur TÜM birimlere -3|-0 verirsin. TÜM birimlere 3 hasar verirsin.","","''Diri diri gömün!''\n- Trundle","Büyü",["ELEMENTAL"],["Freljord"],"DESTANSI"],"03FR002":["Trol Türküsü","Bu tur bir dost birime +0|+2 vererek bir düşmana -2|-0 verirsin.","","Trol türkülerinin biri ötekine benzemez. Gruptan gruba değişirler. Çoğunu da anlamak imkânsızdır. Ama hepsinin ortak noktası, söylenişlerinin tüyler ürpertici olmasıdır. ","Büyü",[],["Freljord"],"YAYGIN"],"03FR011":["İhtiyar Uzgar","","","Önce ayaklarının altındaki toprağın sarsıldığını hissettiler ama ses de yaklaşan fırtınanın gök gürültüleri gibi hemen duyulur oldu.\nMeyrick başını kaldırdı. Gözleri açılmıştı, dinliyordu.\nAnya yayını çekerken telaşla, ''Ne oluyor?'' diye fısıldadı ama Meyrick çoktan yola doğru koşuyordu. \n''KAÇ!''","Birim",[],["Freljord"],"ENDER"],"03FR005":["Yağmacı Trol","Çağrıldığımda 8+ bedelli bir karta Tanıklık etmişsen, Yenilenme kazanırım.","","Avarosa kulübelerinin arasına girince Hgar'ı ön saflara çağırdılar. Gülerek Buzkesen'i havaya kaldırdı. Silahıyla ahşap evleri un ufak etmeye hazırdı.","Birim",[],["Freljord"],"YAYGIN"],"03FR018":["Yabana Çağrı","Destenin en üstündeki 4 kart arasında bulunan tüm yetileri, Poroları ve Elnükleri çekersin. Kalanları destene geri koyarsın.","","''...sonracııma ağaçların arasından böyle KOCAMAN bi' ELNÜK uçarak çıktı sonra da sırtında küçücücük bi' poro vardı bi' tane de YETİ ARKADAŞLARI vardı arkadaşlarıyla oynamaya gelmişti sonra da hepsi RAAAAARRR diye dağdan aşağı koştular sonra...''\n- Küçük Ingvar","Büyü",[],["Freljord"],"YAYGIN"],"03FR010":["Eskilerin Yüzleri","Tur Başı: 8+ bedelli bir karta Tanıklık etmişsen, bu tur fazladan bir mana taşı alırsın.","","''Kalkın Eskiler kalkın,\nBuzla yönetin, göğü kırın.\nKalkın Eskiler kalkın,\nBize güç verin, onları mahvedin.''\n- Trol türküsü","Birim",[],["Freljord"],"YAYGIN"],"03FR019":["Eskilerin Sesleri","2 boş mana taşı alırsın.\nDestenin en üstündeki 5 kart arasından bedeli 8+ olan tüm kartları çekersin. Kalanları destene geri koyarsın.","","Avarosa yerleşimcileri kuşaklardır, kış fırtınalarının hengâmesi arasında tuhaf ve açıklanamaz sesler duyardı. Zamanla iyice kuzeye çıktıklarında, bu seslerin kaynağını sonunda keşfettiler. Kadim trol anıtlarının içinden rüzgâr estikçe, ağızlarından unutulmuş dillerde fısıltılar dökülüyordu.","Büyü",[],["Freljord"],"YAYGIN"],"03FR025":["Trol Hünerleri","Bir dost birime Yenilenme kazandırırsın. Zaten varsa +2|+2 kazandırırsın.","","Bir trolün kanındaki zafer vaadini görenlere yazık olur.","Büyü",[],["Freljord"],"ENDER"],"03FR022":["Heyecanı Hisset","Elinden ve destenden 2 farklı, rasgele şampiyon çağırırsın. Niteliklerini 10|10'a kadar yükseltirsin.","","''Başarmalıyız, her şey bizim elimizde\nAcaba bize dayanabilecek misiniz?''\n- Ahri, ''POP/STARS''","Büyü",[],["Freljord"],"DESTANSI"],"04PZ001":["Ekko","Vuruş: Elinde Geçici bir Zaman Numarası oluşur.","4+ kere Öngörüde bulunduğunda. Seviye atladığımda destende 3 Kronokırılma oluşur.","Ne kadar zamanın olduğu değil, onu nasıl kullandığın önemli.","Birim",[],["Piltover ve Zaun"],"Şampiyon"],"04PZ005":["Çireğen Kuyu İşçisi","Başka bir Çireğen Kuyu İşçisi çağırdığında benim Kökümü Kazırsın ve her yerdeki dost Çireğen Kuyu İşçisi kartlarını Kuyu Belaları Çetesi kartlarına dönüştürürsün.","","Çireğenleri ilk keşfeden Zaun'lu madenciler onların ürkek ve basit canlılar olduğunu sanmışlardı. Fakat yıllar geçip çireğenler insanlara alıştıkça sıkı toplumsal bağları ve teknolojiye görünüşe göre doğuştan gelen yatkınlıkları ortaya çıktı.","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"04PZ014":["İmalat Artışı","Oynamak için tüm mananı harcarsın. Bedeli harcanan manaya eşit rasgele Taretler çağırırsın.","","''Yeterince kaynak mı yok? Ben ilk mekanik aygıtımı atılmış saat parçalarıyla paslı bir termal kapasitörden yaptım. Mucit dediğin elinde ne varsa onu kullanır!''\n- Heimerdinger","Büyü",[],["Piltover ve Zaun"],"ENDER"],"04PZ003":["Kurmalı Kapan","Oynamak için 1 kart atarsın.\nBir düşman birime ya da rakibin Nexus'una 1 hasar ve bir diğerine 1 hasar verirsin.","","''Dikkat et!''\n- Ekko","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"04PZ011":["Tam Yerine Atış","1 kart çekersin.\nDestende bir Paralel Yakınsama oluşur.","","''Zaman akışlarını ayıralım!''\n- Ekko","Büyü",[],["Piltover ve Zaun"],"DESTANSI"],"04PZ002":["Düşen Kedi","Çağrıldığımda destenin en altındaki 10 kart arasında bir Heksit Kristali oluşur.","","''AMA PLANIIIMMİYAAOOOOUUUUVV!''","Birim",["KEDİ"],["Piltover ve Zaun"],"ENDER"],"04PZ020":["Arızalı Değişbot","Oyna: Niteliklerimi başka bir biriminkiyle değiş tokuş edersin.","","''Yeni bir kumarbot mu bu? Bunları yapan fabrika yıllar önce kapanmadı mı?''\n''Öyle duymuştum. 'Yuvarlanan bomba', 'beklenmedik patlama' gibi bir şeyler diyorlardı.''\n''Hmm.''\n''...Oynayalım mı?''\n''Tabii ki.''\n- Zaun'lu müşteriler","Birim",[],["Piltover ve Zaun"],"ENDER"],"04PZ013":["Elnük Gönüllü","Çağrıldığımda, destenin en üstündeki 6 kart arasında rasgele bir elnük oluşur.","","''EVET CANIIIM, SEN ŞİMDİ ORADA GÜZELCE OTUR TAMAM MI, BEN DE BU DÜĞMEYİİİ AÇAYIIIMM VEE BUUM! SONSUZ TANE ELNÜK! Daha çok yere ihtiyacımız olacak. Samana da tabii.''\n- Pratik Mükemmeliyetçi","Birim",["ELNÜK"],["Piltover ve Zaun"],"ENDER"],"04PZ010":["Eş Zaman Akışları","Elindeki takipçilere ''Beni oynadığında, bedeli benimle aynı olan 3 takipçiden birini seçersin ve beni seçtiğin takipçiye dönüştürürsün'' özelliği kazandırırsın.","","''BENİM kurallarımla oynuyoruz.''\n- Ekko","Büyü",[],["Piltover ve Zaun"],"DESTANSI"],"04PZ016":["Bombacı Babun","Çağrıldığımda elinde bir Alevli Patlangaç! oluşur.","","Jinx bir zamanlar daha normal birinden alışveriş yapıyordu. Sonra bir gün araları bozuldu ve satıcı dükkânı kapadı. Çünkü pencereden düşmüştü. Çünkü vurulmuştu. Çünkü Jinx ona ateş etmişti.","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"04PZ007":["Zaman Numarası","Öngörüde bulunursun, sonra 1 kart çekersin.","","''Geleceği ben çizerim!''\n- Ekko","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"04PZ012":["Pratik Mükemmeliyetçi","Oyna: Öngörüde bulunursun. Destende seçtiğin kartın 3 kopyası oluşur.","","''Kay süper bi' kız ya. Pratik yapmadan mükemmel olunmaz diyor, anlatabildim mi? Ve nasıl sıkı pratik yapıyor var ya...''\n- Shomi","Birim",[],["Piltover ve Zaun"],"ENDER"],"04PZ017":["Evrimin İhtişamı","Kartlarının bedelleri 1 düşer, Eklenti alırlar, Evrimin İhtişamı tarafından oluşturulurlar ve Teknolojik olurlar.","","''Gelişim her şeydir. Hazır olsa da olmasa da bu şehre geleceği getireceğim.''\n- Viktor","Büyü",[],["Piltover ve Zaun"],"DESTANSI"],"04PZ015":["Adaptatron 3000","Teknolojik bir kart çağırdığında, tesirleri paylaşırız.","","''Ah evet, Adaptatron 3000! Her koşula uyum sağlar, icat yapabilir ve bence çok da yakışıklı! Konuşabilse pek çok ortak noktamız olduğunu keşfederdik eminim...''\n- Heimerdinger","Birim",["TEKNOLOJİK"],["Piltover ve Zaun"],"DESTANSI"],"04PZ004":["Hava Kaykaycısı","Beni bir Öngörüde görürsen, beni çağırırsın.","","''Ahh, Shomi tam bir uçan kaykay dâhisi! Bir seferinde kuyu kayışından geri ters taklaya geçtiğini, sonra bir rüzgâr yakalayıp üç saltoyla yere indiğini gördüm... ya da öyle bişey. Ya özetle süper biri, tamam mı?''\n- Pratik Mükemmeliyetçi","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"04BW002":["Kemik Zıpkın","Bir dost birim bir düşmana vurur, sonra destenin en üstüne yerleşir.","","''Veda hediyem olsun.''\n- Pyke","Büyü",[],["Bilgewater"],"DESTANSI"],"04BW007":["Jaull Balığı","Oyna: Her bir Pusucu dost birim rasgele bir düşmana vurur.","","''Kime güvenilip kimin öldürüleceğini en iyi jaull balıkları gösterir.''\n- Pyke","Birim",["PUSUCU"],["Bilgewater"],"DESTANSI"],"04BW001":["Kırmızı Yüzgeçli Çekiçburun","Oyna: Bir düşmana Kırılganlık kazandırırsın.","","Çekiçburunlar gemilerin gövdelerini görünüşe göre sırf eğlence olsun diye deliyor. Denize döktükleri tayfaları yemiyor, onlardan sonra gelen yaratıklar kendilerine ziyafet çeksin diye bırakıyorlar.","Birim",["PUSUCU"],["Bilgewater"],"YAYGIN"],"04BW005":["Pyke","Pusuya yattığımda beni Derinlerin İntikamı kartına dönüştürürsün.","Dost Pyke'lar 15+ hasar verdiğinde.","''...sanrılar yine başladı. Jaull balığı ağzını kapatırken bana umutsuzca bakan gözlerini görüyorum. Onu çekmeye çalıştık ama gemimiz çok küçük, o canavar yaratıksa çok büyüktü. Başka seçeneğim yoktu. İpini kesmeye mecburdum. Mecburdum.''\n- Kanla ıslanmış bir mektup","Birim",["PUSUCU"],["Bilgewater"],"Şampiyon"],"04BW010":["Canavar Zıpkını","Yağma: Bedelim 2 azalır.\nBir birime 5 hasar verirsin.","","''Hayvanı deştik zaten oğlum! Şimdi çırpınması durana ve de su maviden kırmızıya dönene kadar şişlemeye devam edin!''\n- Kalpsiz Tayfabaşı","Büyü",[],["Bilgewater"],"YAYGIN"],"04BW014":["Sırala!","Bir Barut Fıçısı çağırırsın.\nElinde bir Devir Geç oluşur.","","''Dediğiniz gibi yaptık kaptan. Bir kıvılcım çakınca fena patlayacak.''\n- Dehşet Yolu tayfası","Büyü",[],["Bilgewater"],"YAYGIN"],"04BW011":["Hileli Zar","Sonraki turda, rakibin Nexus'una hasar verdiğinde 1 kart Aşırırsın.","","''Neyine bahse girmeye varsın arkadaşım?''\n- Tahm Kench","Büyü",[],["Bilgewater"],"DESTANSI"],"04BW015":["Köpekbalığı Yavrusu","","","''Ufaraklar teferekler amma, kan dökmeye çok hevesliler. Bir tanesi seni ısırırsa, büyüyünce de seni nerede bulacağını bilir. En güzeli eldiven takmak.''\n- Jaull Avcıları","Birim",["PUSUCU"],["Bilgewater"],"YAYGIN"],"04BW003":["Kapançene Sürüsü","Oyna: Bir fazladan saldırı başlatırım.","","''Şıp şıp ediyor ne oluyor, suya kan damlıyor,\nCup cup geliyor sürü geliyor, aklı olan boğuluyor,\nHart hart ediyor ne oluyor, dişler kapanıyor herkes bağırıyor,\nDalıyoruz derine, dalıyoruz uykuya, sonsuz rüya görmeye!''\n- Bilgewater çocuk tekerlemesi","Birim",["PUSUCU"],["Bilgewater"],"YAYGIN"],"04BW009":["Kanlı Katil Körfezi","Dost birimler saldırdığında, Pusu devreye girmeden önce, destenin en üstündeki dost birime Pusu kazandırırsın ve birim Pusucu olur.","","Bilgewater'ın en tehlikeli koyları çok geçmeden her cins deniz canavarına ev sahipliği yapmaya başladı. Şimdi hepsi suyun altına çekilmiş, liman amirinin uyarısına kulak asmayacak kadar gözü kara tayfaları bekliyorlar.","Yer",[],["Bilgewater"],"ENDER"],"04BW008":["Kayıp Define","Bir Hazine çekersin. Çekecek Hazine yoksa, bunun yerine destende 2 Hazine oluşur.","","''Köşeyi döndük!''\n- Testere Kasap","Büyü",[],["Bilgewater"],"ENDER"],"04BW013":["Yağmacılar Sırası","Geri Sayım yaptığımda, bedeli 1 olan rasgele bir takipçi çağırırsın.\nGeri Sayım - 2: Bedeli 1 olan dost birimlere +2|+1 ve Korkunç kazandırırsın.","","''Paslı Kanca adını hak ettiğini sanıyorsun ha? Göreceğiz bakalım zıpçıktı. Seninle işimiz bitsin, kendi yükünü taşıyabiliyor musun yoksa taş bağlayıp balık yemi diye denize mi atacağız anlaşılır.''\n- Gemi Astsubayı","Yer",[],["Bilgewater"],"ENDER"],"04BW004":["Kanlı Yem","Destenin en üstünde bir Kapançene Sürüsü oluşur.","","''Jaull balığının ağzına atlarım da kendimi bu yaratıklara yedirmem. Etimi diri diri yerlerken arkadaşlara beni öldürsünler diye bağırmaktansa çabucak ölürüm daha iyi.''\n- Testere Kasap","Büyü",[],["Bilgewater"],"YAYGIN"],"04BW016":["Mahvolmuş Rex","Oyna: Bu tur çektiğin her kart için rasgele hedef alınan düşmanlara 6 kereye kadar Top Salvosu oynarsın.","","''...Rex?''\n- Gemi Astsubayı","Birim",[],["Bilgewater"],"ENDER"],"04BW006":["Liste","Bir düşmana Kırılganlık kazandırırsın. Eğer zaten Kırılgansa, En Güçlü dost birim onu çekerek bir fazladan saldırı başlatır.","","''Senin adın var, benim de yazacak listem.''\n- Pyke","Büyü",[],["Bilgewater"],"ENDER"],"04IO008":["Direniş Dansı","Bir birimi Geri Gönderirsin.\n1 bıçak dans eder.","","''Geri çekilin! Sahneyi başkasına bırakma vakti geldi!''\n- Çelik Kreşendo Zinneia","Büyü",[],["Ionia"],"YAYGIN"],"04IO005":["Irelia","Çağrıldığımda ya da Tur Başı: Saldırı hakkı sendeyse elinde bir Ölümcül Ahenk oluşur.","14+ dost birimle saldırdığında.","''Bir zamanlar güzellikle, sanatla uğraşırdık. Bulutların üstünde yaşardık sanki. Ama duvarlarımızı yıkıp kanımızı döktüklerinde yere düştük...''","Birim",[],["Ionia"],"Şampiyon"],"04IO020":["Dağınık Sürü","Oyna: Yavaş, Hızlı ya da Anlık bir büyü çekersin.\nAydınlanmış: Sıyrılgan kazanırım.","","Bulutiçenlerin tuhaf ve ürkütücü biçimde güzel gök şarkıları Kara Sis'in bir kısmını engelledi... ama sadece bir süreliğine.","Birim",[],["Ionia"],"ENDER"],"04IO004":["Savaş Çiçeği","Oyna: 2 bıçak dans eder.","","''Kimileri sanır ki çiçekler narin, zayıf şeylerdir. Fakat onlar, mütevazı toprağa tutunup her goncayla görenlere ilham vermenin ne kadar çok kuvvet istediğini bilmezler.''\n- Çelik Kreşendo Zinneia","Birim",[],["Ionia"],"YAYGIN"],"04IO003":["Keskin Hapis","Bıçak ile birlikte saldıracak bir dost birim seçersin, sonra 3 bıçak dans eder.","","''Geri çekiliyorlar, durdurun! Bu savaşı Noxus'lular başlattı ama biz bitireceğiz.''\n- Irelia","Büyü",[],["Ionia"],"ENDER"],"04IO015":["Dans Eden Damlacık","Geri Gönderildiğimde 1 kart çekersin.","","''Su esnektir, uyumludur. O an hangi biçime girmesi gerekiyorsa girer. Kimi zaman ileriye çağlar, kimi zaman da kıyıdan çekilir.''\n- Ionia'lı keşiş","Birim",[],["Ionia"],"YAYGIN"],"04IO014":["Gölge Çırağı","Hayali bir dost birim çağırdığında bu tur +1|+0 alırım.","","''Dumansın, rüzgârda sürüklenen bir fısıltısın. Yumrukların gölge gibi karanlığa karışmalı. Şimdi... baştan!''\n- Shi Hoca","Birim",[],["Ionia"],"YAYGIN"],"04IO002":["Çelik Kreşendo Zinneia","Dans Eden Bıçaklar kullandığında, ben Bıçak ile saldırırım.\nOyna: 1 bıçak dans eder.","","''Toplanın bakalım canlarım. Bugün ayaklarımız, bizi büyütmüş topraklarda ailelerimizin öğrettiği hareketlerle uçarcasına ilerleyecek. Biz Ionia'nın evlatlarıyız ve bugün sanat için, hürriyet için, birbirimiz için dans edeceğiz!''","Birim",[],["Ionia"],"DESTANSI"],"04IO007":["Senkop","2 dost birimin yerini değiştirirsin.","","''Dans etmek, dünyadaki her şeyin hareketine ayak uydurmaktır.''\n- Çelik Kreşendo Zinneia","Büyü",[],["Ionia"],"ENDER"],"04IO011":["Uyumlu Adımlar","Bir dost birimi Geri Gönderirsin, elinde bir Ölümcül Ahenk oluşur.","","''Performansımız... unutulmaz olacak.''\n- Çelik Kreşendo Zinneia","Büyü",[],["Ionia"],"YAYGIN"],"04IO013":["Mukaddes Koruyucu","Oyna: Bir dost birime bu tur Bariyer verirsin ve bir Shen çekersin.\nBariyer'e sahip dost birimlerin Çifte Saldırı'sı olur.","","''Biz ülkemizi nasıl koruyorsak, ülkemiz de ayaklanıp bizi koruyor. Gücümüzü toprağın hiddetinden alarak düşmanlarımızı kapı dışarı ediyoruz. Böylece denge sürüyor.''\n- Ionia'lı rahip","Birim",[],["Ionia"],"DESTANSI"],"04IO012":["Geçmişin Gölgeleri","Her bir dost birimi Geri Gönderip yerine bir Canlı Gölge çağırırsın.","","''Bırakın gölgelerle savaşsınlar, silahlarını hiçbir şeye isabet ettiremeyecekler.''\n- Zed","Büyü",[],["Ionia"],"ENDER"],"04IO009":["Kurdele Dansçısı","Oyna: 1 bıçak dans eder.","","''Ay ne fena çocuklar, gücünüz çok ama ritim duygunuz hiç yok. Ne yapalım, herkes yıldız olamaz tabii!''","Birim",[],["Ionia"],"ENDER"],"04IO001":["Savaş Müzisyenleri","Her tur 3 dost birim çağırdıktan sonra büyü manan dolar ve 1 kart çekersin.","","Bazıları için müzik zorluklardan ve şiddetten kaçtıkları ortak bir sığınaktır. Bazıları içinse direniştir.","Birim",[],["Ionia"],"DESTANSI"],"04IO006":["Kıyı Savunmacısı","Başka bir dost birim çağırdığında, bana bu tur +2|+0 verirsin.","","Canım Kay'ciğim, \nBu sabah, ufku bozup doğan güneşi karartan bir sıra gemiyle geldiler. Makineleri Gümüş Ovalar'ı ateşe verdi. Şimdi yaz havasına koyu bir duman karışıyor. Artık elimiz kolumuz bağlı duramayız. Tırmıklarla, küreklerle, tırpanlarla, kılıçlarla silahlanıp yazgımızın karşısına dikilmeliyiz. \nBil ki seni ve vatanımızı kelimelerle ifade edemeyecek kadar çok seviyorum.\n- Yanmış bir mektuptan\n","Birim",[],["Ionia"],"YAYGIN"],"04SH100":["Özenli Hazırlık","Oynamak için elindeki bir kartı destene koyarsın.\nÖngörüde bulunursun, sonra elinde seçtiğin kartın birebir kopyası oluşur.","","''Bugünkü eylemlerimiz, yarının ağaçlarının tohumlarını eker.''\n- Öğrenci Zaman Büyücüsü Tai","Büyü",[],["Shurima"],"YAYGIN"],"04SH070":["Layık Değilsin","Bir düşman takipçiye bu tur -4|-0 verirsin.\nMana taşların rakibininkilerden azsa, takipçiyi öldürürsün.","","''Güneş Shurima toprakları üzerinde yine parlayacak.'' \n- Uyananların Sesi","Büyü",[],["Shurima"],"DESTANSI"],"04SH081":["Kumören Baccai","Oyna: Bir düşmana -1|-0 ve Kırılganlık kazandırırsın.","","Döktüğü her kum tanesiyle hayatlarından bir an daha eksiltiyor, pervasız rüzgârlar misali varlıklarını aşındırıyordu.","Birim",[],["Shurima"],"ENDER"],"04SH077":["Uyananların Sesi","Bir şampiyona seviye atlattıysan dost birimler +2|+0 kazanır.","","''Uzun zaman önce konuşmasını dinlemiştim.'' Yaşlı asker gülümsedi ve torunu bir an hepsini aklında canlandırabildi: Işıklar saçan altın Shurima, Uyananların Sesi kendisini müjdelerken şehrin tepesinde başı dik duran Azir... ''Çoktan yitirdik sandığımız bir tutkuyu körükledi hepimizin yüreğinde.''","Birim",[],["Shurima"],"DESTANSI"],"04SH019":["Rek'Sai","Pusuya yattığımda ya da saldırdığımda: Her yerdeki Pusucu dost birimlere +1|+0 kazandırırsın.\nTur Sonu: Beni destene koyarsın.","10+ Güç değeriyle saldırdığımda.","''Genç Jhuraa her zamanki gibi keşfe çıkmış. Ufak, gizli bir mağarada bazı kadim yazmalar bulmuş! Onları İliknişan'daki tercümanımıza götürdük. Parşömenler meğer... atalarımıza musallat olmuş kadim bir dehşetten bahsediyormuş. Bir kraliçeden. Bir xer'sai kraliçesinden!''\n- Vekaura'lı büyüklerden Fezhaur","Birim",["PUSUCU"],["Shurima"],"Şampiyon"],"04SH138":["Bağışlayıcı","Bir dost birime bu tur +2|+1 verirsin. Bu oyunda bir şampiyona seviye atlattıysan elinde bir Bağışlayıcı'nın Dönüşü oluşur.","","''Herkes bana bunu kullanmamamı söyledi. 'Kimse bu kadar güçlü bir silaha sahip olmamalı,' dediler.''\n- Akshan","Büyü",[],["Shurima"],"YAYGIN"],"04SH089":["Gözü Kara Göçebe","Oyna: Bir Yer kartını yok edersin. Yok edilen kart dost bir Yer kartıysa bir Huysuz Kaya Ayısı çağırırsın.","","''Kadire bugün yine bir şeyler yıktı! Bu kez yıkılan taştan bir duvar olsa da epey eski görünüyordu ve muhtemelen birilerinin ataları için çok önemliydi. Neymiş, Tereshni'de duvar işçiliği daha iyiymiş! Çok kızdım çoook!''\n- Zaifa'nın günlüğünden","Birim",[],["Shurima"],"ENDER"],"04SH015":["Raz Kanlıyele","Saldır: Bu tur düşmanlara -2|-0 verirsin.","","''Aha bu timsah doğduğunda ne zaman ölür diye üstüne bahse tutuştular. Hem yavrulardan en sıskasıydı hem de böyle bir hilkat garibesiydi. Bütün kardeşlerini bunun yiyeceği kimsenin aklına gelmedi. Heh.''","Birim",[],["Shurima"],"DESTANSI"],"04SH058":["Kum Ustası","Saldır: Saldıran bir Kumdan Asker çağırırsın.","","Çölün sanatı pek az kişiye öğretilir. Kumlara Azir gibi hükmetme yeteneği bahşedilenlerin sayısı ise daha az. Bu gücü kullanabilmek ve kumların sırrına erebilmek, sadece Azir'in en sadık ve becerikli takipçilerine nasip olur.","Birim",[],["Shurima"],"YAYGIN"],"04SH080":["Sürüyü Çağır","Oynamak için elindeki bir kartı destenin en üstüne koyarsın.\nElinde 2 rasgele Pusucu oluşur.","","''Güneş gökte parlasın, xer'sai'ler sakın uyanmasın.''\n- Tüccar duası","Büyü",[],["Shurima"],"YAYGIN"],"04SH035":["Ödeme Günü","Elinde bir Şanslı Keşif oluşur.","","''Tabii, herkes gibi benim de hem iyi günlerim hem kötü günlerim oldu. Bu meslekte kötü günler fena halde kötü olabiliyor, iyi günlerse insanı fena halde zengin edebiliyor.'' \n- Sivir","Büyü",[],["Shurima"],"YAYGIN"],"04SH028":["Kadim Hazırlıklar","Oyna: Öngörüde bulunursun.\nGeri Sayım - 2: Bir Saat Dost çağırırsın.","","Tarihin sayfalarına ve yıllarca biriken kumların altına gömülüp unutuldukları düşünülse de otomatlar aslında özenle yerleştirilmişti. Sadece uyandırılmayı bekliyorlardı.","Yer",[],["Shurima"],"YAYGIN"],"04SH054":["Define Arayıcı","Çağrıldığımda elinde bir Yükselen Kumlar oluşur.","","''Bak Davu, şimdi içeri girip şeyi... şu şey her neyse onu alacaksın ve böylece ikimizi de zengin edeceksin. Ben zengin olacağım. Beni zengin edeceksin. Anladın mı? Ayrıca o şey tuzaklı falansa şimdiden özür dilerim.''","Birim",[],["Shurima"],"YAYGIN"],"04SH002":["Can Alıcı Baccai","Bir birimi katlettiğinde +1|+0 kazanırım.","","''Baccai'lerin hepsi ya kaçtı ya da başarısız Yükseliş ayinlerinden sonra canları bağışlandı ve hiçbirini bir daha gören olmadı. O karanlık mezarlarda utanç içinde ne kadardır saklanıyorlar kim bilir?'' \n- Kâtip Kah'nir, Yükseliş'e Ermişler Ordusu'nun Tarihi","Birim",[],["Shurima"],"ENDER"],"04SH042":["Uyuyan Kaya Ayısı","Geri Sayım - 3: Bir Huysuz Kaya Ayısı çağırırsın.","","''BENİM ADIM ZAIFA, HERKES UYUYOR SANDIĞIMDA SAMIR DE UYUYOR SANIP DANDİK DEFTERİME APTAL APTAL ŞEYLER YAZARIM.''\n- Zaifa'nın günlüğünden","Yer",[],["Shurima"],"YAYGIN"],"04SH032":["Kalpsiz Kemikkıran","Şöhret: Bedelim 1 azalır ve çağrıldığımda bana Aban kazandırırsın.","","Asker çırpınırken bir yandan da mızrağına uzanmaya çalışıyordu ama iri yarı kadın onun göğsüne iyice bastırdı. Asker durdu. Kadın, ''Hayır, hayır,'' diye çıkışarak pis pis sırıttı. Sivrilmiş köpekdişleri göründü. ''Bu artık benim.''","Birim",[],["Shurima"],"YAYGIN"],"04SH055":["Harabe Yağmacısı","","","Shurima'nın paralı askerleri ve mezar hırsızları, yeraltı mezarlarına dalmadan önce çölün daha bariz zorluklarıyla başa çıkmayı öğrenmeli. Bunlardan ilki, öldürücü sıcak. İkincisi de gözünü kan bürümüş yağmacılar.","Birim",[],["Shurima"],"YAYGIN"],"04SH039":["Zilean","Oyna: Destende 4 Saatli Bomba oluşur, sonra Öngörüde bulunursun.","2+ dost Saatli Bomba yok ettiğini gördüğümde.","Zilean yıllarca uğraşarak farklı zamanlarda yaşayan ve gelecek vaat eden genç büyücülerle tanıştı. Bunların hepsi, korktuğu başına gelirse ömür boyu uğraştığı işi devam ettirebilecek yetenekteydi. Zilean şefkatli ve yüreklendirici bir hocaydı ama yalnız kaldığında alnı derin üzüntüsünden kırışıyordu. Gözlerindeyse ancak birden çok ömür yaşayanların anlayabileceği bir yorgunluk vardı.","Birim",[],["Shurima"],"Şampiyon"],"04SH073":["Taliyah","Oyna: Dost bir Yer kartının birebir kopyasını çağırırsın.","5+ Yer kartı çağırdığında.","''Göçebelerin adımları rahattır, ne bilsinler kişiyi yere bağlayan köklerin ağırlığını? Onların evi her daim ufkun ötesindedir.''\n- Shurima Toplumları","Birim",[],["Shurima"],"Şampiyon"],"04SH091":["Çırak Khahiri","Çağrıldığımda, bu oyunda Öngörüde bulunduysan +1|+1 kazanırım.","","''Öğrendiklerini unutma,'' dedi Zilean, sesinde alışılmadık bir yumuşaklık, bir ciddiyetle. ''Hazır olduğuna emin misin?''\nKhahiri, hocasına kendinden emin bir şekilde gülümsedi. ''Yakında döneceğim. Hem yıllarca her gün bu an için hazırlandım. Daha fazla beklemenin manası var mı?''","Birim",[],["Shurima"],"YAYGIN"],"04SH024":["Tuzdan Dikenler","Geri Sayım - 2: Bir Huysuz Kaya Ayısı çağırırsın. Sonra, bu oyunda 4+ Yer kartı çağırdıysan En Güçlü dost birime +2|+2 kazandırırsın.","","Shurima'lı tuz işçileri hangi tuz yataklarının tuz toplamaya uygun olduğunu, hangilerindense uzak durulması gerektiğini çabucak öğrenir.","Yer",[],["Shurima"],"YAYGIN"],"04SH003":["Azir","Dost birimler saldırdığında, saldıran bir Kumdan Asker çağırırsın.","12+ dost birim ya da Yer kartı çağırdığında.","''Azir Shurima imparatoru tacını ilk giydiğinde kibirliymiş. Körmüş. Sadece Shurima'nın değil, tüm dünyanın yöneticisi olabilmek için iktidarını pekiştirip Yükseliş ayinini planlamaya başlamış.'' \n- Kâtip Kah'nir, Yükseliş'e Ermişler Ordusu'nun Tarihi","Birim",["YÜKSELMİŞ","KUŞ"],["Shurima"],"Şampiyon"],"04SH011":["Zenotip Araştırmacıları","Çağrıldığımda destendeki 3 rasgele dost birime +3|+3 kazandırırsın.","","Hiçlik sürprizlerle dolu. Her gün büyüyüp kuleye sızmanın yeni yollarını buluyor. Dikenli bir yaban çalısı gibi inatçı ama çok, çok daha ölümcül. Bu yüzden de onu incelemek zor çünkü oluşturduğu tehdidi önceden tahmin edip anlamak için araştırmacılarının da onun kadar akıllı ve direngen olması gerek.","Birim",[],["Shurima"],"ENDER"],"04SH130":["Akshan","Çağrıldığımda ya da Vuruş yaptığımda: Bir Savaş Beyinin Sarayı çağırırsın ya da onu 1 tur ilerletirsin.","Savaş Beyinin Sarayı Geri Sayım'ını bitirdiğinde. Seviye atladığımda, bir Savaş Beyinin Hazinesi çağırırsın.","''Işık Muhafızları'nın düsturu karmakarışık kısıtlamalarla dolu. Yok 'Asla intikam için can alma,', yok 'Kendin için değil dünya için savaş'. Bana gelecek olursak...''","Birim",[],["Shurima"],"Şampiyon"],"04SH114":["Çölün Gazabı","Her yerdeki dost Kumdan Asker kartlarına +1|+0 kazandırırsın.\n2 Kumdan Asker çağırırsın.","","İstirahat nedir, tereddüt nedir bilmiyorlar. Yılmıyor, acımıyor, pes etmiyorlar.","Büyü",[],["Shurima"],"ENDER"],"04SH067":["Renekton","Bir düşmanı çektiğimde, bana bu tur için +2|+1 verirsin.","10+ hasar verdiğimde.","''Krokodil başı çok sevdiği kanlı savaşlara öylesine uyuyor ki, bir zamanlar insan olduğunu unutmak çok kolay...'' \n- Kâtip Kah'nir, Yükseliş'e Ermişler Ordusu'nun Tarihi","Birim",["YÜKSELMİŞ","SÜRÜNGEN"],["Shurima"],"Şampiyon"],"04SH120":["Düşlenen Olasılıklar","Elinde Geri Sayım'ı olan rasgele bir Yer kartı oluşur ya da sana ait Yer kartlarını 1 tur ilerletirsin.","","''Zaman uçar, gider...''\n- Zilean","Büyü",[],["Shurima"],"ENDER"],"04SH119":["Seken Atış","Şöhret: Bedelim 3 azalır.\nRasgele bir düşmana ya da rakibin Nexus'una 5 kere 1 hasar verirsin.","","''Ortalık yine batacak.''\n- Sivir","Büyü",[],["Shurima"],"YAYGIN"],"04SH068":["Xer'Sai Çağırıcı","Oyna: Öngörüde bulunursun.","","Bütün xer'sai'ler katliam için doğmamıştır. Bazıları hem kumları hem duyuları bulandıran, kulak delici bağırışlarla türdeşlerini çağırabilir.","Birim",["PUSUCU"],["Shurima"],"YAYGIN"],"04SH093":["Şekillendirilmiş Taş","Bu tur bir dost birime +1|+1 verirsin.\nBu oyunda bir Yer kartı çağırdıysan, bunun yerine +2|+1 verirsin.","","''Bu diyarın da yardımıyla kendimizi savunacağız!''\n- Taliyah","Büyü",[],["Shurima"],"YAYGIN"],"04SH079":["Kehanet Kumları","Öngörüde bulunursun.\nBir düşmana bu tur -2|-0 verirsin.","","''Kaderimi gördüm. Bu sefer beni durduran çıkamayacak.''\n- Azir","Büyü",[],["Shurima"],"ENDER"],"04SH038":["Kaya Kızakçısı","Çağrıldığımda bir Dalgalı Kumlar çağırırsın.","","''Bugün Nashramae yoluna çıktık. Samir dolunay olmadan Büyük Sai'yi geçmeye kararlı ve O KADAR dağınık gidiyor ki! Bir tanecik kızağın bir kum tepesini çökertebileceğini bilmiyordum. Samir de bilmiyormuş. Neyse, bir şey olmadı.''\n- Zaifa'nın günlüğünden","Birim",[],["Shurima"],"YAYGIN"],"04SH104":["Muhafazacı","Oyna: Dost bir Yer kartını 3 tur ilerletirsin.","","Zilean ne zaman huzur bulmak istese Icathia'nın son bahçesini kendi hatırladığı haliyle ziyaret ediyor.","Birim",[],["Shurima"],"ENDER"],"04SH128":["Vekaura'lı Avare","Çağrıldığımda bir Savaş Beyinin Sarayı çağırırsın ya da onu 2 tur ilerletirsin.","","Akshan'ı dördüncü kat penceresinden sallanırken gören Najah fısıltıyla küfretti. Süslü oğlan ondan önce gelmişti. Yine. Hançerini elinde evirip çevirirken ona ne diyeceğini düşündü. Belki bu sefer Najah'nın varlığını kabul etmek zorunda kalırdı.","Birim",[],["Shurima"],"YAYGIN"],"04SH109":["Kum Batağı","Bu tur bir düşmana -4|-0 ya da 2 düşmana -1|-0 verirsin. Faydalı tesirlerini bu tur devre dışı bırakırsın.","","Çölün bazı bölgelerinde eski harabeler kuma gömülmüş, dikkatsiz gezginlere kucak açan delikler yaratmıştır. ","Büyü",["ELEMENTAL"],["Shurima"],"YAYGIN"],"04SH043":["Kayan Kumlar","Bir birime 4 hasar verirsin.\n2 Kumdan Asker çağırırsın.","","''Gidin. Etraflarını sarın. Toprağın bizzat kendisiyle başa çıkamazlar.''\n- Azir","Büyü",[],["Shurima"],"ENDER"],"04SH099":["İleri!","Bir Kumdan Asker çağırırsın.\nElinde Geçici bir İleri! oluşur.","","''Emir verildi.''\n- Azir","Büyü",[],["Shurima"],"ENDER"],"04SH048":["İç Mabet","Şöhret: Bedelim 3 azalır.\nGeri Sayım - 1: Elinde 2 Şanslı Keşif oluşur.","","''Bazı haritaları çözmek yıllar sürer, bazı tuzakları bozmak aylar sürer, bazı mezarları gezmek haftalar sürer. Ama sonunda başarırsan var ya, işte o harcadığın her ana değer.'' \n- Sivir","Yer",[],["Shurima"],"YAYGIN"],"04SH056":["İşbilir Yağmacı","Çağrıldığımda elinde bir Şanslı Keşif oluşur.","","''Sevgili arkadaşım, bu eşsiz ve de enfes parçayı meşhur İmparator Mezarı'nda buldum ve bizzat heybetli Renekton'un pençesinden çekip aldım. Tam kaçarken etrafımı on... Yok, yirmi kana susamış sauren binicisi sarmasın mı? Böylesi bir hazinenin senin eline geçmiş olması mucize, mucize...''","Birim",[],["Shurima"],"YAYGIN"],"04SH020":["Sivir","","30+ hasar verdiğinde.","Sivir hayatını paralı asker olarak geçirdi ve bu seçimiyle gelen tüm riskleri de, ödülleri de kabullendi. Fena halde sarpa saran bir keşif gezisi neredeyse canına mal olacaktı ama kanı Shurima'nın kumlarına sızarken, hem onu hem de yurdunu akıl etmediği yüceliklere ulaştıracak bir gücü uyandırdı.","Birim",[],["Shurima"],"Şampiyon"],"04SH057":["Kumların Mareşali","Başka bir dost birim çağırdığında ona bu tur +2|+0 verirsin.","","Azir'in kutsamasına erişmek büyük onur. Onun adına bir kutsamada bulunmak daha da büyük onur.","Birim",[],["Shurima"],"ENDER"],"04SH103":["Merhametsiz Avcı","Oyna: Bir düşmana Kırılganlık kazandırırsın.","","''Hah, bak ne güzel paket oldun. Renekton yemeğini, yenirken kıvranabilecek kadar canlı sever.''","Birim",[],["Shurima"],"YAYGIN"],"04SH065":["Yeraltı Devi Xerxa'Reth","Saldır: Güç değerim 8+ ise bana bu tur Korkunç, Aban ve Büyü Kalkanı verirsin.","","''Söylencelere göre, bundan yüzlerce yıl önce Khaleek nehrinin kıyılarında Taraleek diye koca bir ticaret şehri varmış. Ama bir gün yer yarılıp içinden muazzam büyüklükte bir canavar çıkmış ve hem şehri, hem de içinde yaşayan herkesi yok etmiş. Fakat böyle bir şeye hangi canavarın gücü yeter?''\n- Shurima tarihçisi","Birim",["PUSUCU"],["Shurima"],"DESTANSI"],"04SH034":["Saat Uşak","Çağrıldığımda elinde 2 Anlık Asır oluşur.","","Kulenin alt katlarındaki kesilmeyen gümbürtü sesi, yerin altındaki çarkları sürekli kuran Saat Uşak'tan geliyor.","Birim",[],["Shurima"],"DESTANSI"],"04SH082":["Şer Yolu","1 kart çekersin.\nBu tur bir birim katlettiysen rakibin Nexus'una 2 Sömürü hasarı verirsin.","","Kumharmancılarının birincil asker kaynağı düşman saflarıdır. İlk hücumlarından sağ çıkanlara, onlara katılma ya da ölme seçeneği sunulur.","Büyü",[],["Shurima"],"ENDER"],"04SH075":["İmparatorluk Muhafızları","Bu tur düşmanlara Kırılganlık verirsin ve 6 Kumdan Asker çağırırsın.","","''Yürüyün askerlerim!''\n- Azir","Büyü",[],["Shurima"],"DESTANSI"],"04SH018":["Baskınlık Ayini","Bir dost birimi öldürerek ya da bir mana taşını yok ederek bu tur tüm düşmanlara -2|-0 verirsin.","","''Savaşacağız, ölecekler!''\n- Renekton","Büyü",[],["Shurima"],"ENDER"],"04SH009":["Kudurgan Baccai","Oyna: Bu oyunda 4+ birim katlettiysen, bir düşman ve ben birbirimize vururuz.","","Kin tutanın kini, hasımları öldükten çok sonra bile büyümeye devam eder.","Birim",[],["Shurima"],"ENDER"],"04SH049":["Kaderin Seçilmişi Poro","Tur Başı: Bir şampiyona seviye atlattıysan Haşmetli Poro birimine dönüşürüm.","","Ne bulduğunu tam olarak anlamamıştı... ama parlak bir şeydi, şekli de kurabiyeye benziyordu.","Birim",["PORO"],["Shurima"],"YAYGIN"],"04SH045":["Bitkinlik","Bir düşmana bu tur -2|-0 ve Kırılganlık verirsin.","","Çöl sakinleri güneşin kavurucu, aralıksız sıcağından kaçınmayı bilir ama ona göğüs germeye hazırlıklı olmayanların gücü ve enerjisi hızla tükenir.","Büyü",[],["Shurima"],"YAYGIN"],"04SH037":["Toprak Bozumu","2 Dalgalı Kumlar çağırırsın.\n1 kart çekersin.","","Büyük Sai ne kadar güzel olsa da zayıflara göre bir yer değil. Uzanıp giden kum tepeleri arasında çok yaşam sona ermiş. Çoğunu xer'sai'ler kapsa da bu diyarın kendisi de çok can alıyor.","Büyü",["ELEMENTAL"],["Shurima"],"ENDER"],"04SH107":["Yükselmişlerin Uyanışı","Tüm 1. seviye Yükselmiş dost birimlere seviye atlatırsın.","","''Gelecek, Yükselmişler tarafından yazılacak!''\n- Azir","Büyü",[],["Shurima"],"DESTANSI"],"04SH047":["Nasus","Bu oyunda katlettiğin her birim için +1|+1 kazanırım.","Tek seferde 10+ hasarlık vuruş yaptığımda.","''Nasus yeni elde ettiği bu lütuf sayesinde sayısız insan ömrü boyunca araştırma yapmış, yaşamın ve ölümün doğası üstüne düşünmüş. Ama Shurima'nın çöküşünden sonra, bu uzun ömür onun için aynı zamanda bir lanet olmuş.'' \n- Kâtip Kah'nir, Yükseliş'e Ermişler Ordusu'nun Tarihi","Birim",["YÜKSELMİŞ","KÖPEK"],["Shurima"],"Şampiyon"],"04SH097":["Mabedin Bekçisi","Oyna: Düşman bir takipçiyi öldürürsün. Bu oyunda 13+ birim katlettiysen bunun yerine tüm düşman takipçileri öldürürsün, sonra bir kopyamı çağırırsın.","","Baccai'ler kadim hazineleri korumak adına iç mabedi savunmakla görevlendirilmiştir. Tabii, Kumların Efendisi'nin yargısına göğüs gerebileceğini düşünen, kendini akıllı veya yüce zanneden fanilerin iyiliği için bir de.","Birim",[],["Shurima"],"DESTANSI"],"04SH026":["Kum Serdarı","Çağrıldığımda bir Kumdan Asker çağırırsın.","","''İmparatorun emrine hem ben hem kumlar itaat ederiz.''","Birim",[],["Shurima"],"YAYGIN"],"04SH102":["Altın Elçi","Sadakat: Bir şampiyon çekersin ve ona +2|+2 kazandırırsın.","","''Pırıl pırıl geleceğimiz kumların hemen ötesinde. Bu yolda Azir'e yardım etmek bize düşer! Çölün altın imparatorluğu tekrar yükselecek!''","Birim",[],["Shurima"],"YAYGIN"],"04SH001":["Öğrenci Zaman Büyücüsü","Oyna: Öngörüde bulunursun.","","Tai, zaman büyücülüğü öğrencisi olduğu süre boyunca kuşkularıyla kararlılığını uzlaştırmak zorunda kaldı. Ters gidebilecek şeylere kafayı takmaktansa zafere ulaşacağı umudunu beslemek daha iyiydi.","Birim",[],["Shurima"],"YAYGIN"],"04SH022":["Xer'Sai Tepedeviren","","","Tüm xer'sai'ler çok iyi tünel kazarlar ama sadece ''tepedeviren'' xer'sai'ler Büyük Sai'nin her yerine yayılmış sert kaya damarlarını delip bunların ötesindeki toprakları avlanmaya açacak kadar güçlü ve cüsselidir.","Birim",["PUSUCU"],["Shurima"],"ENDER"],"04SH030":["Zaman Kayması","Bir dost şampiyona ''Bu tur ölecek kadar hasar aldığım bir sonraki sefer ölmek yerine tamamen iyileşirim ve +3|+3 kazanırım'' etkisi verirsin.","","''Kaçınılmazı durduramayız... ama geciktirebiliriz.''\n- Zilean","Büyü",[],["Shurima"],"ENDER"],"04SH013":["Muhafazahane","Çağrıldığımda 1 kart çekersin.\nGeri Sayım - 2: 1 kart çekersin.","","Zilean kuleye getirdiği herkese, tam olarak neyi eski haline getirmeye çalıştıklarını gösterir. Bunu bir anlığına da olsa yapabilmesini sağlayan Muhafazacı'dır.","Yer",[],["Shurima"],"ENDER"],"04SH062":["Gömülü Güneş Kursu","Oyun Başlangıcı: Tüm desten Shurima kartlarından oluşuyorsa, destenden benden 1 tane çağırırsın.\nGeri Sayım - 25: Güneş Kursu'nu onarırsın.\nBu oyunda seviye atlamış her Yükselmiş dost birim için beni 9 tur ilerletirsin.","","Azir Shurima başkentinin Güneş Kursu'na bakınca onun o andaki halini değil, asıl amacını gördü: Shurima'yı eski görkemine kavuşturmanın anahtarını.","Yer",[],["Shurima"],"DESTANSI"],"04SH016":["Sömürü Darbesi","Bir dost birim bir birime vurur.\nVurduğu birim ölürse, her yerdeki dost şampiyonlar +2|+2 kazanır.","","''Ruhun ölçülüp biçilecek.''\n- Nasus","Büyü",[],["Shurima"],"ENDER"],"04SH125":["Vekaura'lı Kasa Hırsızı","Oyna: Bu tur bir dost birime +2|+0 vererek bir düşmana -2|-0 verirsin.","","Tena, evcil hayvanının asitli salyasının sarayın arka kapısındaki yaldızlı parmaklıkları eritmesini sabırla bekledi. Az ileride akla hayale sığmayacak kadar kıymetli bir hazine bulacaktı. Vekaura'yı eski görkemine kavuşturmaya fazla fazla yeterdi.","Birim",[],["Shurima"],"ENDER"],"04SH108":["Bıçaklı Bumerang","Bir dost birim En Güçlü ve En Güçsüz düşmanlara sırayla vurur.","","''Eğil.''\n- Sivir","Büyü",[],["Shurima"],"ENDER"],"04SH066":["Zaman Kumbarası","Öngörüde bulunur ve dost bir Yer kartını 2 tur ilerletirsin.","","''Zamanı benim gördüğüm gibi görebilsen, değişmez bir şey olmadığını anlardın.''\n- Zilean","Büyü",[],["Shurima"],"YAYGIN"],"04SH021":["Geri Dönen Khahiri","Çağrıldığımda destende bir kopyam oluşur. Beni bir Öngörü'de gördüysen, her yerdeki dost kopyalarıma +2|+2 kazandırırsın.","","Khahiri yok olduktan bir an sonra aniden geri geldi. Neredeyse on yaş büyümüştü. Elinde tuhaf ve ölümcül görünümlü bir silah vardı. Elbette, hayret ve endişe dolu iç çekişlerle karşılandı.","Birim",[],["Shurima"],"ENDER"],"04SH101":["Sadık Konsey","Tur Başı: Bir şampiyona seviye atlattıysan, şampiyonlarını ve Nexus'unu 2 iyileştirirsin.","","''Kendimi Azir'e, yurdum Shurima'ya adadım! Siz de bana katılmaz mısınız?''","Birim",[],["Shurima"],"ENDER"],"04SH012":["Saygıdeğer Tefsirci","Çağrıldığımda, Gömülü Güneş Kursu kartını 3 tur ilerletirsin.","","''Aa, şu Nashramae'nin büyüklerinden Padjuman değil mi? Galiba herkes bugün bizim şehre gelmiş baba!'' \n- Heyecanlı seyirci","Birim",[],["Shurima"],"YAYGIN"],"04SH031":["Parlak Gelecek","Dost bir Yer kartına ''Geri Sayım etkim iki kere gerçekleşir'' etkisini kazandırırsın.","","''Faniler ömürlerinin çoğunu bekleyerek geçiriyor. En büyük umudum, bu sabırlarının ödülünü almaları.''\n- Zilean","Büyü",[],["Shurima"],"DESTANSI"],"04SH004":["Yargının Ağırlığı","Bir şampiyona 2 hasar ya da bir takipçiye 4 hasar verirsin.","","''Birçok canı kurtarmak için birini feda etmek. Diğer hepsi yaşasın diye bir candan vazgeçmek.''\n- Nasus","Büyü",[],["Shurima"],"YAYGIN"],"04SH059":["Hükümsüzlük Ayini","Bir dost birimi öldürerek ya da bir mana taşını yok ederek tüm Hızlı ve Yavaş düşman büyüleriyle yeteneklerini durdurursun.","","Zaman büyüsünün temelinde analiz yatar çünkü gelecekteki çözümleri üzerine düşünmek için pek çok eylem durdurulur.","Büyü",[],["Shurima"],"DESTANSI"],"04SH044":["Kurmalı Kâhya","Oyna: Dost bir Yer kartını 2 tur ilerletirsin.","","Zilean'ın kulesini koruyan mekanik varlıklar çölün zorlu koşullarına binlerce yıl dayanabiliyor. Bunun tek sebebi, akıllıca yapılmış tasarımları değil.","Birim",[],["Shurima"],"YAYGIN"],"04SH076":["Antik Kum Saati","Bir dost birimin Kökünü Kazıyıp yerine bir Durağan Zaman Heykeli çağırırsın, dost birimi içine koyarsın.","","''Hah, Tai! Böyle gelsene! Şuna bir yardımın gerek.''\n- Xetsa, Hiçlik Araştırmacısı","Büyü",[],["Shurima"],"ENDER"],"04SH118":["Yükselen Kumlar","Bir Kumtaşı Savaşçı çağırırsın.","","''Kutu para edebilir ama içindeki şeyin para etmeyeceği kesin. Yani, açmaya değmez. Geçtik bu yollardan.''\n- Sivir","Büyü",[],["Shurima"],"YAYGIN"],"04SH072":["Vahadaki Bakıcı","Çağrıldığımda dost şampiyonlar ve Yer kartları Büyü Kalkanı kazanır.","","''Tabii ya, çölün ortasında su görmeyi beklemiyordun. Sakın korkma. Gel kana kana iç, yıkanıp serinle. Gölgede biraz dinlen. Burası Azir'in yeni Shurima'sı. Tüm ülke bir vaha.''","Birim",[],["Shurima"],"YAYGIN"],"04SH041":["Sai Gözcüsü","Oyna: Öngörüde bulunursun. Seçimin Yer kartıysa, ben Sıyrılgan kazanırım.","","''Demin başımıza iş açıldı! Batıdan şiddetli bir fırtına geliyordu, Taliyah da güneydeki xer'sai tünellerini geçmişti. Kuzeyde bir tapınak gördüm. Şimdi onun toprak duvarları arasında güvendeyiz. Herkes uyuyor. Benim de mumum, gücüm gibi bitmek üzere. Umarım güzel rüyalar görürüm.''\n- Zaifa'nın günlüğünden","Birim",[],["Shurima"],"YAYGIN"],"04SH005":["Kana Susamış Talancı","","","Kumharmancıları her şeyi yoldaşlarıyla birlikte yapar. Birlikte savaşır, avlanır, öldürür... ve yemek yerler.","Birim",[],["Shurima"],"YAYGIN"],"04SH083":["Yabani Sezgi","Öngörüde bulunursun.","","''Yüzgeç korkutur ama dişler öldürür.''\n- Shurima sözü","Büyü",[],["Shurima"],"ENDER"],"04SH092":["Zaman Geldi","Bir Saat Dost çağırırsın.\nBu oyunda Öngörüde bulunduysan, 1 yerine 2 tane çağırırsın.","","''Gel buraya, kıpırdanıp durma! Çarklarına kum kaçmış.''\n- Öğrenci Zaman Büyücüsü Tai","Büyü",[],["Shurima"],"YAYGIN"],"04SH046":["Kumtaşı Kimera","Bu oyunda bir dost birimin saldırdığı her sefer için bedelim 1 azalır.","","Azir döndüğünde Shurima'lılar efsanelerde dinledikleri kadim canavarları kendi gözleriyle gördüler. Kumdan yapılmışlardı ama yine de çok etkileyiciydiler.","Birim",[],["Shurima"],"ENDER"],"04SH105":["Kumla Kaplı Mezar","Dost birimler saldırdığında, saldıran bir Kumtaşı Savaşçı çağırırsın.","","Vadideki yarıktan geçerken Kum Ustası sihirli sözleri söyledi. Kanyonu bir rüzgâr sesi aldı ve sonra yerini yaklaşan toynakların gürlemesine bıraktı.","Yer",[],["Shurima"],"ENDER"],"04SH131":["Kanca Tabancası","Bu tur hedef aldığın bir dost birim bir düşmana vurur.","","''Kanca tabancasına herkes şaşırıyor!''\n- Akshan","Büyü",[],["Shurima"],"ENDER"],"04SH074":["Xer'Sai Yavrusu","","","Bir kervan kaçamaz hale getirildiğinde, avcılar ara sıra çekilip yavrularının saldırmasına izin verir. Genç xer'sai'ler hangi seslerin çölün sıradan sesleri, hangilerininse avlarının sesi olduğunu böyle öğrenerek içgüdülerini keskinleştirir.","Birim",["PUSUCU"],["Shurima"],"YAYGIN"],"04SH137":["Uğuldayan Sürü","Çağrıldığımda bu oyunda bir şampiyona seviye atlatmışsan elinde bir kopyam oluşur.","","Dev gübre böceklerinin soyunun, Shurima imparatorluğunun çöküşüyle tükendiği düşünülüyordu. Ama sisin uğursuz uzantıları kumların ta derinlerine gömülüp bu kadim canlıları Viego'ya köle etti.\n","Birim",[],["Shurima"],"DESTANSI"],"04SH069":["İnsafsız Yırtıcı","Bu tur bir dost birime +2|+0 vererek bir düşmana Kırılganlık verirsin.","","''Parçalayın!''\n- Renekton","Büyü",[],["Shurima"],"YAYGIN"],"04SH121":["Çağrı Ayini","Bir dost birimi öldürerek ya da bir mana taşını yok ederek bir şampiyon çekersin.","","''Gerekli bir fedakârlık.''\n- Nasus","Büyü",[],["Shurima"],"YAYGIN"],"04SH110":["Taş Dokuma","Bedelini ödeyebileceğin bir Yer kartı Cisimlenir.","","''Gelin, görecek çok şey var!''\n- Taliyah","Büyü",["ELEMENTAL"],["Shurima"],"DESTANSI"],"04SH051":["İmparatorun Kürsüsü","Dost birimler saldırdığında, saldıran bir Kumdan Asker çağırırsın.","","Kum Ustaları kollarını kaldırdı; kumu zırhlı, yüzü olmayan askerlerin tanıdık biçimlerine dönüştürerek ilah imparatorları için savaşmaya hazır, yorulmaz bir ordu yaptılar. ","Yer",[],["Shurima"],"ENDER"],"04SH106":["Ruh Ateşi","Düşmanlara bu tur -2|-0 ve ''Tur Sonu: 2 hasar alırım'' özelliğini verirsin.","","''Ruhları yanacak.''\n- Nasus","Büyü",[],["Shurima"],"ENDER"],"04SH129":["Vekaura'lı Kötekçi","Vuruş: Elinde bir Şanslı Keşif oluşur.","","''Evet Barbiş'çiğim, bu kattaki son muhafız buydu. Ama yine de kimse burada olduğumuzu çakmamalı.''\n''BLARGH-BLAA!''\n''Küçük sesinle konuş Barbara.''\n''Blarb.''\n''Aferin kızıma.''","Birim",[],["Shurima"],"ENDER"],"04FR006":["Draklorn İnfazcı","Çağrıldığımda bir Donuk Köle çağırırsın.\nTur Sonu: Donuk Köle birimlerinden herhangi birinin Geri Sayımı 4 ya da daha azsa, onları 0'a ilerletirsin.","","''Hanımım bana rüyalarımda görünüyor. Sesi neredeyse bir fısıltı. Bana, 'Takip et,' diye buyuruyor. Bu emre karşı gelmeye cüret edemem.''","Birim",[],["Freljord"],"DESTANSI"],"04FR012":["Buza Gömülü","Her bir düşmanın Kökünü Kazıyıp yerlerine birer Donmuş Mezar çağırırsın, düşmanları içlerine koyarsın.","","''Soğuk zamanla her şeyin hakkından gelir.''\n- Lissandra","Büyü",["ELEMENTAL"],["Freljord"],"DESTANSI"],"04FR016":["Savaş Ganimeti","Bir dost birime +1|+2 kazandırırsın.\nYağma: Onun yerine +2|+4 kazandırırsın.","","''Siz Avarosalar verimli tarlalarınızda semirip ürkekleşiyorsunuz. Yatın uyuyun bakalım güçsüz zavallılar. Rüyanızda yarının ürünlerini görürken her şeyiniz bizim olacak.''\n- Pençe Anası Vrynna","Büyü",[],["Freljord"],"YAYGIN"],"04FR013":["Soğuk Direnç","Boş bir mana taşı alırsın ve bir dost birime +0|+2 kazandırırsın.","","''Buzdan sakının... Daha da önemlisi... altında yatandan sakının!''\n- Freljord'da bir hanın duvarına karalanmış yazı","Büyü",["ELEMENTAL"],["Freljord"],"YAYGIN"],"04FR005":["Lissandra","Çağrıldığımda bir Donuk Köle çağırırsın ve onu 2 tur ilerletirsin.","Bedeli 8+ olan 2+ dost birim çağırdığında. Seviye atladığımda, elinde bir Gözcü oluşur.","''Gözcüler hemen bu duvarın ardında, buzların içinde, akmayan zamanlarında tutsak halde bekliyor. Onlar bekleyedursun, benim başlatmam gereken tasarılarım var...''","Birim",[],["Freljord"],"Şampiyon"],"04FR011":["Soğuğa Boyun Eğ","Bir düşmana Buz Tutturursun.\nBir Donuk Köle çağırırsın.","","''Soğuk pek çok tepki uyandırır. Bakalım sen hangisini vereceksin?''\n- Lissandra","Büyü",["ELEMENTAL"],["Freljord"],"YAYGIN"],"04FR001":["Donuk Köle","Geri Sayım - 9: Bir Buz Muhafızı Kölesi çağırırsın.","","Trundle'ın karmakarışık ordusunda ön saflarda düşmana yem edilebilecek bol bol yarım akıllı savaşçı vardı elbette. Ama Lissandra çok daha sadık, başka hiç kimseye değil, sadece kendisine hizmet edecek bir şey istiyordu...","Yer",[],["Freljord"],"YAYGIN"],"04FR007":["Mezara Göm","Bir birimin Kökünü Kazıyıp yerine bir Donmuş Mezar çağırırsın, birimi içine koyarsın.","","''Ya boyun eğ, ya don.''\n- Lissandra","Büyü",["ELEMENTAL"],["Freljord"],"ENDER"],"04FR017":["Ataların Lütfu","Destenin en üstündeki dost birime +2|+2 kazandırırsın.\nAydınlanmış: Bunun yerine destendeki tüm dost birimlere +2|+2 kazandırırsın.","","Freljord'un sonu gelmez soğuğu ve amansız fırtınaları, çorak topraklarına ayak basan çoğu kişiyi öldürür. Ama sağ kalabilenler öyle bir içsel güçle dolar ki ömürleri boyunca yıkılmazlar.","Büyü",[],["Freljord"],"YAYGIN"],"04FR014":["Marazlı Koyak","Çağrıldığımda Nexus'unu 2 iyileştirirsin.\nGeri Sayım - 1: TÜM birimlere 2 hasar verirsin.","","Bu dar, derin vadinin her yüzeyinden tuhaf biçimli kara buzlar fırlamış. Dışarı dönük uçları, girmeye yeltenecek herkesi vazgeçirecek kadar sivri.","Yer",[],["Freljord"],"ENDER"],"04FR009":["Keskin Buz","HER ŞEYE 1 hasar verirsin.","","''Dünyayı buzla kaplayacağım.''\n- Lissandra","Büyü",["ELEMENTAL"],["Freljord"],"YAYGIN"],"04FR015":["Efsanevi Poro","Çağrıldığımda, dost Porolara rasgele bir tesir kazandırırsın.","","Tüm porolarca efsane olarak kabul edilen bir kişi olduğu söylenir. Derler ki bu kişi gezileri sırasında karşılaştığı kürklü dostlarına hak ettiklerini düşündüğü büyülü hediyeler verirmiş.","Birim",["PORO"],["Freljord"],"ENDER"],"04FR019":["Buz Dişli Sürü Anası","Çağrıldığımda bir Buz Dişli Kurt Sürüsü çağırırsın.","","Buz dişli kurtlar yere iyice yaklaşarak Drüvask'ın etrafını sardı. Tetikteydiler. Hayvandan keskin ve boğucu bir ölüm kokusu yayılıyordu.","Birim",["KÖPEK"],["Freljord"],"ENDER"],"04FR018":["Koca Yeti Muhafız","Ben elindeyken Tur Başı: 2+ Yetin varsa beni çağırırsın ve destende bir kopyam oluşur.\nOyna: Bir Yeti çekersin.","","''...çok da sinsiler haa! Oralara son gidişimde bir mağaraya sığındım. Bir de ne göreyim, içeride mışıl mışıl uyuyan yavrular var! Uzak durmaya çalıştım ama sonra anası mıdır babası mıdır dönüp geldi. Dağ kadar bi' şey, üstü buz kaplı! Bak bana iyi kulak ver, çünkü...''\n- Ödü Kopmuş Bjerg","Birim",["YETİ"],["Freljord"],"DESTANSI"],"04FR010":["Üç Kız Kardeş","Elinde Geçici bir Ani Donduruş, Kuzeyin Hiddeti ya da Mezara Göm oluşur.","","Freljord'lu kız kardeşler Avarosa, Serylda ve Lissandra muazzam güce sahiptiler. Ama hepsi bu gücü farklı bir şekilde kullandı; biri merhametli, biri savaş yanlısı, biri de kötücül oldu.","Büyü",[],["Freljord"],"ENDER"],"04NX002":["Fısıldanan Kelimeler","Şöhret: Bedelim 2 azalır.\n2 kart çekersin.","","Haberler gelmeden dedikodu gelir. Dedikodu çıkmadan oyun çıkar. Oyun yazılmadan plan yapılır.","Büyü",[],["Noxus"],"ENDER"],"04NX010":["Gülün Dikeni","Çağrıldığımda elinde bir Kurnazlık oluşur.","","''En kıymetli dostum ve iş arkadaşım Aelana! Lord Duin'e şey diyecektim... Ah, ne fena. Bu akşam onunla biraz hoşbeş ederiz diye umuyordum. Umarım fazla kaçırmamıştır. Kaç yaşında adam, başına kötü bir iş gelmesin...'' \n- Kara Gül Casusu Leydi Auvray","Birim",[],["Noxus"],"YAYGIN"],"04NX021":["Emekli Hesapçı","Beni hedeflediğinde +1|+0 kazanırım.","","Beryn sayısız çarpışmadan sonra canı tehlikede olsa bile kılıcını bir daha eline almamaya ant içmişti. Fakat garip sisler Noxus'a doluşup Thea'yı ele geçirdiğinde bu sözünü bozması gerektiğini anladı. Onu ne olursa olsun kurtaracaktı.","Birim",[],["Noxus"],"ENDER"],"04NX022":["Mahvolmuş Hesapçı","Çağrıldığımda elinde bir Geceyarısı Baskını oluşur.","","Cezası bittiğinde Thea bir daha asla halkının arasına karışamayacağını biliyordu. Savaş (ve Noxus) onu değiştirmişti, katile dönüştürmüştü. Huzura kavuşamayacaktı. Bu yüzden yeni becerilerini arenalarda paraya çevirmeye başladı.","Birim",[],["Noxus"],"ENDER"],"04NX015":["Kanlı İş","Şöhret: Bedelim 2 azalır.\nGüç değeri 5+ olan bir dost birim, bir düşmana vurur.","","''En büyük tehditler, gözden saklı olanlardır.''\n- LeBlanc","Büyü",[],["Noxus"],"YAYGIN"],"04NX019":["Direnen Kapanbağa","Bir düşman beni karşıladığında bu tur +3|+0 alırım.","","Ionia kıyılarında buldukları yaratığın dayanıklılığına şaşıran genç general, onun asıl gücünü öğrenmek için kendi ülkesine götürmekte ısrar etti.","Birim",["SÜRÜNGEN"],["Noxus"],"DESTANSI"],"04NX008":["İş Bitirici Taktisyen","Şöhret: Bedelim 2 azalır.\nÇağrıldığımda Silahlanırsın.","","Kara Gül'ün gizli odalarında, Noxus'lu soylular piyonlarını oynar ve uzaklardaki kurbanlarının payına cinayet düşer.","Birim",[],["Noxus"],"ENDER"],"04NX006":["Kara Gül Casusu","Şöhret: Çağrıldığımda beni bu tur vuruş yapmış olan En Güçlü dost birimin birebir kopyasına dönüştürürsün.","","''Bir sırrın tek değeri, onu saklamanın bedelidir.''","Birim",[],["Noxus"],"DESTANSI"],"04NX001":["Taklit","Şöhret: Bedelim 3 azalır.\nBu tur oynadığın bir sonraki büyüyü aynı hedeflere kopyalarsın.","","Taklitler asıllarını yaşatır derler ama burada pek öyle bir niyet yok.","Büyü",[],["Noxus"],"ENDER"],"04NX004":["LeBlanc","","15+ hasar verdiğini gördüğümde. Seviye atladığımda, elinde bir Ayna Görüntüsü oluşur.","''Aa, kendi aramızda didişmenin ne lüzumu var? Gelin ihtiyatsız hareketlerden kaçınalım. Elçimizden haber gelince yine toplanırız. Neticede...''","Birim",[],["Noxus"],"Şampiyon"],"04NX016":["Bağıran Örümcek","Saldır: Dost Örümceklere bu tur +2|+0 verirsin.","","''Hadi şekerim bağır, çağrını hepsi duysun. Ne kadar heyecanlandıklarını biliyorsun. Beni ne kadar memnun ettiğini de...''\n- Elise","Birim",["ÖRÜMCEK"],["Noxus"],"ENDER"],"04NX007":["Harap Eden Atakhan","Oyna: Ölmüş olan En Güçlü dost birim dirilir.\nSaldır: Bana tüm dost birimlerin toplam Güç değeri kadar Güç kazandırırsın.","","Dumanla dolu odada, isimsiz bir ucube tepelerinde dikiliyordu. Büyücüler ahenksiz bir koro halinde büyülü sözleri tekrarlıyorlardı. Sesleri dehşetten tizleşmiş, neredeyse delice bir hal almıştı. Canavar artan korkularını içine çekti ve her nefes ona korkunç bir güç verdi.","Birim",[],["Noxus"],"DESTANSI"],"04NX018":["Kızıl Kanalıcı ","Çağırdığın bir sonraki dost birime 1 hasar verir, bana +1|+1 kazandırırsın.","","''Bunları ev hayvanı olarak beslemezler tabii pek. O pençelerle azıcık tırmalasalar bile bir damarı kesebilirler... ama bence sakıncası yok.''\n- Kızıl Talebe Clara","Birim",["KEDİ"],["Noxus"],"YAYGIN"],"04NX003":["Şer Mührü","Şöhret: Bedelim 2 azalır.\nHerhangi bir şeye 2 hasar verirsin.","","Kişi savaşı kazanır kazanmaz hiç tereddütsüz devam edip düşmanını yeryüzünden silmelidir.","Büyü",[],["Noxus"],"YAYGIN"],"04NX017":["Sayı Üstünlüğü","2 Lejyon Yağmacısı çağırırsın.","","Noxus askerleri zaten pek kimsenin canını bağışlamaz, hele bu yağmacılar daha da azını sağ bırakıyor.","Büyü",[],["Noxus"],"YAYGIN"],"04NX009":["Dikenli Hançer","Bir dost birime bu tur +5|+0 verirsin.","","''Zarif ve nazik olacaksın. Pohpohlayacaksın, yatıştıracaksın. Dinleyeceksin. Öğreneceksin. Sonra vakti geldiğinde saldıracaksın ve MUTLAKA öldüreceksin.''\n- LeBlanc","Büyü",[],["Noxus"],"YAYGIN"],"04SI005":["Kindred","Her tur, ilk kez bir birim katlettiğinde En Güçsüz düşmanı damgalarım.\nTur Sonu: Damgaladığım düşman birimi öldürürsün.","Damgaladığım 2+ birimi katlettiğini gördüğümde.","Evvel zaman içinde yalnız bir adam varmış\nBölmüş kendini ortadan ikiye\nBirken iki olmuş artık\nHep bir arkadaşı olsun diye","Birim",[],["Gölge Adalar"],"Şampiyon"],"04SI055":["Viego","Her tur ilk defa başka bir dost birim öldüğünde bir Yutan Sis çağırırsın.","Toplam 20+ Güç değerine sahip dost birimin öldüğünü gördüğümde.","''Genç kralda beni derinden huzursuz eden bir şey var. Yüreğindeki bir şey... doyurulamaz bir açlık, tatmin edilemeyen bir arzu.''\n- Camavor'lu Nunyo Necrit'in kayıtlarından","Birim",[],["Gölge Adalar"],"Şampiyon"],"04SI016":["Ruh Sülüğü ","Oyna: Bir dost birimi öldürerek 2 kart çekersin.","","Gölgelerde pusmuşlar, akıbetini kabullenmiş veya dalgınlığa yenik düşmüşleri bekliyorlar. Sonra pençeler çıkıyor, koca bir ağız açılıyor ve en nihayetinde her şey karanlığa gömülüyor.","Birim",[],["Gölge Adalar"],"YAYGIN"],"04SI007":["Akıbet Umacısı","Oyna: Bir düşmanı öldürmek için bir dost birimi öldürürsün.","","''Buradaki zamanım sona ererken düşünmeden edemiyorum; ilk ölümüm değil de ikincisi hakkında... Adımı en son kim hatırlayacak? Anılarımı zihninde taşıyan o son kişi de girince toprağa... ne olacak halim?''\n- Saygın Hayırsever","Birim",["KUŞ"],["Gölge Adalar"],"ENDER"],"04SI011":["Günbatımına","1 kart çekersin.\nAkşam: Bir dost birimin Akşam etkisini, hedeflenen kısımları görmezden gelerek etkinleştirirsin.","","''Gel, çocuğum. Korkacak bir şey yok.''\n- Maskeli Ana","Büyü",[],["Gölge Adalar"],"ENDER"],"04SI018":["Uğursuz Koruluk","3+ Korkunç veya Akşam'lı dost birimin saldırdığını gördüğümde beni yok edip bir Zehirçene çağırırsın.","","Patikalarında yürüyen yok, uykuda sunakları,\nAma ancak ahmaklar unutur karanlıkta gezinen canavarı.","Yer",[],["Gölge Adalar"],"DESTANSI"],"04SI015":["Deniz Böceği","Başka bir dost birim öldüğünde ya da Son Nefes: 1 kartı Denize Atarsın.","","''Acele edin de şu tuzakları çekin! Unutmayın ha: deniz böceği görürseniz anında halatı kesip başka tuzağa geçin. Mideye bir şeyler indirmişlerdir diye gemiyi tehlikeye atmaya hiç niyetim yok, anlaşıldı mı?''\n- Bilgewater'lı kaptan","Birim",["DENİZ CANAVARI"],["Gölge Adalar"],"ENDER"],"04SI004":["Kanatlar ve Dalga","Oyna: Beni İlk Dalga ya da Son Rüzgâr olarak oynarsın.","","Kinkou'lar sadece iki ilah bilir: yaşamı sıcak sularında büyüten ilk dalga ve yaşamın bitimindeki soğuk iç çekişleri kapıp kaçan son rüzgâr.","Birim",[],["Gölge Adalar"],"DESTANSI"],"04SI017":["Adaların Şarkısı","Bir dost birime Can Çalma, Korkunç ve Hayali tesirlerini kazandırırsın.","","''Gel, çocuğum. Gördüklerimi gör, hissettiklerimi hisset. Karanlıktan korkmak beyhude.''\n- Ruh Közcüsü","Büyü",[],["Gölge Adalar"],"YAYGIN"],"04SI054":["Camavor Askeri","Çağrıldığımda bir Yutan Sis çağırırsın.","","Camavor askerleri önce yaşarken, ardından öldükten sonra Viego'nun buyruğuyla savaştı. Sadakatleri hiç eksilmedi.","Birim",[],["Gölge Adalar"],"YAYGIN"],"04SI001":["Kuzunun Şefkati","En Güçsüz dost birime bu tur ''Hasar alamam ya da ölemem'' verirsin.","","''Her şey bitmeden bir kez daha parılda.''\n- Kuzu","Büyü",[],["Gölge Adalar"],"DESTANSI"],"04SI056":["Solduran Sis","2 düşmana 2 Sömürü hasarı verirsin.","","''Ne istersem alır, istemediklerimi def ederim.''\n- Viego","Büyü",[],["Gölge Adalar"],"ENDER"],"04SI012":["Astral Tilki","Oyna: Bir dost birimi öldürerek rakibin Nexus'una 3 hasar verirsin.","","Sayıları bir elin parmağını geçmeyen bazı Targon kabileleri, gökyüzünde yalnız bir yıldız olarak görülen bir ölüm ilahından bahseder. Efsanelere göre, bu tilki ilah her ölümde dağa iner, kendi karanlık takımyıldızını yapmak için ruhu gökyüzüne götürürmüş.","Birim",[],["Gölge Adalar"],"YAYGIN"],"04SI029":["Yeis","Nexus'una vuracak bir birim seçersin, sonra onu öldürürsün.","","''Onu bulmak için her şeyimi verdim ama yine de yetmedi.''\n- Viego","Büyü",[],["Gölge Adalar"],"YAYGIN"],"04SI009":["Ruhören","Çağrıldığımda, bu tur bir dost birim ölmüşse +1|+1 ve Korkunç tesirini kazanırım.","","''Evvel zaman içinde, bir örümceğin kalbini kazanmaya çalışan bahtı kara, genç bir adam varmış. Örümceğin ağına düşebileceğini hiç tahmin etmemiş...''","Birim",["ÖRÜMCEK"],["Gölge Adalar"],"YAYGIN"],"04SI013":["Maskeli Ana","Oyna: Bir dost birimi öldürürsün, onun tüm niteliklerini ve tesirlerini kazanırım.","","Derler ki ölümün tüm suretleri gibi Kindred'a da Maskeli Ana şekil vermiş. Peki, kendisi oymadıysa maskesini nereden aldı?","Birim",[],["Gölge Adalar"],"YAYGIN"],"04SI021":["Sürünen Yılanejderi","Beni oynamak için, bir dost birime vururum ya da Nexus'una 3 hasar veririm.","","Demacia'lı askerler başta meydanın taşlarında gezinen düzinelerce pençenin tıkırtısını duyduklarını sandılar. Seslerin tek bir yaratıktan geldiğini ancak gözcü kulesi yıkılınca anladılar.","Birim",["EJDER"],["Gölge Adalar"],"YAYGIN"],"04SI002":["Ruh Yolculuğu","Bir birimi öldürüp diriltirsin.","","''Ara verdik sadece.''\n- Kuzu","Büyü",[],["Gölge Adalar"],"ENDER"],"04SI053":["İşgalci Hidra","Çağrıldığımda ya da Tur Başı: Bir Yutan Sis çağırırsın.","","Maokai, Gölge Adalar'da yaşamı yeşertmek için dur durak bilmeden çalıştı. Sisin belirsizliği, ironik yönlerinin zalimliğini azaltmadı.","Birim",[],["Gölge Adalar"],"DESTANSI"],"04SI003":["Yiten İlah","Çağrıldığımda bir Av çağırırsın.","","Ölümsüzlüğün lanetini üzerinde taşıyanlardan başka kim unutabilir ki kendi ölüm ilahını? Ve unutulup gitmekten başka ne daha büyük bir korku salabilir ki ölüm ilahının yüreğine? ","Birim",[],["Gölge Adalar"],"YAYGIN"],"04SI028":["Camavor Ejderi","Beni oynamak için, bir dost birime vururum ya da Nexus'una 3 hasar veririm.\nBaşka bir birimi öldürdüğümde, rakibin Nexus'una 1 Sömürü hasarı verirsin.","","Kara Sis yüzyıllar boyunca dünyanın dört köşesine yayılıp bulduğu canlıları çarpıttı, yozlaştırdı ve onları kâbuslardan fırlamış yaratıklara dönüştürdü.","Birim",["EJDER"],["Gölge Adalar"],"ENDER"],"04MT014":["Ra-Horak'ın Gözü","Geri Sayım - 1: En Güçsüz 2 düşmanı Sersemletirsin.\nŞafak: Geri Sayım'ı 2 olan bir kopyamı çağırırsın.","","''Güneş ışığını üzerimize yaydıkça, zayıf ve kıymetsiz olanlar o görmesin diye kaçışacak!''\n- Solari Rahibe","Yer",[],["Targon"],"ENDER"],"04MT008":["Malphite","Oyna: Bir düşmanı Sersemletirsin.","10+ manalık Yer kartı çağırdığında. Seviye atladığımda saldırı hakkı sendeyse elinde bir Önlenemez Güç oluşur.","''İşteee Taşkın'la Taygon gezmesinin son duyağına geldiiik: BABAAAM! Babam Taygon devleyinin en büyüyü ayrıca çok güsel şaykı söyley tamam mı! Ama babama tıymanmayın çünki ayakkaplayınızdaki çivileyden gıdıklanıp hapşıyıyo düşüyosunuz soona.''\n- Taşkın'la Maceralar - 6","Birim",[],["Targon"],"Şampiyon"],"04MT010":["Ucu Yıldızlı Zirve","Geri Sayım - 2: Elinde, bedeli 3 ya da daha az olan 2 rasgele Semavi kart oluşur.","","Targon Dağı'na çıkmaya baş koyanlar kısa süre sonra Runeterra'nın en görkemli manzaralarıyla ödüllendiriliyor. Tırmanış çetinleştikçe, ödülleri de artıyor.","Yer",[],["Targon"],"ENDER"],"04MT005":["Taşkın","Bu oyunda bir Yer kartı çağırdığında bana +2|+2 kazandırırsın.","","''Meyaba nabey meyaba benim adım Taşkın sizle Taygon'u geziceez! Üff ne biçim de büyük bi' dağ o yüzden düzgün ayakkabı giyin haa! Eveet GİDİYOYUZ!''\n- Taşkın'la Maceralar - 1","Birim",[],["Targon"],"YAYGIN"],"04MT009":["Sarmal Merdiven","Geri Sayım - 3: Elinde bir Güç Tohumu oluşur.","","''Eveeet tuyumuzda ilk durmakımız buyası. Ben buraya hep bacak tityetici diyoyum çünki üfff ne biçim de çok basamak vay! Manzaya da çok güsel. Bence Taygon'un en güzel şeysi! Hadi GİDİYOYUUZ!''\n- Taşkın'la Maceralar - 2","Yer",[],["Targon"],"ENDER"],"04MT001":["Düşürenkaya Yolu","Geri Sayım - 2: En Güçsüz düşmanın Kökünü Kazırsın.","","''Timdi heykeş beni dinneşin çünkiii buyda KOMACAAAN bi uçuyum vay ve de ben düştüm buydan o yüzden biliyoyum ÇOK YÜKSEK. Ben kaya olduyum için düşünce bi şiy olmuyoy tabiy ama size olabiliy o yüzden dikk... Aaa Sarp buydaymış. Hadi ona meyaba diyelim!''\n- Taşkın'la Maceralar - 3","Yer",[],["Targon"],"YAYGIN"],"04MT018":["Korkmuş Dağ Keçisi","Desteklendiğimde bana ve beni destekleyen dost birime bu tur +1|+1 verirsin.","","''Korkma uğuldayan rüzgârdan\nEser o tepelerden, dağlardan\nSakın korkma yavrum, sıkma canını,\nAnnen yanında, koy yastığa başını.''\n- Targon ninnisi","Birim",[],["Targon"],"YAYGIN"],"04MT004":["Mavi Gözcü","Son Nefes: Bir Sezgi Sorgucu çağırırsın.","","''Şimdi hep biydeen 'MEYABA MAVİ' diyoyuz biy ki üüüç MEYABA MAVİ! Bi kereşinde o da bana MEYHABA MAVİ dedi sandım ama soona dedim ki heyalde kendi sesim duvaydan sekmiştir bence kesin. NEYSEE Mavi büyülü filan bi de mavi o yüzden konuşmasına geyek yok bence. GÜLE GÜLE MAVİ HADİ GİDİYOYUZ!''\n- Taşkın'la Maceralar - 5","Birim",[],["Targon"],"YAYGIN"],"04MT013":["Solari Güneş Atmacası","Şafak: En Güçlü düşmanı Sersemletirsin.","","Solariler Ölümsüz Ateş'in dikkatini çekip ona ölüm ve yeniden doğum döngüsüne girme ilhamı verenin, göz alıcı telekleriyle Targon güneş atmacaları olduğuna inanır.","Birim",["KUŞ"],["Targon"],"YAYGIN"],"04MT003":["Toprak Elementali","Bu oyunda 4+ Yer kartı çağırdığında bana +3|+0 kazandırırsın.","","''Eveet işte bu da Saaaarp ve de o çok büyük biyişi ve de çok şeyler görükmüş geçirikmiş tabii, yaaa. Ayrıcana bence çok yakışıklı biyişi ve de aslında çok iyi biyişi ama üzeyinde çok yük vay ve de o yükley bazen insanlayın üstüne düşüyo o yüzden dee ÇOK DİKKATLİ OLUN tımam mı? Evet devam ediyoyuz!''\n- Taşkın'la Maceralar - 4","Birim",[],["Targon"],"YAYGIN"],"04MT002":["Taşkıran","Oyna: Bu oyunda 4+ Yer kartı çağırdıysan bir düşmana 4 hasar, rakibin Nexus'una 2 hasar verirsin.","","Targon'un muazzam devleri ara sıra uykularından uyanıp yüce dağın daha yükseklerinde yeni yerler ararlar. Bu geziler hem pek gürültülü hem de son derece tehlikeli geçer.","Birim",[],["Targon"],"DESTANSI"],"04MT006":["Yıldızlı Aydınlanma","Yakarırsın.\nSemavi dost birimin varsa, destenin yerini 20 tane Sonsuzluğa Bakış alır.","","''Bak Kulun! Yıldızların anlatacak ne çok öyküsü var! Bu akşam hangisini okuyalım, hıı?''\n- Aydüşleyen","Büyü",[],["Targon"],"DESTANSI"],"04MT012":["Kaderin Çağrısı","Elindeki bir dost birime +8|+8 kazandırırsın.","","''Kaderine kucak aç ve kimsenin tahmin etmediği kadar parlak ışıklar saç.''\n- Taric","Büyü",[],["Targon"],"DESTANSI"],"04MT007":["Yeri Sars ","Bir birimi Sersemletirsin. Bu oyunda bir Yer kartı çağırdıysan ona 3 hasar verirsin.","","''İhihi iveet yer saysıldı tabiy ki de ama tabiy ki de babam hiçbi yere falan VURMADI TAMAM MI evet yine devam ediyoyuz!''\n- Taşkın","Büyü",["ELEMENTAL"],["Targon"],"ENDER"],"04MT015":["Sema Hizada","Şafak: Elinde rasgele bir Akşam kartı oluşur.\nAkşam: Elinde rasgele bir Şafak kartı oluşur.","","Günle gece birbirini izler, döngüleri böyle sürer gider.","Büyü",[],["Targon"],"YAYGIN"],"04DE004":["Gayretli İz Sürücü","Seçkin bir birim çağırdığında bedelim 1 azalır.","","Noxus'lular tuzaklarını iyi kurmuşlardı ama kimse ormanı Demacia izcilerinden daha iyi bilemezdi. Kırılan her dal, bırakılan her ayak izi onları prenslerine götüren bir ipucuydu.","Birim",["SEÇKİN"],["Demacia"],"ENDER"],"04DE014":["Ejdere Yem","Bir Ejder oynadığında, Ejder bana vurur ve sen 1 kart çekersin.","","''Taa yukarılardan gelen o carlama var ya? İşte o kuş sesi değil evladım. Avlanan bir ejderin çığlığı.''\n- Demacia'lı Çiftçi","Birim",[],["Demacia"],"YAYGIN"],"04DE001":["Onurlu Lord","Bir düşmanı ilk çektiğimde, bana bu tur için Bariyer verirsin.","","Oğlunun kaybolduğunu öğrenen Kral Jarvan III, çok güvendiği dostu Lord Barrett Buvelle'i bir arama ekibi kurmakla görevlendirdi. Prens sağ salim döndü fakat Lord Buvelle dönemedi. Kral bu olaydan ebediyen pişmanlık duydu.","Birim",["SEÇKİN"],["Demacia"],"YAYGIN"],"04DE012":["Savaşta Terfi","Bu tur oynadığın bir sonraki birime Öncü kazandırırsın. Bu birim artık Seçkin olur.","","Demacia'lılar kendilerini en çok zor zamanlarda gösterir.","Büyü",[],["Demacia"],"YAYGIN"],"04DE003":["Afet","Bir dost birim bir rakibi çekerek bir fazladan saldırı başlatır.","","''Kral için!''\n- Jarvan IV","Büyü",[],["Demacia"],"ENDER"],"04DE002":["Altın Kalkan","Bir dost birime bu tur Bariyer verirsin.\nSilahlanırsın.","","''Yılmak yok Demacia askeri!''\n- Jarvan IV","Büyü",[],["Demacia"],"ENDER"],"04DE006":["Savaş Meydanı Hüneri","Bir dost birime +1|+1 kazandırırsın.","","''Sana bazı öğütlerim var.''\n- Lord Buvelle","Büyü",[],["Demacia"],"YAYGIN"],"04DE008":["Jarvan IV","Saldırdığında, bedelimi ödeyerek beni çağırırsın ve En Güçlü düşmanı çekerim.","Dost birimler, karşılayan düşmanların 3+ vuruşundan sağ çıktığında.","Noxus'lular Prens Jarvan'ın nerede avlanacağını, yanında kaç Demacia'lı olacağını ve onurunun kaçmasına müsaade etmeyeceğini biliyorlardı. Tuzak kurulmuştu.","Birim",["SEÇKİN"],["Demacia"],"Şampiyon"],"04DE005":["Bulutların Efendisi Cithria","Çağrıldığımda benim dışımdaki tüm dost birimlerin Güç ve Can değerlerini ikiye katlayıp onlara Rakipçeker verirsin.","","''Demacia, prensini kurtarmaya Bulutların Efendisi'nden başka kimi yollayacaktı?''\n- Kral Jarvan III","Birim",["SEÇKİN"],["Demacia"],"DESTANSI"],"04DE020":["Mahvolmuş Ejdermuhafızı","Hiddet tesirine sahip bir dost birim bir birimi öldürdüğünde, ek +1|+1 kazanır.","","Sis Gregem'in zihnini çarpıtıp onu Çitduvar'da olanları tekrar tekrar yaşamaya zorladı. Nicedir gömülü kalmış bir kin ve hiddetle dolarak eski silah arkadaşlarına düşman kesildi.","Birim",[],["Demacia"],"YAYGIN"],"04DE010":["Kral Jarvan III","Çağrıldığımda Jarvan IV çekersin.\nO zaten oyundaysa, dost birimlere bu tur Rakipçeker ve Öncü verirsin.","","''Rica ederim düşün, bir baba oğlunu kurtarmak için ne feda etmez ki? Ya o baba bir de kralsa?''\n- LeBlanc","Birim",["SEÇKİN"],["Demacia"],"DESTANSI"],"04DE016":["Mahvolmuş Kadregrin","Oyna: Bir dost birime Rakipçeker ve +1|+1 kazandırırsın.","","Kadregrin, Kara Sis'in Demacia'ya ulaşmasından çok önce korku ve kaos saçıyordu. Ama Viego'nun komutasında, bu yetenekleri Mahvolmuş Kral'ın ordusunu daha da güçlendirecekti.","Birim",["EJDER"],["Demacia"],"ENDER"],"04DE013":["Heybetli Taşboynuz","Düşman büyülerinden ya da yeteneklerinden hasar almam.","","Rivayete göre, Taşboynuz denen bu koca varlıklar petrisit ormanının henüz genç olduğu devirlerde ortaya çıkmış. Boynuzları, artık taşlaşmış olan bu kadim ağaçlara benzer bir maddeden oluşuyor.","Birim",[],["Demacia"],"YAYGIN"],"04DE015":["Çevikkanat Birliği","Oyna: Elinde bir Gümüşkanat Öncüsü, Kör Eden Saldırı ya da Çeviktüy İz Sürücü oluşur.\nSaldır: Rakip çeken diğer dost birimlere bu tur +1|+1 verirsin.","","Çevikkanat birliğini sadece görmek bile çok aşağılarındaki meydanda savaşan Demacia'lı askerlere ilham vermeye yeter. Onların bulutlardan süzülerek inişini görenler yeniden güç bulup savaşa devam etmeye hazır olur.","Birim",["SEÇKİN","KUŞ"],["Demacia"],"DESTANSI"],"04DE007":["Pişman Er","Çağrıldığımda Seçkin bir karta Tanıklık ettiysen elinde bir Yırtılmış Sancak oluşur.","","Şehrin surlarına vardığında dizlerinin bağı sonunda çözüldü. Yılmaz Öncüler mesajını krala iletecekti, kral da prensi kurtaracaktı. Hatasını böylece tamir etmiş olacak, onuru lekelenmeyecekti.","Birim",[],["Demacia"],"YAYGIN"],"04DE009":["Yürekli Süvari","Bir düşmanı ilk çektiğimde Yılmaz Öncü Süvarisi birimine dönüşürüm.","","Çağrı yapılır yapılmaz, prensin aranmasına yardım etmek için tüm Demacia askerleri toplandı. O anda en önemlisi, amaca odaklı hareket etmekti.","Birim",["SEÇKİN"],["Demacia"],"ENDER"],"05BC058":["Kennen","Çağrıldığımda, elinde bir Fırtına İşareti oluşur.","Aynı dost birimi 5+ kez çağırdığında.","Bu görünmeyen şeyin kükremesini Kennen de duymuştu. İnsan olsun, canavar olsun önemi yoktu. Kinkoular ne pahasına olursa olsun diyarlarını korur.","Birim",["YORDLE"],["Bandle Şehri","Ionia"],"Şampiyon"],"05BC010":["Köpekbalığı Eğitmeni","Dost birimler saldırdığında, saldıran bir Kısadiş çağırırsın.","","Eğitmenin her akşamı aynı geçiyor. Akşam yemeğinde balık yiyip bira içiyor, baloncuk piposundan bir-iki nefes çektikten sonra köpekbalıklarını yatırıyor, burunlarından öpüp onlara bir masal anlatıyor.","Birim",["YORDLE"],["Bandle Şehri","Bilgewater"],"ENDER"],"05BC102":["Eski Kurt Büyücü","Tur Başı: 1 büyü manası doldurursun.","","Kâğıt kesiğinden daha büyük acı yoksa, bu acıyı kütüphanecilerden daha iyi anlayan da yoktur.","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC230":["Ruh Kapısı","Oynamak için 1 kart atarsın. Dost birimlere +1|+1 kazandırırsın.","","''Bunlar nasıl çalışıyordu?''\n- Poppy","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC099":["Kaslı İzci","Çağrıldığımda, sahip olduğun diğer her dost Yordle için +1|+1 kazanırım.","","''Sırrım ne mi? Pazularıma sor. Ben susarım, kaslarım konuşur.''","Birim",["YORDLE"],["Bandle Şehri"],"ENDER"],"05BC133":["Tristana","Bu oyunda çağırdığın her çok bölgeli dost birim için +1|+0 alırım.\nÇok bölgeli bir dost birim çağırdığında ona +1|+0 kazandırırsın.","5+ çok bölgeli dost birim çağırdığında.","''A planını açıklıyorum: Kapıyı patlatarak içeriye girip ateş açacağız. O işe yaramazsa B planı: Duvarı patlatarak çıkıp ateşe devam edeceğiz. Ardından C planına geçeceğiz, yani toplanıp tekrar A planını uygulayacağız.''","Birim",["YORDLE"],["Bandle Şehri"],"Şampiyon"],"05BC023":["Miniti","Tur Sonu: Bu tur rakibin Nexus'una hasar verdiysen Megati kartına dönüşürüm.","","Minitilerin sevdiği şeyler: Nakotak kabile topraklarının yakınlarındaki sıcak kumlara uzanıp uyuklamak. Minitilerin sevmediği şeyler: Küstah yordle'lar tarafından bu sıcak kumlardan kışkışlanmak...","Birim",[],["Bandle Şehri"],"DESTANSI"],"05BC029":["Yuumi","Tur Başı: Yapıştığım birim +1|+1 kazanır. Yapışık değilsem ben +1|+1 kazanırım.","Kendim ya da Yapıştığım birim 3 kez saldırdığında.","Yuumi, onca sızlanmaya rağmen Kitap'ı epey sevdiğini itiraf etmeliydi. Kokusunu seviyordu. Resimlerini seviyordu. Kapılarından geçmek bile çok hoşuna gidiyordu! Ama hiçbir şey Norra'nın sağ salim eve dönmesinin yerini tutamazdı.","Birim",["PERİ","KEDİ"],["Bandle Şehri","Targon"],"Şampiyon"],"05BC078":["Elektro Zıpkın","Oynamak için 1 kart atarsın. Herhangi bir birime 2 hasar ve rakibin Nexus'una 2 hasar verirsin.","","''Gösteri görsünler!''\n- Rumble","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC106":["Hödüksüböcek","","","''Boyutları hayli küçük olsa da hödüksüböcekler büyük bir iştaha ve ancak 'ciddi davranış problemi' şeklinde tasvir edebileceğim bir tutuma sahiptir.''\n- Kabukolog Ekoloji Günlüğü, 17. Gün","Birim",[],["Bandle Şehri","Bilgewater"],"YAYGIN"],"05BC161":["Gnar","Vuruş: Elinde bir Dürtme Çomağı oluşur. Zaten varsa, bedeli 2 azalır.","Tur Sonu: Bu tur rakibin Nexus'una hasar verdiğinde.","Yıllar önce, Gnar ve soydaşları Nakotak Vadisi'nde yaşıyordu. Burası modern dünyanın tehlikelerinden uzak, masum bir yerdi. Ne yazık ki zamanın acımasızlığı burayı Gnar'ın elinden aldı. Ama neyse ki Bandle Şehri'nde zaman beklenenden farklı işliyor.","Birim",["YORDLE"],["Bandle Şehri","Freljord"],"Şampiyon"],"05BC073":["Buluşçu Kimyager","Çağrıldığımda, bir Hurda Bombası çağırırsın.","","Giselle, Profesör Heimerdinger'in en parlak öğrencilerinden biriydi... Ziggs'in Zaun'daki değişik deneylerini duyana dek. Sonrası hep ''Sihirmayınlar!'' aşağı, ''Staj için adımı versen''ler yukarı... ","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC039":["Aksi Bombacı","Sadakat: Bedeli 3 ya da daha az olan rasgele bir Yordle takipçi çağırırsın.","","''Alice'in içinde iki atışlık cephane var. Biri karşılama, diğeri veda için. Tanışmak ister misiniz?''","Birim",["YORDLE"],["Bandle Şehri"],"ENDER"],"05BC148":["Tepesi Atmış Patlıcanavar","Çağrıldığımda, bu oyunda rakibin Nexus'una 4+ kez hasar verdiysen bana 4 Ağır Darbe kazandırırsın.","","Dışı yumuşak, içiyse sert ve kararlı.","Birim",["PERİ"],["Bandle Şehri","Piltover ve Zaun"],"YAYGIN"],"05BC119":["Minyon","Son Nefes: Sonraki Tur Başında elinde bir kopyam oluşur.","","''Gerçek bir süperkötüye minyon dayanmaz! Yerini bilen, bir dediğinizi iki etmeyen ve mütemadiyen geri gelip daha fazla emir isteyen kısa tiplerden bol bol lazım.''\n- Lord Veigar'ın ''Nasıl Süperkötü Olunur'' kitabının 2. bölümünden alıntı","Birim",[],["Bandle Şehri","Gölge Adalar"],"YAYGIN"],"05BC019":["Gökkuşağı Balığı","","","Gökkuşağı Balığı, hayatında hiç sıçramadığı kadar yukarı sıçramak zorunda kaldığı halde havadan keşif yapmaktan memnundu. Yuumi'nin sulanmış ağzına yem olmaktan kurtulmak için ne gerekiyorsa yapardı.","Birim",["PERİ"],["Bandle Şehri"],"YAYGIN"],"05BC093":["Veigar","Çağrıldığımda, elinde yoksa bir Karanlık oluşur. Tur Başı: Her yerdeki Karanlık kartları 1 hasar kazanır.","Karanlık'la 12+ hasar verdiğinde.","''Bu dünya benden korkacak. Açtığım yaraları sonsuza dek taşıyacak. Gücümün ağırlığı altında ezilecek. Akıl almaz devasalığımın gölgesinde titreyecek!''\n- Lord Veigar'ın ''Nasıl Süperkötü Olunur'' kitabının 1. bölümünden alıntı","Birim",["YORDLE"],["Bandle Şehri","Gölge Adalar"],"Şampiyon"],"05BC007":["Taş Diziciler","","","Yordle'lar yerçekimi olayını henüz tam anlayabilmiş değiller ama öte yandan yerçekiminin de Bandle Şehri'ni tam anlayabildiği söylenemez.","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC174":["Arkadaşlık!","Bir dost birime bu tur Bariyer ya da Büyü Kalkanı verirsin.","","''Seni korumanın yolu en vahşi şekilde ve öfkeyle... miyav!''\n- Yuumi","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC185":["Kabuk Oyunu","Büyü manan dolar. Bir dost birime bu tur Sıyrılgan ve +1|+1 verirsin.","","''Soldaki kabuğa girdiklerini GÖRÜYORUM ama o kabuğu seçtiğimde içi boş çıkıyor. Bu oyunun hileli olduğundan şüphelenmeye başlıyorum.''\n- Kabukolog Ekoloji Günlüğü, 14. Gün","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC096":["Dehşet Tenoru","Çağrıldığımda, bu oyunda oluşturulmuş bir kart oynamış ya da büyüyle bir birim öldürmüşsen bir Kulak Patlatan Baslar çağırırsın.","","Veigar'ın adalet saraylarını yıkmak için yardıma ihtiyaç varsa, bu ikisi çok işine yarayacaktı. Camları patlatacak tizlikte notalara çıkabiliyorlardı. Miksolidyan gamınkiler hariç tabii.","Birim",["YORDLE"],["Bandle Şehri","Gölge Adalar"],"ENDER"],"05BC088":["Rumble","Oyna: 3 taneye kadar kart atarak her yerdeki dost Rumble kartlarına atılan ilk kart için Ağır Darbe, ikinci kart için İlk Saldırı ve üçüncü kart için Büyü Kalkanı kazandırırsın.","Dost Meka Yordle'ların 12+ hasar verdiğini gördüğümde.","''Veee bu da tamamlanmış oldu.''\n''HATA.''\n''NE? Daha yeni düzelttim seni!''\n''SİSTEM ÇÖKMEK ÜZERE.''\n''Kapat şunu. KAPAT ŞUNU!''\n- Rumble ve Tristy","Birim",["MEKA","YORDLE"],["Bandle Şehri","Noxus"],"Şampiyon"],"05BC056":["Rüzgâr Keşişi","Çağrıldığımda, elinde bir Bulut Duruşu oluşur.","","''Öğretilerimizdeki teknik nefes kontrolünden gelir. Tıpkı rüzgârdan doğan fırtına gibi.''","Birim",["YORDLE"],["Bandle Şehri"],"ENDER"],"05BC190":["Arena Meka Yorumcusu","Saldır: Saldıran diğer dost birimlere bu tur +2|+0 verirsin.","","''Her gece avazım çıktığı kadar bağırıp nasıl mı maç sunuyorum? Motoryağıyla gargara yapıyorum. Sabah ve gece beşer dakika.''","Birim",["YORDLE"],["Bandle Şehri","Noxus"],"DESTANSI"],"05BC042":["Morçilek Tozu","Bir dost birimi bu tur 3|3 niteliklerine çıkarırsın.","","''Eskiden ben de senin gibiydim, bir pofkep mantarını bile kaldıramazdım. Ama sonra Morçilek Tozu Sağlık İçeceği'ni keşfettim. İçinde, en sıska yordle'ları çelik gibi kaslara kavuşturmak gereken her şey var. Sıkı bir antrenmandan sonra vücudunu Morçilek Tozu'yla besle, sen de benim gibi kaslı ol!''\n- Basılı el ilanı","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC205":["Kara Delik","Bir düşmanı Sersemletirsin ve Güç değeri 2 ya da daha az olan tüm düşmanları Sersemletirsin.","","''Tam... Tam orada dur. Kımıldama.''\n- Veigar","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC223":["Tuzağa Çek","Düşmanın destesinden seçilen 3 birimden ya da büyüden birini çekersin ve tüm kopyalarına 3 Zehirli Pofkep Mantarı koyarsın.","","''986. kural: Tuzaklar oyuncak değildir... ama yine de çok eğlenceliler!''","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC091":["Bilet Satıcısı","Oyna: 1 kart atarsın, bir Meka Yordle Cisimlendirirsin ve bedelini 1 azaltırsın.","","''BİLETLER BURADA! BİLETİNİ ALMAYAN KALMASIN! SANA YARI FİYATINA OLUR! Hay sincaplar... Bu biletleri satamazsam patron fişimi çeker... kalıcı olarak.''","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC163":["Ziggs","Saldır: Beni karşılayana ve rakibin Nexus'una 1 hasar veririm.","4+ dost Yer kartını yok ettiğinde.","''İyi bir izlenim bırakmamız ÇOK önemli! Yeni güvenlik müfettişi uğrayacak, ne yapmamız gerektiğini biliyorsun!''\n''Patlama yapmayacak mıyız?''\n''NE? Hayır! Müfettişin görmeyeceği yerlerde yapacağız! Patlama yapmayacakmışız... Deli midir nedir?''\n- Ziggs ve Otto","Birim",["YORDLE"],["Bandle Şehri","Shurima"],"Şampiyon"],"05BC151":["Ayna Sihirbazı","Oluşturulmuş bir takipçi oynadığında, aynısının birebir kopyasını çağırırsın. Oluşturulmuş bir büyü oynadığında, onu aynı hedeflere kopyalarsın.","","''Ah, evet, aynaların ustasıdır. Tasarımlarım onun elinde daha da büyüleyici görünüyor. Malum birini, ufacık bir ışık oyunuyla, biraz daha... dikey mesafeye sahipmiş gibi gösterebiliyor...''\n- Yüksek Ökçeli Terzi","Birim",["YORDLE"],["Bandle Şehri"],"DESTANSI"],"05BC027":["Sihirmayın Tarlası","Çağrıldığımda ya da beni yok ettiğinde, En Güçlü düşmanı Sersemletirsin.","","''Güvenli görünmüyor derken?''\n- Ziggs","Yer",[],["Bandle Şehri"],"YAYGIN"],"05BC200":["Yordle Geçidi","Oynamak için 1 kart atarsın. Bedeli 3 ya da daha az olan bir Yordle Cisimlendirirsin ve çağırırsın.","","''Biz topçularımızı arkada bırakmayız!''\n- Tristana","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC021":["Seksek Bomba","Bir birime 2 hasar ya da iki düşmana 1 hasar verirsin.","","''Bomba geliyor!''\n- Ziggs","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC167":["Bandle Komandosu","Nexus Vuruşu: Elinde bir Aç Puhukedi oluşur.","","''Sokakta asker, evde anniş!''","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC179":["Yordle Kolcu","Saldır: Güç değeri benimkiyle eşit ya da benimkinden daha az olan dost birimlere +0|+1 kazandırırsın.","","''Poppy! Yeni taktiğimizi çok iyi eyleme döktün. Sence adını 'Fıstıklı Yaprak Fırtınası' koyalım mı?''\n''Eee, ben, şey, kötü adama sadece çekicimle vurdum. Adını sadece 'Çekiç' koysak olmuyor mu?''\n''Son üç tanesinin de adını Çekiç koyduk ama!''\n- Kip ve Poppy","Birim",["YORDLE"],["Bandle Şehri","Demacia"],"DESTANSI"],"05BC214":["Cehennem Bombası","Tüm düşmanlara 1 hasar verirsin, sonra tekrar verirsin.","","''Bombayı getirin... en büyüğünü!''\n- Ziggs","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC221":["Mantar Kafa","Çağrıldığımda ya da Tur Başı: Bana bu tur oyundaki ya da Yapışık haldeki dost Perilerin sayısına denk Güç değeri verirsin.","","Bu minnoşlar aşırı sevimli, ayrıca kafalarının üstünde mantar yetiştiriyorlar.","Birim",["PERİ"],["Bandle Şehri","Ionia"],"ENDER"],"05BC041":["Poppy","Saldır: Güç değeri benimkiyle eşit ya da benimkinden daha az olan dost birimlere +1|+1 kazandırırsın.","Dost birimlerle birlikte 3 kere saldırdığımda.","Alçakgönüllülük kahramanlık belirtisidir ama pek çok tarihçi Poppy'nin artık biraz abarttığı konusunda hemfikir.","Birim",["YORDLE"],["Bandle Şehri","Demacia"],"Şampiyon"],"05BC176":["Sinsi Atış","Bir düşman birime 1 hasar verirsin. Bir dost birime +1|+0 kazandırırsın.","","''Çıldııııırr!''\n- Yuumi","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC105":["Bandle Topçuları","Bu oyunda çağırdığın her çok bölgeli dost birim için bedelim 1 azalır.\nÇağrıldığımda bana 3 Ağır Darbe kazandırırsın.","","Ekip gibi ekip be.","Birim",["YORDLE"],["Bandle Şehri"],"ENDER"],"05BC066":["Uyanık Tüy","","","''N... o... r... r... a... n... e... r... e... d... e...? Of, ne desem acaba?''\n- Kâhya fare","Birim",["PERİ"],["Bandle Şehri"],"YAYGIN"],"05BC177":["Origami Ejderha","","","''Bir kez daha katladık mı tamamdır. İşte sana zürafa! Adı Çorap olsun.'' \n''Neden 'Çorap'?'' \n''Norra çorapları çok sever, o yüzden ona da bayılacak!''\n- Kâhya fareler","Birim",["PERİ"],["Bandle Şehri"],"DESTANSI"],"05BC136":["Hurda Yığını","Oynamak için 1 kart atarsın.\nBir Meka Yordle Cisimlendirirsin.","","''İşe yaramaz. Dandik. Çöp... Bak işte tam da BUNU arıyordum!''\n- Rumble","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC164":["Zehirli Ok","Herhangi bir şeye 1 hasar verirsin ve rakibin destesine 3 tane Zehirli Pofkep Mantarı koyarsın.","","''Hehe! Tam isabet!''\n- Teemo","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC194":["Bandle Ağacı","Tur Başı: Elinde yeni bir bölgeye ait bir takipçi oluşur. Ardından, 10 bölgeden dost birim gördüysem oyunu kazanırsın.","","Semanın gözle seçilemez, ölçülemez yüksekliklerine uzanan Bandle Ağacı, şehrin tam ortasına yerleşmiş ve doğa kurallarına göre imkânsız olması gereken bir anıt. Heybetli, büklümlü dallarının altında yaşayan yordle'lardan bazıları onu umut ve arkadaşlık timsali, bazılarıysa uğursuz, bilmece dolu bir sır sütunu olarak görüyor. Bandle Ağacı'na bakmanın, çok eski ve güçlü bir şeyin ruhuna bakmak olduğundaysa herkes hemfikir.","Yer",[],["Bandle Şehri"],"DESTANSI"],"05BC127":["Sessiz Fırtına Rissu","Çağrıldığımda bir Fırtınabulutu çağırırsın.","","Bir Fırtınabulutu'nu hayata geçirmek zaman isteyen bir işti ve Rissu'nun böyle bir vakti yoktu. Sapma mesafeyi kapatırken elleri dur durak bilmeden çalışıyordu. Biraz bulut, bir parça yıldırım... İşte. ÇAT! BAM! Başarmıştı ama yeterli olacak mıydı?","Birim",["YORDLE"],["Bandle Şehri"],"DESTANSI"],"05BC216":["Yordle İcadı","Bir Yer kartını yok edersin ya da elinde çok bölgeli iki rasgele takipçi oluşur.","","''Dayanın, geliyoruz!''\n- Bombacı İkizler","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC212":["Güvenlik Müfettişi","Tur Başı: Elinde bir Teftiş Geçildi! oluşur.","","Wilfred en başta şüpheci yaklaştı. Teftiş boyunca da öyle. Hatta doğrusu istenirse, teftişin son anına kadar da şüpheciydi. Fakat Ziggs'le diğer sihirmayın uzmanları, patlayıcılarla süper bir havai fişek gösterisi düzenlemeyi bildiklerini çok iyi kanıtladılar. ","Birim",["YORDLE"],["Bandle Şehri"],"ENDER"],"05BC141":["Destancı","2 dost birime bu tur +2|+1 verirsin.","","''İşte kahramanlar tam burada sırt sırta vermişlerdi...''\n''Popo popoya mı yani? Hehehehehe!''\n''Sulu şakalarını başka zamana sakla Peppy, önemli bir şey anlatıyorum!''\n- Yordle'ların kamp ateşi etrafında anlattığı hikâyelerden","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC209":["Stres Savunması","Bir birimin niteliklerini bu tur için 1|6 yaparsın.","","Gıdakağan normal şartlarda sadık ve dayanıklı bir binek. Fakat çokça strese maruz kalırsa... beklenmedik tepkiler verebiliyor.","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC210":["Alev Makinesi","Bir dost birime +2|+0 ve Ağır Darbe kazandırırsın.","","''Çığırmıyorlarsa yeteri kadar ısınmamış demektir! Hehe.''\n- Rumble","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC013":["Düzenbaz Dokunaçlar","Rakibin, en düşük bedelli kartını atar.","","''Kendime not: Sonraki keşif gezimde tüm değerli eşyalarımı ÖN cebime koyacağım.''\n- Kabukolog Ekoloji Günlüğü, 19. Gün","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC100":["Pofkep Köpüş","Vuruş: Rakibin destesine 3 tane Zehirli Pofkep Mantarı koyarsın.","","''Ne oldu oğlum? Acemilerden ikisi ormanda keşif yaparken korkunç bir çimen canavarına rastladı ve şimdi uzun süre can çekişerek ölme riskleri mi var? Yolu göster çabuk!''\n- Teemo","Birim",["KÖPEK"],["Bandle Şehri"],"YAYGIN"],"05BC098":["Hainlik Katalizörü","Vuruş: Her yerdeki Karanlık kartlarına fazladan 1 hasar kazandırırsın.","","Karanlık karşımıza her boyda, her şekilde çıkabiliyor. Bunlardan bazıları şaşılacak kadar sevimli!","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC122":["Acemi Yordle","Başka bir Yordle çağırdığında, bu tur bana +2|+0 verirsin.","","''Devus çimenus. Bu korkunç yaratıklar çimen gibi yerde yatarak kamufle olur ve üzerlerinde yürüyecek kadar şanssız herkese saldırırlar. Karşılaşırsanız hiç durmadan kaçın!''\n- Ava Naptınama","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC120":["Yordle Yüzbaşı","Güç değeri benimkiyle eşit ya da benimkinden daha az olan bir dost birim çağırdığında, ona +1|+1 kazandırırsın.","","''Macera demek kötüleri bulup onları dostun yapmak demektir!''","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC046":["Şimşek Yumruk","Çağrıldığımda, bu oyunda bir Şimşek Yumruk çağırdıysan beni Ezen Şimşek Masa kartına dönüştürürsün.","","Masa idman kuklasına saldırırken yumruğundan bir yıldırım koptu ve ahşap kuklayı ikiye bölüp ellerindeki tüyleri yaktı. İpe asılıp bronz eli kendisine çekti ve eğitimini düşündü, nihayet hazırdı. Sonra aniden uzaklarda bir yaratığın kükremesi yankılandı.","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC018":["Çalımlı Şövalye","","","''Dokuz yüz doksan sekiz, dokuz yüz doksan dokuuz... bin! İşte bitti Bawky, her zamanki gibi mükemmelsin. Şimdi sen benimkini tara!''","Birim",["YORDLE"],["Bandle Şehri","Demacia"],"ENDER"],"05BC132":["Gülle Atışı","Tristana kartın varsa ya da bu oyunda 4+ bölgeden kart oynadıysan bedelim 2 azalır.\nBir birime 3 hasar verirsin.","","Her ''dıkşınya''nın içinde doğmayı bekleyen bir ''badagümm'' vardır.","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC168":["Benekli Kurbağa","Tur Sonu: Bu tur rakibin Nexus'una hasar verdiysen Dev Gromp kartına dönüşürüm.","","Nakotak Vadisi'nde yaşayan yordle'lar, uzun yıllar boyunca Gromp komşularını anlamaya çalıştı. İlk başta Şef Hegabo onları çomakla dürtmeyi denedi. Daha sonra Şef Babobu onları çomakla dürtmeyi denedi. Şef Nakotak'ın ise yepyeni bir planı vardı, onları çomakla dürtecekti.","Birim",[],["Bandle Şehri"],"ENDER"],"05BC014":["Yavru Dehşet","Tur Sonu: Bu tur rakibin Nexus'una hasar verdiysen Dehşetkanat kartına dönüşürüm.","","Nakotak Vadisi'ndeki canlılar tıpkı vadinin toprakları gibi çeşitli ve canlı... ancak patlama olasılıkları da bir o kadar yüksek.","Birim",["KUŞ"],["Bandle Şehri"],"YAYGIN"],"05BC138":["Düzeltiverinciler","İlk kez bir kart attığında ya da rakibin Nexus'una hasar verdiğinde bana +2|+1 kazandırırsın.","","''Evet, güzel dövüş oldu. Herkesin eline koluna sağlık. Şimdi şu çöpleri kaldırın ve ne yapacağınızı unutmayın: Kurtarılabilir ne varsa alın, düzeltiverin, dükkâna koyun ve onlara geri satın! AHAHAHA!''\n- Arena Sahibi Karl","Birim",[],["Bandle Şehri"],"YAYGIN"],"05BC198":["Grup Fotoğrafı","Bir birime 1 hasar verirsin. 4+ dost birimin varsa, bunun yerine 2 hasar verirsin.","","''Bunu aylık bültene koyacağız. Bu sefer gülümseyin ha! Biir... ikiii... üç!''\n- Tristana","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC181":["Bulut Duruşu","Bir dost birime bu tur +2|+0 ve ''Tur Sonu: Beni geri gönderirsin'' verirsin.","","''Tekrar nefes al ve gücünü bul!''\n- Rüzgâr Keşişi","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC160":["Mağara Porosu","","","Eski devirlerin porolarının kafatasları günümüzün porolarına göre çok daha kalındı. Bu onları biraz daha aptal ve tos atmaya çok çok daha hevesli yapıyordu.","Birim",["PORO"],["Bandle Şehri","Freljord"],"YAYGIN"],"05BC005":["Yosunkızları","Nexus Vuruşu: Elinde bir Sulu Şaka oluşur.","","''Hayırlar olsun, çok tuhaf bir rüya gördüm. Yosunlar arasında debelenerek deniz kabuğundan şapkamı arıyordum ki aniden kulağıma dünyanın en şahane şarkısı çalındı. Sonra bir baktım, elimde kalemle burada oturmuş bunları yazıyorum. Yatıp uyuduğumu hatırlamıyorum...''\n- Kabukolog Ekoloji Günlüğü, 22. Gün","Birim",[],["Bandle Şehri"],"ENDER"],"05BC020":["Kütüphane Asistanı","Nexus Vuruşu: Bedeli 3 ya da daha az olan bir büyü çekersin.","","''Jöli benim EN İYİ ARKADAŞIM! Yani senden sonra, Kitap. Bir de Norra'dan sonra. Tamam tamam, Jöli ÜÇÜNCÜ EN İYİ ARKADAŞIM. Hiç fena bir sıralama değil bence.''\n- Yuumi","Birim",["PERİ"],["Bandle Şehri"],"YAYGIN"],"05BC049":["Kabukolog","Oyna: Bölgelerinden bedeli 3 ya da daha az olan bir büyü Cisimlenir.","","''Bugün tarihe geçecek bir gün! Derinlerdeki keşiflerime başlıyorum. Her şey yolunda gidecek, yeter ki... dalga geçmeyeyim! Hah hah hah!''\n- Kabukolog Ekoloji Günlüğü, 1. Gün","Birim",["YORDLE"],["Bandle Şehri"],"ENDER"],"05BC001":["Minimorf","Bir birimi 3|3 bir Mini Miniti kartına dönüştürürsün ve onu Susturursun.","","''Oh hoh ho! Ne şeker! Ne şirin! Ne kadar KÜÇÜK!''\n- Veigar","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC026":["Gizli Patikalar","Bu oyunda 2+ kart oluşturduysan bedelim 2 azalır. 2 kart çekersin.","","Bandle Şehri'ne giden yolu pek az yabancı bilir ama Runeterra kayalarında ve ağaçlarındaki garip işaretler, neyi aradığını bilenlere ipucu olur.","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC152":["Suratsız Gezginler","Çağrıldığımda, TÜM oyuncular 1'er kart çeker. Ardından rakibin, en yüksek bedelli kartını atar.","","''Bu ne biçim gezi ya, rezillik.''\n- Elle","Birim",["YORDLE"],["Bandle Şehri","Piltover ve Zaun"],"YAYGIN"],"05BC070":["Ava Naptınama","Çağrıldığımda ya da Tur Sonu: Rakibin destesine 3 tane Zehirli Pofkep Mantarı koyarsın.\nRakibin kartlarındaki tuzaklar etkinleştiğinde iki katına çıkar.","","''378. kural: İyi bir izci hep cesurdur, hep hazırlıklıdır ve hep gözüpektir!''","Birim",["YORDLE"],["Bandle Şehri"],"DESTANSI"],"05BC015":["Minnak Sürüngen","Tur Sonu: Bu tur rakibin Nexus'una hasar verdiysen Lav Sürüngeni kartına dönüşürüm.","","Nakotak (galiba), ''Şu biberi yesene!'' diye bağırdı. Jojo, ''Asıl SEN ye!'' diye cevap verdi (herhalde). Onlar tartışadururken mini mini bir sineği kovalayan minik bir sürüngen hızla yanlarına yanaştı. İki yordle önce birbirlerine, sonra bibere, sonra yine birbirlerine baktı. Tam o an kafalarında bir ampul yandı.","Birim",["SÜRÜNGEN"],["Bandle Şehri"],"YAYGIN"],"05BC145":["Yordle Yaver","Oyna: Elinde bir Minicik Mızrak ya da Minicik Kalkan oluşur.","","''Benim mızrağımı da eskiden büyük bir kahraman kullanmış... Poppy'ye verdim, tam bir dakika tuttu!''","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC140":["Poro Kızağı","Saldır: Bedeli 1 olan ve saldıran rasgele bir Poro çağırırsın.","","''Şonya da Bıyıkcan poro demiş ki ''ŞUYDAN GİDELİM'' şonya da hufka doğru uzaklaşmışlar, öbürsü porolar da yetişmek için aykalayından koştuymuş!''\n- Küçük Ingvar","Birim",["PORO"],["Bandle Şehri","Freljord"],"DESTANSI"],"05BC129":["Arena Sahibi","","","''Her dakika yeni bir enayi doğuyor. Hepsinin etinden sütünden faydalanmamak ziyan. Bu meka arenasında PARA BASACAĞIM.''","Birim",["YORDLE"],["Bandle Şehri","Noxus"],"YAYGIN"],"05BC004":["Ahtamur","Çağrıldığımda, elinde bir Sulu Şaka oluşur.","","''Meraklı ve oyuncu canlılar olan ahtamurlar son derece neşelidir. Bir dakika, samurpot muydu yoksa? Bir dakika, üç sandviç getirmemiş miydim ben?''\n- Kabukolog Ekoloji Günlüğü, 7. Gün","Birim",[],["Bandle Şehri"],"YAYGIN"],"05BC155":["Köz Keşişi","Başka bir dost birim çağırdığında +1|+0 kazanırım.","","''Ufak kıvılcımlar gürleyen bir yangına dönüşür. Bizler yıkımınızı getiren közleriz!''","Birim",["YORDLE"],["Bandle Şehri"],"ENDER"],"05BC104":["İlkel Güç","Bir dost birime +2|+2 ve Ağır Darbe kazandırırsın.","","Evet, çok tatlı. Evet, biraz asabi biri. Hayır, tanık olmak istemezsin.","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC218":["Destek Perisi","Elinde bir Aç Puhukedi oluşur. Elindeki dost Perilere +1|+1 kazandırırsın.","","''Bunları durmadan kim besliyor ya?''\n- Poppy","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC192":["Bombacı İkizler","Çağrıldığımda, elinde bedeli 2 ya da daha az olan rasgele bir Yer kartı oluşur.","","Panikayak Bombaratör-X tam da yapması gereken şeyi yapıyor, şahane kargaşa çıkarıyordu. Ayrıca paralel park etmesi çok kolaydı. ","Birim",["YORDLE"],["Bandle Şehri","Shurima"],"YAYGIN"],"05BC162":["Şef Nakotak","Bir dost birim dönüştüğünde tamamen iyileşir ve +1|+1 ile Ağır Darbe kazanır.","","Şef Nakotak, bölgelerinin yakınlarındaki kar yığınlarından birinde büyük bir dinozor kemiği bulunca kendini kabilenin lideri ilan etti. Kabiledeki hiç kimse dinozor kemiği bulmanın kişiyi lider yaptığından haberdar değildi ama bu durumu kimsenin pek de umursadığı söylenemezdi. Dolayısıyla, Nakotak şef oldu.","Birim",["YORDLE"],["Bandle Şehri"],"ENDER"],"05BC032":["Parlak Fener","Her tur, oynayacağın ilk Peri'nin bedeli 2 azalır.","","''Fener Norra'yı, ay güveleri Fener'i, fareler de ay güvelerini takip ediyor! Takibe takip!''","Birim",["PERİ"],["Bandle Şehri"],"ENDER"],"05BC166":["Dürtme Çomağı","Herhangi bir şeye 1 hasar verirsin. 1 kart çekersin.","","Deney yapmanın ilk kuralı: Dürt bakalım ne olacak.","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC006":["Cephanelik Arnie","Çağrıldığımda, bu oyunda yok ettiğin her dost Yer kartı için bana rasgele bir tesir kazandırırsın.\nDost bir Yer kartını yok ettiğinde, bana rasgele bir tesir kazandırırsın.","","Ziggs nereye gitse Arnie de peşinden gidiyordu. Sakin tavırları, Ziggs'in enerjik kaosuna doğal bir zıtlık teşkil ediyordu. Görevleri cephane stoklarını dolu tutmak, yangın söndürmek ve Ziggs kulak koruyucularını (kaçınılmaz olarak) unuttuğunda ellerini onun kulaklarının önünde çırpmaktı. ","Birim",["YORDLE"],["Bandle Şehri"],"DESTANSI"],"05BC110":["Bilge Tırmanışçı","","","''Evet, bana çayı, çorapları, seni, düğmeleri ve ıvır zıvır koleksiyonu yapmayı ne kadar çok sevdiğini söyledin ama hâlâ neye BENZEDİĞİYLE ilgili tek kelime etmedin!'' ","Birim",["YORDLE"],["Bandle Şehri","Targon"],"YAYGIN"],"05BC063":["Kasırga Savaşçı","Çağrıldığımda bana +1|+0 ve rasgele bir tesir kazandırırsın.\nGeri Gönderildiğimde bu nitelik ve tesirleri kaybetmem.","","Kasırga nefes egzersizleriyle sakinliğini koruyordu... bir de içindeki telaşı vahşi ve ölümcül bıçaklardan oluşan bir hortuma dönüştürerek. ","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC217":["Peri Filizi","Bir Peri Cisimlendirirsin ve ona +1|+1 kazandırırsın.","","Her canlı beslenmeye ihtiyaç duyar. Herkes gibi periler de beslenir ama bunu nasıl yaptıkları pek bilinmez.","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC180":["Hızlan","Güç değeri 3 ya da daha az olan bir birimi Geri Gönderirsin.","","''Biz hızlıyız! Biz rüzgârız!''\n- Kennen","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC040":["Ziynet Takası","Bir Ahtamur ya da bölgelerinden bedeli 3 ya da daha az olan 2 büyüden birini Cisimlendirirsin.","","''Sandviçimi derhal bırakmanı salık veririm!''\n- Kabukolog","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC213":["Göçert","Bir düşmana 1 hasar verirsin ve onu Sersemletirsin.","","''Ahanga!''\n- Gnar","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC208":["Kahraman Hücumu","Bir dost birim bir düşmana vurur. Ölmezse, düşmanı Sersemletir.","","''Yürü!''\n- Poppy","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC085":["Makineci Serseri","Oyna: 1 kart atarsın, bir Meka Yordle Cisimlendirirsin ve ona Büyü Kalkanı kazandırırsın.","","''Azıcık sessiz olacak mısın? Bunca parayı sayarken kendi sesimi zor duyuyorum!''\n- Arena Sahibi Karl","Birim",["YORDLE"],["Bandle Şehri"],"ENDER"],"05BC112":["Saçartohum Fidesi","Oyna: Bu tur bana Bariyer verir ya da Ağır Darbe kazandırırsın.","","Saçartohum Fideleri utangaç varlıklardır. İlk başta geri çekilseler de tehdit edildikleri an...","Birim",["PERİ"],["Bandle Şehri","Ionia"],"YAYGIN"],"05BC135":["Çift Atış","Bir dost birim, bir düşmana vurur. Dost birim çok bölgeliyse, düşmana tekrar vurur.","","''Meşepalamudu M1-85: tam otomatik, Bandle odunundan dürbünlü, mor çilek rengi, meşe kalibre bir tüfek. Anneniz bu akşam size ziyafet çekecek!''\n- Bandle Komandosu","Büyü",[],["Bandle Şehri"],"YAYGIN"],"05BC084":["Cıyakçı","Oyna: 1 kart atarsın, bir Meka Yordle Cisimlendirirsin.","","Kendisi küçük, karakteri ÇOK BÜYÜK.","Birim",[],["Bandle Şehri"],"YAYGIN"],"05BC184":["Zırvacı Ozanlar","Çağrıldığımda, elinde bir Aç Puhukedi oluşur.","","''Şarkımızın konusu\nPoppy, çok güçlü kolu!\nOndan güçlüsü yok, kolu çok... güçlü!''\n- ''Benzeri Gelmemiş Ozanlar Reginaldactyl ve Faltimisquee'in Şarkı Defteri'nden üstü karalanmış şarkı sözleri''","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC116":["Bandle Şehri Belediye Başkanı","Her tur, oynayacağın ilk çok bölgeli birimin bedeli 1 azalır.\nOyna: Çok bölgeli bir takipçi Cisimlenir.","","Bandle Şehri'nin, belediye başkanını gerçekten seçip seçmediği belli değil ama heybetli bir bıyığın bu görev için şart olduğu belli.","Birim",["YORDLE"],["Bandle Şehri"],"DESTANSI"],"05BC111":["Aksiyon Yordle'ları ","Dost birimlere bu tur +2|+2 verirsin. 4+ bölgeden kart oynadıysan, bunun yerine +3|+3 verirsin.","","''Şu an... aşırı havalı görünüyoruz.''\n- Tristana","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC224":["Çaprazlama","Bir dost birimi Geri Gönderirsin. Bu tur oynadığın, eşit ya da daha az bedele sahip bir sonraki dost birimin bedeli 0 olur.","","''Bedeni hızlı olanın aklı da hızlı olur!''\n- Kennen","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC130":["Kavruk","Saldır: Destenin en üstündeki şampiyona +1|+1 ve rasgele bir tesir kazandırırsın.","","Otto'nun yaz aylarında düzenlediği mangal partilerinin belli bir ünü var. Izgara yapmayı çok sevse de misafirleri hep ''çok pişmiş'' ya da ''aşırı çok pişmiş'' etler yemek durumunda kalıyor.","Birim",["YORDLE"],["Bandle Şehri","Shurima"],"YAYGIN"],"05BC191":["Muhafızın Hükmü","Düşman destesinin en üstüne bir düşman birimi koyarsın.","","''Sakın geri dönme!''\n- Poppy","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC052":["Çöpten Vurgun","Elin rasgele kartlarla dolar. Hepsinin bedeli 0'dır ve hepsi Geçicidir. Bu tur sadece 3 kart daha oynayabilirsin.","","Fanilere çöp gibi görünüyor olabilir ama kimi yordle'lara göre içinden bin türlü icat çıkacak bir hazine.\n","Büyü",[],["Bandle Şehri"],"ENDER"],"05BC050":["Benemon","Çağrıldığımda, elinde 2 Sulu Şaka oluşur.","","''Midesi kolay bulananlar bu nazik deve ÇOK AMA ÇOK dikkatli yaklaşmalı. İç organlarınız size minnettar kalacak. Bu minvalde, ikinci mantarlı sandviçi yememeliydim...''\n- Kabukolog","Birim",[],["Bandle Şehri"],"YAYGIN"],"05BC094":["Karaışıklı Çırak","Çağrıldığımda, elinde yoksa bir Karanlık oluşur.","","''Evet, eminim ki çatıdaki arkadaşın çok yaşanmışlıkları vardır. Eminim ki hikâyelerini anlatmak istiyordur. Fakat bir de NE DEDİĞİNİ anlasak!''\n- Yüksek Ökçeli Terzi","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC146":["Bandle Ressamı","Oyna: 1 kart atarsın. Elinde çok bölgeli bir takipçi oluşur ve bedeli 1 azalır.","","''Resim yapmak gördüklerini kopyalamak değil, dünyayı NASIL gördüğümüzü ifade etmek. Ben de şu an senin yine hareket ettiğini görüyorum. Kımıldama lütfen!''","Birim",["YORDLE"],["Bandle Şehri","Piltover ve Zaun"],"YAYGIN"],"05BC235":["Yordle Demirci","Saldır: Güç değeri benimkiyle eşit ya da benimkinden daha az olan dost birimlere bu tur İlk Saldırı verirsin.","","''Poppy beni hiç dinlemez, bari sözüme sen kulak ver: Marifet çekiçte değil, onu savuran yordle'da.''\n","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC175":["Kaçan Teleskop","Oyna: Bedeli 3 ya da daha az olan bir Semavi kart, destansı ya da çok bölgeli takipçi Cisimlenir.","","En tuhafı teleskopun ayaklanması, gerinmesi ve gezinmeye başlaması değil, hava durumuna göre giyinmekte ısrar etmesi ve istediği rahatlıkta bir atkı bulmak zorunda kalmasıydı.","Birim",["PERİ"],["Bandle Şehri","Targon"],"ENDER"],"05BC182":["Şimşek Gibi","Herhangi bir şeye 2 hasar vermek için bir dost birimi Geri Gönderirsin.","","''Önce çatırdar, sonra patlar!''\n- Kennen","Büyü",["ELEMENTAL"],["Bandle Şehri"],"ENDER"],"05BC069":["Nasihatçi Yordle","Saldır: Elinde Geçici bir Zehirli Ok oluşur.","","Aman, başlamasın şimdi.","Birim",["YORDLE"],["Bandle Şehri"],"ENDER"],"05BC057":["Yüksek Ökçeli Terzi","Çağrıldığımda, her yerdeki Karanlık kartlarının bedeli 1 azalır.","","''Kötülük lobinizi kurarken, her habis ruhlu üyenin farklı bir süperkötülük özelliği olmasına dikkat etmelisiniz. Örneğin benim yardımcılarımdan birinin affetmeyen bir tarzı var...''\n- Lord Veigar'ın ''Nasıl Süperkötü Olunur'' kitabının 4. bölümünden alıntı","Birim",["YORDLE"],["Bandle Şehri"],"ENDER"],"05BC108":["Yordle Kâşif","Başka bir Yordle çağırdığında, ona +1|+0 kazandırırsın.","","''Keşfin görkemine paha biçilmez ama en büyük keşifler daima... ehem... kârlıdır.''","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"05BC183":["Peri Dede","Çağrıldığımda, elinde bir Aç Puhukedi oluşur.\nBaşka bir Peri çağırdığında ona +1|+0 kazandırırsın.","","''Gelin yamacıma dinleyin beni,\nPeri Dede'nin hazin hikâyesini.\nHer gün toplardı aç kuşları başına,\nBeslerdi onları ne olduğu belirsiz tohumlarla...''\n- Bandle Şehri Masalı","Birim",["PERİ"],["Bandle Şehri","Ionia"],"ENDER"],"05BC188":["Meraklı Kabuklu İnsan","Rasgele belirlenmiş seçenekler arasından şampiyon olmayan bir kartı seçtiğinde, elinde bir kopyası oluşur ve kartın bedeli 1 düşer.","","Çekingenlikleriyle ünlü, kimselere pek görünmeyen kabuklu insanlar meraklarına yenilene kadar deniz kabuklarının içinde saklanır. Çıktıklarındaysa oyuncu kişiliklerini sonuna kadar gösterirler. Buna diğer deniz canlılarının sesini ustaca taklit ederek yaptıkları kandırmacalar da dahildir!","Birim",[],["Bandle Şehri"],"DESTANSI"],"05FR001":["Alacakurt Şamanı","Tur Sonu: Bu tur rakibin Nexus'una hasar verdiysen Alacakurt Hücumcu kartına dönüşürüm.","","''Korkak olarak ölmeyeceğiz! Pençelerimizi açmaya, dişlerimizi göstermeye devam edeceğiz. Kurt'u ancak böyle onurlandırabiliriz.''\n- Hepgörür Hyara","Birim",[],["Freljord"],"YAYGIN"],"05FR002":["Mamut Şamanı","Tur Sonu: Bu tur rakibin Nexus'una hasar verdiysen Mamut Hücumcu kartına dönüşürüm.","","Mamut sürüleri, yırtıcı hayvanlarla karşılaştıklarında yavruların ve hamilelerin etrafına dizilir. Böylece, yüce mamut ruhu şamanları sadece ruhlarının fiziksel gücünden değil, aynı zamanda ailelerini korumalarına olanak sağlayan birliğin gücünden de destek alır.","Birim",[],["Freljord"],"ENDER"],"05FR013":["Udyr","Çağrıldığımda ya da Vuruş yaptığımda: Elinde bir Hal Değişimi oluşur. Zaten varsa, bedeli 0 olur.","3+ kez Hal Değişimi oynadığında.","''Ruhlar dünyamızı şekillendirirken biz ve dünyamız da ruhları şekillendiriyoruz. Onlardan aldığımız gücü aslında kendi içimizden alıyoruz.''","Birim",[],["Freljord"],"Şampiyon"],"05FR016":["Şamanın Çağrısı","Elinde bedeli 0 olan Geçici 2 Hal Değişimi oluşur.","","''Göreceksiniz... dişli pençeli, pullu tüylü yüce ruhlar gelecek. Korku ve huşuyla titrediğiniz o anda, Kadim İlahların bizi unutmadığının farkına varacaksınız.''\n- Hepgörür Hyara","Büyü",[],["Freljord"],"YAYGIN"],"05FR012":["Hepgörür Hyara","Çağrıldığımda elinde bir Hal Değişimi oluşur.\nHer tur oynayacağın ilk Hal Değişimi kartının bedeli 0 olur.","","Herkesin büyük saygı duyduğu yüce şaman Hepgörür Hyara, görme kabiliyetini uzun yıllar önce kaybetti. Artık dünyayı dağın tepesindeki evine yuva yapan şahin ve kartalların gözünden görüyor. Aldığı üzücü haberler üzerine dağdan inmeye karar veren Hyara, kehanetlerin gerçeğe dönüşmemesini umut ediyor.","Birim",[],["Freljord"],"ENDER"],"05FR014":["Freljord'un Gazabı","Oyna: Bir düşmana Buz Tutturursun.\nGüç değeri 3 ya da daha az olan düşmanlar karşılayamaz.","","''Yıllar önce oradaydım... Önce soğuk bastırdı, keskin ve gaddardı. Sonra fırtına başladı, öfkeli ve umursamazdı. En son bir kükreme duyuldu, iliklerime kadar işledi. Dizlerimin üstüne çöküp yakarmaya başladım, affı olmayan bir hata yaptığımızdan korktum. Yüce bir ruhu çağırdığınızda, intikam mı alacak... yoksa merhamet mi edecek bilemezsiniz.''\n- Hepgörür Hyara ","Birim",[],["Freljord"],"DESTANSI"],"05FR017":["Hayvani Güdü","Bir dost birime bu tur +1|+1 verirsin. Elinde bir Hal Değişimi oluşur.","","''Toplanın ruhlar, toplanın...''\n- Udyr","Büyü",[],["Freljord"],"YAYGIN"],"05FR006":["Diş Sözcüsü","Oyna: HER BİR Nexus'a 1 hasar verirsin.","","Kışın Pençesi kabilesine Chuluun'unki kadar uzun süre hizmet eden şaman ailesi azdır. Yüce mors şamanı Chuluun, denizin hediyelerinin... ve aynı zamanda tehlikelerinin elçiliğini ve haberciliğini yapar. ","Birim",[],["Freljord"],"YAYGIN"],"05FR015":["Özgür Ruhlar","Her yerdeki dost birimlere +1|+1 kazandırırsın. Sonra HER ŞEYE 1 hasar verirsin.","","''Kadim ruhlar, dört bir yanımızı saran soğuğa karşı koymamıza yardım edin. Buz fırtınaları düşmanlarımızı alıp götürsün. Adınız hep ağzımızda, varlığınız hep aklımızda.''\n- Alacakurt Şamanı'nın Yakarışı","Büyü",[],["Freljord"],"ENDER"],"05FR005":["Kemik Kâhini","Hasar alıp sağ kalırsam rakibin Nexus'una 1 hasar veririm.","","Geleceği, Kemikten Geyik'e hizmet eden şamanlar kadar iyi görebilen çok az kişi vardır. Geleceğini merak eden kişilerin nasıl öleceğini görmeye katlanabilenlerse çok daha azdır.","Birim",[],["Freljord"],"YAYGIN"],"05FR004":["Tilki Gezgin","Çağrıldığımda, elinde bir Hal Değişimi oluşur.","","''Şevkli ve ihtiyatlı. Hızlı ve sessiz. Tilkiler her şeyi görür ama kimseye görünmez. Yolculukta ve savaşta, bilge liderler tilki ruhunun yolundan gidenleri onurlandırır. Çünkü hiçbir savaş kâşifler ve öncüler olmadan kazanılmaz.''\n- Pençe Anası Vrynna","Birim",[],["Freljord"],"YAYGIN"],"05IO003":["Avare Bilge","Bu tur Geri Gönderdiğin her birim için bedelim 2 azalır.","","''Sizinle seyahat etmek bir onur, Himon'she. Bana akıl almaz bir bilgeliğe sahip olduğunuz söylendi. Nereye gidiyoruz?''\n''Eyvah. Ben de seni takip ediyordum!''\n- Ahri ve Avare Bilge","Birim",[],["Ionia"],"YAYGIN"],"05IO004":["Ahri","Saldır: İlk kez saldırırken vuruş yaptığımda, sağımdaki dost birimle yerimi değiştirirsin ve ardından onu Geri Gönderirsin.","5+ birimi Geri Gönderdiğinde.","Kendisini başka insanların sırlarında aradı. O kadar çok kişinin gözlerinden gördü ki kendini... Ormana yaklaşırken bu yolculuğun da sadece bir bakış açısından mı ibaret olacağını merak ediyordu, yoksa bu kez bir ayna bulabilir miydi?","Birim",[],["Ionia"],"Şampiyon"],"05IO023":["Ayartan Öpücük","Bu tur bir düşmana Kırılganlık vermek için bir dost birimi Geri Gönderirsin.","","''Bana bir sır ver.''\n- Ahri","Büyü",[],["Ionia"],"YAYGIN"],"05IO020":["Rüzgârşakıyan","Oyna: Bir birimi Geri Gönderirsin.","","Kaos zayıflara bile diş pençe çıkarttırır. Avının takibinde bir kurt önüne düşen bir dal yüzünden başarısız olabilir. Dalışa geçen bir şahin ani bir rüzgârla tepetaklak olabilir. Biz dalız. Biz rüzgârız.","Birim",[],["Ionia"],"YAYGIN"],"05IO007":["Bin Kuyruklu Sai'nen","Çağrıldığımda 2 kart çekersin ve dost birimlere bu tur +1|+1 verirsin.","","Orman sırlarını karşılık beklemeden sunar... ama çok azı gerekli soruları soracak kadar cesurdur.","Birim",[],["Ionia"],"DESTANSI"],"05IO021":["İlah Söğüt Fidesi","Oyna: Bir dost birimi Geri Gönderip Hayali bir kopyasını çağırırsın.\nGeri Sayım - 3: Bir Hayali kopyasını daha çağırırsın.","","Bir zamanlar Omikayalan'ın içinde İlah Söğüt büyümüş. Orada yetişen şeyler artık daha güçlü de olabilir, daha zayıf da. Önemli olan yeni olmasıdır.","Yer",[],["Ionia"],"ENDER"],"05IO024":["Ormanın Evlatları","Bir dost birimi Geri Gönderirsin ya da 8 mana harcayarak bu oyunda Geri Gönderdiğin En Güçlü 3 takipçinin Hayali kopyalarını çağırırsın.","","Anıların dişleri sivridir.","Büyü",[],["Ionia"],"DESTANSI"],"05IO001":["Ormanın Bekçisi","Çağrıldığımda bu tur bana +1|+0 ve Sıyrılgan verirsin.","","''Diyorlar ki diğerleri bildiklerinin ağırlığı altında ezilmesin diye konuşmuyormuşsun. Hmm... bence sürekli soru cevaplamaktan bıktın usandığın için.''\n- Ahri","Birim",[],["Ionia"],"YAYGIN"],"05IO025":["Tüy Pelerinli Baş Hanım","Her tur bir takipçiyi ilk defa Geri Gönderdiğinde onun birebir, Hayali bir kopyasını çağırırsın.","","Gizem, çözümünden çok daha öte bir şey.","Birim",[],["Ionia"],"ENDER"],"05IO026":["Yitip Gidenler","Nexus Vuruşu: Beni Geri Gönderirsin.","","Avın usulüne saygı göstereceksen önce bir durup avlanan için gözyaşı dökmen lazım.","Birim",[],["Ionia"],"ENDER"],"05IO006":["Dokuz Can","Bir Sınır Muhafızı çağırırsın.","","Ormanın bir muhafıza ihtiyacı vardı, sınırlarında yıllarca hatta belki yüzyıllarca kıpırdamadan nöbet tutabilecek birine. Gai'sh büyük hevesle gönüllü oldu ve bu yeni sorumluluğuna ne kadar bağlı olduğunu on yıllık bir uykuyla hemencecik kanıtladı.","Büyü",[],["Ionia"],"DESTANSI"],"05IO002":["Hatırat Pelerini","Rakibe ait ve tek bir dost birimi hedef alan Hızlı büyüler, Yavaş büyüler veya Yetenekler tarafından hedef alınan bir dost birim seçersin ve hepsini durdurursun.","","Ok ne avcının amacını bilir, ne de avın değerini.","Büyü",[],["Ionia"],"YAYGIN"],"05SH014":["Xerath","Dost bir Yer kartını yok ettiğinde, En Güçsüz düşmana 1 hasar verirsin.","4+ dost Yer kartını yok ettiğinde.","''İkisi bir zamanlar dosttu ama aradan geçen zaman ve samimiyetleri onları kardeş yapmıştı. Azir'in başarıları, Xerath'ın yanında olması sayesinde elde edilmişti.''\n- Kâtip Kah'nir, Yükseliş'e Ermişler Ordusu'nun Tarihi","Birim",["YÜKSELMİŞ"],["Shurima"],"Şampiyon"],"05SH017":["Büyücünün Habercisi","Çağrıldığımda, bu oyunda 4+ dost Yer kartı yok etmişsen, her yerdeki şampiyonlarına +2|+2 ve Aban kazandırırsın.","","Büyücünün Habercisi kollarını açabildiği kadar açarak Shurima göklerinde asılı duran kan kırmızısı güneşe çevirdi. Vecd içinde, ''Yüksek Büyücü'ye selam olsun!'' diye haykırdı. Sesi yıkık sütunlarda yankılandı. ''Xerath'a selam olsun!''","Birim",[],["Shurima"],"ENDER"],"05SH011":["Ebedi Mürit","Son Nefes: Bir Lahit çağırırsın.","","Mezar çok görkemli süslenmiş olsa da bu ne ölülerin umurundaydı ne de sürgünlerin.","Birim",[],["Shurima"],"ENDER"],"05SH022":["Çöl Düellosu","Bu tur bir düşmana -2|-0 verirsin. Bir dost birim ve bu düşman birbirine vurur.","","''Çölden korkmayan gezgin, çölü tanımıyor demektir.''\n- Shurima atasözü","Büyü",[],["Shurima"],"YAYGIN"],"05SH003":["Güç Dikilitaşı","Geri Sayım - 3 ya da çağrıldığımda veya beni yok ettiğinde: En Güçlü dost birime +2|+0 kazandırırsın.","","Kumlardan parıldayan, çatırdayan sütunlar yükseldi. Xerath'ın buyruğuna girmiş, zaten güçlü olan ordusunu daha da kuvvetlendirecek güç noktalarıydı bunlar.","Yer",[],["Shurima"],"YAYGIN"],"05SH016":["Harap Mürit","Oyna: Dost bir Yer kartını yok ederek her yerdeki Harap Mürit kartlarına +1|+1 kazandırırsın.","","Xerath'ın tüm çırakları güç için kendilerinden bir şeyler feda ediyordu ama en güçlü takipçileri artık kendilerinin birer hayaleti haline gelmişti. Yeni imparatorlarına hem güç sağlıyor hem de bu gücü iletiyorlardı.","Birim",[],["Shurima"],"YAYGIN"],"05SH018":["Yok Oluşa Hizmet","Bu tur ölen tüm dost birimleri ve yıkılan dost Yer kartlarını içinde saklamak için bir Durağan Zaman Heykeli çağırırsın.","","Sihir gücü dağılmaz, dönüşüp yeniden kullanılır.","Büyü",[],["Shurima"],"DESTANSI"],"05SH012":["Yükselen Sunak","Geri Sayım - 3 ya da beni yok ettiğinde: Bir Zincirsiz Dami'yin çağırırsın.","","''Her güç noktasına bir dikilitaş dikilecek. Yüksek Büyücü bu dikilitaş aracılığıyla kumların altındaki gücü dilediğince kullanabilecek.''\n- Büyücünün Habercisi","Yer",[],["Shurima"],"DESTANSI"],"05SH020":["Yok Edici Yapım","Elinde bir Harap Mürit ya da Güç Dikilitaşı oluşur.","","''Shurima'yı kendi suretimde şekillendireceğim.''\n- Xerath","Büyü",[],["Shurima"],"YAYGIN"],"05SH015":["Kum Kâhini","Çağrıldığımda 1 kart çekersin. Çektiğin kart Yer kartıysa bu etkiyi tekrarlarsın.","","Gözleri önünde uzanan ufuk enerjiyle şakıyordu âdeta. Herkesin kum ve çamur gördüğü yerlerde o, istediği gibi kullanabileceği sihir hatlarının oluşturduğu göz kamaştırıcı ağları görüyordu.","Birim",[],["Shurima"],"DESTANSI"],"05SH004":["Serbest Kalan Enerji","Bir dost birime bu tur +2|+1 verirsin ya da dost bir Yer kartını yok ederek bir dost birime bu tur +4|+2 verirsin.","","''Çölün gücünü söküp alacağım ve bana karşı duranları mahvedeceğim!''\n- Xerath","Büyü",[],["Shurima"],"YAYGIN"],"05SH002":["Çorağın Gezgini","Dost bir Yer kartını yok ettiğinde, bana +1|+1 kazandırırsın.","","Çırakları Xerath'ın peşine düşmeden önce de başarılı kişilerdi. Ama bir zamanlar onun da geçmiş olduğu eğitimden geçtikleri için artık durdurulamazlardı.","Birim",[],["Shurima"],"YAYGIN"],"05SH007":["Sihir Ayini","Dost bir Yer kartını ya da bir mana taşını yok ederek bir birime 4 hasar verirsin.","","''Büyük güce kavuşmak için küçük bir fedakârlık.''\n- Xerath","Büyü",[],["Shurima"],"ENDER"],"05NX009":["Kayıp Ruh","Çağrıldığımda ya da atıldığımda, elinde bir İkiz Kılıçlı Hortlak oluşur.","","Demacia'lılar sürünerek kalelerine kaçarken, ölümün çok güvendikleri surlardan yağdığını gördüler. Gri Lejyon'un bir kısmını durdurabilmişlerdi ama savaşın karanlık dalgası çok geçmeden onları altına aldı.","Birim",[],["Noxus"],"DESTANSI"],"05NX006":["Dirilmiş Bombacı","Oynamak için 1 kart atarsın.\nAtıldığımda birebir kopyamı çağırırsın.","","''Karşımızda beklenmedik bir sapma var. Dirilttiklerimizin çoğu yaşama dönmüş olmaktan nefret ederken bu arkadaş hem görevinin bilincinde hem de bunun sunduğu fırsatlardan keyif alıyor. İlginç.''\n- Dr. Esslanger'den notlar","Birim",[],["Noxus"],"YAYGIN"],"05NX005":["Kadim Devrin Savaşçısı","Atıldığımda En Güçlü dost birim +2|+0 kazanır.","","Leydi Noradi'nin güçleri arttıkça, Noxus'un en eski mezarlarında yatan cesetlere de işleyip işlemeyeceklerini merak etmeye başladı. Bu boş kabuklarda yaşamın sadece ufacık bir ateşini bulabildi ama bu titreşen alevlerde hâlâ savaşın gölgeleri dans ediyordu.","Birim",[],["Noxus"],"ENDER"],"05NX001":["Sion","Atıldığımda En Güçlü dost birim Aban kazanır ve beni destene geri koyarsın.\nBu oyunda attığın her kart için +1|+0 alırım (en fazla +7|+0).","35+ Güç'lük kart çağırdığında ya da attığında.","Sion tam çözümleyemediği anılardan anlık görüntüler hatırlıyordu. Karşısında hazır olda bekleyen bölükler. Madalyalar. Taçlar. Bir kralın son nefesi. Sonsuz Boşluk. Kan. Ama rüzgârda dalgalanan soluk şeritler gibi bilincinin yanından geçer geçmez yok oluyorlardı.","Birim",[],["Noxus"],"Şampiyon"],"05NX003":["Tuz ve Dikişler","Oynamak için bir kart atarsın.\nBir Dirilmiş Bombacı çağırırsın ve ona bu tur +2|+0 verirsin.","","''Ayağa kalk, çocuğum.''\n- Mezar Hekimi Dr. Esslanger","Büyü",[],["Noxus"],"ENDER"],"05NX015":["Ölmüş Hesapçı","Çağrıldığımda, En Güçsüz düşmana Karşılayamaz kazandırırsın.\nSon Nefes: Elinde bir Dirilmiş Hesapçı oluşur.","","''İlk dirilttiğim minotorlar uysal, işe yaramaz hayvanlardı. Ne savaş davulları ne de ölüm tehdidi onları şevke getirebiliyordu.''\n- Dr. Esslanger'den notlar","Birim",[],["Noxus"],"ENDER"],"05NX019":["Şanımız İçin!","Şöhret: Bedelim 3 azalır. 2 Şöhret Heveslisi Lejyoner çağırırsın.","","Şana ulaşmak isteyenlerin bu uğurda yapmayacağı şey yoktur.","Büyü",[],["Noxus"],"ENDER"],"05NX013":["Ölmüş Süvari","Atıldığımda elinde bir Dirilmiş Süvari oluşur.","","''Basiliskin hışmından ancak binicinin zırhına Siyahgölge yaprakları sürerek kurtulabildiler. Bu bitkiler tıpkı hayvanların kendileri gibi buraya özgü ve kötü koktukları kadar zehirliler de.''\n- Dr. Esslanger'den notlar","Birim",[],["Noxus"],"YAYGIN"],"05NX012":["İnfazcının Kükremesi","Oynamak için 1 kart atarsın. En Güçsüz düşmanı öldürürsün.","","''Dost… düşman… fark etmez!''\n- Sion","Büyü",[],["Noxus"],"YAYGIN"],"05NX014":["Yitenlerin Silahları","Bir birime 3 hasar verirsin ve bir Trifaria Kalkan Kırıcısı çağırırsın.","","''Kalkan kırıcı!''\n- Sion","Büyü",[],["Noxus"],"YAYGIN"],"05NX004":["Mezar Hekimi","Oyna: 1 kart atarsın, bir birim çekersin.","","Dr. Esslanger bir zamanlar saygıdeğer ve emeklilik yolunda bir doktordu. Güvenilirliğini yıllarca çok sıkı çalışarak duyurmuştu. Ama Noxus'a gerçekten hizmet etmeye, muayenehanesine getirilen, kanı ihanetle kararmış genç bir soyluya başladı.","Birim",[],["Noxus"],"YAYGIN"],"05NX016":["Kanın Hanımı","Geçici olmayan bir birim attığında, elinde onun Geçici bir kopyası oluşur.","","Leydi Faris Noradi, Gri Lejyon'unu gecenin karanlığına gizleyerek Noxus'un başkentinden çıkardı. Üç zor, kanlı hafta sürdü ama sonunda öncülerin saptadığı küçük Demacia sınır karakoluna yaklaşmışlardı. Gösterinin zamanı gelmişti.","Birim",[],["Noxus"],"DESTANSI"],"05NX002":["Soylu Asi","Bu oyunda 3+ kart attığında +2|+1 kazanırım.","","''Hıyanete özenen birini yola getirmek için, vahşice öldürülüp Noxus bayrağı altında savaşmak için diriltilmiş bir komplocuyu göstermekten daha iyisi var mı? Öyle ya da böyle, hepsi hizmet edecek.''\n- Kanın Hanımı","Birim",[],["Noxus"],"YAYGIN"],"05BW005":["Nami","Bir büyü oynadığında Hareketsiz olmayan diğer En Güçsüz dost birime +1|+0 kazandırırsın.","Dost bir Nami oyundayken 5+ büyü oynadığında.","''Herkesle vedalaştın mı?''\n''Vedalaştım büyük ana.''\n''Korkuyor musun?''\n''...Evet büyük ana.''\n''İyi. Korkarsan temkinli olursun. Ama biz sana nasıl güveniyorsak sen de kendine öyle güven. Hadi git artık. Akıntılar seni esirgesin.''","Birim",[],["Bilgewater"],"Şampiyon"],"05BW006":["Cezir","Rasgele bir düşmana ya da rakibin Nexus'una 2 hasar verirsin ve elinde bir Med oluşur.","","''Med cezirin öfkesinden sakın...''\n- Nami","Büyü",["ELEMENTAL"],["Bilgewater"],"YAYGIN"],"05BW002":["Gezgin Kumsıçrayan","","","''Evet, bazıları bizi avlıyor ama her şeyi avlıyorlar zaten. Benim karşılaştığım karada yürüyenlerin çoğu sadece bu engin maviliklerin tadını çıkarmaya çalışıyordu. Tıpkı bizim gibi. Hepimiz insanız.''","Birim",[],["Bilgewater"],"YAYGIN"],"05BW008":["Dipsiz Deniz Savaşçısı","Bir büyü oynadığında bu tur +2|+0 alırım.","","''Kabilemizde çoğu kişi Loto'dan biraz çekinirdi. Ona bakınca sadece yorulmaz bir savaşçı görürler, dertli bakışlarını mesafeli bulurlardı. Ama onun yüreğinde aslında neler olduğunu ben biliyorum: bizi koruyacak kadar güçlü olmadığı korkusu... ve olağanüstü bir sevgi.''\n- Marai Şarkıcı Tama","Birim",[],["Bilgewater"],"YAYGIN"],"05BW011":["Filo Amirali Shelly","Her tur 2 büyü oynadığında, diğer dost birimlere +1|+1 kazandırırsın.","","''BANA BAK ASKEV! BENİM ELİMDEN KAYITLAVA GEÇMİŞ TAM ÜÇBEŞYÜZBİN TANE ÖLÜM ÇIKTI VE DE TÜM DOMAMMADAKİ EN BÜYÜK AMİVALİM! O YÜZDEN SANA YÜZ DEDİĞİMDE YÜZÜCEKSİN ANLAŞILDI MI! EVET TEŞEKKÜVLEV GİDELİM!''","Birim",[],["Bilgewater"],"DESTANSI"],"05BW003":["Gelgit Dalgası","Rasgele hedef alınan iki farklı düşmana 1 hasar verirsin ve destende bir Kırılan Dalga oluşur.","","''Okyanus, hepsini yut!''\n- Nami","Büyü",["ELEMENTAL"],["Bilgewater"],"ENDER"],"05BW004":["Dalgaların Sözcüsü","Mana taşı kazanacağın zaman, bunun yerine büyü mananı doldurursun.\nBir büyü oynadığında, elinde bedeli 3 ya da daha az olan rasgele bir büyü oluşur ve ona Geçici kazandırırsın.","","Marai'ler Leo'lei'yi büyük değişimlerin habercisi olarak kabul eder. Zarif kanatlarını her açışında okyanus akıntılarını etkilediği söylenir.","Birim",[],["Bilgewater"],"DESTANSI"],"05BW001":["Marai Koruyucu","Çağrıldığımda, 1 manalık rasgele bir takipçi çağırırsın.","","Marai'lerin yurtlarından uzaklaşma hevesi pek yoktur. Ama Ai'la yüreğinde merakla doğmuştu. Görev bilinci onu kabilesine bağlasa da uyanık olduğu her anı sonunda gerçekten özgür olacağı günü hayal ederek geçiriyor.","Birim",[],["Bilgewater"],"ENDER"],"05BW010":["Marai Büyük Ana","Çağrıldığımda, destende bedeli 6+ olan 5 rasgele büyü oluşur ve bedelleri 3'e düşer.","","Marai'lerin geleneksel yuvasını, ay taşının göksel ışığı korur. Ay taşı her 100 yılda bir sönükleşmeye başlar ve yeni bir Dalga Çağıran yine ay taşı bulmakla görevlendirilir. Çünkü onun ışığı olmadan Marai halkı karanlığa gömülür ve derinliklerde kol gezen canavarlara yem olur.","Birim",[],["Bilgewater"],"YAYGIN"],"05BW013":["Marai Şarkıcı","Çağrıldığımda, bu tur büyü oynamışsan bana Sıyrılgan kazandırırsın.","","''Okyanus dalganın döneceğine inanır,\nMete itimat eder, cezre güvenir,\nOndandır ki dalgalar çarptığında kıyıya,\nOkyanus onların kükremesiyle gönenir.''\n- ''Dalga Çağıran'a Seranat''tan bir dize","Birim",[],["Bilgewater"],"ENDER"],"05PZ015":["Adalet Peşinde","Rakibin her kart çektiğinde, destesinin en üstündeki 8 kart arasına 1 tane Kör Edici Bomba Tuzağı koyarsın.","","''Memurun şüpheliyi kendi yaptığı bir tuzağa yüksek hızda kovaladığı görüldü. Tutuklamanın ardından memur kendine kestiği hız aşımı cezasını ve bedelini teslim ederek (pek gerekli olmayan bir abartıyla) 'Adalet herkes için eşit işlemeli,' dedi.''\n- Bir fedainin devriye raporundan","Birim",[],["Piltover ve Zaun"],"DESTANSI"],"05PZ012":["Karakol Arşivcisi","Oyna: Destenin en üstündeki 5 kart arasından bir büyü seçersin ve elinde birebir Geçici bir kopyası oluşur, ardından en üstteki o 5 kartı destene koyarsın.","","İpuçları olmasa dedektifler hiçbir iş yapamaz. Bir arşivcinin görevi her istihbarat kırıntısını toplayıp daha önce bulunmayan olanaklar ortaya çıkarmaktır.","Birim",[],["Piltover ve Zaun"],"ENDER"],"05PZ026":["Montaj Hattı","2 Dökümhane İşçisi çağırırsın.","","''Vardiya değişimi!''\n- Dökümhane Ustabaşısı","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"05PZ019":["Azılı Suçlu","Seçtiğin oyuncu en düşük bedelli kartını atıp 3 kart çeker.","","''Her şeyin bir bedeli var.''\n- Corina Veraza","Büyü",[],["Piltover ve Zaun"],"DESTANSI"],"05PZ031":["Albus Ferros","Çağrıldığımda Jayce kartını çekersin.Saldır: Rakibin Nexus'una 3 hasar verirsin. Bu oyunda oynadığın 6+ bedelli her büyü vereceğin hasarı 1 arttırır.","","''Yüce gönüllü Albus Ferros, Jayce'in Hexgeçidi araştırmalarına sponsorluk için yapılan açık arttırmada verdiği fiyatla Cadwalder ve Giopara hanelerini açık ara geçerek gözleri bir kere daha üstüne topladı. Malum, 'Ferros Hanesi gülerse tüm Piltover güler,' derler ve dün Ferros Hanesi'nin yüzünde güller açtı.''\n- Günlük Piltover gazetesinde yayınlanan sponsorlu tam sayfa ilandan","Birim",[],["Piltover ve Zaun"],"DESTANSI"],"05PZ027":["Şok Patlaması","Bir düşman birime ya da rakibin Nexus'una 3 hasar ve bir diğerine 3 hasar verirsin.","","''Ateş!''\n- Jayce","Büyü",[],["Piltover ve Zaun"],"ENDER"],"05PZ022":["Jayce","Oyna: Bana İlk Saldırı ya da Rakipçeker kazandırırsın.","6+ manalık 2 büyü oynadığında. Seviye atladığımda elinde bir Hızlandırma Geçidi oluşur.","''Bildiğin üzere bu güçformasyon teknolojisi dünyayı değiştirmeyi vaat ediyor Rosa'cığım.''\n''Gerçekten de çığır açan bir çalışma Jayce. Hele o koinhiberatörlerin iç içe geçmesi soluk kesici.''\n''Öyle, öyle! Üstelik hepsi Axel'ın fikri. Çok akıllı adamsın.''\n''Beni bilirsin dostum, övünmeyi sevmem...''","Birim",[],["Piltover ve Zaun"],"Şampiyon"],"05PZ017":["Kuyu Kokusu","Bir birime 2 hasar verirsin. Bu tur eline 2+ kart eklediysen, bunun yerine 3 hasar verirsin.","","''Biraz dışarı koy da havalansınlar. Piltoşlar kokusuna dayanamıyor. Ama bir alıştın mıydı var ya... başka hiçbir şey istemezsin!''\n- Pofkep Mantarı Satıcısı","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"05PZ013":["Piltover Silahı","Bir birime 2 hasar verirsin ve rakibin destesinin en üstündeki 8 kart arasına 2 tane Kör Edici Bomba Tuzağı koyarsın.","","''Bu da kartvizitim.''\n- Caitlyn","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"05PZ020":["Pusu","Bir birime bu tur +2|+0 verirsin. Eline bu tur 2+ kart eklediysen o birime bu tur Sıyrılgan verirsin.","","''Konumun etrafını sararken hareketlerimizi duman pervaneleriyle gizleyeceğiz.''\n- Caitlyn","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"05PZ024":["Ferros Finansçısı","Oyna: Bölgelerine ait 6+ manalık bir büyü Cisimlendirirsin.","","''Ferrosların çalışmalarımı finanse etmesinin tek iyi tarafı Reggie ile birlikte çalışabilmek. Adam hem tanıdığım en becerikli kişilerden biri hem de harika bir insan.''\n- Jayce'in günlüğünden alıntı","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"05PZ010":["İleri İstihbarat","Rakibin destesinin en üstündeki 8 kart arasına 2 tane Kör Edici Bomba Tuzağı koyarsın.\n1 kart çekersin.","","''İşaret verdiğimde.''\n- Caitlyn","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"05PZ014":["Dâhi Suçlu Corina","Oyna: Rakibin destesinin en üstündeki 5 kart arasına 5 tane Kör Edici Bomba Tuzağı koyarsın veya rakibin destesinin en üstündeki 5 kartta bulunan tüm tuzakları etkinleştirirsin.","","Piltover Muhafızları kapısını kırıp kıymetli çiçeklerini ayakları altında ezerken Corina gülümsedi. Çiçekler zehirli polen yayıyordu. Her şey planladığı gibi gidiyordu.","Birim",[],["Piltover ve Zaun"],"DESTANSI"],"05PZ002":["İçeriden Bilgiler","TÜM oyuncular 2 kart çeker.","","''Bayağı popüler bir vaka. Az önce başka bir bey de onun belgelerine bakıyordu. İyi eğlenceler!''\n- Karakol Arşivcisi","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"05PZ021":["Yarınların Dökümhanesi","Çağrıldığımda bir Dökümhane İşçisi çağırırsın. Bedeli 6+ olan bir büyü oynadığında beni yok edersin ve büyü mananı tekrar doldurursun.","","Piltover icatlarla ileri gidiyorsa, onu ilerleten motor dökümhaneleri.","Yer",[],["Piltover ve Zaun"],"ENDER"],"05PZ025":["Dökümhane Ustabaşısı","Vuruş: 1 büyü manası doldurursun.","","''Sayfalara yazdığın bir fikri elinle tutabileceğin bir nesne haline getirmek için iki şey lazım. Denklemin bir yarısı para bulmak, diğeri de iyi bir dökümhane. Üstelik iş dökümhanedeki aletler ya da malzemelerle de bitmiyor, dökümhane ustabaşısı iyi değilse fikrin kâğıt üstünde kalır.''\n- Jayce","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"05PZ006":["Caitlyn","Vuruş: Rakibin destesinin en üstündeki 8 kart arasına 2 tane Kör Edici Bomba Tuzağı koyarsın.","5+ tuzağın etkinleştiğinde.","Caitlyn daima inatçı ve detaycı bir dedektif olmuştu. Bu özelliği sayesinde Piltover Emniyeti'nde hızla yükselmişti. Ama sayısız diğer fedainin yarım bıraktığı malum ''C'' vakası ile karşılaştığında, sonunda neredeyse onu bile zorlayacak bir olaya çatmıştı. Neredeyse.","Birim",[],["Piltover ve Zaun"],"Şampiyon"],"05PZ004":["Memur Timi","Çağrıldığımda, elinde bir Azılı Suçlu oluşur.","","Hazırlıklar uzun sürmedi, sessizce sokağa dağılıp koçbaşını hazırladılar. Artık geriye sadece Caitlyn'in işaretini beklemek kalmıştı.","Birim",[],["Piltover ve Zaun"],"ENDER"],"05PZ009":["Baskın Memuru","Nexus Vuruşu: Rakibin destesinin en üstündeki 8 kart arasına 2 tane Kör Edici Bomba Tuzağı koyarsın.","","Tüm Zaun'lu çocuklar gibi Zayne Asako da şiddet dolu ve karanlık sokaklarda vaktinden önce büyümek zorunda kalmıştı. Kardeşini anlamsız Zaun çete suçlarından birinde kaybedince kanunun ve mantığın, şehrine sonunda huzur getireceği umuduyla Piltover Emniyeti'ne katıldı.","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"05PZ016":["Son Darbe","Rakibin bir takipçisini onun destesine koyarsın, ardından rakibin 1 kart çeker.","","Görkemli Piltover şehrinde Runeterra'nın en işlek zihinlerinden bazıları yaşıyor. Piltover'ın hapishanelerinde de durum aynı.","Büyü",[],["Piltover ve Zaun"],"ENDER"],"05PZ030":["Hextech Anomalisi","Beni çektiğinde, elinde oluştuğumda ya da her Tur Başı: Elindeyken 6+ manalık rasgele bir büyüye dönüşürüm.","","''...karşıma çıkan en büyük zorluksa hextech'i kararlı bir duruma getirecek konfigürasyonu bulabilmek oldu. Çoğu gece, kristaller ve heksit sanki aralarında plan yaparak beni başarısızlığa uğratmaya çalışıyorlardı. Bileşenlerin parçalarını uyum içinde çalıştırmayı ancak kapsamlı deneme ve yanılmalardan sonra başarabildim...''\n- Jayce'in günlüğünden alıntı","Büyü",[],["Piltover ve Zaun"],"ENDER"],"05PZ028":["Ferros Gök Devriyesi","Bu oyunda bedeli 6+ olan bir büyü oynadığında +2|+0 kazanırım.","","''Bu şehrin halkı 'zekânın' karşısında yerlere kapanır. Ama kendini ifade edecek olanakları olmadıkça en büyük zihinler bile ne yapabilir ki? Hayır, ben Piltover'a asıl yüceliği göstereceğim. Tepelerinden bakacak. Güneşi gölgeleyecek. Ve benim adımı taşıyacak.''\n- Albus Ferros","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"05PZ038":["Roket Yağmuru","Bir düşmana 4, tüm diğer düşmanlara 1 hasar verirsin.","","''Olamaz! Yukarı gitmeleri gerekiyordu, DÖRT BİR YANA değil!''\n- Heimerdinger","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"05PZ035":["Kokuşuk Gömpeç","Son Nefes: Rakibin destesinde 2 Zehirli Pofkep Mantarı takılı bir kopyam oluşur.","","Pofkep mevsiminin en bereketli dönemindeki gömpeçlerin kokusu başka hiçbir şeye benzemez. Bir hafta önce bayatlamış balıklarla ve çürük yumurtalarla dolu bir lağımdan iki kat daha kötü kokarlar.","Birim",[],["Piltover ve Zaun"],"ENDER"],"05PZ029":["Hextech Kotarıcı","Bu oyunda bedeli 6+ olan bir büyü oynadıysan her yerdeki dost Teknolojik birimler +1|+0 kazanır.","","Hextech Kotarıcı aslında Piltover içinde hammade nakliyatı yapmak için üretilmişti. Ama zamanla halk nedense onu çok sevdi. Jayce'in ekibi ona Demirbaş adını taktı, söylentilere göre Piltover'lı bir lord başındaki şapkayı verdi ve yanından geçen çocuklar artık onu ellerine geçirdikleri her şeyle süslüyorlar.","Birim",["TEKNOLOJİK"],["Piltover ve Zaun"],"ENDER"],"05SI014":["Pişmanlık Kataloğu","Tur Başı: Elinde önceki tur oynadığın Geçici olmayan bir büyünün Geçici kopyası oluşur.","","Kutlu Adalar unutur, Gölge Adalar hatırlar. Gölge Adalar unutur, Kutlu Adalar hatırlar.","Yer",[],["Gölge Adalar"],"DESTANSI"],"05SI013":["Sis Kurtarıcıları","Her tur, bir birimi büyüyle öldürdüğün ilk sefer Hayali bir Ruh Sisi çağırırsın.","","Kara Sis kurbanlarını kendi kendilerine çektirdikleri eziyetlerden oluşan sonsuz bir döngüye hapsediyor. Tek ve Kana, bu ruhlara döngüyü kendi güçleriyle kırmaları için bir şans veriyor.\n","Birim",[],["Gölge Adalar"],"ENDER"],"05SI009":["Senna","Çağrıldığımda ya da Saldırdığımda: Elinde yoksa bir Karanlık oluşur. Hasar veren ve öldüren büyülerin hızlanarak Hızlı olur.","Büyülerle 3+ birimi öldürdüğünü veya dost bir Lucian’ın öldüğünü gördüğümde.","''Işık Muhafızı olmak savaşmak demek. Ya kendini ya da sevdiklerini kaybetmek demek. Ama ondan da çok... yaşamak demek. Hem kendin hem sevdiklerin için.''","Birim",[],["Gölge Adalar"],"Şampiyon"],"05SI016":["Gölgelerin Şafağı","Bir birimi öldürürsün ve tüm düşmanlara bu tur -2|-0 verirsin.","","''Gölge ışığa muhtaç, hayatsa ölüme.''\n- Senna","Büyü",[],["Gölge Adalar"],"YAYGIN"],"05SI004":["Adaların Işık Muhafızı","Her tur, bir birimi büyüyle öldürdüğün ilk sefer rakibin Nexus'una 2 hasar verirsin.","","''Köpüş köpüştür.''\n- Ruha yazılmış bilgece sözler","Birim",[],["Gölge Adalar"],"ENDER"],"05SI012":["Solari Işık Muhafızı","Çağrıldığımda, elinde yoksa bir Karanlık oluşur.","","''Artık güneşi hissedemiyorum. Ama hatırası hâlâ benimle ve bu yeterli.''","Birim",[],["Gölge Adalar"],"YAYGIN"],"05SI008":["Ixtal'lı Işık Muhafızı","Çağrıldığımda, elinde yoksa bir Karanlık oluşur. Bu tur oynadığın bir sonraki Karanlık kopyalanır ve rakibin Nexus'unu hedef alır.","","''Bana bu savaşa neden geldiğimi sordun ya Senna, anlatayım. Sis elimden hiçbir şey almadı, yurdumu da tehdit etmiyor. Var olmaması gerek ama var. Neden olduğunu keşfetmeye geldim. Yardım edebilmem için duygusal bağ şart mı?''","Birim",[],["Gölge Adalar"],"ENDER"],"05SI003":["Deşen Karanlık","Bir birimi 5 Sömürürsün.","","''Ölüm yaşama çekilir.''\n- Senna","Büyü",[],["Gölge Adalar"],"YAYGIN"],"05SI010":["Dess ve Ada","Çağrıldığımda, elinde yoksa bir Karanlık oluşur. Bu tur bir sonraki Karanlık kullanımının bedeli 0 olur ve ''Tüm düşman hedeflere hasar veririm'' kazanır.","","''Yine mi kâbus gördün?''\n''Çok da kötü değildi. Sen yoktun.''\n''Eşek. Kötü kısmı neydi?''\n''Sen yoktun.''","Birim",[],["Gölge Adalar"],"DESTANSI"],"05SI011":["Yeni Yetişen Işık Muhafızı","Bir birimi büyüyle öldürdüğün ilk sefer +2|+1 kazanırım.","","Sis Maeve'e baktığında ne görüyor? Canlılık, kendine güven, bastırılamaz bir iyimserlik. Onunla âdeta dalga geçen bu ışığı söndürmek için can atıyor olmalı. Ölüm yaşamdan başka neden korkar ki?","Birim",[],["Gölge Adalar"],"YAYGIN"],"05SI015":["Buhru Işık Muhafızı","Bir birimi büyüyle öldürdüğün ilk sefer +2|+1 kazanırım.","","Buhru ve Işık Muhafızı felsefeleri çok önemli bir konuda aynı fikirde: Her şey sona ermeli, bazıları da zorla sona erdirilmeli.","Birim",[],["Gölge Adalar"],"YAYGIN"],"05MT004":["Şüphe Saçan Camphor","Çağrıldığımda, dost birimleri 4 farklı turda hedef aldıysan, bana Büyü Kalkanı, Aban ve Rakipçeker kazandırırsın.","","Camphor denen iblis yüzyıllardır Targon topraklarında dolanıyor, kurbanlarının özünden onları kendileri kılan güçlü yönleri çekip alıyordu. Kudretli olanların kudretini, bilge olanların bilgeliğini sömürüyordu. Ama onun bu güçlere hiç ilgisi yoktu, kurbanlarına tattırdığı acı, şüphe ve ıstıraptan besleniyordu. Camphor kelimenin tam anlamıyla bir canavardı.","Birim",[],["Targon"],"DESTANSI"],"05MT006":["Yaralı Akyalaz","","","''İlahların gaddarlığını görmek isteyen Targon'luların çok araştırması gerekmez. Bize yaptıklarına bakın. En değer verdiğimiz yoldaşlarımıza neler yaptıklarına bakın.''\n- Pantheon","Birim",["EJDER"],["Targon"],"ENDER"],"05MT008":["Kalkan Hücumu","Bir dost birime +1|+1 kazandırırsın ve bir düşmanı Sersemletirsin.","","Pantheon savaş meydanlarında az ter dökmemişti. Girdiği sayısız savaşlarda çok iyi öğrendiği bir şey vardı; düşmanları daima mızrağını takip eder ve kalkanına nadiren bakardı.","Büyü",[],["Targon"],"ENDER"],"05MT014":["Semavi Mucize","İki düşmanı Sersemletirsin.","","''Targon'un gökyüzü, geceleri tasviri mümkün olmayan güzelliklerle doluyor. O devasa boşluğa bakıp yıldızların nerelere uzandığını düşünüp oralardan ne gibi varlıkların bize baktığını merak ederken insan resmen kendini kaybediyor...''\n- Targon'lu tırmanışçı","Büyü",[],["Targon"],"YAYGIN"],"05MT003":["Pantheon","","Dost birimleri 5+ farklı turda hedef aldığında.","Karşındaki özgürlüğü saygı duyduğu Suretlerce elinden alınan Atreus'dur. Karşındaki, Atreus'a az sayıda faninin anlayabileceği hediyeler bırakan Savaş'ın külleridir. Karşındaki değer verdikleri için savaşmaya ve ölmeye hazır bir insandır.","Birim",[],["Targon"],"Şampiyon"],"05MT013":["Iula","Oyna: Bir dost birime Büyü Kalkanı veya Aban kazandırırsın. Birim seçmezsen bana kazandırırsın.","","Kocasının ölüm haberini alınca tüm vücudunu saran o keder Iula'nın dün gibi aklındaydı. Pantheon ona gelip tam da böylesi bir acıdan beslenen bir canavarı yok etmek için yardım istediğinde karar vermesi çok sürmedi.","Birim",[],["Targon"],"YAYGIN"],"05MT009":["Savaş Bağları","2 dost birime +2|+2 kazandırırsın.","","İlahlara karşı savaşmak ahmaklıktı. Ama o bir avuç cesur kişi, yaralar ve çığlıklar arasında onlar hakkında çok şey öğrenmişti. İlahlar bencildi, sadece kendilerini düşünüyorlardı, yoldaşlık etme erdemini kaybetmişlerdi. Silahları da bu olacaktı, zırhları da.","Büyü",[],["Targon"],"YAYGIN"],"05MT010":["Kör Şaman","Oyna: Bir dost birime +1|+1 kazandırırsın ve düşman bir takipçiyi Susturursun.","","Bir zamanlar görüş yetisini ihtiyaç duyanlara yardım etmek için kullanan Eshiyme isimli bir kâhin varmış. Ama Camphor ona bahşedilen bu lütfu ondan çalmış. İblis, kâhinin kaçınılmaz ıstırabıyla ziyafet çekmek istiyormuş. Ama cesur Eshiyme'yi ne kadar hafife aldığından hiç haberi yokmuş.","Birim",[],["Targon"],"YAYGIN"],"05MT002":["Tek Yüreğiz","2 dost birime bu tur +1|+2 verirsin.","","''Gücümüzü kardeşlik bağlarımızdan almalıyız.''\n- Pantheon","Büyü",[],["Targon"],"ENDER"],"05MT012":["Serbest Kalan Dev","Çağrıldığımda ya da Saldırdığımda: Elinde bir Mücevher oluşur.","","Devler Targon'un en kutsal sayılan yerlerine bekçilik eden kadim ve saygın varlıklardır. Onlara zarar vermek, bizzat dağın kendisine hakaret etmek demektir. Onlara işkence etmekse hiçbir Targon'lunun affedemeyeceği bir suçtur.","Birim",[],["Targon"],"YAYGIN"],"05MT011":["İmkânsız Olsa Da","Rakibin sahasında seninkinden daha fazla birim varsa, bir dost birime rakibin fazlalık her birimi için +1|+1 kazandırırsın.","","Bu bir avuç yiğit, akla hayale sığmayacak kadar kudretli varlıklarla savaşa atılacaklarını biliyordu. Ölüm riskinin çok yüksek olduğunun farkındalardı ama bu, atılmalarını durdurmadı.","Büyü",[],["Targon"],"DESTANSI"],"05MT005":["Destan Arayan","","","Tor her yeni kalp atışıyla hayatının biraz daha kendisinden uzaklaştığını hissedebiliyordu. Ama dehşeti kucaklamasının beklendiği o bitimsiz ve kasvetli karanlıkta yeni bir gaye buldu. Ölümün karşısına kendi isteğiyle dikilmekle kalmayacak, yanında yaşamına erkenden son veren iblisin ta kendisini de götürecekti. Bu Tor'un mirası, Tor'un destanı olacaktı.","Birim",[],["Targon"],"YAYGIN"],"05DE003":["Çetin Gorlith","Oyna: Nexus'unun Can değeriyle kendi Can değerimi değiş tokuş ederim.\nCan değeri benimkinden düşük olan düşmanlar beni karşılayamaz.","","''Ölse bile hiç unutulmayanların onurlu hatıralarını yaşatmak için: Demacia halkı, onun üzerinden yansıyan güneş ışıklarını her gördüğünde umudu hatırlayacak ve yapımına ilham veren boyun eğmez ruh onunla birlikte yaşamaya devam edecek.'' \n- Durand atölyesi tabelası","Birim",[],["Demacia"],"DESTANSI"],"05DE009":["Galio","Çağrıldığımda diğer dost birimlere +0|+3 kazandırırsın.","Tur Sonu: Dost birimlerin toplam Can değeri 25+ olduğunda.","Galio yapımının ardından uzun yıllar boyu uykudaydı. Hiçbir şey hissetmiyor, hiçbir şey bilmiyordu. Fakat büyü sayesinde canlandıktan sonra, savaşın heyecanını tatmış ve hayatta olmanın ne olduğunu öğrenmişti. Artık uykuya döndüğünde yaşadığı bu güzel hisleri çok özlüyordu!","Birim",[],["Demacia"],"Şampiyon"],"05DE020":["Durand Kalkanı","Bir dost birime +0|+3 kazandırırsın. Sonraki Tur Başında bu birime +0|+2 kazandırırsın.","","Galio'yu görmek bile Demacia'lıların soylu yüreklerini umutla dolduruyor.","Büyü",[],["Demacia"],"ENDER"],"05DE021":["Yılmaz Öncülerin Kudreti","Oynamak için tüm mananı harcarsın. Bir Yılmaz Öncü çağırırsın ve niteliklerini harcadığın mana sayısına denk olacak şekilde arttırırsın. 9+ mana harcadıysan, diğer dost Seçkinlere +2|+2 kazandırırsın.","","Tüm umutlar tükendiğinde Demacia askerlerinin imdadına Yılmaz Öncüler koşar.","Büyü",[],["Demacia"],"DESTANSI"],"05DE017":["Savaş Yelleri","Bir dost birimi tamamen iyileştirirsin. Sonra bu dost birim ve bir düşman birim birbirine vurur.","","''Hadi başlayalım o zaman!''\n- Galio","Büyü",[],["Demacia"],"ENDER"],"05DE010":["Durand Heykeltıraş","Başka bir dost birim çağırdığında ona +0|+1 kazandırırsın.","","''Eğitimsiz gözler farkında olmayabilir ama sanatçının becerisi keski izinden belli olur.''","Birim",[],["Demacia"],"YAYGIN"],"05DE013":["Petrisit Geyik","Destekle: Desteklediğim dost birime gelen tüm hasarı bu tur ben alırım.","","Bu zarif tasarım, sırtında bir kolcuyla gezen geyikten ilham alınarak yapılmış olsa da, asıl canlının yanında dev gibi kalıyor.","Birim",[],["Demacia"],"DESTANSI"],"05DE015":["Dağ Ejderi","Hiddet bana +1|+1 yerine +0|+2 kazandırır.","","Uysal dağ ejderleri görünümlerinin aksine çabuk öfkelenmezler. Diğer dağ yaratıklarına karşı metanetli duruşları sayesinde savunmasız varlıkları korurlar.","Birim",["EJDER"],["Demacia"],"DESTANSI"],"05DE019":["Durand Mimar","Destekle: Desteklediğim dost birim bu tur +0|+2 ve Çetin Ceviz alır.","","''Kolcu Ağaçyürek tatsız haberler getirdi,'' dedi mimar sakince. Ellerinin nasıl da titrediğini saklamak için parşömeni sarmaya odaklanmaya çalışıyordu. Bekleyen heykeltıraşlara döndü, başıyla gergin bir işaret verdi. ''Demacia'nın görünmez muhafızlarının saklandıkları yerden çıkma vakti geldi zannederim.''","Birim",[],["Demacia"],"ENDER"],"05DE014":["Durand Çırağı","Oyna: Bir dost birime +0|+1 ve Dayanıklı kazandırırsın.","","Shireen başını işinden kaldırıp nal seslerine kulak verdi. Korucunun telaşı onu hem tedirgin etmiş hem de meraklandırmıştı. Petrisit kuşunu göğe saldı ve korucuyu takip etmeye başladı.","Birim",[],["Demacia"],"YAYGIN"],"05DE012":["Petrisit Açıkkanat","Başka bir dost birimi çağırdığında Rakipçeker kazanırım.","","Bitap düşmüş Demacia'lı askerler, tepelerinden uçarak geçen Açıkkanat'ı görünce tezahürat etmeye başladılar. Heybeti onlara güç verdi.","Birim",[],["Demacia"],"ENDER"],"05DE018":["Petrisit Tazı","","","''Canlandıklarını görmek büyük bir keyif. İnsan bazen birbirlerinden ne kadar farklı olduklarını unutuyor. Her birinin karakteri, onu yapan sanatçıyı yansıtıyor.''\n- Durand Heykeltıraş","Birim",[],["Demacia"],"YAYGIN"],"06NX024":["Yeleli Lord","Oyna: Bir düşmana 2 hasar verirsin.\nHızlı büyülerin, Yavaş büyülerin ve Yeteneklerin ''Sersemlemiş ya da hasar almış bir düşmana hasar verdiğimde, onu öldürürsün'' alır.","","''İkinci Perde: Aşırdığı Kashuri eldivenini gururla takan, adı sanı pek duyulmamış ikiyüzlü bir lord, Ionia'lı seyircileri büyülüyor. Ama incelikten yoksun maskesinin ardını görmek çocuk oyuncağı. Hayatta kalmak için yalvarıyor, bir cahillik ettiğini söylüyor. Hükmetmek istediği demirden el artık bomboş.''","Birim",[],["Noxus"],"ENDER"],"06NX033":["Stratejik Uygulama","2 düşmanı Sersemletirsin ya da bunun yerine 6 mana harcayarak bir Lejyon Generali çağırırsın.","","Görevlendirme, savaşlardan önce verilmesi gereken ilk ve en önemli kararlardan biridir. Becerikli bir komutan, zafere giden yolun...","Büyü",[],["Noxus"],"ENDER"],"06NX012":["Annie","Saldır: Beni karşılayana 2 hasar veririm. Ölür ya da oyundan kalkarsa, onun yerine rakibin Nexus'una 2 hasar veririm.","6 Hızlı büyü, Yavaş büyü ya da Yetenek oynadığını gördüğümde. Seviye atladığımda, elinde bir Tibbers oluşur.","Yaklaşık on yıl kadar önce, Amoline Kiosar elinde göz kamaştıran ve paha biçilemez bir varlıkla birlikte Ravenbloom Konservatuvarı'ndan kaçtı. Ravenbloom askerleri onu imparatorluğun dört bir yanında aradılar fakat duydukları söylentilerin hiçbiri onları Amoline'a götürmedi. Aradan geçen yılların ardından Demirdiş Dağları'nın kuzeyinde öfkeyle yanan kayıp bir kızın haberi geldiğinde, Fynn Retrick gönülsüzce eşyalarını toplayarak olayı araştırmak üzere yola çıktı. Kayda değer bir şey bulacağını ummuyordu. Ne büyük yanılgıydı ama...","Birim",[],["Noxus"],"Şampiyon"],"06NX029":["Gri Eczacı","Güç değeri 5+ olan bir dost birim öldüğünde, elinde Güç değeri 5+ olan rasgele bir takipçi oluşur.","","''Bugün Penrose Hill'deki küçük revirimi ve orada fizyolojinin sırlarını çözmeye çalışırken geçirdiğim yılları düşündüm. Onca yıl! Şimdi Leydi Noradi için çalıştığım şu kısacık birkaç ayda fark ettim ki o zamanlar hiç ama hiçbir şey bilmiyormuşum. O zamanlar ne basit düşünüyormuşum. Ne kadar şanslıymışım...''\n- Dr. Esslanger'den notlar","Yer",[],["Noxus"],"DESTANSI"],"06NX032":["Yumuşak Başlı Ejderan","Bir dost birim saldırdığında, onunla birlikte saldırırım.","","''Ejderanlar ne tatlı, değil mi? Sürekli seni memnun etmeye çalışıyorlar. Öyle uysallar ki... Keşke düşmanlarım için de aynısını söyleyebilseydim.''\n- Gülün Dikeni","Birim",["KÖPEK"],["Noxus"],"YAYGIN"],"06NX030":["Firari Lejyoner","Dost birimlerin her yerdeki güçlendirmelerini kazanırım.","","''Birinci Perde: Eski bir asker, kadim bir Kashuri eserini çaldıktan sonra görevini bırakmış. Qayanvi'de bir barda saklanıyor; sarhoşluğu kibrini örtmeye yetmiyor. O çalınan hazinenin gerçek sahibine gördüğü her şeyi fısıldadığının hiç mi hiç farkında değil! Damarlarındaki yaşam, şarap gibi dökülüp gidiyor. Ionia altınına Noxus kızılı bulaşıyor.''","Birim",[],["Noxus"],"ENDER"],"06NX013":["Büyüşor","Oyna: Bir düşmanı Sersemletirsin ya da zaten Sersemlemişse onun yerine 2 hasar verirsin.","","''Öğrenci: Sydell Kythera\nÖğretmen: J. Willough\nKarar: Sol kolumda örümcek ısırığı var. Sydell bunun bir yanlış anlaşılmadan ibaret olduğunu iddia ediyor ama suratındaki sırıtıştan masum olmadığı belli. İki haftalık sosyal hizmet cezasına çarptırıldı (yemekhanede).''\n- Ravenbloom disiplin raporu","Birim",["ÖRÜMCEK"],["Noxus"],"YAYGIN"],"06NX040":["Lejyoner Eğitim Arenası","Her tur ilk defa Güç değeri 5+ olan bir dost birim saldırdığında Silahlanırsın.","","''Ben emrettiğimde savaşa atılacaksınız! Silah arkadaşınızı öldürürseniz, yenisini bulun! Ölürseniz, bilin ki döktüğünüz kan Noxus'u daha güçlü kılacak! Trifaria askerleri... davranın!''\n- Lejyoner Seçme Uzmanı","Yer",[],["Noxus"],"DESTANSI"],"06NX028":["Ravenbloom Konservatuvarı","Geri Sayım - 11: Elinde bir Tybaulk oluşur.\nBu oyunda oynadığın her Hızlı büyü, Yavaş büyü ya da Yetenek için 1 tur ilerlerim.","","''...şimdiye kadar Roseguard Akademisi'nin endişe verici başarısızlığı mutlaka kulağınıza gelmiştir. Kardeş okulunuzun yanlışlarından ders çıkaracağınızı umuyorum. Okulunuzu imparatorluğa fayda sağlayacak şekilde yöneteceğinizi umuyorum.''\n- Konservatuvarın enkazında bulunan yanmış bir mektuptan","Yer",[],["Noxus"],"ENDER"],"06NX014":["Yok Et","Bir birim seçersin. Birim bu turda bir dahaki sefere 1 ya da daha fazla hasar aldığında onu öldürürsün.","","Noxus öğretileri hakkında uzun uzadıya konuşan Müdire Telsi'yi dinleyen çocuklar, sıkılıp huzursuzlanmaya başlamıştı. Öğrencilerin hemen hepsi bu huzursuzluklarını saklamayı başarırken Annie harekete geçti. Önce duman göründü, sonra ateş.","Büyü",["ELEMENTAL"],["Noxus"],"YAYGIN"],"06NX031":["Tutsak Yeti","Şöhret: Bedelim 4 azalır.","","Bordent'in efsanevi dövüş arenasına getirilen zincire vurulmuş iki yeti kalabalığın ağzını açık bırakıyor. Yetilerin ne kadar kuvvetli olabileceklerini bilmediklerinden olsa gerek, zincirlerinden kurtulduklarında herkes şaşkına dönüyor.","Birim",["YETİ"],["Noxus"],"YAYGIN"],"06NX009":["Esir Küllüsırt","Saldır: Beni karşılayana 3 hasar veririm. Ölür ya da oyundan kalkarsa, onun yerine rakibin Nexus'una 3 hasar veririm.","","''Üçüncü Perde: Zalim bir sahip ve hayvanı. Küllüsırt, korkunç şeyler yapıyor olmasına rağmen masum. Sadece taşıdığı büyülü eser yüzünden emirlere boyun eğmek zorunda. Sahibi, kendi hayvanına yem olurken tek bir çığlık bile atmıyor. Keşke tüm Noxus'lular böyle asil ölmeyi başarabilseydi.''","Birim",[],["Noxus"],"YAYGIN"],"06NX015":["Manaruhu Öğrencisi","Her tur ilk defa Hızlı bir büyü, Yavaş bir büyü ya da Yetenek oynadığında, bir Büyü Közleri oynarım.","","''Daani'yle zannederim iki yıl önce tanıştım. Akıllı bir çocuk. Ailesi de çok iyi insanlar. Ama son seyahatim sırasında köyüne uğradığımda, zavallı Daani'nin köy meydanında bir başına oturduğunu gördüm. Ailesinin eve dönmesini beklediğini söyledi. Zavallı çocuk, herhalde aylardır öylece oturuyordu. Ona yolda neler gördüğümü anlatmaya dilim varmadı...''\n- Fynn Retrick","Birim",[],["Noxus"],"YAYGIN"],"06NX037":["Noxus Söztaşları","Elinde Geçici bir Bilenmiş Azim, Ölüm Pervanesi ya da Yitenlerin Silahları oluşur.","","''Clara'cığım, taşlardaki kanı temizlemezsen olmaz ki ama.''\n- Ophelia Noradi, Kızıl Aristokrat","Büyü",[],["Noxus"],"ENDER"],"06NX008":["Sınıf Başkanı","Hızlı bir büyü, Yavaş bir büyü ya da Yetenek oynadığında, bana +1|+0 kazandırırsın.","","''Şu anda çocukların çoğu otoriteye isyan etme eğilimlerinin yüksek olduğu bir yaşta. Ama şanslıyız ki çocukların en büyüğünün arası iki tarafla da iyi, onun bu uysallığı çok işimize yarayabilir. Öğrenciler derslerimizi görmezden gelmeye kalkarsa dersleri onun aracılığıyla öğretebiliriz.''\n- Müdire Telsi","Birim",[],["Noxus"],"DESTANSI"],"06MT044":["Solari Gökboynuz","Şafak: Diğer dost birimlere bu tur +0|+2 verirsin.","","Gökboynuzlar yıldızlardan doğmuştur ve tıpkı yıldızlar gibi onlar da eşsiz ve özeldir.","Birim",[],["Targon"],"YAYGIN"],"06MT036":["Göklerin Rehberliği","Tüm dost birimleri tamamen iyileştirirsin, sonra Güç değerlerini Can değerlerine eşit olacak şekilde arttırırsın.","","''Her şeyden önce kendimize merhamet göstermeliyiz. Gerisi zaten gelecektir.''\n- Soraka","Büyü",[],["Targon"],"DESTANSI"],"06MT039":["Ejder Tüneği","Geri Sayım - 3: Bir Inviolus Vox çağırırsın.","","''Semavi ejderlerin bizzat nebulalardan doğduğu söylenir, puslu kozmik tozlar arasından birdenbire ortaya çıkarlarmış. Ama biz faniler gerçeği nereden bilebiliriz ki? Bu kadar uzaktan görebildiğimiz tek şey nasıl da parıldadıkları.''\n- Ejderlerin Habercisi","Yer",[],["Targon"],"DESTANSI"],"06MT045":["Semavi Üçlü","Düşük, orta ve yüksek bedelli bir Semavi karta Yakarırsın.","","''Yıldızlar büyük bir potansiyel seziyor. Yaklaşan biri var. Bakalım neye benziyor. Bunu bilmek bana düşmez! Sen ne dersin, Kulun?''\n- Aydüşleyen","Büyü",[],["Targon"],"ENDER"],"06MT043":["Targon Söztaşları","Elinde Geçici bir Sonsuzluğa Bakış, Sükûnet ya da Targon'un Lütfu oluşur.","","''Çok tuhaf, Shorin... Taşın arkası çevrili ama ben yine de üstünde hangi takımyıldızın çizili olduğunu kesinlikle biliyorum.''\n- Gezgin Tyari","Büyü",[],["Targon"],"ENDER"],"06MT029":["Dünyanın Nefesi Esmus","Çağrıldığımda, destenin en üstündeki karta 1 adet Tını koyarsın.\nDestekle: Desteklediğim dost birim +1|+1 kazanır.","","''...ama benim duyduğuma göre Esmus'u bizzat Koruyucu dünyamıza getirdi ve onun doğumuyla birlikte ses kavramı da dünyaya geldi!''\n''Yok artık! Esmus'un bir meleğin kalbine ve ölülerin sesine sahip ihtiyar bir şarkıcının yüzünü taşıdığını herkes bilir... Tabii sonra Bard ona dünyalar güzeli bir ses vermiştir!''\n''Yok artık! Esmus aslında...''\n- Esmus'un Doğumu adlı çokça sevilen ozan oyunundan bir an","Birim",[],["Targon"],"YAYGIN"],"06MT038":["Işık Sarmalı","Akşam: Diğer dost birimlere bu tur +2|+1 ve Aban verirsin.","","''Ay Ana, bize gücünü bahşet.\nBahşet ki, dört bir yanımızı saran karanlığı\nSenin ışığınla aydınlatalım.''\n- Lunari duası","Birim",[],["Targon"],"YAYGIN"],"06MT047":["Mistik Girdap","Çağrıldığımda ya da Geri Sayım yaptığımda, destene 3 tane Tını koyarsın. Geri Sayım - 2: 1 kart çekersin.","","''Sonra onu gördüm. Binlercesi bir o yana bir bu yana dans edip şarkı söylüyordu. Bir de baktım ki, pat diye bir ışık patlamasın mı? Hepsi gitti, tapınak dahil. Arkalarında tek bir taş bile komadılar. Bana ne mi oldu? İhtiyar Dilbaz elinde bir tane tınıyla öyle kalakaldı işte.''\n- İhtiyar Dilbaz'dan Masallar, 3. Bölüm","Yer",[],["Targon"],"ENDER"],"06MT041":["Fezatazı Sürüsü","Her yerdeki dost Fezatazı Sürüsü kartları benim Yazgılı güçlendirmelerimi kazanır.","","Dağcılar, fezatazıları yolculuklarından geri dönmeye hiçbir şekilde ikna edemedi. Tazılar zaten çok ilerlemiş ve görünüşe göre dağın sihrini kanıksamışlardı.","Birim",["KÖPEK"],["Targon"],"YAYGIN"],"06MT049":["Mikael'in Lütfu","Bir dost birime +1|+2 kazandırırsın ve sahip olduğu tüm olumsuz tesirleri kaldırırsın.","","Çanın sesinin saflığı duyanları hayrete düşürür.","Büyü",[],["Targon"],"ENDER"],"06RU025":["Evelynn","Köken: Azabın Kucağı.\nÇağrıldığımda, rasgele bir Kabuk çağırırsın.","Senin ya da bir dost birimin dost bir Kabuk'u öldürdüğünü gördüğümde, bu tur onun faydalı tesirlerini alırım ve seviye atlarım.","Rahibenin gözbebekleri kocaman olmuştu, heyecandan elleri tir tir titriyordu. Artık hazırdı. Evelynn'in sabırsızlıkla beklediği an gelmişti işte. Önce gülümsedi, sonra yavaşça kaşlarını çattı. Ardından çığlıklar başladı, her zaman olduğu gibi.","Birim",[],["Runeterra"],"Şampiyon"],"06RU001":["Bard","Köken: Kozmik Koruyucu.\nSaldır: Destene 3 tane Tını koyarsın.","Oyundaki ya da elindeki dost birimlerin toplam niteliklerini 20+ arttırdığında.","''İhtiyar Dilbaz kendine yetecek kadar acayiplik görmedi mi sanarsın! Önce Koruyucu'nun kendisi geldiydi galiba. Gökyüzünden kayan bir yıldız gibiydi. Sanki tüm dünya durduydu da onunla biz kaldıydık gibi...''\n- İhtiyar Dilbaz'dan Masallar, 1. bölüm","Birim",[],["Runeterra"],"Şampiyon"],"06RU002":["Jhin","Köken: Virtüöz.\nSaldır: Sersemlemiş tüm düşmanlara 2 hasar verirsin.","12+ Hızlı büyü, Yavaş büyü ya da Yetenek oynadığında.","''Giriş: Yaşlı bir ustanın genç bir öğrenciyi çağırdığı Qayanvi şehrinden başlıyoruz. Bu öğrenci kötü kalpli bir grup haini ortadan kaldırıp çalınmış kutsal eserleri kurtarmak üzere görevlendirildi. Öğrenci hevesli fakat henüz ustasının yerini alabilecek kabiliyette değil. Şimdilik sadece hazırlanarak bekliyor.''","Birim",[],["Runeterra"],"Şampiyon"],"06FR029":["Korkudan Donakalan","Bir düşmana Buz Tutturursun ve bir Buz Dişli Kurt Sürüsü çağırırsın.","","Soğuk bastırınca buz dişli kurtlar ortaya çıkıyor. Avlarından daha hızlı koşmalarına gerek yok... Daha fazla beklemeleri yeter.","Büyü",["ELEMENTAL"],["Freljord"],"DESTANSI"],"06FR033":["Avcı Yabandomuzu","Son Nefes: Boş bir mana taşı alırsın.","","Freljord'da yaşam ve ölüm döngüsü epey farklı işler. Acımasız çevre koşulları hiçbir şeyin israf edilmemesi gerektiğini öğretir.","Birim",[],["Freljord"],"YAYGIN"],"06FR038":["Buz Ankası'nın Kanatları","TÜM birimlere 3 hasar verirsin.\nAydınlanmış: Bunun yerine tüm düşmanlara 3 hasar verirsin ve Nexus'unu 3 iyileştirirsin.","","Yüce Buz Ankası'nın kanatları altında, takipçileri sevinç içinde ilerlerken düşmanlarının dizlerinin bağı çözülmüştü.","Büyü",["ELEMENTAL"],["Freljord"],"ENDER"],"06FR030":["Kölelerin Habercisi","Oyna: Bir Donuk Köle çağırırsın ya da tüm Donuk Köle kartlarını 1 tur ilerletirsin.","","Tepedeki yaratığın tuhaf, ıslığı andıran çığlığı zar zor duyuluyordu ama öncüler, vadinin taş duvarlarından çınlayan o sesin kemiklerini titrettiğini hissetti. Hemen oracıkta, buzun yüzeyinde büyük bir hızla biçimsiz çatlaklar oluşmaya başladı.","Birim",["KUŞ"],["Freljord"],"YAYGIN"],"06FR039":["Yabanpençenin Hıncı","Dost bir takipçiyi Lider Yabanpençe kartına dönüştürürsün.","","''Ulu yabanpençe ruhu, bize gücünü bahşet!''\n- Udyr","Büyü",[],["Freljord"],"ENDER"],"06FR028":["Tandırnameci Revna","Çağrıldığımda destendeki birimlere benim niteliklerimi kazandırırsın, ardından Güç değeri 5+ olan bir birim çekersin.","","Genellikle kabilenin çok şeyler görmüş geçirmiş büyüklerinden oluşan Avarosa tandırnamecileri, insanları koruyup kollar ve hikâyeler anlatırlar. Hikâyeleri ve şarkılarıyla hem av hem de savaş geleneğini yaşatırlar. ","Birim",[],["Freljord"],"DESTANSI"],"06FR037":["Çatlayan Buz","Bir düşmana ''Sonraki Tur Başında bana Buz Tutturursun'' kazandırırsın.","","Ne kadar sağlam görünürse görünsün, buza ayak basmadan önce iki kere düşünmek gerekir.","Büyü",["ELEMENTAL"],["Freljord"],"YAYGIN"],"06BC045":["Kaşındıran Büyütme Tozu!","Dost birimlere bu tur +1|+1 verirsin. Bu birimler oluşturulmuş kartlarsa onun yerine +2|+2 verirsin.","","''MERHABA. BEN MANTAR. BEN KONUŞUYOR NE OLDU NİYE OLDU NASIL OLDU BİLMİYOR SADECE MANTAR OLMAK İSTİYOR. LÜTFEN. TEŞEKKÜR. GÖRÜŞÜRÜZ.''\n- Mantar","Büyü",[],["Bandle Şehri"],"DESTANSI"],"06BC036":["Muhteşem Paparo","Oyna: Bir Yordle Cisimlendirirsin.\nSaldır: Dost Yordle'lara +1|+0 kazandırırsın.","","''Paparo'yu KİM sevmez ki! Her yaz bize dünyanın dört bir yanından lezzetli, sevimli veya kafa karıştırıcı hediyeler getirir! Bazı hediyeler bu üç özelliği birden içerir!''\n- Ava Naptınama","Birim",["YORDLE"],["Bandle Şehri"],"DESTANSI"],"06BC040":["Bandle Söztaşları","Elinde Geçici bir Yordle İcadı, Destancı ya da Elektro Zıpkın oluşur.","","Yordle'lar oyun oynamaktan asla kaçmaz... ama oyunun ortasında kurallar değişirse sakın şaşırma!","Büyü",[],["Bandle Şehri"],"ENDER"],"06BC039":["Bombayı Sal","Bir birime 2 hasar verirsin ve bir Hurda Bombası çağırırsın.","","''Bu hiç ama hiç hayra alamet değil,'' diyor Giselle sessizce, bir yandan siper alırken.","Büyü",[],["Bandle Şehri"],"YAYGIN"],"06BC044":["Kozmik Bağ","Bir düşmana 2 hasar verirsin ve başka bir düşmanı Sersemletirsin. Destene 6 tane Tını koyarsın.","","''Anne, Koruyucu nerelere gider?''\n''O her yere gider yavrum. Gözün görebildiği her yere.''\n''Neden peki?''\n''Ah, benim güzel çocuğum. Nedenini düşünme. Koruyucu'nun yöntemlerini anlamaya en bilge büyüklerimizin bile aklı ermez.''\n- Bir anne ve çocuğu","Büyü",[],["Bandle Şehri"],"ENDER"],"06BC026":["Zilli Byrd","Çağrıldığımda, destenin en üstündeki karta 1 adet Tını koyarsın.","","''...öbür seferki daha da büyüktü. Yerleri süpürürken bir baktım ki yemeğem masaya dökülüvermiş, tencere tavalar sanki ayakları varmış gibi pat pat kapıya doğru yürümeye başlamış! Dizlerim yettiğince, hızlı hızlı peşlerine takılıverdim. Bir de baktım ki şu tapınağa gittiler. Sanki bir şey arıyormuş gibi rafların altını üstüne getiriyorlar.''\n- İhtiyar Dilbaz'dan Masallar, 2. Bölüm","Birim",[],["Bandle Şehri"],"YAYGIN"],"06BC030":["Serseri Pofkep Mantarı","Bir birime 1 hasar verirsin. Bu tur bir tuzağın ya da lütfun etkinleştiyse, bunun yerine 3 hasar verirsin.","","''Parladı mı patlar, işte o kadar!''\n- Bandle İzcisi Andı Madde 463","Büyü",[],["Bandle Şehri"],"YAYGIN"],"06BC031":["Bolkollu Bekçi Maduli","Çağrıldığımda, destenin en üstündeki karta 1 adet Tını koyarsın. Destendeki lütuf sayısı ikiye katlanır.","","''Çok korktum çok. Sanki bin tane kolu vardı. Dişleri kafam kadardı. Hele de yaratık tokmağını dişlerinin arasında gezdirdi mi öyle bir ses çıkardı ki korkudan hık diye gidivereceğim sandım. Ne yapacağım, kaçtım tabii. Ama kaçarken gökteki delikleri gördüm... Belki yüz tane delik vardı!''\n- İhtiyar Dilbaz'dan Masallar, 4. Bölüm","Birim",[],["Bandle Şehri"],"ENDER"],"06BC035":["Kâğıt Ağaç","İlavesi olan bir dost birim saldırdığında, ilavesine +1|+0 kazandırırsın.","","Peri sihrinden meydana gelen Kâğıt Ağaç'ın yaprakları, yine aynı sihrin etkisiyle ışıl ışıl parıldıyor. Minik kuşları andıran bu yapraklar, yine tıpkı kuşlar gibi parlak şeylerin cazibesine direnemiyor.","Yer",[],["Bandle Şehri"],"ENDER"],"06IO005":["Tüyler Ürperten Tiyatro","Can değeri 3 ya da daha az olan bir birimi Geri Gönderirsin.","","''Sanat aceleye gelmez.''\n- Jhin","Büyü",[],["Ionia"],"YAYGIN"],"06IO038":["Manevi Destek","Bu oyunda bir dost birimi desteklediysen bedelim 2 azalır. Bir dost birime bu tur Bariyer verirsin.","","''Dengeye güven. Yaşamla ölüm arasındaki çizgiyi hisset.''\n- Shen","Büyü",[],["Ionia"],"YAYGIN"],"06IO012":["Kinkou'nun Çağrısı","Şimdi ya da sonraki Tur Başında bir Maskelerin Muhafızı çağırırsın. 1 kart çekersin.","","''Eski maskeler, genç gözler.''\n- Maskelerin Muhafızı","Büyü",[],["Ionia"],"YAYGIN"],"06IO009":["Ejderha Pususu","2 Ejder Yavrusu ile birlikte bir fazladan saldırı başlatırsın.","","''Arzular beden buldu.''\n- Ejderha Efendisi","Büyü",[],["Ionia"],"YAYGIN"],"06IO033":["Bıçak Tufanı","Oyun boyunca, Dans Eden Bıçaklar kullandığında, saldıran bir Bıçak daha çağırırsın.\n1 bıçak dans eder.","","''İyisi mi dansı sen yönet, ben sana göre hareket edeyim!''\n- Kurdele Dansçısı","Büyü",[],["Ionia"],"DESTANSI"],"06IO004":["Deha","Oyna: Güç değeri benimkinden daha az olan bir birimi Geri Gönderirsin.","","''Deha olağanüstü bir yaratıcılığa sahip. Efsanevi bir sanatçı! Yaptığı işler sanatsal açıdan emsalsiz! Uygulama açısından kusursuz! Onun elinden çıkmış bir enstrümanı kullanmayı bırak, huzurunda olmak bile büyük bir onur.''\n- Kashuri Şahidi","Birim",[],["Ionia"],"ENDER"],"06IO010":["Esintili Tepecik","Çağrıldığımda Yasuo kartını çekersin ve En Güçlü düşmanı Sersemletirsin.\nSaldırı hakkı sana geçtiğinde En Güçlü düşmanı Sersemletirsin.","","Çoğu kimse için huzur, mutlu bir yuva ve sevdiğinin kollarında bulunan samimi dinginliktir. Ancak Yasuo'ya göre huzur, rüzgârın dindiği ve beraberinde hatıraları değil umudu getirdiği ender anlarda saklıdır. ","Yer",[],["Ionia"],"DESTANSI"],"06IO036":["Ionia Söztaşları","Elinde Geçici bir Tüyler Ürperten Tiyatro, Yenilenme Ayini ya da Birlikten Kuvvet Doğar oluşur.","","''Rakibini okumak zaruri bir beceridir, dövüşmediğin zamanlarda bile. Ama daha da önemlisi, bir oyunun esas amacı eğlenmektir. Şimdi bana bir leğen kap gel, ayaklarımı yıkayacağım da!''\n- İlham Veren Hoca","Büyü",[],["Ionia"],"ENDER"],"06IO003":["Sahne Görevlisi","Oyna: Bir düşmanı Sersemletirsin.","","''Dördüncü Perde: Hikâyemize genç bir rahibe katılıyor. Trajedi dolu bir geçmişi var, ihanet ettiği kimselerce dilden dile aktarılmış. Günahlarının kefaretini ödeme amacıyla kollarında büyük bir yük taşıyor; topraklarına kabul ettiği Noxus'lular için hazırladığı göz alıcı bir hediye. Geriye cevap bekleyen tek bir soru kalıyor: Kalbini asıl kıran şey çektiği acılar mıydı, yoksa mermi mi?''","Birim",[],["Ionia"],"YAYGIN"],"06IO035":["Kinkou Öğrencisi","Başka bir dost birim Bariyer aldığında, bu tur yoksa bana Bariyer verirsin.","","''Dengeyi her yönünle kucakla: zihninle, bedeninle ve ruhunla. Gençliğin getirdiği fevri dürtülere karşı diren. Bakış açını genişlet.''\n- Shen","Birim",[],["Ionia"],"ENDER"],"06PZ032":["Cızırdayan Fonograf","Bedeli 2 olan iki yeni büyüden birini seçersin. Seçtiğin kart elinde oluşur ve bu tur bedeli 0 olur. Aynı şeyi iki kez daha tekrar edersin.","","Zaun'un ilk fonografı şaşırtıcı bir şekilde epey sağlamdı. Tek sorun, hiç kimsenin sesin nereden kısıldığını bilmemesiydi.","Büyü",[],["Piltover ve Zaun"],"DESTANSI"],"06PZ042":["Kusurlu Kötü","Oyna: Elinden bir kart seçersin. Destende bu kartın 4 adet birebir kopyası oluşur ve bedelleri 1 azalır.","","''Bugünle ilgili sadece bir şey söyleyeceğim: Daha iyi olabilirdi. Konuyla ilgili tek bir kelime daha etmem. Gelecekteki ben... ikimiz de ne yaptığımızı biliyoruz.''\n- Kay'in günlüğünden","Birim",[],["Piltover ve Zaun"],"DESTANSI"],"06PZ025":["Sulugöz","Çağrıldığımda, rasgele bir Kabuk çağırırsın.\nBedeli 1 olan bir dost birim çağırdığında ona rasgele bir tesir kazandırırsın.","","''Asma Kat'tan eve dönerken şu zavallı avarenin yine küçük bir ara sokakta ağladığını gördüm. Ona bakınca resmen içim eziliyor, yüreğim burkuluyor. Uzansam, ümitsizliğini elimle tutabileceğim sanki. Yarın yine karşılaşırsak ona elimden geldiğince yardım etmeye karar verdim.''\n- Leydi Sempescu'nun günlüğünden notlar","Birim",[],["Piltover ve Zaun"],"ENDER"],"06PZ043":["Piltover Söztaşları","Elinde Geçici bir Artçı Şok, Hextech Dönüştürücü ya da Gelişim Günü! oluşur.","","''Böyle kaliteli parçaları başka hiçbir yerde bulamazsınız, efendim. Kızım en ufak ayrıntılar için bile öyle çok emek verdi ki...''\n- Corin Reveck ","Büyü",[],["Piltover ve Zaun"],"ENDER"],"06PZ027":["Sınırlı Davetiye","Elinde Geçici bir Şaibeli Tip ya da Zaun'lu Gitarist oluşur ve bedeli 1 azalır.","","Zaun'da gece yaşamının tadı davetiyeli etkinliklerle çıkar. Eğer bir müzik grubunda değilsen yer bulmak için çok ama çok önemli biri olman gerekir. Ya da yerde bir bilet bulan biri.","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"06PZ038":["Elden Düşme Kamuflaj Pelerini","Bir dost birime Sıyrılgan ve ''Nexus Vuruşu: 1 kart çekersin'' kazandırırsın.","","''Bugün ne bulduğuma İNANAMAYACAKSINIZ!''\n- Toplayıcı Kuyu Çocuğu","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"06PZ039":["Artık Hurda","Oynamak için 2 taneye kadar kart atarsın. Bölgelerine ait, bedeli 1 daha yüksek olan, attığın kart sayısı kadar takipçi oluşur ve bedelleri 1 azalır.","","Zaun'un derinliklerinde, insanlar hayatını sürdürmek için çöpten topladıkları hurdaları ve artıkları işlenebilir malzemelere dönüştürmek zorunda kalıyor. Bunu yıllardır yaptıkları düşünülünce, dönüştürme işinde iyi olmaları hiç de şaşırtıcı değil.","Büyü",[],["Piltover ve Zaun"],"ENDER"],"06BW006":["Illaoi","Saldır: 1 Dokunaç Çıkarırsın, ardından bu tur En Güçlü Dokunaç kartının Güç değerini benimkine eklersin.","Kendimin veya dost Dokunaç kartlarının 15+ hasar verdiğini gördüğümde.","''Nagakabouros'un Gözü'' sadece bir isim ancak Illaoi bu ismi bir meydan okuma olarak kabul ediyor. Tanrısı hep yanında olan ve her şeyden hemen sıkılan bir yoldaşmış gibi yaşıyor.","Birim",[],["Bilgewater"],"Şampiyon"],"06BW036":["Rıhtım Sıçanı","Rakibin Nexus'una hasar verdiğin her farklı tur için +1|+0 alırım.","","''Bilgewater'ın en kanlı yeri körfezidir. Şu sıçanlara baksana. Sırf kan kokusuna geliyorlar. Kana doyamıyorlar resmen. İğrenç mahluklar.''\n- Testere Kasap","Birim",[],["Bilgewater"],"DESTANSI"],"06BW038":["Kocadiş","Sen Derin olduğunda, dost birimlerini ve Nexus'unu 3 iyileştirirsin.","","''Ne istiyor bu böyle?''\n''Şey... portakalların peşinde galiba!''\n''Sakallı Hanım aşkına, TÜM SEPETİ VERELİM GİTSİN!''\n- Bahtsız denizciler","Birim",["DENİZ CANAVARI"],["Bilgewater"],"YAYGIN"],"06BW030":["Nagakabouros'un Gözü","2 Dokunaç Çıkarırsın.\n2 kart çekersin.","","Nagakabouros cömert bir tanrıdır, tabii sadece sınavından sağ kurtulabilenler için.","Büyü",[],["Bilgewater"],"YAYGIN"],"06BW011":["Nagakabouros","Çağrıldığımda ya da Tur Başı: 2 Dokunaç Çıkarırsın. En Güçlü Dokunaç kartın 12+ Güç değerine sahipse, elinde bir Nagakabouros'un Feveranı oluşur.","","''Yılan Ana. Büyük Kraken. Sakallı Hanım. Nagakabouros için isimlerin pek önemi yoktur. Huzursuz ölülerinse hiç önemi yoktur.''\n- Illaoi","Birim",[],["Bilgewater"],"DESTANSI"],"06BW021":["Akıntı Vaazı","Bir düşman birime 3 hasar verirsin.\n3 Dokunaç Çıkarırsın.\nRakibin Nexus'una 1 hasar verirsin.","","''Biz tehlikeli sularda yüzmeyi çocukluğumuzda öğreniriz. Mücadele etmek ölmek demektir. İşte bu yüzden, bir rahibenin üstesinden gelmek zorunda olduğu ilk sınav bunu unutmak ve tüm gücüyle dalgalara karşı savaşmaktır. Çünkü Sözcü, yüzücü değil, akıntının kendisidir.''\n- Illaoi","Büyü",[],["Bilgewater"],"DESTANSI"],"06BW045":["Sudaki Kan","Herhangi bir şeye 1 hasar verirsin, ardından Silahlanırsın.","","Kanlı Katil Körfezi'nde dönüp dolaşan köpekbalıklarını uzak tutmak mümkün değil. Kanın tadını bir aldılar mı gitmek bilmiyorlar.","Büyü",[],["Bilgewater"],"YAYGIN"],"06BW028":["Dokunaç Darbesi","2 Dokunaç Çıkarırsın, ardından En Güçlü Dokunaç kartın ve bir düşman birbirine vurur.","","''Hayat bir sınavdır. Ve biz inanmak istesek de istemesek de acı en iyi öğretmendir.''\n- Illaoi","Büyü",[],["Bilgewater"],"ENDER"],"06BW035":["Denizin Sesi","Saldır: 1 Dokunaç Çıkarırsın ve En Güçlü Dokunaç kartına bu tur Aban verirsin.","","Nagakabouros'u çağırmak öyle herhangi bir ritüel ya da ayin değildir. O sadece ruhu okyanusun her bir dalgasıyla, her bir kabarmasıyla boy ölçüşebilen ruhların çağrısına yanıt verir. Bu pek az kimsenin dayanabileceği bir mücadeledir.","Birim",[],["Bilgewater"],"ENDER"],"06BW015":["Kabul Olmuş Dua","2 Dokunaç Çıkarırsın ya da 5 mana harcayarak 4 Dokunaç Çıkarırsın.","","Nagakabouros'a dua etmek yalvarmak anlamına gelmez. Bir şey istemek ya da sunmakla da ilgisi yoktur. Onun lütfu yaşamdan farksızdır: Didinirsin, mücadele edersin, çabalarsın ve arada sırada uğraşlarının ödülünü alırsın.","Büyü",[],["Bilgewater"],"YAYGIN"],"06BW007":["Gözcü İdol","Tur Başı: Bana 2 hasar verirsin ve 1 Dokunaç Çıkarırsın.","","Korkunç varlıklar Gölge Adalar'dan akın akın çıkmaya başladığında idol ufukta ışıl ışıl parıldamaya başlar.","Birim",[],["Bilgewater"],"YAYGIN"],"06BW037":["Ödül Zenginleri","Bedelini ödeyebileceğin bir takipçi Cisimlendirirsin.","","''Evet, Baz. Tekrar denemek istediğine emin misin?''\n''Üç benim uğurlu sayım, Gav. Ayrıca bu rezil şehir için öyle az buz savaşmadık.''\n''Savaştık ve kaybettik, Baz.''\n- Baz ve Gav, acemi ödül avcıları","Büyü",[],["Bilgewater"],"DESTANSI"],"06BW041":["Katakulli","Rakibin elinden şampiyon olmayan iki karttan birini seçip elinde bir kopyasını oluşturursun. Yağma: Bedelim 1 azalır.","","''BEŞ as mı? Bu oyun da bende!''\n- Bilardo Sansarı","Büyü",[],["Bilgewater"],"ENDER"],"06BW016":["Buhru Nöbetçisi","Çağrıldığımda 3 Dokunaç Çıkarırsın.","","Yaşamın güzelliği basit şeylerde saklıdır. Yüze çarpan tuzlu suda, şakıyan kuşlarda... ve ufukta görünen ne olduğu bir bakışta anlaşılan düşmanda...","Birim",[],["Bilgewater"],"YAYGIN"],"06BW009":["Buhru Lideri","Oyna: Bedeli 1 olan bir dost birim fazladan saldırı başlatır.","","''Okyanusun ne denli kudretli olduğunu aklınızdan çıkarmayın! O hareket etmeyeni hareket ettirir! Yolunu kaybeden sesimi takip etsin. Düşmanın da kendi yolundan gittiğini unutmayın.'' ","Birim",[],["Bilgewater"],"ENDER"],"06BW043":["Bilgewater Söztaşları","Elinde Geçici bir Barut Getirin!, Oyunbaz Düzenbaz ya da Denizin Dişleri oluşur.","","''Taş oyununda blöf yapan kişiyi yakalamaya çalışmak çok anlamsız. Bilgewater sağlam yalancılarla dolu bir yer. Gerçekten kazanmak istiyorsan karşındakinin ellerini iyi izlemelisin.''\n- Twisted Fate","Büyü",[],["Bilgewater"],"ENDER"],"06BW018":["Steem","Çağrıldığımda, rasgele bir Kabuk çağırırsın.\nBedeli 1 olan bir dost birim çağırdığında En Güçlü düşmana Kırılganlık kazandırırsın.","","Evelynn'in Steem'le ilk karşılaşması şiddetli ve tüyler ürperticiydi. Evelynn, derisini yüzerken Steem'in nasıl da keyifle gülümsediğini anımsıyordu; sıra kendisine geldiğinde o da tıpkı Evelynn gibi can acıtma konusunda fazla hevesliydi. Steem'i nihayet alt etmesinin ardından, Evelynn kendisinden daha güçsüz olan bu iblisi öldürmek istemediğine karar verdi. Fakat onu sonsuza dek kendisine bağlayacaktı. Vahşete duydukları bu ortak sevgiyi birlikte tüm dünyayla paylaşabileceklerini düşünüyordu.","Birim",[],["Bilgewater"],"YAYGIN"],"06SH014":["Hiçlik Ucubesi","Çağrıldığımda, dost birimlerin bu oyunda sahip olduğu tüm faydalı tesirleri kazanırım.\nBir dost birim yeni bir faydalı tesire sahip olduğunda, o tesiri kazanırım.","","''Daha önce Hiçlik yarıklarının şehirleri nasıl yakıp yıktığıyla ilgili efsaneler duymuştuk. Ama kendi gözlerimle görünce... Gördüğüm o manzarayı, yaşadığım o dehşeti hayatım boyunca asla unutamayacağım.''\n- Belveth felaketinden sağ kurtulan biri","Birim",[],["Shurima"],"DESTANSI"],"06SH016":["Kovan Elçisi","Oyna: Bir birime ve bana birbirimizin faydalı tesirlerini kazandırırsın.","","''Beni... tanıyormuş gibi konuştu. Sanki... bir şeyi... görmemi istermiş gibi.''\n- Kai'Sa","Birim",[],["Shurima"],"ENDER"],"06SH009":["Kai'Sa","Çağrıldığımda ya da Tur Başı: Saldırı hakkı sendeyse elinde bir İkinci Deri oluşur.","Evrildiğinde.","Henüz birkaç gün önce, Kai'Sa ikinci derisinin yepyeni bir heyecanla kaynamaya başladığını ve kendisini gittikçe artan bir hevesle Shurima kıyılarına doğru çektiğini fark etmişti. Yanlış giden bir şeyler vardı ve Kai'Sa, Belveth'e yaklaşırken önünde ne denli büyük bir dehşetin uzandığını fark etmesi çok sürmemişti.","Birim",[],["Shurima"],"Şampiyon"],"06SH048":["Çığır","Bu oyunda yok edilmiş dost bir Yer kartı Cisimlendirirsin ve çağırırsın.","","''Zamandan kurtarılmış bir an.''\n- Zilean","Büyü",[],["Shurima"],"YAYGIN"],"06SH037":["Kurupençe Baccai","Oyna: Bir düşmana Kırılganlık kazandırırsın.\nBir rakip Çekildiğinde ona bu tur -2|-0 verirsin.","","Akılları rüzgârda uçuşan kumlar misali uçup gitmişti ve yerinde hiçbir çöl pınarının besleyemeyeceği öfke tohumları yeşermişti.","Birim",[],["Shurima"],"YAYGIN"],"06SH008":["Belveth'li Bilge","","","Shalatai önünde uzanan dehşet manzarasına baktı. Yardımsever kasabın kızı Ferai hareketsiz yatıyordu; ezilerek ölmüştü. Hemen yanında yatan balıkçının oğlu Gorrub, son nefesini verirken elini uzatıp sevdiğine ulaşmaya çalışmıştı. Tüm hatıralar yok olmuştu. Kim bilir kaç kişi can vermişti. Shalatai kaşlarını çatarak yüzünü kötülüğe döndü. Halkından geriye kalanları korumak için hayatını vermeye hazırdı.","Birim",[],["Shurima"],"YAYGIN"],"06SH042":["Shurima Söztaşları","Elinde Geçici bir İnsafsız Yırtıcı, Yargının Ağırlığı ya da Ruh Ateşi oluşur.","","''Söztaşı oyununda kimin kazandığı değil oynarken ne kadar iyi göründüğün önemli!''\n- Akshan","Büyü",[],["Shurima"],"ENDER"],"06SH050":["Zamanın Kumları","Düşmanlara bu tur -2|-0 verirsin. Elinde Geçici bir Anlık Asır oluşur.","","Zamanın kumları zerre umursamadan akmaya devam ediyor. Acımasız bir kayıtsızlık oyunu oynasalar da duygusuz entrikalarına köle olmayanlar da var...","Büyü",[],["Shurima"],"ENDER"],"06SH049":["İhtişamın Çağrısı","Bu oyunda çağırdığın her farklı Yükselmiş dost birim için bedelim 2 azalır.\nİmparatorun Destesi'nden bedeli 9 ya da daha az olan bir kart Cisimlendirirsin.","","''Eserlerimize bakın! Yaptıklarımıza bakın!''\n- Azir","Büyü",[],["Shurima"],"ENDER"],"06SH036":["Yenilenme Odası","Bir şampiyon çağırdığında beni yok edip ona +2|+1 ve Büyü Kalkanı kazandırırsın.","","Nasus lahitten çıktı, zihni temizlenmiş ve yaraları tamamen iyileşmişti. Birkaç not karaladı ve yukarıda asılı duran lahitlere baktı, içinde yatan canavarların nasıl bir ruh hali içinde olduklarını düşündü. Bu büyünün Baccai'leri deliliklerinden döndürüp döndürmeyeceğini zaman gösterecekti. Diğer Yükselmişler bu büyüye bir zamanlar karşı çıkmıştı ama artık yoklar. Renekton ve deliliğiyse varlığını sürdürüyor. Nasus, sonunda kardeşini kurtarmanın bir yolunu bulduğunu umarak birkaç kelime daha karaladı.","Yer",[],["Shurima"],"DESTANSI"],"06SH011":["Gücün Sınırı","Bir dost birime Aban ve Büyü Kalkanı kazandırırsın.","","''Nasıl savaşılırmış gör.''\n- Kai'Sa","Büyü",[],["Shurima"],"YAYGIN"],"06SH017":["Hiçlik Topu","Bir takipçiye 1 hasar verirsin. Eğer Evrilmişsen, bunun yerine bir birime 3 hasar verirsin.","","''Acıtır, biliyorum.''\n- Kai'Sa","Büyü",[],["Shurima"],"ENDER"],"06SH007":["Hiçlik Haşeresi","Elindeyken her tur değişen rasgele bir tesirim olur. Çağrıldığımda bu tesiri kazanırım.","","Dharna pencereleri açtığı ve taze pişmiş ekmek kokusunu içine çektiği o sabahı hatırladı. Aşağıdaki yolda balıkçılar o gün yakaladıkları balıkları öğle pazarına doğru götürmeye çoktan başlamıştı. Güzel bir gün olacağını düşünerek nasıl da gülümsemişti...","Birim",[],["Shurima"],"YAYGIN"],"06SH010":["Hiçlik Direnişçisi","","","Belveth şehrindeki Hiçlik saldırısı ani ve tüyler ürperticiydi. Şehri büyük bir hızla ele geçiren kaos yüzünden hemen hemen herkes korkudan ne yapacağını şaşırmış ve şehirden mümkün olan en hızlı şekilde kaçmaya çalışmıştı. Ancak Koyemi, herkes değildi.","Birim",[],["Shurima"],"YAYGIN"],"06SH034":["Sahibe","Çağrıldığımda, rasgele bir Kabuk çağırırsın.\nBedeli 1 olan bir dost birim çağırdığında ona +1|+0 kazandırırsın.","","Bazen güçlülerin tek istediği şey güçsüz hissetmektir.","Birim",[],["Shurima"],"DESTANSI"],"06DE045":["Umut Işığı","Dost birimlere Cesaret kazandırırsın.","","''Artık saklanmak yok! Işığa adım atıp benimle birlikte parıldayın!''\n- Lux","Büyü",[],["Demacia"],"YAYGIN"],"06DE038":["Sihir Avcısı Lideri Lord Eldred","Diğer dost birimler ve Nexus'un Dayanıklı alır.\nBir dost birim hasar alıp sağ kaldığında, ona +1|+1 kazandırırsın.","","''Hararetli fısıldamalarına kulak misafiri oldum, karıcığım. Sokak ortasında aile meselelerinden bahsederken daha dikkatli olmanı öneririm. Sonuçta yerin kulağı var, öyle değil mi?''","Birim",[],["Demacia"],"DESTANSI"],"06DE037":["Kraliyet Fermanı","Bir dost birime bu tur +2|+2 ve Rakipçeker verirsin ya da bir Onurlu Lord çağırırsın.","","''Hemen, Kral Jarvan. Bedeli ne olursa olsun bu işi yapacağız.''\n- Onurlu Lord Barrett Buvelle","Büyü",[],["Demacia"],"ENDER"],"06DE035":["Petrisit Sütun","TÜM büyülerin bedeli 2 artar.\nGeri Sayım - 2","","Sihir avcıları, zindanlarının dört bir yanına petrisitten dikilitaşlar yerleştirir. Böylece en güçlü büyücülerin bile eli kolu bağlanır.","Yer",[],["Demacia"],"YAYGIN"],"06DE042":["Demacia Söztaşları","Elinde Geçici bir Prizmatik Bariyer, Tutukla ya da Demacia İçin! oluşur.","","''Neden 'krallara layık bir oyun' diyorlar ki? Kraliçeler de oynayamaz mı yani?''\n- Bulutçayırlı Cithria","Büyü",[],["Demacia"],"ENDER"],"06DE036":["Kanat Geren Baba Ejder","Saldır: Bir birim çekersin. Çektiğin birim bir Ejderse, saldıran olur.","","''Neyse ki araştırmalarıma göre baba ejderler zamanlarının büyük bölümünü yavrularından epey uzakta avlanarak geçiriyormuş. Tabii söylememe gerek yok ama erkek ejder dönecek olursa, hepimizi ham diye yutuverir. Haha!''\n- Yumurta Araştırmacısı Anden Mayne","Birim",["EJDER"],["Demacia"],"DESTANSI"],"06DE030":["Yürek Yakan","Rasgele bir Kabuk çağırırsın ve ona +1|+0 kazandırırsın.","Missing Translation","''Yaklaş, tatlım...''\n- Evelynn","Büyü",[],["Demacia"],"YAYGIN"],"06SI012":["Gwen","Saldır: Başka bir dost birim Kutlu olarak Güç aldığında, ben de alırım. Rakibin Nexus'una 2 Sömürü hasarı verirsin.","10+ hasar verdiğimde.","Gwen, Kara Sis'i kırt kırt keserek ilerliyor, sisin tüm bölgeyi nasıl da kapladığını şaşkınlıkla izliyordu. Nihayet sisten çıktıktan sonra, kasvetli ağaçların arasında beliren büyülü köşkün bir fener gibi ışıldadığını gördü. Gwen merakla o yöne doğru yöneldi. Öyle ilginç ve öyle büyüktü ki!","Birim",[],["Gölge Adalar"],"Şampiyon"],"06SI020":["Nefret Dikeni","Bir dost birimi öldürerek bir birime 3 hasar verirsin ve başlangıç destende Evelynn varsa rasgele bir Kabuk çağırırsın.","","''Gönlünce haykır.''\n- Evelynn","Büyü",[],["Gölge Adalar"],"ENDER"],"06SI013":["Ebedi Dansçılar","Saldır: Ebedi Dansçılar olmayan En Güçlü ölü dost birimin, Güç değeri benimkine eşit ya da daha az olan, saldıran ve Hayali bir kopyası dirilir.","","Pistte dans eden birine katılmak, piste ilk çıkan olmaktan çok daha kolaydır. Ancak ikizler, gerçek dansın nasıl olması gerektiğini herkese göstermekten hiç çekinmezler.","Birim",[],["Gölge Adalar"],"DESTANSI"],"06SI037":["Gölge Adalar Söztaşları","Elinde Geçici bir Adaların Damgası, Ruh Yolculuğu ya da Ufalan oluşur.","","''Cilalı... süslemeler. Taşlar... kural öğreniyor. Acayip bir oyun. Nefes kesici... eşi benzeri olmayan bir ustalık... Unutulmaz.''\n- Bulunmuş günlük","Büyü",[],["Gölge Adalar"],"ENDER"],"06SI040":["Harrowing'in Dönüşü","Ölmüş olan En Güçlü dost takipçiyi diriltirsin ve ona Hayali ile Korkunç kazandırırsın. Düşmanlara bu tur -1|-0 verirsin.","","Ruhlar bir süreliğine kovulsalar da hep geri dönerler.","Büyü",[],["Gölge Adalar"],"DESTANSI"],"06SI027":["İğneye İplik Geçirmek","Bir dost birimi öldürerek bir düşmana kartın Güç değeri kadar hasar verirsin.","","''İğneler hazır!''\n- Gwen","Büyü",[],["Gölge Adalar"],"YAYGIN"],"06SI018":["Vora","Çağrıldığımda, rasgele bir Kabuk çağırırsın.","","Kurbanlarını hileyle kandırıp kendilerine çeken diğer iblislerin aksine, Vora'nın açlığı ve arzuları tuzak kuracak kadar sabırlı olmasına izin vermiyor. Avının peşine düşen bir yırtıcı gibi değil, beslenmesi gereken vahşi bir hayvan gibi hareket ediyor.","Birim",[],["Gölge Adalar"],"ENDER"],"06SI015":["Müzik Başlasın","İki Garip Grup çağırırsın.","","''Daha canlı! Daha hızlı!''\n- Sislerin Şefi","Büyü",[],["Gölge Adalar"],"YAYGIN"],"06SI030":["Resmi Davet","Elinde bu oyunda ölmüş olan 2 dost takipçinin kopyaları oluşur.","","''İşte geldik, canım. İşittiğime göre bu akşam harikulade bir eğlence tertip ediliyormuş. Zannediyorum pek çok tanıdık yüz göreceğiz!''\n- Keyifçi Hayalet","Büyü",[],["Gölge Adalar"],"ENDER"],"06SI026":["Sislerin Şefi","Son Nefes: Elinde bir Garip Grup oluşur.","","''Çalmaya devam edin, dostlarım! Daha öncekilerle kıyaslanamayacak kadar canlı bir konser olacak!''","Birim",[],["Gölge Adalar"],"ENDER"],"06SI033":["Lanetli Mezar","Geri Sayım - 2: Ölmüş olan En Güçlü dost birim dirilir.","","Kalkana çarpan kılıcın sesi ölüm çanı gibiydi. Dünyayla bağları tamamen kesilmemiş ve ölümle bile iradeleri bastırılamamış tüm ruhları açığa çıkardı.","Yer",[],["Gölge Adalar"],"DESTANSI"],"06SI016":["Şamatacı Ev Sahibi","","","''Herkese HÜRMETLER! GECE YARISI EĞLENCEMİZDE sizleri de aramızda görmek isteriz. PORSELEN KÖŞK'TE içki, dans ve keyifle dolu bir akşama davetlisiniz! (Not: Kutlamalar biz bitti demeden bitmeyecektir.)''\n- Son derece muntazam bir el yazısıyla yazılmış bir davetiyeden","Birim",[],["Gölge Adalar"],"ENDER"],"06SI028":["Hayalet Kâhya","","","Partiyi parti yapan şey içeceklerdir.","Birim",[],["Gölge Adalar"],"YAYGIN"],"06SI043":["Habis Bitki","3 kartı Denize Atarsın.\nBir birime 2 Sömürü hasarı verirsin.","","Gölge Adalar'da bile balta girmemiş orman yeni amaçlara yelken açabilir.","Büyü",[],["Gölge Adalar"],"YAYGIN"],"06SI022":["Meçhul Âşık","","","Bir hayalet miydi, hatıra mıydı yoksa rüya mıydı bilmiyorum ama... sanki onu daha önceden tanıyor gibiydim.","Birim",[],["Gölge Adalar"],"YAYGIN"],"06SI019":["Sultur","Çağrıldığımda, rasgele bir Kabuk çağırırsın.","","''Bu lanetli adalarda kimlerin gülümsediğine dikkat edin. Bir ihtimal henüz nasıl dehşet verici bir yerde olduklarını fark etmediklerinden gülümsüyorlardır. Veyahut akıllarını kaybetmişlerdir. Belki de bambaşka bir sebebi vardır. Ama dikkatli olmakta fayda var.''\n- Jens Tommen'in notlarından","Birim",[],["Gölge Adalar"],"YAYGIN"],"06NX022":["Lejyoner Tayini","Güç değeri 5+ olan bir dost birim çekersin ya da bir dost birimin Güç değerini bu tur 5'e çıkarırsın.","","''Pek az kişi Trifaria Lejyonu'na katılmaya hak kazanır. Elinizdeki bu fırsatın değerini bilin.''\n- Lejyoner Seçme Uzmanı","Büyü",[],["Noxus"],"DESTANSI"],"06NX019":["Noxus Kaçkını","Saldır: Güç değerim bu tur En Güçlü Kuşanmış dost birime denk olur.","","''Yine rüyalar görmeye başladım, karanlıkta yine o sesi duyuyorum. On yıl oldu... İmparatorluğun sadık köpeği olarak harcadığım koskoca on yıl. Şuraya git. Şunu öldür. Peki ne için? Noxus'un zaferi için mi? Zafer dediğin yalandan ibaret, benim de inandığım bir yalan. Ama artık buraya kadar. Kayn bana başka bir yol öğretti, intikamdan geçen bir yol.''\n- Kasap Royce'un günlüğünden","Birim",["TARİKATÇI"],["Noxus"],"YAYGIN"],"06NX023":["Ionia'lı Oltacı","Çağrıldığımda, Doğaçlama yaparım.","","Trisk'in hayatı, katıldığı son balıkçılık yarışmasında altüst oldu. Bir şekilde, balık yerine boğulmak üzere olan Jax'i tutmuştu. Jax bu olay hakkında konuşmayı pek sevmiyor ama Trisk'in kendisini elinden kurtardığı deniz canavarı, Trisk hikâyeyi her anlattığında daha da büyüyor.","Birim",["SİLAH ÜSTADI"],["Noxus","Ionia"],"YAYGIN"],"06NX044":["Sinsi Kader Dokuyan","Saldır: Saldıran diğer dost birimlerin Güç değeri bu tur benimkine denk olur.","","''İyi bir anne çocuklarına avlanmayı öğretir ancak harika bir anne... onlar için avlanır.''\n- Elise","Birim",["ÖRÜMCEK"],["Noxus"],"YAYGIN"],"06NX041":["Kızıl Güvercin","Destekle: Desteklediğim dost birime 1 hasar vererek bana bu tur +1|+1 verirsin.","","''Kuş beslemek eğlenceli iş. Zavallı Feoward'la iddiaya girmiştik. Ona, 'Bu kuşlar Bordent basiliski gibi iştahla kan emiyor,' demiştim. Sonra ne mi oldu? Bu kuşların has Noxus'lu olduğunu anladım!''\n- Kızıl Küratör Edvin Cortain","Birim",["KUŞ"],["Noxus"],"DESTANSI"],"06NX020":["Darkin Balistası","8 mana harcayarak beni Zuretta'lı Naganeka olarak oynayabilirsin.","","Doğu Valoran'ın çorak bozkırları, Noxii halkını beslemek ve barındırmak için uygun değildi. Ancak aradan geçen asırlarda büyümeye aç, yeni bir imparatorluk kurulmuştu. Boş araziler yeni tarım tekniklerinin kullanılmasıyla bereketlenirken, vakti zamanında güvende kalması için buralara gömülen silahlar bir kez daha gün yüzü görmüş oldu.","Ekipman",["DARKİN"],["Noxus"],"DESTANSI"],"06NX039":["Hovardanın Ziyafeti","Bir dost birime 2 hasar vererek bu tur dost birimlere +2|+0 verirsin.","","''Çığlıklar yükselmeden ziyafet olmaz. O yüzden bağırmaya başla, evlat.''\n- Vladimir","Büyü",[],["Noxus"],"YAYGIN"],"06NX026":["Koca Çekiç","","","Vessid, Bordent'in en hızlı hesapçısı olmaktan uzak ama koca çekici hedefi bulduğunda, rakibinden geriye pek bir şey kalmıyor.","Ekipman",[],["Noxus"],"YAYGIN"],"06NX034":["Gözü Dönmüş Savaşçı","Kuşanmış bir dost birim bir düşmana vurur.","","''Kan kardeşim, yine beraberiz!''\n- Noxus Kaçkını","Büyü",["TARİKATÇI"],["Noxus"],"ENDER"],"06NX036":["Rün Kalfası","Çağrıldığımda Yeniden Döversin.","","Aylar boyunca yağmur çamur demeden, görünürde hiçbir yere varmayacak nankör bir vazife uğruna çalışıp didinmişti. Ama bir yere varmıştı işte. Nihayet başarmıştı.","Birim",[],["Noxus"],"YAYGIN"],"06NX027":["Vahşi Müsademe","Bir düşman birimin ekipmanını yok edersin. Bir dost birim ve bu düşman birbirine vurur.","","''O piti piti, işte çığlıklar yükseldi\nAsker hemencecik yanıverdi\nKapkara kaldı bedeni\nTam Tibbers'ın istediği gibi!''\n- Annie","Büyü",[],["Noxus"],"ENDER"],"06MT035":["Kan Dokuyan Xolaani","Güç değeri arttırılmışken ölen her dost birim için +2|+2 alırım.\nPotansiyel - 16: Suretin Felaketi Xolaani kartına dönüşürüm.","","Anaakca yok etmek için var gücüyle savaştığı düşmana boyun eğip dizlerinin üstüne çökerken Xolaani onu yalnızca izliyordu. Çok geçmeden onun da kalbi diğerleriyle ahenk içinde atmaya başladı. Artık o da hükmedilecek bir kalpten, komuta edilecek bir bedenden ibaretti.","Birim",["DARKİN"],["Targon"],"DESTANSI"],"06MT007":["Hülya Ejderi","Potansiyel - 5: Aban.","","''Ah, şimdi anlıyorum... Dağa işlenmiş şekiller basit mühürlerden ibaret değilmiş. Meğer yıldızların ötesinden gelen varlıklar için açılan geçitlermiş...''\n- Masalcı Skai'en","Birim",["EJDER"],["Targon"],"ENDER"],"06MT037":["Çelik Mühür","Bir dost birimin Kökünü Kazırsın ve o birimin niteliklerine sahip bir Yozlaşmış Suret oluşturursun.","","Bu silahlara gömülü düşmüş ilah savaşçıları ortadan kaldırmak imkânsıza yakındı. Bu yüzden bunun yerine silahlara hapsedildiler.","Büyü",[],["Targon"],"ENDER"],"06MT031":["Adaletin Sureti Mihira","Tur Sonu: Oyundaki ve elindeki dost birimlere +1|+1 kazandırırsın.\nPotansiyel - 5: Sıyrılgan, Can Çalma ve Aban.","","''Kimileri suretleri ilah sayar. Kimileriyse onları öte âlemden gelen elçiler olarak görür fakat onlardan yine de korkarlar... ve muhtemelen korkmakta çok haklılar.''\n- Masalcı Skai'en","Birim",[],["Targon"],"DESTANSI"],"06MT010":["Yüce Adalet","Bir dost birime bu tur ''Hasar alamam ya da ölemem'' verirsin.\nTüm dost birimlere bu tur +1|+0 verirsin.","","''Doğruluk ateşinde korun!''\n- Kayle","Büyü",[],["Targon"],"ENDER"],"06MT016":["Kanatlı Ulak","Potansiyel - 3: Sıyrılgan.","","''Evet... Seni tanıyorum. Taşıdığın mesaj... Demek beni çağırıyorlar.''\n- Ryze","Birim",[],["Targon"],"YAYGIN"],"06MT015":["Arındıran Alev","Elindeki 2 dost birime +2|+2 kazandırırsın.","","''Kötülük yanarak son bulacak!''\n- Kayle","Büyü",[],["Targon"],"YAYGIN"],"06MT042":["Alacakaranguk Koruyucusu","Şafak: Şafak'lı dost birimlere bu tur +1|+1 verirsin.\nAkşam: Akşam'lı dost birimlere +1|+0 kazandırırsın.","","Alacakaranlıkta ve seherde öten baykuş, sana gün batımıyla şafağın sınırlarında kalanları anımsatır.","Birim",["KUŞ"],["Targon"],"ENDER"],"06MT008":["Kayle","Güç değeri arttırılmış bir dost birimin saldırdığı her sefer için +1|+0 alırım.\nÇağrıldığımda, dost birimlere +1|+0 kazandırırsın.\nPotansiyel - 6: İlk Saldırı.","Tur Başı: Güç değerim 11+ olduğunda.","''Demacia'lılar onu Kanatlı Muhafız olarak bilir. Yıldızlı kubbenin altında yaşayan biz Targon'lularsa onu yıldızateşi kılıcını ilahi bir amaçla savuran Adalet'in Kızı olarak tanıyoruz.''\n- Masalcı Skai'en","Birim",[],["Targon"],"Şampiyon"],"06MT004":["Gezgin Çoban","Oyna: Bir dost birim seçersin, bu birim Doğaçlama yapar. Birim seçmezsen ben Doğaçlama yaparım.","","Jax, Chaska'nın sürüsünü saldırgan bir patlıcanavardan kurtarmasına yardım etti. Sonra Chaska, Jax'i saldırgan patlıcanavardan kurtardı. Artık beraber seyahat ediyorlar, tabii biri ortalıktan kaybolmadıkça.","Birim",["SİLAH ÜSTADI"],["Targon","Bandle Şehri"],"YAYGIN"],"06MT017":["Ulvi Keşiş","Potansiyel - 3: Can Çalma.","","''Rivayete göre Mihira buradan göçüp gittiğinde kendinden bir parçayı, ışığıyla aydınlatan kutsal bir ateşi geride bıraktı. Ailem, bir gün geri döneceği umuduyla ateşin bir an bile sönmesine izin vermedi.''","Birim",[],["Targon"],"ENDER"],"06MT040":["Ebediyet Koruması","Bu oyunda bir dost birimi Kuşattığında, bedelim 2 azalır.\nBir dost birime bu tur Büyü Kalkanı verirsin.","","Gece vakti geldiğinde göğe bak ve gök kubbenin küçük bir bölümüne odaklan. Çağlar boyunca orada yaşamış herkesi, öğrenilmiş her şeyi ve yaşanmış bütün deneyimleri düşün. Bütün bu bilgilerin cebine sığacak kadar küçük bir kristale sığdırıldığını düşün. Bu kristalle sahip olabileceğin irfanı düşün. Sahip olabileceğin gücü düşün.","Büyü",["TARİKATÇI"],["Targon"],"ENDER"],"06MT034":["Semavi Darbe","Bir birimin ya da Yer kartının Kökünü Kazırsın. Nexus'unu 3 iyileştirirsin.","","''Zor zamanımızda imdadımıza kim koşacak?''\n- Shurima'lı Bilge","Büyü",[],["Targon"],"ENDER"],"06MT033":["Ejder Kolçağı","Taşıyıcım bir Ejderdir.","","Runeterra'da pek çok kişi farklı yöntemlerle olsa da ejderlerin gücüne başvurur. Bir semavi ejdere güç bahşetmesi için yakaranlar, asıl gücün kendi içlerinde, yıldızlardan daha da parlak ve sıcak bir biçimde harlandığını idrak ederler.","Ekipman",[],["Targon"],"YAYGIN"],"06MT053":["Cömert Mücevher Ustası","Bir büyü oynadığında elindeki rasgele bir dost birime +1|+1 kazandırırsın.","","Nazik gözleri dışında peçenin arkasında kalan yüzü âdeta bir muamma. Kutsal yolculuğuna çıkmaya hazır olanlara kristal tespih boncuğu dağıtıyor. Karşılığındaysa hiçbir şey istemiyor zira bedel dağda ödenecek.","Birim",[],["Targon"],"DESTANSI"],"06MT006":["Darkin Mıknatısı","Destekle: Desteklediğim dost birim +1|+1 kazanır.\n8 mana harcayarak beni Horazi olarak oynayabilirsin.","","Belki de darkinleri tutsak edenler, efsanevi savaşçı Horazi'yi yıldız metalinden bir kürenin içine hapsetmenin, onun hiddetli iradesini kırmakta yeterli olacağını düşünmüşlerdi. Ama generali harekete geçtiğinde, Horazi de aynı şeyi yaptı. Targon'un kadim koruyucularının bile uzaklardan fısıldanan vaatlerle cezbedilebileceğinin farkına varmıştı.","Ekipman",["DARKİN"],["Targon"],"DESTANSI"],"06MT018":["Adaletin Askeri","Oyna: Güç değeri benimkinden daha az olan düşmanları Sersemletirsin.","","''Korkarım ki o gün geldi çattı... Adalet, altın sarısı kanatlarıyla geri döndü ve beraberinde parlak ordusunu da getirdi!''\n- Masalcı Skai'en","Birim",[],["Targon"],"YAYGIN"],"06MT052":["Semavi Lütuf","Oyundaki ve elindeki birer dost birime Cesaret kazandırırsın.","","''İlahi lütufla!''\n- Kayle","Büyü",[],["Targon"],"YAYGIN"],"06MT032":["Lunari Tarikatçı","Çağrıldığımda ya da bu oyunda bir dost birimi Kuşattığında, elinde bir Mücevher oluşur.","","Güneş ve Ay'ın arasındaki çatışmaya bir son vermeye, gündüzle geceyi barıştırmaya çalışıyordu. Yay ona güç sundu ama bu gücün bedeli oldukça ağırdı. Buna rağmen savaşı sonsuza kadar bitirmek umuduyla kendini yaya adadı. ","Birim",["TARİKATÇI"],["Targon"],"YAYGIN"],"06RU008":["Jax","Köken: Silah Ustası.\nOtomatik Kuşan: Icathia'nın Işığı.","Kuşanmış dost birimler toplam 16+ Güç değeriyle saldırdığında.","Asırlar önce, Jax'in memleketi Hiçlik'e yenik düşmüştü. Jax şimdi, bir gün o korkunç düşmanın karşısına çıkıp onu alt edebilmek için dünyayı gezerek irade gücüne ve cesarete sahip savaşçılar arıyor.","Birim",["SİLAH ÜSTADI"],["Runeterra"],"Şampiyon"],"06RU006":["Ryze","Köken: Rün Büyücüsü.\nÇağrıldığımda ya da Tur Başı: Destende 2 Geçmişe Bakış oluşur.","3+ eşsiz Dünya Rünü gördüğümde.","Ryze, Kayle'ın sessiz hizmetkârıyla birlikte dağın sırtına çıkıyordu. Aşağıdaki savaştan harap olmuş topraklara bir baktı ve birbirine girmiş darkin canavarlarını gördü. Yüzyıllar boyunca insanlığın bir felaketten başka bir felakete sürüklenişini izlemişti fakat şimdi aklında durmadan şu soru dönüyordu: Ya bütün çabaları boşunaysa ve Runeterra yok olmaya mahkûmsa?","Birim",[],["Runeterra"],"Şampiyon"],"06RU005":["Kayn","Köken: Gölge Cellat.\nOtomatik Kuşan: Darkin Tırpan.\nBir düşmanı öldürdüğümde beni 2 iyileştirirsin.","İki vuruş yaptığımda. Seviye atladığımda beni Geri Gönderirsin.","Biri daha can verirken Kayn neşe dolu bir kahkaha patlattı. Yakında diğer darkin silahını da gün yüzüne çıkaracağını biliyordu. İçindeki Rhaast'sa gittikçe sabırsızlanıyordu, Kayn'in sonunun çok yakın olduğunun farkındaydı.","Birim",["DARKİN"],["Runeterra"],"Şampiyon"],"06RU026":["Aatrox","Köken: Dünyaların Sonu.\nOtomatik Kuşan: Darkin Kılıcı.\nÇağrıldığımda ya da Vuruş yaptığımda: Nexus'unu 2 iyileştirirsin ve elinde yoksa bir Dünyaların Sonu oluşur.","Dünyaların Sonu kartını oynadığında.","Kıtalarca uzakta olmasına rağmen Aatrox onun uyandığını hissetti. İçindeki nefret hâlâ cayır cayır yanıyordu. Onun heykellerini çoktan yıkmıştı. Artık Icathia'nın Korkağı'na son bir savaş açabilir ve onu yok ederek bu acınası dünyanın sonunu getirebilirdi.","Birim",["DARKİN"],["Runeterra"],"Şampiyon"],"06RU009":["Varus","Köken: İntikam Oku.\nOtomatik Kuşan: Darkin Yayı.","7+ dost birimi hedef aldığında.","Peki ya darkine dönüşen adam zaman geçtikçe içindeki fani seslerin kıpırdanmasıyla kendini hatırlarsa? Ya sesleri tamamen bastırmak yerine onlara kulak vermeye başlarsa?","Birim",["DARKİN"],["Runeterra"],"Şampiyon"],"06FR004":["Silah Uzmanının Çırağı","Bir dost birimi ilk defa Kuşattığında, onu İşlersin.","","Ornn, Yaşayan Ocak'ı yıllar yıllar önce üretti ama onu aramaya henüz yeni başladı. Ocağın yeni sahibini bulmak için kendi başına dolaşmaya çıkacağı aklının ucundan bile geçmemişti.","Birim",[],["Freljord"],"YAYGIN"],"06FR011":["Ornn","Oyna: Beni bir dost birimin ekipmanının ya da elindeki En Güçlü ekipmanın birebir kopyasıyla Kuşatırsın.\nSaldır: Beni iki kez İşlersin.","Bir dost birim tek seferde 8+ hasarlık vuruş yaptığında.","Ornn'a neden bu kadar sabırsız olduğu sorulduğunda, cevap olarak sadece sabırlı olduğunu söylerdi. Hem de ne sabır... Zaten tam da bu sayede eşi benzeri olmayan eserlere imza atıyordu. Aslında sadece İNSANLARA karşı sabırsızdı. Ancak bunu kimse sormadığı için o da söylemedi.","Birim",[],["Freljord"],"Şampiyon"],"06FR035":["Yardıma Geldik","Bu tur bir dost birime +0|+3 verirsin. Hasar almışsa, bunun yerine +2|+3 verirsin.","","''Hiç korkmayasın, minik poro. Ben yanındayım!''\n- Braum","Büyü",[],["Freljord"],"YAYGIN"],"06FR034":["Acımasız Soğuk","En Güçlü düşmana Buz Tutturursun. Bu oyunda bir dost birimi Kuşattıysan, beni kopyalarsın.","","Anaakca öyle hızlı hareket ederdi ki Freljord'da zaman yavaşlardı sanki. Onun katliamından sağ kalanların bedenleri donar, kalpleri atmayı bırakırdı.","Büyü",["TARİKATÇI"],["Freljord"],"YAYGIN"],"06FR018":["Darkin Mızrağı","Saldır: Destenin en üstündeki 2 dost birime +1|+1 kazandırırsın.\n8 mana harcayarak beni Anaakca olarak oynayabilirsin.","","''Savaş Anası, kışın soğuğu etkisini göstermeye başladı. Avarosalar karakollarının ötesine kaçtılar. Kuzeyimiz zaten deniz, yani tek seçeneğimiz doğu.''\n''Aman diyeyim, Savaş Anası. O tarafta hudut var ve onun da ötesinde fısıldayan yabanlar. O lanetli yere gitmektense ölmek daha iyi.''\n''Neyse ki halkımın kaderi ikinizin de elinde değil.''\n''Haklısınız, Savaş Anası. Ancak belki üçüncü bir seçeneğimiz vardır. Doğuya gitmeme izin verin. Karanlığa bir gözcü kaybetmek, tüm halkımızı kaybetmekten yeğdir.''\n- Savaş Anası Sejuani, generalleriyle istişare ederken","Ekipman",["DARKİN"],["Freljord"],"DESTANSI"],"06FR012":["Gözde Zanaatkâr","Çağrıldığımda, elinde bir Zaman ve Azim oluşur.","","''Annem bana Ornn'u anlatırdı, onun annesinin ona anlattığı gibi. Ve onun annesinin ona... Şimdi de ben size. Dikkatle dinleyin. Lafımı kesmeyin. Yıllar önce, kocaman, sıcak, hırçın bir denizde...''","Birim",[],["Freljord"],"YAYGIN"],"06FR005":["Ornn'un Ocağı","Çağrıldığımda ya da Tur Başı: Elinde Geçici bir Zaman ve Azim oluşur.","","Ocak-Yuva'nın demirhanesinde tek başına, sadece aşağıda yavaş yavaş akan erimiş nehrin ve örse vuran çekicin sesi eşliğinde durmak... çok hoşuna gitmişti.","Yer",[],["Freljord"],"ENDER"],"06FR040":["Kabilelerin Bekçisi","Çağrıldığımda, bu oyunda çağırdığın her farklı alt tip için dost birimlere +1|+1 kazandırırsın.","","''...biy de KÜÇÜCÜK canavaycıkların heeeeepsini koyuyup kollayan KOCUMAN bir canavay vaymış...''\n- Küçük Ingvar","Birim",[],["Freljord"],"DESTANSI"],"06FR020":["Tuz Buz","HER ŞEYE 1 hasar verirsin ya da bir birimin ekipmanını yok edersin.","","Soğuğun karşısında hiç kimse ve hiçbir şey duramaz.","Büyü",["ELEMENTAL"],["Freljord"],"ENDER"],"06FR027":["Yünlü Salyanmut","Potansiyel - 8: Yenilenme.","","Trollerin pek zeki varlıklar oldukları söylenemez ancak şaşırtıcı derecede yaratıcı oldukları kesin.","Birim",[],["Freljord"],"ENDER"],"06FR032":["Ocakkanlılar'ın Hediyesi","Nexus'unu 4 iyileştirirsin ve destendeki tüm dost birimlere ve ekipmanlara +1|+1 kazandırırsın. Bunlardan bir tanesini çekersin.","","''Gel, ateşin başında biraz ısın.''\n- Ocakkanlı Tamirci","Büyü",[],["Freljord"],"DESTANSI"],"06FR022":["Harlı Ateş","Bir dost birimi İşlersin ve TÜM birimlere 1 hasar verirsin. Sonra bunu tekrar yaparsın.","","''İrade tavında dövülür.''\n- Ornn","Büyü",["ELEMENTAL"],["Freljord"],"ENDER"],"06FR021":["İnatçı Poro","Potansiyel - 3: Aban, Yenilenme ve Dayanıklı.","","''Hadi ya, ilacını içmen lazım! İçmezsen iyileşemezsin bak!''\n- Küçük Ingvar","Birim",["PORO"],["Freljord"],"YAYGIN"],"06FR023":["Dövülmüş Dev","İlk kez Kuşandığımda, elinde bedeli 4 olan bir kopyam oluşur. Ona ekipmanın niteliklerini kazandırırsın.","","Ornn itiraf etmek istemese de devlerden epey memnundu. Devler, kendilerine verilen görevi layığıyla yerine getiriyordu. Ve en güzeli, hiç konuşmuyordu.","Birim",[],["Freljord"],"DESTANSI"],"06FR008":["Ocakkanlı Tamirci","Oyna: Bir dost birimi iki kez İşlersin ve hem onu hem Nexus'unu 3 iyileştirirsin.","","Ornn dünyayı terk ettiğinde, Ocakkanlılar'ın hepsi teker teker ortadan kaybolmuştu. Aradan geçen uzun yıllardan sonra, geride isimlerini hatırlayan kimse kalmamıştı. Fakat son zamanlarda, Ornn'un hikâyelerinin yeniden su üstüne çıkmasıyla Ocakkanlılar'ın da geri dönmeye başlandığı söyleniyor.","Birim",[],["Freljord"],"YAYGIN"],"06FR009":["Hünerli Silah Uzmanı","Oyna: Bir dost birimi İşlersin.","","Fiske yanına bir çırak almaya karar verdiğinde azimli, zanaatını ciddiye alan, güçlü ve becerikli birini hayal etmişti. Kindra bu sıfatların hiçbirini taşımıyordu. Gün içinde hayallere dalıp dalıp gidiyordu. Çalışmak değil oyun oynamak istiyordu. Sürekli o küçük kaplumbağasıyla ilgileniyordu. Ama... öğreniyordu. Önemli olan da buydu.","Birim",[],["Freljord"],"YAYGIN"],"06FR024":["Kemik Sopa","","","''Çat!''\n- Kabilesiz Tarkaz","Ekipman",[],["Freljord"],"YAYGIN"],"06FR017":["Donukvadili Tarikatçı","Kuşanmış dost birimlerin Aban alır.","","Kışın Pençesi kabilesindekiler haklıydı. Avarosalar bir süredir FAZLA merhametli davranıyorlardı. Yeni bir lider gerekiyordu. Freljord'u barışı sağlayarak değil, her yere hükmederek birleştirecek bir lider. ","Birim",["TARİKATÇI"],["Freljord"],"ENDER"],"06FR041":["Kışın Dokunuşu","Boş bir mana taşı alırsın. Aydınlanmış: Bedelim 1 olur. 1 kart çekersin.","","Elindeki mücevherin her yüzü tuhaf rünlerle dolup taşıyor. Ürkütücü bir parıltıyla rünlerin ışıkları cevherden dışarıya çıkıyor ve döne döne kolunu soğuk bir sarmalla kaplıyor. Ancak kolundaki soğuk üşümene sebep olmuyor, aksine onun özüyle efsunlanmışçasına canlandığını hissediyorsun. ","Büyü",["ELEMENTAL"],["Freljord"],"DESTANSI"],"06FR036":["Yırtıcı Şamanizm","Boş bir mana taşı alırsın.\nBir Yabanıl Şaman çağırırsın.","","''Ruhlar ve yıldız... bizi tekrar kavuşturdu.''\n- Hepgörür Hyara","Büyü",[],["Freljord"],"DESTANSI"],"06BC015":["Norra","Nexus Vuruşu: Destenin en üstündeki 4 kart arasına 1 tane Gizemli Geçit koyarsın.","6+ oluşturulmuş dost birim çağırdığında.","Norra, evini bir an olsun aklından çıkarmadan hızla çalışıyordu. Geçit işi ziyadesiyle çetrefilli bir işti ve o daha günün ilk çayını bile içmemişti. Ama Norra zorlu bulmacaları severdi, özellikle de bulmacanın cevabı zamanın ve mekânın arasında sıkışmış bu cep evrenlerden kurtulmasını sağlayacaksa. Canından çok sevdiği kedisini düşünerek daha hızlı çalışmaya koyuldu. Acaba kedisi korkuyor muydu? Akşam yemeğinde ne yiyecekti?","Birim",["YORDLE"],["Bandle Şehri"],"Şampiyon"],"06BC043":["Poro Masalları","Elinde bedeli 1 olan rasgele 3 Poro oluşur.","","''ŞONYA DA PORO DEMİŞ Kİ 'PİŞŞT BEN DE KUYABİYE İSTİYOYUM' DEMİŞ O YÜZDEN BÜTÜÜÜÜÜM POROLAR PORO SALONUNDA TOPLANMIŞLAY ÇÜMKÜ POROLARIN BİİİSSÜRÜ DERTLERİ VAYMIŞ ÜZGÜNMÜŞLER ÇÜMKÜ MESELA KUYABİYELEYİ YOKMUŞ Bİ DE ÖBÜRSÜ POROLAR KAYIPMIŞ Bİ DE...''\n- Küçük Ingvar","Büyü",[],["Bandle Şehri"],"YAYGIN"],"06BC051":["Muzır Topçu","Oyna: Bir birime Güç değerim kadar hasar verirsin.","","''HOP! ARANIZDA POTASYUMA İHTİYACI OLAN VAR MI?''\n- Muzeyyen, ''Kaza'' gerçekleşmeden hemen önce ","Birim",["YORDLE"],["Bandle Şehri"],"ENDER"],"06BC047":["Paylaştıkça Çoğalır","İlavesi olan bir dost birime bu tur ilavesinin niteliklerini ve tesirlerini verirsin ve ilaveyi başka bir dost birime taşırsın.","","Bir çobanın savaş alanında hiçbir yerinin olmadığını düşünebilirsiniz ancak yeri geldiğinde becerileri büyük fayda sağlayabilir. Nihayetinde tüm savaşçılar, güdülmeye muhtaç koyunlara benzer.","Büyü",["SİLAH ÜSTADI"],["Targon","Bandle Şehri"],"ENDER"],"06BC019":["Çaycı","Çağrıldığımda, destenin en üstündeki 4 kart arasına 1 tane Gizemli Geçit koyarsın.","","Ashane, Âlemin Ucu'nda kaybolmadan önce herkesçe tanınan bir çaycıydı. Bir gün yeni tatlar bulmaya çalışırken karışmaması gereken iki yaprağın bir araya gelmesi, onun derin bir uykuya dalmasına sebep oldu. Tuhaf varlıklarla ve acayip yapılarla dolu, sanki sonsuz bir ufka doğru uzanıyormuş gibi görünen diyarlarla ilgili acayip rüyalar gördü. Ancak uyandığında, bunların rüya olmadığını fark etti.","Birim",["PERİ"],["Bandle Şehri"],"YAYGIN"],"06BC029":["Darkin Asası","Vuruş: 1 büyü manası doldurursun.\n8 mana harcayarak beni Baalkux olarak oynayabilirsin.","","Bandle Ormanı'nın darkin silahı saklamak için ideal bir yer olduğunu düşünmüşlerdi. Ormanda yön bulmak zaten imkânsızdı ve yordle'lar böyle bir beladan uzak durmaları gerektiğini bilecek kadar akıllı varlıklardı. Ancak Targon'lular, böyle tuhaf bir büyünün kudretini ve yerel bitki örtüsü üzerinde yaratabileceği tahribatı hesaba katmamıştı.","Ekipman",["DARKİN"],["Bandle Şehri"],"DESTANSI"],"06BC038":["Ani Güç Patlaması","Bu oyunda bir dost birimi Kuşattığında, bedelim 2 azalır.\nBir dost birimi bu tur 4|4 niteliklerine çıkarırsın.","","''İçimizde öyle çok güç var ki.''\n- Varus","Büyü",["TARİKATÇI"],["Bandle Şehri"],"ENDER"],"06BC017":["Geçit Cümbüşü","Destenin en üstündeki 4 kart arasına 2 tane Gizemli Geçit koyarsın.\n1 kart çekersin.","","''Alçak Yollar'ı daha sık kullanmaya başlamam gerek. Ama her seferinde dalgınlıktan kafamı çarpıyorum.''\n- Norra","Büyü",[],["Bandle Şehri"],"ENDER"],"06BC020":["Origami Dilimleyici","Bu tur etkinleşen her tuzağın ya da lütfun için bana +1|+0 verirsin.","","Sihirli kâğıt katlama sanatı ortaya bazen olağanüstü sonuçlar çıkarabilir. Bu sanatta, yeni bir esere imza atma niyeti kadar, eserin şekillendirilme arzusu da önemlidir.","Ekipman",[],["Bandle Şehri"],"ENDER"],"06BC028":["Çiçeklenen Tarikatçı","Bu oyunda bir dost birimi Kuşattığında, bana Sıyrılgan kazandırırsın.","","İnsan, bitki ya da hayvan... Darkinlerin yozlaştırıcı etkisinin mahvedemeyeceği hiçbir şey yok.","Birim",["TARİKATÇI"],["Bandle Şehri"],"YAYGIN"],"06BC021":["Toplama Hurda","Son Nefes: Destenin en üstündeki 4 kart arasına 1 tane Gizemli Geçit koyarsın.","","Doğalı henüz bir gün olmuştu ama Norra'nın şefkatle Muhteşem adını verdiği varlık, ona büyük bir şevkle asistanlık ediyordu. Ancak kendisinden ''çöp'' değil de ''hurda'' olarak bahsedilmesi konusunda ısrarcıydı. Öbür türlüsü hakaret sayılırdı çünkü.","Birim",["PERİ"],["Bandle Şehri"],"YAYGIN"],"06BC042":["Meraklı Fırıldak","Dost bir takipçi başka bir takipçiye dönüştüğünde, onun birebir kopyasına dönüşürüm.","","Bukalemun, şukalemun, okalemun.","Birim",[],["Bandle Şehri"],"ENDER"],"06BC023":["Bön Levhası","Hızlı veya Yavaş bir büyüyü ele geri gönderirsin ya da bir birimin ekipmanını yok edersin. 1 kart çekersin.","","''Ay başıma gelenler! Bu taraftan mıydı, o taraftan mı... yoksa şu taraftan mı? Bir türlü öğrenemedim şunu!''\n- Norra","Büyü",[],["Bandle Şehri"],"ENDER"],"06BC041":["Antik'in Zımbırtı Dükkânı","Atıldığımda beni tekrar çağırırsın. Bir Meka Yordle çağırdığında, ona rasgele bir tesir kazandırırsın.","","Küçük, büyük, cansız ya da başka türlü, hiç fark etmez. Aradığınız her çeşit zamazingo Antik'in Zımbırtı Dükkânı'nda! Ancak Antik'e aradığınız şeyin nerede olduğunu hiç boşuna sormayın zira kendisi bir şeyleri kategorilere ayırmanın gereksiz olduğunu düşünüyor.","Yer",[],["Bandle Şehri"],"ENDER"],"06BC011":["Sihirli Yolculuk","Destenin en üstündeki 4 kart arasına 1 tane Gizemli Geçit koyarsın ve destenin en üstündeki karta 1 tane Tını koyarsın.","","Farklı farklı âlemlerde diyar diyar gezinen Bard, büyük bir çatışmanın yaklaştığını hissediyor. Yaşamın bütün şarkılarını susturabilecek bir çatışma.","Büyü",[],["Bandle Şehri"],"YAYGIN"],"06BC032":["Derleme Koleksiyon","Her dost birim için, kendi destenin en üstündeki 10 kart arasına 1 tane Gizemli Geçit ile 3 tane Tını ve rakibin destesine 1 tane Kör Edici Bomba Tuzağı ile 3 tane Zehirli Pofkep Mantarı koyarsın.","","''Yer gök boyut geçidi.''\n- Norra","Büyü",[],["Bandle Şehri"],"DESTANSI"],"06BC024":["Âlemin Bakıcısı","Her tur, bir tuzağın ya da lütfun ilk defa etkinleştiğinde, bu tur dost birimler +1|+1 ve Ağır Darbe alır.","","Gaspar, Âlemin Ucu'na ulaşan ilk yordle'dı. Uzun yıllar boyunca, hiçbir yere çıkmayan dolambaçlı yollarda ve geçitlerde bir başına gezindi durdu. Sonraları, aynı şeylerin kimsenin başına gelmesini istemediğini fark etti. Bu yüzden artık evine dönmeye çalışan diğer kayıp gezginlere yardım ediyor.","Birim",["PERİ"],["Bandle Şehri"],"ENDER"],"06BC033":["Meka Ezici","Oynamak için 1 kart atarsın.","","''İşte! Bu boks eldivenini batmış bir geminin kalıntıları arasından çekip aldım. Yayları, Zaun dedikleri şehrin derinliklerinde buldum ve gerekli metali Demacia ocaklarından elde ettim! Bu, dünyanın bize sunduğu nimetlerin bir ürünü!''\n- Muhteşem Paparo","Ekipman",[],["Bandle Şehri"],"YAYGIN"],"06BC016":["Yaşayan Kütüphane","Çağrıldığımda, bu tur bir tuzağın ya da lütfun etkinleştiyse 1 kart çekersin.","","Sonsuz bilgiye sahip olmak görevi olduğundan olsa gerek, Âlemin Ucu'ndan geçen seyyahlardan koca koca kitaplar topluyor. Ne yazık ki edindiği her yeni bilgi kibrine kibir katıyor.","Birim",["PERİ"],["Bandle Şehri"],"YAYGIN"],"06IO044":["Huzurlu Gök Ozanı","Çağrıldığımda, destendeki büyülerin bedeli yarıya iner. Sayı üste yuvarlanır.","","''Kimileri meditasyon yoluyla huzura varır, kimileriyse öz farkındalık için bilginin peşinden gider. Ruhunun dengesini fikir ve yaratıcılıkla kuranlar, diğerlerinin de huzuru bulabilmesini sağlayabilir.''\n- Karma","Birim",[],["Ionia"],"DESTANSI"],"06IO013":["Wuju Stili","Bir dost birime bu tur +2|+0 verirsin.\nElinde bir Meditasyon oluşur.","","''Pek çok kesikten biri.''\n- Master Yi","Büyü",[],["Ionia"],"ENDER"],"06IO023":["Darkin Yelpazesi","Saldır: Saldıran bir Ejder Yavrusu çağırırsın.\n9 mana harcayarak beni Gedikgezer Praa olarak oynayabilirsin.","","''Dünyalar arasındaki köprüde uzun zamandır suskun bir öfkeyle dolup taşan bir gölge seziyorum. Onu kovalarsam karanlığa sürükleneceğimi çok iyi biliyorum ancak bu varlığın öfkesi son zamanlarda çok daha güçlendi ve yoğunlaştı. Korkarım ki Ruhlar Âlemi'nden yaratıklar pek yakında bu varlığın peşine düşecek.''\n- Shen","Ekipman",["DARKİN"],["Ionia"],"DESTANSI"],"06IO029":["Wuju Ruhu","Akış: Bedelim 2 azalır.\nÇağrıldığımda, bir büyü çekersin.","","''Doran Usta'ya göre Wuju Ruhu'nun her gözü, kişinin mevcudiyetine dair eşsiz bir içgörü yansıtırmış. Fakat ben ne kadar çabalarsam çabalayayım, başlığımdaki mercekler yeşilin farklı tonlarından başka bir şey yansıtmıyor. Neyi yanlış yapıyorum acaba?''\n- Doran'ın Öğrencisi Lui","Birim",[],["Ionia"],"YAYGIN"],"06IO037":["Kara Alev","Oyna: Bir dost birimi Zapt Edersin. Her tur ilk defa saldırdığında, bu birimin saldıran Hayali bir kopyasını çağırırsın.","","''Yaşam dediğin varoluşun gölgesinden başka nedir ki? Karanlığa kucak aç ve sonsuza dek yaşa.''\n- Zed","Yer",[],["Ionia"],"DESTANSI"],"06IO031":["Ruh Kılıcı","Akış: Bedelim 2 azalır.","","''Kılıç ve beden.''\n- Master Yi","Ekipman",[],["Ionia"],"YAYGIN"],"06IO014":["Vastaya Öğrenci","Nexus Vuruşu: Beni Geri Gönderirsin ve Shimon Rüzgârı kartına dönüştürürsün.","","Düşmanlar tapınağa doğru akın akın ilerlerken Ting sırıtıyordu. Kendini gösterme fırsatı ayağına gelmişti! Önce Wukong, sonra Yi... İkisi de yeteneklerini göz ardı etmişti. Diğerleri ''ustalarını'' bulmak için koşuşup dururken o hazırdı. O, Shimon Rüzgârı'ydı. ","Birim",[],["Ionia"],"DESTANSI"],"06IO008":["Master Yi","Tur Başı: Elindeki bir büyünün bedeli 1 azalır ve Akış: Her yerdeki tüm dost Master Yi kartlarına +2|+0 kazandırırsın.","Dost Master Yi'ler 12+ hasar verdiğinde.","Master Yi'nin aklı o darkin silahındaydı. Keşfedildiğinden beri içinde kötü bir şeyler olacağına dair bir his vardı. Öğrencilerinden bazıları silahla yakından ilgileniyordu, biraz fazla yakından. O da kıvrık kılıçları tapınağın derinliklerinde koruma altına aldı. Biraz çabalayarak bu düşünceleri zihninden atmayı başardı ve meditasyonuna devam etti. Wuju öğretilerini aktarmaktan önemli hiçbir şey yoktu ve Jun büyük umut vaat ediyordu.","Birim",[],["Ionia"],"Şampiyon"],"06IO040":["İkiz Rüzgâr Tekniği","Bir takipçi seçersin. Seçtiğin takipçinin birebir Hayali bir kopyasını çağırırsın. Takipçi bir düşmansa onu Sersemletirsin.","","Ionia'lılara göre rüzgâr en dengesiz element olmasına karşın dizginlenemez değildir. ","Büyü",[],["Ionia"],"ENDER"],"06IO011":["Mucize Jun","İlk kez Kuşandığımda, bana bu tur Bariyer ve Can Çalma verirsin.","","Yi'nin işaretiyle Jun ardı ardına, ancak Yi'nin başarabileceği kadar isabetli ataklar yapmaya başladı. Yi ataklardan ustaca kurtulmayı başardı tabii, ardından kızın önünde gururlu bir gülümsemeyle eğildi.","Birim",[],["Ionia"],"ENDER"],"06IO015":["Şahit","Akış: Bedelim 2 azalır.\nOyna: Bir düşmanı Sersemletirsin.","","Peki bu tuhaf ve ürkünç gösteride onun rolü nedir? Ah, o bir izleyiciden de fazlası, o bir gözlemci. Her şey onun merceğinden geçip hakikat ve güzellikle sınanmalı. O her şeye şahit olmalı, her şeye!","Birim",[],["Ionia"],"YAYGIN"],"06IO030":["Puslubayır","Çağrıldığımda bir ekipman çekersin.\nHer tur ekipmanı olmayan bir dost birim ilk kez Kuşandığında, 2 büyü manası doldurursun.","","''Puslubayır kutsal bir mekândır. Bu kılıçlar asırlardır burada duruyor... Ve ben, kabzasında bir şiirle buraya bırakılan tüm kılıçların, kayıp savaşçıların ruhunu çağıracağına ve bu ruhların kılıca lütuflarını bahşedeceğine inanıyorum.''\n- Doran'ın Öğrencisi, el yazması parşömenden","Yer",[],["Ionia"],"ENDER"],"06IO034":["Kritik Seçim","Bu oyunda bir dost birimi Kuşattıysan, bedelim 1 azalır.\nBir dost birime bu tur +2|+0 ya da +0|+2 verirsin.","","Jun, yerde yatan cansız bedenler arasında gezinirken yanaklarından öfke dolu gözyaşları boşanıyordu. Onları yüzüstü bırakmıştı. Ustasını yüzüstü bırakmıştı. Artık geriye tek bir seçenek kalmıştı...","Büyü",["TARİKATÇI"],["Ionia"],"ENDER"],"06IO028":["Mest Edici Yem","Bir dost birime bu tur Rakipçeker verirsin. Bu birim Kuşanmışsa 1 kart çekersin.","","Yemek güzel olduğunda herkes ''açım'' der.","Büyü",["SİLAH ÜSTADI"],["Ionia","Noxus"],"ENDER"],"06IO025":["Gölgekılıç Tutkunu","Bu oyunda bir dost birimi Kuşattığında, elinde bir Gölge Canavar oluşur.","","Karanlıkta onu gördü. Gölgeleri delip geçecek bir silah. İşte tam o anda, onu çağıran sesi duydu. Uzaktan geliyordu ancak kudretliydi. Kayn'e ulaşıncaya dek sesin peşine takıldı, sözlerinin gerçekliği ona rehberlik etti.","Birim",["TARİKATÇI"],["Ionia"],"YAYGIN"],"06IO039":["Navori Uzunkuyruk","Oyna: Bir Navori Eşkıyası çağırırsın ya da diğer dost birimlere bu tur +1|+1 verirsin.","","Uzunkuyruk'un Eşkıya'yla dostluğu terk edilmiş bir kamp ateşinin közlerini paylaştıkları bir kış akşamına dayanıyor. İkili o akşamdan sonra daha bir hafta geçmeden ortak bir muziplik anlayışına sahip olduklarını ve ışıl ışıl altınlara ilgi duyduklarını fark etmişti.","Birim",[],["Ionia"],"YAYGIN"],"06IO032":["Değersiz Ruh","Akış: Bedelim 2 azalır.\nBir birimi ya da Yer kartını Geri Gönderirsin. Üstünde bir ilave varsa, önce onu yok edersin.","","''Elindeki gücü hak etmiyorsun.''\n- Rhaast","Büyü",[],["Ionia"],"ENDER"],"06IO001":["Doran'ın Öğrencisi","Çağrıldığımda, elinde bir Hazırlık oluşur.","","''Bu kutsal sanatı devam ettirmek için öğrenmem gereken her şeyi öğrendim. Tıpkı Doran gibi. Tıpkı onun ustası ve onun ustası gibi... Ruhları çekicime rehberlik etsin.''\n- Doran'ın Öğrencisi, el yazması parşömenden","Birim",[],["Ionia"],"YAYGIN"],"06IO016":["Ejderçağıran","Tur Başı: Akış: Bir Arşejderi çağırırsın ve ona Hayali kazandırırsın.","","''Su arzuların aynasıdır. Söyle bakalım, gezgin... Neler görüyorsun?''","Birim",[],["Ionia"],"DESTANSI"],"06PZ034":["Hextech Yok Edici","Bir birime 6 hasar verirsin. Ölecek kadar hasar aldıysa, bunun yerine Kökünü Kazırsın.","","Bazı yaratıkları öldürmek yetmez.","Büyü",[],["Piltover ve Zaun"],"ENDER"],"06PZ006":["Bis","Elinde bedeli 2 olan rasgele yeni bir büyü oluşur. Büyünün bedeli 2 azalır ve Geçici kazanır.","","Akordunu da yaptıysan seni kimse tutamaz.","Büyü",[],["Piltover ve Zaun"],"ENDER"],"06PZ021":["Seraphine","Çağrıldığımda, elinde bedeli 2 olan rasgele yeni bir büyü oluşur.","9+ yeni büyü oynadığında.","Seraphine'le babası, Seraphine'in altşehri ''gizli gizli'' ziyaret etmesi ya da sahnesinde ufak tefek değişiklikler yapması hakkında pek konuşmazdı. Babasının Zaun'un en paspal müzik ikilisine katılmasına müsaade etmeyeceğinden emindi. Gelgelelim babası bir gece ikilinin broşürünü Seraphine'in kapısının altından uzattı. Seraphine sadece gülümsedi ve işe koyuldu.","Birim",[],["Piltover ve Zaun"],"Şampiyon"],"06PZ040":["Leş Bar","Çağrıldığımda bir Leş Barın Sahibi çağırırsın.\nYeni kartlarının bedeli 1 azalır.","","Barın sahibi, son bardağı da kuruladıktan sonra mekânına şöyle bir göz gezdirdi. İşte tam burası, evi evi güzel evi, sayısız yabancıyla dost oluşuna tanıklık etmişti. Duvarları, çılgın gecelerin anısına çizimler ve çentiklerle doluydu. Kendi kendine gülümsedi. Mükemmel bir yer olmasa da eviydi işte.","Yer",[],["Piltover ve Zaun"],"DESTANSI"],"06PZ008":["Darkin Arpı","8 mana harcayarak beni Styraatu olarak oynayabilirsin.","","Targon'lular darkin silahlarını nereye saklayacaklarını düşünürken içlerinden biri daha sonra Zaun olarak anılacak toprakları önerdi. Mağaralarla dolu, dolambaçlı geçitlerin derin duvarları bu iş için biçilmiş kaftandı. Buralara insanların ulaşması imkânsızdı. Fakat hiç kimse çireğenleri hesaba katmamıştı.","Ekipman",["DARKİN"],["Piltover ve Zaun"],"DESTANSI"],"06PZ018":["Yüksek Perde","Bir birime 2 hasar verirsin. Bu oyunda 6+ başka yeni büyü oynadıysan, başka bir birime 1 hasar verirsin.","","Ruhun gıdası.","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"06PZ014":["Fan Kulübü Başkanı","Oyna: Bedeli 5 olan bir büyü Cisimlenir ve bedeli 2 olur.","","''Önemli olan sesinin değil, kalbinin gücü!''\n- Fan Kulübü Başkanı","Birim",[],["Piltover ve Zaun"],"ENDER"],"06PZ030":["Yaratıcı Planlar","Saldır: Elinde bedeli 2 olan yeni bir büyü oluşur ve Geçici kazanır.","","''Olamaz, yağmur sesi mi o?''\n''Yok artık, baba. Baksana, gökyüzünde tek bir bulut bile yok.''\n''Çabuk, çizimlerin üstünü ört! BEYİN fırtınası başladı!''\n''Ya babaaa!''\n- Seraphine ve babası","Ekipman",[],["Piltover ve Zaun"],"ENDER"],"06PZ046":["Formül","2 kart çekersin. Büyü mananı tekrar doldurursun.","","''Aslında büyü, henüz keşfetmediğimiz bilimsel bir hakikattir.''\n- Jayce","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"06PZ007":["İhtiraslı Tarikatçı","Bu oyunda bir dost birimi Kuşattığında, elinde bedeli 2 olan yeni bir büyü oluşur ve bu tur bedeli 0 olur.","","''Bilim uğuruna fedakârlıkta bulunmaktan hiçbir zaman kaçınmadım. Kendimi ne tür bir tehlikenin içine atmış olursam olayım, karşılığında kazandığım bitmek bilmeyen güç bana her seferinde doğru şeyi yaptığımı hatırlattı.''","Birim",["TARİKATÇI"],["Piltover ve Zaun"],"YAYGIN"],"06PZ041":["Kurnaz Kedicik","Çağrıldığımda, eğer oluşturulmuşsam 1 kart çekersin ve bana +2|+1 kazandırırsın.","","Kediler gündüzleri uyumadıkları, geceleri orayı burayı tırmalamadıkları ya da sağı solu devirmedikleri zamanlarda her daim bir yaramazlık peşindedir.","Birim",["KEDİ"],["Piltover ve Zaun"],"YAYGIN"],"06PZ036":["Zaun'un Divası","Oyna: Tüm düşmanlara 1 hasar verirsin. Bu oyunda 6+ yeni büyü oynadıysan, bunun yerine 3 hasar verirsin.","","''Zaun! Herkes bağırmaya hazır mı? Burayı bir kez daha yerin dibine batıralım mı?''\n- Zaun'un Divası","Birim",[],["Piltover ve Zaun"],"ENDER"],"06PZ010":["Ses Teknisyeni","Vuruş: Elinde bedeli 2 olan rasgele yeni bir büyü oluşur.","","Bir zamanlar Zaun'u geride bırakıp kalbindeki şarkıyla dünyayı dolaşmanın hayalini kurardı. Şimdiyse tüm dünyası odasında mışıl mışıl uyuyor ve yarının getireceği şarkıları umutla bekliyor.","Birim",[],["Piltover ve Zaun"],"DESTANSI"],"06PZ022":["Davul Solosu","2 kart çekersin.\nAkış: Çektiğin kartların bedeli 1 azalır.","","Müzikte en önemli şey zamanlamadır. Ama arada bir ''koyuver gitsin'' demeyi bilmek gerekir.","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"06PZ029":["Seyircinin Gözbebeği","Bir dost birime bu tur +2|+0 ve İlk Saldırı verirsin.\nAkış: Elinde bedeli 2 olan yeni bir büyü oluşur.","","''Sesini duyamıyorum, Zaun!''\n- Seraphine","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"06PZ020":["Hexteknisyen Palo","Nexus Vuruşu: Elindeki en pahalı büyünün bedeli 1 azalır.","","Hiçbir projede veya şarkıda adı geçmese de bilenler bilirdi: Palo tüm operasyonun beyniydi.","Birim",[],["Piltover ve Zaun"],"DESTANSI"],"06PZ009":["Dehşet Akoru","Akış: Bedelim 2 azalır.\nTüm düşmanlara 1 hasar verirsin.","","Zaun'un kuru gürültüsünde kendini duyurmak için eşsiz bir ses gerekir fakat Diva için bu iş çocuk oyuncağı.","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"06PZ037":["Bozuk Akort","Bir birime 1 hasar verirsin. Bu oyunda bir dost birimi Kuşattıysan, beni aynı hedefe kopyalarsın.","","Akordun bozuksa kendini kakofoniye bırak.","Büyü",["TARİKATÇI"],["Piltover ve Zaun"],"ENDER"],"06PZ019":["Zaun'lu Koruma","Tur Başı: Akış: 2 büyü manası doldurursun.","","Ona kalsa HİÇ KİMSE içeri giremezdi.","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"06PZ033":["Delmelendirici Sürüm 1.0","Büyülerin ve yeteneklerin fazladan 1 hasar verir.","","''Konum: 3. Sektör, 19B Yolu\nTür: Yasadışı Ateşli Silah\nNotlar: Aydınkuyu Operasyonu'nda el konuldu. Tehlikeli bir silah. Taşınırken çok dikkatli olunmalı.''\n- Bir Piltover Muhafızı'nın saha raporundan","Ekipman",[],["Piltover ve Zaun"],"YAYGIN"],"06BW029":["Piltover'lı Avare","Çağrıldığımda, Doğaçlama yaparım.","","Pesh, Jax'le bir liman kavgası sırasında tanıştı. İkisi için tam zamanında kaçmak, bir araya gelmekten çok daha kolaydı. Ancak Pesh o günden beri Jax'i gemisiyle taşıyor çünkü Jax'in bulunduğu ortamda çok fazla şey kırılıyor. Ve Pesh'in kaliteli hurdadan daha çok sevdiği tek şey kırılan eşyaları tamir etmek.","Birim",["SİLAH ÜSTADI"],["Bilgewater","Piltover ve Zaun"],"YAYGIN"],"06BW034":["Ağır Metal","Bir birimin ekipmanını yok edersin ve ona 2 hasar verirsin.","","''BAR KAVGASINDA ÇAPA FIRLATMAK DA NE DEMEK? SİZ MANYAK MISINIZ?''\n- Bilgewater'lı Barmen","Büyü",[],["Bilgewater"],"ENDER"],"06BW027":["Bütünün Parçaları","Oynamak için 1 kart atarsın. 2 kart çekersin ve bir ekipmanı attıysan, bir Icathia Serabı çağırırsın.","","Jax'in ekibi, bütünün parçalarının toplamından çok daha fazlası olabileceğini kanıtlar nitelikte. Pesh'inse farklı bir felsefesi var: Bazen, parçalar da kendi başına gayet süper olabilir.","Büyü",["SİLAH ÜSTADI"],["Bilgewater","Piltover ve Zaun"],"ENDER"],"06BW039":["Durmayan Dalga","Bu oyunda bir dost birimi Kuşattığında, bedelim 2 azalır.\n2 kart çekersin ve onlara Geçici kazandırırsın.","","Ibaaros'un yaşlı kemikleri ağır ağır hareket etse de önünde kabaran sular akıl almaz bir hızla ilerliyordu.","Büyü",["TARİKATÇI"],["Bilgewater"],"ENDER"],"06BW026":["Buhru Tarikatçı","Kuşanmış dost birimler saldırdığında, rakibin Nexus'una 1 hasar verirsin.","","Gücün nereden geldiğinin bir önemi yoktu. Tanrıçası bunu hiç umursamıyordu. Önemli olan tek şey, öldürdüğü canavarların ona getireceği şöhretti.","Birim",["TARİKATÇI"],["Bilgewater"],"YAYGIN"],"06BW014":["Darkin Zıpkını","Saldır: Sonraki Tur Başında 1 kart çekersin ve ona Geçici kazandırırsın.\n9 mana harcayarak beni Ibaaros olarak oynayabilirsin.","","''Daray boğazında habis fısıldar sular, aldatır rüzgârlar\nDerler ki geçme sakın yakınından\nKorkar denizde yaşayanlar, göklerde uçanlar\nOrada, derinliklerinde yatan karanlıktan.''\n- Bilgewater şiiri","Ekipman",["DARKİN"],["Bilgewater"],"DESTANSI"],"06BW004":["Ruh Sınavı","Bir düşmana bu tur Kırılganlık verirsin. Bu tur ölürse, rakibin Nexus'una 1 hasar verirsin.","","''Karşı duramayan korkaktır.''\n- Illaoi","Büyü",[],["Bilgewater"],"ENDER"],"06BW044":["Cingöz Semender","Nexus Vuruşu: 1 kart çekersin ve ona Geçici kazandırırsın.","","''Bu hayvanlar kadar adisini görmedim. Hırsızlık yapmaya da bayılıyorlar ha. Neyse, en azından bir şey arakladıklarında onları bulmak kolay oluyor.''","Birim",["SÜRÜNGEN"],["Bilgewater"],"YAYGIN"],"06BW047":["Muzip Marai","Bir büyü oynadığında bir Barut Fıçısı çağırırsın.","","''Evet, Bibi biraz... dengesiz. Ama onun en sevdiğimiz yönü de bu zaten!''\n- Marai Koruyucu Ai'la","Birim",[],["Bilgewater"],"ENDER"],"06BW023":["Dişli Pala","Yağma: Bedelim 2 azalır.","","''Ee, ne demişler? Bilgewater'da hırgürü bitirmenin en hızlı yolu pala çekmektir.''\n''Silah çekmek daha iyi olmaz mı?''\n''Kes sesini, Baz.''\n- Baz ve Gav, acemi ödül avcıları","Ekipman",[],["Bilgewater"],"YAYGIN"],"06BW042":["Dolu Gemi","Bir birime 2 hasar verirsin. Sonraki Tur Başında verilen her hasar için 1 kart çekersin ve bu kartlara Geçici kazandırırsın.","","''Merak etme, patlamayı Rex halledecek. Ben de hazineyle ilgileneceğim. Rex'in payıyla da ben ilgilenirim, yine topa koyup havaya uçurmaya kalkmasın. Ortalık batmasın diye söylüyorum canım.''\n- Gemi Astsubayı","Büyü",[],["Bilgewater"],"DESTANSI"],"06BW040":["İlahın Gözü","Saldır: 2 Dokunaç Çıkarırsın.","","''Bakışlarının önünde dik dur!''\n- Illaoi","Ekipman",[],["Bilgewater"],"ENDER"],"06SH032":["Gömülü Cephane","Geri Sayım - 2: Elinde bir Kumların Hazinesi oluşur.","","''Ne diye her şeye dokunuyorsun?''\n''Neden? Bubi tuzağı olduğunu mu düşünüyorsun? Sence tepemizden pat diye kaya mı...''\n''İMDAAAAT!''\n- Mezar soyguncuları Argus ve Silvio","Yer",[],["Shurima"],"YAYGIN"],"06SH035":["Kan Sunağı","Bir birimi katlettiğinde, oynayacağın bir sonraki Darkin birimin bedeli 1 azalır.","","Sunak bir kez daha sarsıldı. Çevresindeki kumlar yavaş ve sabit bir ritimle titreşiyordu. Xolaani'nin takipçilerinin her biri aynı ritmi kalplerinin ta en derinlerinde hissediyordu. Tüm kasları, tüm düşünceleri, tüm anları... artık onun kontrolündeydi.","Yer",[],["Shurima"],"ENDER"],"06SH046":["Müridin Emaneti","Çağrıldığımda, elinde bir Harap Mürit oluşur. Beni yok ettiğinde, destenin en üstündeki 5 kart arasında bir Müridin Emaneti oluşur.","","''Ellerimiz çöle şekil verir!''\n- Harap Mürit","Yer",[],["Shurima"],"ENDER"],"06SH033":["Uğursuz Mezar","Öngörüde bulunursun. Bir birime bu tur ''Çifte hasar alırım ve ölecek kadar hasar alırsam beni öldürmek yerine Kökümü Kazırsın'' verirsin.","","''Yalnızca ahmaklar kontrol edemeyecekleri bir gücü arzular.''\n- Xerath","Büyü",[],["Shurima"],"ENDER"],"06SH028":["Hiçlik Kapısı","Bir dost birim çağırdığında ya da bir dost birim öldüğünde, onun faydalı tesirlerinin her birini destendeki 3 dost birime kazandırırsın.","","Kovan Elçisi elleriyle üstündeki devasa yapıya uzandı. ''BİR TAHT,'' diye haykırdı, ''BİR İMPARATORİÇEYE LAYIK.'' Tepesindeki Hiçlik kapısı hareketlenmeye başladı. Çok az kalmıştı.","Yer",[],["Shurima"],"DESTANSI"],"06SH005":["Terk Edilmiş Baccai","Oyna: Öngörüde bulunursun. Seçimin bir Darkin ya da ekipmansa, +1|+1 kazanırım.","","Elinde, arkadaşı Rhaast'ın Yükseliş töreninden önce hediye ettiği örgülü kemeri tutuyordu. Darkinin gücüne her ne kadar saygı duysa da sert kalbindeki kırgınlık geçmiyordu.","Birim",["TARİKATÇI"],["Shurima"],"YAYGIN"],"06SH056":["Haşla","TÜM takipçileri öldürürsün.","","Bazen güneş ışığına doğru gidersin, bazense o sana doğru gelir.","Büyü",[],["Shurima"],"ENDER"],"06SH040":["Pervasız Diriliş","Bu oyunda bir dost birimi Kuşattığında, bedelim 2 azalır. Ölmüş olan En Güçlü dost şampiyon dirilir.","","''Ölmeyeceksin. Ölmene asla izin vermem.''\n- Xolaani","Büyü",["TARİKATÇI"],["Shurima"],"DESTANSI"],"06SH021":["Saklı Dehşet","Oyna: Bir düşmana vururum.","","Saldırı devam ederken gittikçe genişleyen geçitten gittikçe büyüyen, gittikçe vahşileşen varlıklar dökülmeye başladı. Belveth şehri düşmüştü ancak feleğin cilvesi olacak ki ismi yaşamaya devam edecekti.","Birim",[],["Shurima"],"ENDER"],"06SH051":["Kaya Ayısı Çobanı","Başka bir dost birim çağırdığında, en yüksek Geri Sayım'a sahip Yer kartını 1 tur ilerletirsin.\nÇağrıldığımda, bir Uyuyan Kaya Ayısı çağırırsın.","","''Kayadupları, Sadira'yı kendilerinden biriymiş gibi görüyor. Şu küçük yaramaza bi' izin versem onlarla hemencicik kaçıverir, ruhum bile duymaz!''\n- Gözü Kara Göçebe Kadira","Birim",[],["Shurima"],"ENDER"],"06SH055":["Çöl Işığı Rahibesi","Tur Başı: Bana 4 hasar verirsin. Bir şampiyon çekersin ve ona +2|+2 kazandırırsın. Başlangıç destende 6+ farklı şampiyon varsa bunun yerine bir şampiyon çağırırsın.","","Kötülük etraflarını sararken yıkılmamış itikatlılar son takatlarıyla adaletin ışığını çağırmaya hazır. Bu, karanlık onları ele geçirmeden önce gerçekleşeceğine inandıkları umarsız bir kurtuluş dileği.","Birim",[],["Shurima"],"DESTANSI"],"06SH004":["Darkin Kandöken","Son Nefes: Taşıyıcım bir Darkin Köle değilse, bir Darkin Köle çağırırsın.\n6 mana harcayarak ve bir dost birimi öldürerek beni Xolaani olarak oynayabilirsin.","","Savaş gittikçe şiddetlenirken, çaresiz ve ağır yaralı haldeki Jun kafasının içinde fısıldayan seslere kulak verdi. Yaz yağmuru kadar yumuşak bu ses, ''Ölmeyeceksin,'' diyordu. ''Ölmene asla izin vermem.''","Ekipman",["DARKİN"],["Shurima"],"DESTANSI"],"06SH038":["Savrulan Kargı","Vuruş: Elinde bir Şanslı Keşif oluşur.","","''Neyi istiyorsan, acımadan kovala.''\n- Harabe Yağmacısı\n","Ekipman",[],["Shurima"],"YAYGIN"],"06DE048":["Kollayan Porsukayı","","","''Dostumuz olanlara hay hay, onların başımızın üstünde yeri var. Yalnız kalbinde yatan kötülükle bu diyarlara adım atanın vay haline zira onlar bu diyarın kudretli koruyucusunun öcüne maruz kalacak!''","Birim",["SEÇKİN"],["Demacia"],"YAYGIN"],"06DE024":["Tut!","Bir dost birime bu tur +1|+1 verirsin ya da onu bedeli 2 ya da daha az olan, elindeki bir ekipmanla Kuşatırsın.","","Henüz kimse yemek yemediyse bu hareket daha da çok can acıtıyor.","Büyü",["SİLAH ÜSTADI"],["Demacia","Freljord"],"ENDER"],"06DE025":["İyi Kalpli Çaylak","Çağrıldığımda, Kuşanmış dost birimlere bu tur Bariyer verirsin.","","''Şu çocuk bize âdeta yük oluyor. Bizimle ava gelmemesi gerektiğini defalarca kez söyledim. Çocuk ısrarla avladığımız o iğrenç yaratığın kendisinin 'kız kardeşi' olduğunu söylüyor. Onun bu denli saf olması açıkçası beni iğrendiriyor ama ona acımıyor değilim. Tabii ki de acıyorum. En azından bu av ona iyi bir ders olacak.''\n- Gelenekçi Kolcu Şövalye Sirius Rowill'in şahsi günlüğünden","Birim",[],["Demacia"],"ENDER"],"06DE033":["Sustur ve Bastır","Bir birimin ekipmanını yok edersin ve bu birim bir takipçiyse, onu Susturursun.","","''Kendin kaşındın.''\n- Sihir Avcısı Lideri Lord Eldred","Büyü",[],["Demacia"],"ENDER"],"06DE039":["Icathia'nın Haykırışı","Elindeki bedeli 2 ya da daha az olan 2 taneye kadar ekipmanla Kuşanmış 2 Icathia Serabı çağırırsın.","","Jax, yitip gitmiş soydaşlarıyla sırt sırta savaştığını görüyordu rüyalarında. Kâh kazanıyor kâh kaybediyorlardı ama her seferinde birlikteydiler.","Büyü",["SİLAH ÜSTADI"],["Demacia"],"ENDER"],"06DE011":["Darkin Kalkanı","5 mana harcayarak beni Joraal olarak oynayabilirsin.","","''Oğlum, beni dinle. Kalkana kimse dokunmamalı. Bu kalkan onu korumamız ve ona asla dokunmamamız koşuluyla uzun zaman önce hanemize bahşedildi. Bu sözü tutmak benim vazifem ve ben göçüp gittiğimde bu vazifeyi sen yerine getireceksin. İyi dinle. Kalkana bir daha tırmanmak yok. Ona asla ama asla dokunmamalısın.''\n''Ama anne, kalkandan gelen ses... beni çağırıyor. Öyle kederli bir ses ki.''\n''İşte dokunmaman için bir sebep daha, evladım.''\n- Leydi Fortis ve oğlu","Ekipman",["DARKİN"],["Demacia"],"DESTANSI"],"06DE021":["Vayne","Çağrıldığımda ya da Tur Başı: Elinde bir Takla oluşur. Zaten varsa, bedeli 1 azalır.","4 kere saldırdığını gördüğümde.","''Hedefimiz bir zamanlar insandı, yani bildiğiniz canavarlardan daha zeki. Yanlış bir hamleniz hepimizin ölümüne neden olabilir. Daima birbirinizi görebilecek şekilde konuşlanın, herhangi bir şeyden şüphelendiğinizde söyleyin ve en önemlisi de şunu sakın unutmayın...''","Birim",[],["Demacia"],"Şampiyon"],"06DE043":["Vefalı Koçköpeği","İlk defa Seçkin bir birim çağırdığında bana +2|+2 kazandırırsın.","","''Bir gümüşkanat kadar hızlı olmasa da o minik bacaklarıyla nasıl da patır patır koşturduğunu görseniz şaşkınlıktan küçükdilinizi yutarsınız.''\n- Bulutların Efendisi Cithria","Birim",["KÖPEK"],["Demacia"],"YAYGIN"],"06DE018":["Kazıkatar","Bu tur 2+ kere saldırdıysan, bedelim 5 azalır.\nBir dost birim bir düşmana vurur.","","''Okum arındırır.''\n- Vayne","Büyü",[],["Demacia"],"YAYGIN"],"06DE041":["Şampiyonların Gücü","Dost birimlere bu tur +4|+4 verirsin ve Silahlanırsın.","","''Kalbimizde ışık, savaşa gidiyoruz!''\n- Lux","Büyü",[],["Demacia"],"DESTANSI"],"06DE026":["Icathia Efsaneleri","Elinde bu tur bedeli 0 olan bir Icathia Serabı oluşur ya da elinde bir Altın Spatula oluşur.","","Bir efsaneye göre Altın Spatula'nın ilk sahibi, Jax kadar güçlü ve korkusuz bir savaşçı olmak isteyen ve muazzam mutfak hünerlerine sahip bir deniz canlısıymış.\n\nDaha inanılası olan başka bir efsaneye göreyse Altın Spatula'nın ilk sahibi efsanesi, kafayı FENA sıyırmış bir aşçının uydurmasıymış.","Büyü",[],["Demacia"],"ENDER"],"06DE044":["Petrisit Savaşçı","Düşman büyülerinden ya da yeteneklerinden hasar almam.","","''Petrisitten güçlü bir şey yok.''\n- Durand Mimar","Birim",[],["Demacia"],"ENDER"],"06DE017":["Balık Kavgası","Bir dost birim ve bir düşman birim birbirine vurur ya da Kuşanmış bir dost birim bir düşmana vurur, ardından ekipmanını çıkarır.","","''Yüzümle tanış!''\n- Ionia'lı Oltacı","Büyü",["SİLAH ÜSTADI"],["Demacia"],"YAYGIN"],"06DE040":["Cazip İhtimal","Destenin en üstündeki 4 kart arasından bir takipçi ya da ekipman seçersin. Seçtiğin kartı çekersin, kalanları destene koyarsın.","","Hafif, kışkırtıcı fısıltılar kalbin derinliklerine arzular ekiyor. Arzular tıpkı bir yara gibi gittikçe iltihaplanıyor, büyüdükçe büyüyor, acıkıyor. Açlık beraberinde günahı, günahsa ölümü getiriyor. Ve döngü böylece devam ediyor.","Büyü",["TARİKATÇI"],["Demacia"],"YAYGIN"],"06DE028":["Kanla Lanetlenmiş Harpi","Oyna: Beni elindeki bedeli 2 ya da daha az olan bir ekipmanla Kuşatırsın.\nKuşanmışken ilk defa ölecek kadar hasar aldığımda, ölmek yerine tamamen iyileşirim ve ekipmanım yok olur.","","''Kian, bunu okuyorsan... bu umarım ben öldüm demektir. Başıma gelenleri kontrol edemiyorum. Tırnaklarımın arasındaki kan asla çıkmıyor. Sürekli kaşınıyorum ama kaşıntı ne yaparsam yapayım asla durmuyor. Canım yanıyor. Artık bitsin istiyorum. Bir şekilde hâlâ yaşıyorsam artık beni bulmaya çalışmayacağına söz ver.\n\nSenden beni affetmeni isterdim ama ben bunu bile hak etmiyorum. Annemize iyi bak, olur mu?''\n- Parçalanmış bir çantadaki buruşturulmuş mektup","Birim",[],["Demacia"],"DESTANSI"],"06DE027":["Gelenekçi Kolcu Şövalye","Saldır: Kuşanmış dost birimlere bu tur +1|+1 verirsin.","","''Adın Janan'dı, değil mi? Bana Sirius'la ilgili ne söyleyebilirsin?''\n''Ha, Kolcu Şövalye Rowill'i mi diyorsun? Birkaç sene önce unvanını elinden aldılar. Bildiğim kadarıyla sebebi verilen hiçbir emre kulak asmamasıymış. Sanırım kendisi canı ne isterse onu yapan ve hayırdan asla anlamayan birisi.''\n''Demek öyle...''\n''Ya... peki sen niye onun bu ava katılmasına izin verdin?''\n''İzin vermedim ki.''\n''O zaman neden... ha, anladım. Harika.''\n- Vayne ve Dul Avcı Janan","Birim",[],["Demacia"],"ENDER"],"06DE019":["Dul Avcı","Oyna: Beni elindeki bedeli 2 ya da daha az olan bir ekipmanla Kuşatırsın.","","''Kadının yetenekli bir savaşçı olduğu belli ama acısı daha çok taze ve bu onu tüketecek gibi. Kederin ne kadar kuvvetli bir motivasyon kaynağı olduğunu pekâlâ biliyorum ama kederin bu kadarı insana ne yapar, kim bilir? Belki de ölmeye çalışıyordur...''\n- Gelenekçi Kolcu Şövalye Sirius Rowill'in şahsi günlüğünden","Birim",[],["Demacia"],"YAYGIN"],"06DE032":["Demacia Çeliği","","","Demacia'nın miğferli savaşçılarının kullandığı standart kılıç ve kalkan.","Ekipman",[],["Demacia"],"YAYGIN"],"06DE029":["Dikbaşlı Geyik","İlk kez bir dost birim Kuşandığında, Dayanıklı kazanırım.","","''Uzak dur, seni iğrenç yaratık! Hele Saflık'ın kusursuz postundan bir tanecik tüy kopar, sana SONSUZ ISTIRAP NEYMİŞ GÖSTERİRİM!''\n- Gelenekçi Kolcu Şövalye Sirius Rowill","Birim",[],["Demacia"],"YAYGIN"],"06DE010":["Kolcu Şövalye Kaçkını","Bu oyunda bir dost birimi Kuşattığında, bana Öncü kazandırırsın.","","Yıllarca büyü yeteneklerini baskılaması, kendine duyduğu nefreti körüklemişti. Bu nefreti acımasızca kurbanlarının üstüne salıyordu. Kolcu şövalyelerden kaçtıktan sonra, içindeki öfkeyi nereye yönelteceğini bilemiyordu, ta ki karanlıktan gelen o sesi duyana kadar. Ses, yeni bir düzenden bahsediyordu, özgürce zulmedebileceği bir düzenden.","Birim",["TARİKATÇI"],["Demacia"],"ENDER"],"06DE006":["Savaşçı Aşçı","Çağrıldığımda Doğaçlama yaparım, ardından beni İşlersin.","","Demacia ordusunda geçirdiği günlerin ardından, Breshi emekli olup uzak bir kasabanın sakin bir hanında aşçılık yapacağını düşünüyordu. Ama Jax, haşlanmış yumurtalar hakkında belirttiği berbat fikriyle bir bar kavgası çıkararak Breshi'nin emekliliğini mahvetti. O günden beri, Breshi'nin hayatta yeni bir amacı var: Jax'in damak zevkini geliştirmek.","Birim",["SİLAH ÜSTADI"],["Demacia","Freljord"],"YAYGIN"],"06DE034":["Sadık Kurt Köpeği","Bu tur bir dost birim öldüyse bedelim 2 azalır.\nOyna: Beni elindeki bedeli 2 ya da daha az olan bir ekipmanla Kuşatırsın ve İşlersin.","","''Maggie'yi o daha küçücük bir yavruyken sahiplendim. Biraz ihtiyarlamış olabilir ama zihni hâlâ bıçak gibi keskin. Onun için canımı veririm ve eminim ki o da benim için aynısını yapar.''\n- Dul Avcı Janan","Birim",["KÖPEK"],["Demacia"],"YAYGIN"],"06SI045":["Ruhlarını Sök","Bir dost birimi öldürüp 2 Hayali kopyasını çağırırsın.","","Zaten son günlerde pek bir ruhsuzlardı.","Büyü",[],["Gölge Adalar"],"ENDER"],"06SI007":["Darkin Kargısı","Beni oynamak için bir dost birimi öldürürsün.\n10 mana harcayarak beni Taarosh olarak oynayabilirsin.","","Hücresinden kurtulmak için çırpınan Taarosh, generalinin çağrısını duydu. Şu ya da bu şekilde, bu çağrıya yanıt verecekti.","Ekipman",["DARKİN"],["Gölge Adalar"],"DESTANSI"],"06SI034":["Yankıların Hayaleti","Tur Sonu: Bu tur ölmüş olan her dost birim için her yerdeki dost kopyaları +1|+1 kazanır.","","''Ne tür karanlık büyüler yaptıklarını bilmiyorum, zaten bilmek de İSTEMİYORUM. Bildiğim tek şey şu: Ayaklanacak olurlarsa onları geberteceğim. Bir kez daha.''\n- Adaların Işık Muhafızı","Birim",[],["Gölge Adalar"],"DESTANSI"],"06SI029":["Kem Mızrak","Bu tur bir dost birim öldüyse bedelim 2 azalır.","","''Adalet diye bir şey yok, sadece intikam var.''\n- Kalista","Ekipman",[],["Gölge Adalar"],"YAYGIN"],"06SI032":["Kaçınılmaz Son","Güç ve Can değerleri toplamı 4 ya da daha az olan bir birimi öldürürsün ya da bir birimin ekipmanını yok edersin.","","Gölge Adalar'da ölüm kendini nasıl gösterirse göstersin, hızlı olsun yeter.","Büyü",[],["Gölge Adalar"],"ENDER"],"06SI031":["Düşenlerin Kılıçları","Bir dost birime bu tur ''Son Nefes: Benim ekipmanıma sahip bir Icathia Serabı çağırırsın'' verirsin.","","Bazen, can veren dostlarımız için yapabileceğimiz en iyi şey yere düşen silahlarını alıp savaşmaya devam etmektir.","Büyü",["SİLAH ÜSTADI"],["Gölge Adalar","Shurima"],"ENDER"],"06SI014":["Debdebeli Fuaye","Çağrıldığımda bir Garip Grup çağırırsın.\nTur Başı: Saldırı hakkı sendeyse bir Garip Grup çağırırsın.","","''Oyuncular hazır, sahne kurulu ve seyircilerimiz beklemede. Artık başlayalım mı, Maestro?''\n- Şamatacı Ev Sahibi","Yer",[],["Gölge Adalar"],"DESTANSI"],"06SI038":["Aklanmış Dâhi","Saldır: Saldıran bir Garip Grup çağırırsın.","","Kusursuzun peşinden koşmak kısıtlayıcıydı, hiç esnek değildi. Kusursuzun bir hayatı yoktu ki, nefes alamazdı. Ancak kusursuz kusurluluk öyle mi? İşte o, peşinden koşulmaya değerdi.","Birim",[],["Gölge Adalar"],"ENDER"],"06SI003":["Çölün Celladı Fireth","Çağrıldığımda, Doğaçlama yaparım.","","Jax, yolculuklarının ilk haftalarında Fireth'e defalarca adını sormuştu. Fireth'se her seferinde terslenerek, ''Benim adım Cellat!'' diye yanıtlamıştı. Breshi bu soruna ilginç bir çözüm buldu: Bir pasta yapmak. Doğru düzgün kutlama yapmak için grubun en güçlü mensubunun adını bilmek şarttı tabii!","Birim",["SİLAH ÜSTADI"],["Gölge Adalar","Shurima"],"DESTANSI"],"06SI006":["Kutunun Muhafızı","Bu oyunda bir dost birimi Kuşattığında, bana Can Çalma kazandırırsın.","","''Kutu sırlarını karşılıksız paylaşmaz, Shieda Kayn. Ona layık bir bedel ödemeden olmaz. Ancak gölgelerin gölgesine bakmaya cesaretin varsa içinde nasıl harika, nasıl dehşetli şeylerin yattığını görebilirsin.''\n- Kutunun Muhafızı Ysdra","Birim",["TARİKATÇI"],["Gölge Adalar"],"YAYGIN"],"06SI039":["Korkunun Yansıması","Bir dost birimi öldürerek bir Yutan Sis çağırırsın.","","Yalnızca bir aptal, tanıdık simalar görmek için Kara Sis'e bakar.","Büyü",[],["Gölge Adalar"],"YAYGIN"],"06SI042":["Ölümsüz Şövalye","Bana Hayali kazandıracağın zaman, bunun yerine +1|+1 kazandırırsın.","","Hayattayken işkencelere katlanmaları için eğitilen askerler, öldüklerinde çok daha yetenekli olmalarının yanı sıra soğuk, acı ya da korku tanımıyorlar.","Birim",[],["Gölge Adalar"],"ENDER"],"06SI036":["Mutlak Yıkım","Dost Darkinler ve Kuşanmış dost birimler dışındaki TÜM birimleri öldürürsün.","","Silahları ele geçirdiğinde insanlığını kaybetmişti. Bir zamanlar sadece bir öğrenci olan Jun'un bomboş bedeni, nefret kaynaklı bir özle dolup taşmaya başladı. Öz, her zerresinden, dört bir yanından geçip dünyaya doğru akıyor, uykudaki darkinleri hareketlendiriyordu.","Büyü",["TARİKATÇI"],["Gölge Adalar"],"ENDER"],"06SI046":["Fasılasız Gözcü","Son Nefes: 1 kart çekersin.",""," ''...ve benim nöbetim ebediyen sürecek zira vazifem yaşamdan da ölümden de öte.''","Birim",[],["Gölge Adalar"],"YAYGIN"],"06SI041":["Mehtaplı Vadi Bekçisi","Hayali bir dost birim çağırdığında, ona +1|+0 kazandırırsın.\nAkşam: Bir Fide çağırırsın.","","Gölge Adalar kıyılarından çok uzakta, dikkatli bakmayan gözlere çoktan ölmüş, çarpık çurpuk ve hareketsiz gibi görünen ağaçlar bulunur. Ancak dikkatle bakanlar ay ışığında yıkanmış toprakların yeni yaşamlarla dolup taştığını fark edebilir.","Birim",[],["Gölge Adalar"],"YAYGIN"],"07PZ009":["Gelişmiş Saat Dost","Oyna: Öngörüde bulunursun, ardından 1 kart çekersin ve bedelini 1 azaltırsın.","","''Bu ufaklığın biraz bakıma ihtiyacı vardı. Üç beş parça değişimi ve yeni bir kolla resmen ömrü uzadı. Bence zaman, herkesin biraz daha fazla sahip olması gereken bir hazine.''\n- Ekko","Birim",[],["Piltover ve Zaun"],"DESTANSI"],"07PZ017":["Kör Edici Bomba Satıcısı","Bir büyü oynadığında, rakibin destesinin en üstündeki 8 kart arasına 1 tane Kör Edici Bomba Tuzağı koyarsın.","","''Bu bebekleri mantarlardan daha iyi kılan ne biliyor musun? Ne zaman patlayacaklarını belirleyebiliyorsun! Tam bir fiyat performans ürünü!''","Birim",[],["Piltover ve Zaun"],"ENDER"],"07PZ005":["Barut Aşımı","Bir düşmana ve rakibin Nexus'una 1 hasar verirsin. 2 taneye kadar kart atarak verilen hasarı attığın her kart için 1 arttırırsın.",""," ''Ya evet, sadece bir kez yapabiliriz bunu ama harbiden diyorum, manyak bir şey olacak!''\n- Jinx","Büyü",[],["Piltover ve Zaun"],"ENDER"],"07NX009":["Estetik Atış","Rakibin Nexus'una 1 hasar verirsin. Bu tur bir dost birimin Nexus'a vuruş yaptığı bir sonraki sefer, elinde bir Estetik Atış oluşur.","","''Bırak silahları, taş ve sopalarla savaşsam bile kimse benimle boy ölçüşemez. Herkes haddini bilsin.''\n- Samira","Büyü",[],["Noxus"],"DESTANSI"],"07NX008":["Zarif Bıçak","Yağma: +2|+0 kazanırım.","","''Beni tutmak pahalıya patlar, öyle herkes için de çalışmam. Bana iş verebilecek kadar şanslıysan hedeflerini asla ıskalamayan kılıçlarımın yanı sıra zarafetim, duruşum ve bilhassa tarzımı elde edersin. Sonuçta gösterişle öldürmeyi kim sevmez?''","Birim",[],["Noxus"],"YAYGIN"],"07NX014":["Etrafında Dön","Yağma: Bedelim 2 azalır.\nHerhangi bir şeye 1 hasar verirsin ve bir düşmanı Sersemletirsin.","","''Ne? Daha ısınıyordum oysaki. Isınmam bile bitmeden öldüğünü söyleme bana.''\n- Zarif Bıçak","Büyü",[],["Noxus"],"ENDER"],"07NX007":["Samira","Yağma ya da Vuruş yaptığımda: Elinde yoksa bir Gösteriş oluşur.","6 kart oynadığını gördüğümde. Bir tura saldırı hakkıyla başladığında sıfırlanır.","''Ödeyemeyeceği borcun altına giren yarım akıllıları her daim bir kenara yazarım çünkü gün gelip borçlarını ödeyemediklerinde alacaklıları onları avlamam için benim kapıma geliyor.''","Birim",[],["Noxus"],"Şampiyon"],"07NX006":["Çıtkırıldım Züppe","Yağma: Güç değerim ikiye katlanır.",""," ''Açıkçası canım, normalde 'yüze ve saçlara dokunmak yok' gibi kurallar koymayı severim ama bana el süremeyeceğin için buna gerek bile yok.''","Birim",[],["Noxus"],"YAYGIN"],"07NX015":["Soyguncu Hatun","Yağma: Dost birimlere +1|+0 kazandırırsın.","","''Ah, Hatun'dan mı bahsediyoruz? Gösterişe çok meraklı biri. Bazıları biraz şatafatlı olmaya burun kıvırabilir ama o havaya bir girdi mi hepimizin cebi dolar.''\n- Zarif Bıçak","Birim",[],["Noxus"],"YAYGIN"],"07NX003":["Göster Kendini","Bir dost birime bu tur +2|+0 verirsin.\nYağma: Bunun yerine +2|+1 verirsin.",""," ''Indari kargaşa çıkarmadan içeri girebilelim diye araya birilerini soktu ama umarım çıkışta ortalığı birbirine katmak için biraz zamanım olur.''\n- Samira","Büyü",[],["Noxus"],"YAYGIN"],"07NX004":["Marifetli Mucit","Çağrıldığımda, tüm dost birimlerin Yağma etkilerini devreye sokarsın.","","''Bazı yerlerde tezgâh kurmak zordur ancak buradaki müşterilerin Lani'yle benim ürünleri görmesiyle cüzdanlarını çıkarması bir oldu. Ürünlere göz gezdirenler arasında bizimkini göremedim ama bu gece kimler kimler caniliğe bürünecek bir bilsen... Sonuçta kimin kimi öldürmek istediğini anlamak, bölgeyi tanımak için oldukça elverişli bir yöntem.''\n- Miel","Birim",[],["Noxus"],"ENDER"],"07NX001":["Sıra Dışı İmhacı","Oyna: Rakibin Nexus'una 1 hasar verirsin ya da bir dost birimin Yağma'sını etkinleştirirsin.","","''Silah işinde olmak bilgileri iyi kullanmayı gerektirir çünkü tasarlama, deneme, yeniden oluşturma ve değiştirme aşamalarının tümü verilere dayanır. Sahaya çıkıp iyi bir numune boyutu belirlemek ve hazır çıkmışken birkaç krater açmak da epey zevkli tabii!''\n- Lani","Birim",[],["Noxus"],"ENDER"],"07NX005":["Yüzbaşı Indari","Çağrıldığımda, Doğaçlama yaparım.\nYağma: Diğer dost birimleri İşlersin.","","''Şimdiye kadar elimden pek çok asker geçti. Kimisi gayet yetenekli kimiyse tam bir baş belasıydı. Ancak Samira'nın yeri apayrı. Baktım ona söz geçiremiyorum ben de kavgayı ayağına getirmeye başladım. Ara sıra olaya ben de dahil oluyorum tabii.''","Birim",["SİLAH ÜSTADI"],["Noxus"],"ENDER"],"07BW018":["Kafadan Kontak Teyze","Mana doldurduğunda, dolan her mana için +1|+0 kazanırım.","","''Jack evladım, hele bak ne diyeceğim! Tam senlik bir şey buldum, değil mi ama?''","Birim",[],["Bilgewater"],"YAYGIN"],"07BW021":["İnsafsız Korsan","Yağma: Bedeli 1 olan rasgele bir takipçi çağırırsın ve ona Gözü Pek kazandırırsın.","","''Yerinde olsam ondan uzak dururdum. Onda sorunlarını başkalarının üstüne atmak gibi pis bir huy var.''\n- Samira","Birim",[],["Bilgewater"],"YAYGIN"],"07BW002":["Jack","Vuruş: Elinde bir Sikke oluşur.\nMana doldurduğunda, dolan her mana için 1 iyileşirim.","Bir turda 12+ mana harcadığında.","''Benim karşıma çıktıysan ya cesursun ya da aptalın teki. Ama sonuç her türlü aynı olacak. Sen onu bunu bırak, canlı çıkmaya bak.''","Birim",[],["Bilgewater"],"Şampiyon"],"07BW040":["Sivri","Çağrıldığımda elinde Geçici bir Mako oluşur.","","''Birazcık burayı, birazcık da şurayı keselim. Bak, çok güzel oldu. Denize azıcık kan dökülmesinden bi' zarar gelmez. Yani en azından bana gelmez.''\n- Sivri","Birim",[],["Bilgewater"],"ENDER"],"07BW001":["Sinsi Bilet Satıcısı","Mana doldurduğunda, elinde bedelini tam olarak karşılayabileceğin rasgele bir Geçici takipçi oluşur.","","''Kan mı görmek istiyorsun? O halde Jack'e gideceksin. Kim, kiminle, nerede, ne yapıyor öğrenmek mi istiyorsun? O halde bana geleceksin.''","Birim",[],["Bilgewater"],"ENDER"],"07BW003":["Yankesici","Son Nefes: Elinde bir Sikke oluşur.","","''Gel buraya, seni hergele! Alın teriyle kazandım onları!''\n- Feneriye","Birim",[],["Bilgewater"],"YAYGIN"],"07BW014":["Beş Yumruk Pablo","Çağrıldığımda elinde Geçici bir Paralı Dövüş oluşur.","","''Aferin be oğlum Jack! Sen Bilgewater şanını böyle yürütmeye devam et, ben de seni turp gibi yapayım. Bak böyle deyince eski günler aklıma geldi. Bana o zamanlar 'Müthiş Pablo' derlerdi... Ne dedin? Öyle demezlerdi demek ha... Senin kafana sağlam vurmuşlar, hafızan körelmiş.''\n- Beş Yumruk Pablo","Birim",[],["Bilgewater"],"YAYGIN"],"07BW013":["Feneriye","Yağma: Elinde 3 Sikke oluşur.","","''Elinden gelen bu mu? Ne tatlı. Şimdi sıra bende.''","Birim",[],["Bilgewater"],"YAYGIN"],"07BW006":["Riskli Bahis","Bir birime 3 hasar verirsin. Ölürse elinde 2 Sikke oluşur.","","''Benim gibiler risk almaktan hiç korkmaz çünkü risksiz bir kuruş kazanç olmaz.''\n- Jack","Büyü",[],["Bilgewater"],"DESTANSI"],"07BW026":["Dikenli Zincir","Yağma: Bedelim 2 azalır.\nSonraki Tur Başında 2 kart çekersin ve onlara Geçici kazandırırsın.","","Tıngırtı duyuyorsan artık kaçmak için çok geç demektir.","Büyü",[],["Bilgewater"],"ENDER"],"07BW027":["Hiddet Reis","Yağma: 1 büyü manası doldurursun ve elinde bölgelerine ait, bedeli 1 olan rasgele bir büyü oluşur.","","Hiddet Reis'in nereden geldiği, ejder tarihinden bile daha gizemli. Kendisine sorulduğunda dahi kimse kesin bir cevap alamıyor. Tabii bunun nedeni ortalığı yakıp yıktığı için ne dediğinin duyulamaması da olabilir.","Birim",[],["Bilgewater"],"ENDER"],"07BW008":["Paralı Dövüş","Bir dost birim ve bir düşman birim birbirine vurur. Bu vuruşta iki birimin de Can değeri 1'in altına düşemez.","","Bazen üç beş sikke ve lamba yağıyla ekmeğini kazanmaya çalışırsın, bazense yumruklarınla. Burada işler böyle... Hele bir de hakkın olanı alabilirsen ne mutlu sana!","Büyü",[],["Bilgewater"],"YAYGIN"],"07BW041":["Kekamuşta","Vuruş: Elinde bir Sikke oluşur.","","''Hmm, evet, bunlar bildiğin ekipmanlara benzemiyor. O konuda haklısın ama bi' dene bak, harbiden seveceksin.''\n- Koç","Ekipman",[],["Bilgewater"],"ENDER"],"07BW004":["Kral Divanı","Çağrıldığımda bir Jack çekersin.\nBir dost birim çağırdığında, elinde Geçici bir Paralı Dövüş oluşur.\nBir dost birim hasar alıp sağ kaldığında, ona Gözü Pek kazandırırsın.","","Jack ve tayfası, Jack'in şahsi gemisiyle Bilgewater'dan Ionia'ya kadar Runeterra'daki tüm denizleri gördü. Geminin batmadan suyun altında nasıl ilerlediği tam bir muamma. Ama rivayete göre esas tehlike denizlerin dibinde yatıyor...","Birim",[],["Bilgewater"],"DESTANSI"],"07BW025":["Kıvılcım","Yağma etkinleştirdiğinde, 1 kart çekersin ve ona Geçici kazandırırsın.","","''Gemide kundakçılığın da getirisi yok değil. Deniz sağ olsun, ateşin öyle kontrolden çıkıp oraya buraya yayılmasını engelliyor, üstelik senden bunun için bir kuruş bile istemiyor.''","Birim",[],["Bilgewater"],"ENDER"],"07IO020":["El Ver!","Bir dost birimi Geri Gönderirsin ve elinde bir Sikke oluşur ya da 5 mana harcayarak bir düşman birimi Geri Gönderirsin ve elinde bir Sikke oluşur.","","''Yalnızca iki koşulda gelirim: Rakibin seni pataklarken çok eğleniyorsa ya da sen onu pataklarken çok eğleniyorsan ve ben de payımı istiyorsam!''\n- Çukur Uzmanı","Büyü",[],["Ionia"],"ENDER"],"07IO014":["Yetenek Avcısı Bingwen Usta","Oyna: Bu tur oynadığın bir sonraki birimin birebir Hayali bir kopyasını çağırırsın.","","Lakabını turna gibi duruşundan ve çevikliğinden alan Kuş Bingwen de bir zamanlar dövüşçüydü. Emekli olduktan sonraysa eğitmenliğe soyundu. O zamandan beri keskin gözünü ve katı disiplinini kullanarak yetenek avcılığı yapıyor.","Birim",[],["Ionia"],"DESTANSI"],"07IO023":["Eski Toprak","Oyna: En Güçlü düşmanı Geri Gönderirsin. Bu tur 16+ mana harcadıysan, bunun yerine tüm düşmanları Geri Gönderirsin.","","''Maske çıkmayacak dedim. Ayrıca suratının bu mahluka benzemesini istemiyorsan bir daha sorma.''","Birim",[],["Ionia"],"ENDER"],"07IO011":["Sett","Saldırırken ilk defa Can değerimi 1'in altına düşürecek kadar hasar aldığımda, bunun yerine Bariyer alırım.","40+ mana harcadığında.","Sett, özel yeraltı arenasına doluşmuş kalabalığın haykırışlarının tadını çıkarırken uzun zaman sonra ilk kez iç sesine kulak veriyor. Uğruna dövüştüğü her şeyi anımsıyor, uğruna dövüşebileceği şeyleri düşünüyor ve şundan bir kez daha emin oluyor: Patron olmak gibisi yok!","Birim",[],["Ionia"],"Şampiyon"],"07IO046":["Asil Parlakkanat","Diğer Kuş dost birimler +1|+0 ve İlk Saldırı alır.","","''Bu ormanda güzellikle ölümcüllük hep doğru orantılı ilerliyor.''\n- Anura","Birim",["KUŞ"],["Ionia"],"ENDER"],"07IO009":["Külyutmaz Muhasip","Nexus Vuruşu: Elinde bir Sikke oluşur.","","Sett'e göre Lis'i diğer hırslı düzenbazlar ve çıkarcı kurnazlardan ayıran en önemli özelliği güvenilir olması. Kendisi şimdiye kadar hiçbir işten kaçmadı, asla yetersiz kalmadı ve Sett'i şüphelendirecek hiçbir şey yapmadı. Böylece Sett'in desteğini kazandı ve bela arayanlara da ihtar çekmiş oldu: Paranı Kasa'ya karşı basarsan kaybedersin.","Birim",[],["Ionia"],"ENDER"],"07IO019":["Tatlı Dilli Barmen","Oyna: Bir dost birimi ya da Nexus'unu 3 iyileştirirsin ve elinde bir Sikke oluşur.","","''İlk bardakta tanışıyoruz, ikincisinde ahbap oluyoruz. Üçüncüsünde dert ortağı, dördüncüsündeyse sırdaş oluyoruz. O kadar ki neler duyduğumu anlatsam yalancı diye adım çıkar!''","Birim",[],["Ionia"],"YAYGIN"],"07IO017":["Bahisleri Alalım","2 kart çekersin ve elinde 2 Sikke oluşur.",""," ''Onlar bize para veriyor, biz de onlara şans veriyoruz. Hehe... Bazıları da 'Kasa nasıl her zaman kazanıyor?' diye düşünsün dursun.''","Büyü",[],["Ionia"],"YAYGIN"],"07IO047":["Ayartan Kobra","Her tur ilk defa başka bir takipçi oynadığında, onun birebir kopyasını çağırırsın. Tahtan doluysa, bunun yerine niteliklerini ve tesirlerini bana kazandırırsın.","","''Sence bu çiçeklerin ederi ne? Bir de bana mı öyle geliyor yoksa... dans mı ediyor onlar?''\n- Piltover'lı Avcı","Birim",["SÜRÜNGEN"],["Ionia"],"DESTANSI"],"07IO013":["Çukur Uzmanı","Çağrıldığımda, elinde bir Sikke oluşur.","","''Kimi para için kimi kan dönmek için kimiyse seyircilerin kükremesine nail olmak için gelir. Ben mi? Beni öyle tek şey kesmez. Hepsini istiyorum ve burada hepsini fazlasıyla elde ediyorum.''","Birim",[],["Ionia"],"YAYGIN"],"07IO012":["Mekânın Fedaisi","Çağrıldığımda, elinde Geçici bir Mekânın Fedaisi oluşur ve diğer Mekânın Fedaisi kartlarına +1|+1 kazandırırsın.\nPotansiyel - 5: İlk Saldırı.","","''Kalın kafalı olduğunu düşünürlerse bırak düşünsünler. Bırak o dingiller kendilerini bir halt sansınlar. İnan seni hafife aldıklarını fark ettikleri anda yüzlerinde oluşan ifadeden güzeli yok şu hayatta.''\n- Sett","Birim",[],["Ionia"],"ENDER"],"07IO007":["Surat Dağıtan","2 düşmanı Sersemletirsin ve elinde bir Sikke oluşur.","","''Ne var? Her şeyle yüzleşmeye hazırım dedi, ben de çaktım yüzüne yumruğu!''\n- Sett","Büyü",[],["Ionia"],"YAYGIN"],"07SH023":["Düşmüş Kum Generali","Bu oyunda çağırdığın her Hayali dost birim için +1|+0 alırım.","","''Bu düşman için kum tanelerinden farksız olsan da seni görüyorum. Kumullardaki varlığını hissedebiliyorum. Gücünü benimle paylaş ve birlikte düşmanlarımızı yere serelim!''","Birim",[],["Shurima"],"ENDER"],"07SH018":["Sır Bekçisi","Çağrıldığımda destenin en altında; elinde, destende ya da oyunda olmayan rasgele iki tane 2. seviye şampiyon oluşur.","","Ne gördüğünü veya felaketin nasıl ya da ne zaman geleceğini kendisi de bilmiyor ama bu dünyayla içindeki insanların buna hazır olmadığını biliyor. Hiçbir zaman hazır olamayabileceğini de.","Birim",[],["Shurima"],"DESTANSI"],"07SH008":["Sürü Saldırısı","Tüm dost Kedilerin birebir Hayali kopyalarıyla bir fazladan saldırı başlatırsın.","","Yalnız bir yırtıcı yeterince korkutucu olsa da sürüsüyle dolaşan bir yırtıcının yanından bile geçemez.","Büyü",[],["Shurima"],"YAYGIN"],"07FR008":["Yavru Ayazpost","6 mana harcayarak beni Anne Ayazpost olarak oynayabilirsin.","","Freljord'un soğuk hakikatlerinden bihaber olanları burada sayısız tehlike bekler.","Birim",["KÖPEK"],["Freljord"],"YAYGIN"],"07FR009":["Yenilikçi Demirci","Çağrıldığımda, Doğaçlama yaparım.\nHer tur, bir dost birimi ilk defa İşlediğinde ya da Kuşattığında, Nexus'unu 1 iyileştirirsin.","","''Tüylü ufaklık işimi hızlandırmasa da beni her zaman güldürmeyi başarıyor. Bu yardımı bana yeter de artar bile.''\n- Yenilikçi Demirci","Birim",["SİLAH ÜSTADI"],["Freljord"],"ENDER"],"07FR005":["Zebella Köle","Dost büyülerinden ya da yeteneklerinden hasar almam.","","''Çığ düşmeye başladığında onu durdurmak imkânsızdır.''\n- Lissandra","Birim",[],["Freljord"],"ENDER"],"07SI002":["Ruh Hasadı","Güç değeri 3 ya da daha az olan bir takipçiyi öldürürsün veya 3 mana harcayarak Güç değeri 3 ya da daha az olan bir şampiyonu öldürürsün.","","Havadaki fısıltıdan yoktur farkı, zar zor duyulur ama yakar sayısız canı, işte geldi ölüm tüccarı.","Büyü",[],["Gölge Adalar"],"ENDER"],"07SI001":["İmha","Güç değeri 3 ya da daha az olan TÜM birimleri öldürürsün.","","Bana bakanlar kıyamete tanık olacak ve bunu asla unutamayacak.","Büyü",[],["Gölge Adalar"],"DESTANSI"],"07SI007":["Mezar Yoldaşı","Her tur ilk defa başka bir dost birim öldüğünde, 1 kart çekersin.","","''Ona yeni bir numara öğrettim! Görmek ister misin?''\n- Şakacı Hortlak","Birim",["KÖPEK"],["Gölge Adalar"],"YAYGIN"],"07MT003":["Kozmik Yavru","Tur Başı: Beni ve Nexus'unu 1 iyileştirirsin.","","Kutup ışıklarından kopmuşçasına göklerde dolaşırlar. Aydınlık bakışları huzur getirir, yaraları sarar ve kırıkları onarır.","Birim",[],["Targon"],"ENDER"],"07MT001":["Kayan Yıldız","Bu tur saldırmış ya da Sersemlemiş olan bir düşmana 4 hasar verirsin.","","Yıldızlar iyi veya kötü tüm eylemlerimizi değerlendirir. Erdemliler ödüllendirilirken kötüler cezalandırılır.","Büyü",[],["Targon"],"YAYGIN"],"07MT007":["Fedakâr Âlim","Son Nefes: Beni hedef alarak oynadığın ilk 3 büyünün kopyası elinde oluşur.","","''Camphor'un zulmüne kurban giden öyle çok can var ki... Bu yüzden ölüm kapını çaldığında onu kucakla. Camphor'a bu zevki tattırma.''\n- Pantheon","Birim",[],["Targon"],"DESTANSI"],"07BC005":["Oyma Kılıç Ustası","","","''Bak bunu hiç beklemiyordum.''\n- Yordle Kılıç Ustası","Birim",["PERİ"],["Bandle Şehri"],"YAYGIN"],"07BC009":["Pasta Atışı","Bir birime 1 hasar verirsin. Elinde bir Ağır Tatlı oluşur.","","Siper alın!","Büyü",[],["Bandle Şehri"],"ENDER"],"07BC015":["Küçült","Bir takipçi seçersin. Elinde bedeli 1 olan bir kopyası oluşur ve nitelikleri 1|1 olur.","","''Ağaaa... Demek ki minik olan her zaman şirin olmuyormuş!''\n- Lulu","Büyü",[],["Bandle Şehri"],"ENDER"],"07DE002":["Arama İzni","Güç değeri 4+ olan bir dost birim, bir birimi Zapt Eder ya da bir dost birim bir Yer kartını Zapt Eder.","","''Olduğunuz yerde kalın ve sesinizi kesin. Zorluk çıkarmanız sizin aleyhinize olur.''\n- Müfettiş Sihir Avcısı","Büyü",[],["Demacia"],"ENDER"],"07DE005":["Hizaya Gel!","Bir dost birime bu tur +2|+2 verirsin.","","''Başınız dik durun! Zorlanabilirsiniz ama asla yıkılamazsınız!''\n- Yılmaz Öncü","Büyü",[],["Demacia"],"YAYGIN"],"07DE008":["Birlik Sunağı","Çağrıldığımda bir birim çekersin.\nBir dost birim çağırdığında, niteliklerini mana bedeline denk olacak şekilde arttırırsın.","","Cithria sunağı ilk gördüğünde ağzını açıp söyleyecek tek kelime bulamamıştı. Şerefli kahramanların azametine hayran hayran bakmakla yetindi bir süre. Bir gün onların yanında yer alacak kadar cesur olabilecek miydi?","Yer",[],["Demacia"],"ENDER"],"07PZ019":["Kimyasal Motortıl","Bu oyunda çağırdığın bedeli 1 olan her dost birim için +1|+0 alırım.","","''Bak şindi, keytenkele abicik, atımıza bissürü toynak çizcez çünkü ÇABUÇAK kaleye gitmemiz geyek. Ayy, biyazcık... komik oldu. Biy de çok yeşil oldu yaa!''\n- Küçük Ingvar","Birim",[],["Piltover ve Zaun"],"ENDER"],"07PZ021":["Anura ve Vırak","Oyundaki diğer dost birimlerden farklı alt tipe sahip dost birimlerin bedeli 1 azalır.","","''Ben senin dostunum, sana zarar vermem! Buraya yakıp yıkmak için değil, bilim için geldim.''","Birim",["SÜRÜNGEN"],["Piltover ve Zaun"],"DESTANSI"],"07PZ022":["İlahi Cereyan","Bir düşman birime ya da rakibin Nexus'una 1 hasar ve bir diğerine 1 hasar verirsin.","","Piltover'lıların çoğunluğu rüzgârın nasıl estiğiyle hiç mi hiç ilgilenmez. Fakat pek çok Zaun'luya göre en ufak esinti bile beraberinde kurtuluşu taşıyor olabilir.","Büyü",["ELEMENTAL"],["Piltover ve Zaun"],"YAYGIN"],"07PZ013":["Kuyu Anıtı","Nexus'un Zehirli Pofkep Mantarı harici hasar alacağı zaman, bunun yerine rakibin her hasar için destene 5 Zehirli Pofkep Mantarı koyar.","","Zaun sokaklarının ücra köşelerinde ne yersen osun.","Yer",[],["Piltover ve Zaun"],"DESTANSI"],"07PZ015":["Çığır Açan Hurdabuluş","Oynamak için tüm mananı harcarsın. Bir Kontrolden Çıkmış Hurdabot çağırırsın ve niteliklerini harcadığın mana sayısına denk olacak şekilde arttırırsın.","","''Bir bilim insanının en mühim sorumluluğu değişkenleri daima kontrol etmektir. Bizimki gibi bir çalışma alanında meydana gelecek bir kazanın sonuçlarını, nasıl desem... düşünmesi bile korkunç!''\n- Profesör Heimerdinger","Büyü",[],["Piltover ve Zaun"],"YAYGIN"],"07NX028":["Yüzbaşı Kalrix","Nexus Vuruşu: Rakibin Nexus'una, onun canının yarısı kadar hasar verirsin. Sayı üste yuvarlanır.","","Noxus her şeyden önce genişlemek için kurulmuş bir imparatorluk. Dolayısıyla savunmalarınız ister tahtadan ister taştan isterseniz de çelikten olsun, hepsi nafile. İlerlemekte olan bir Noxus koçbaşını hiçbir şey durduramaz.","Birim",[],["Noxus"],"DESTANSI"],"07NX034":["Kızıl Ziyafet Salonu","Dost birimlerin bedeli 1 azalır. Bir dost birim oynadığında ona 2 hasar verirsin.","","''Buyurun dostlarım, geçin oturun! Dost meclisimizde içki bahane, muhabbet şahane! Akşam yemeğinde ne olduğunu göstermeyi iple çekiyorum.''\n- Vladimir","Yer",[],["Noxus"],"DESTANSI"],"07NX032":["Ravenbloom Cildi","Taşıyıcım bir Yetenek oynadığında, onu kopyalarsın.","","Ravenbloom Konservatuvarı barındırdığı engin metin koleksiyonuyla bilinirdi fakat ne yazık ki bunların büyük çoğunluğu baş belası bir öğrencinin çıkardığı korkunç yangında kül oldu.","Ekipman",[],["Noxus"],"ENDER"],"07NX033":["Kemikderili Üçkuyruk","Çağrıldığımda, diğer dost birimlerin sahip olduğu her farklı alt tip için +1|+1 kazanırım.","","''Yavaş olun, mankafalar! Noxus'lular dövüştürecekleri hayvanı almadan önce kusursuz durumda olmasına dikkat ediyor. Kemiği bir çizilsin var ya, tüm zararı yevmiyenizden keserim!''\n- Büyük Hayvan Taciri","Birim",["KEDİ"],["Noxus"],"YAYGIN"],"07RU015":["Poro Kralı","Köken: Poro Kralı'nın Fermanı.\nHer tur ilk defa başka bir Poro çağırdığında, elinde bir Poro Kurabiyesi oluşur.","6+ başka yeni Poro çağırdığında. Seviye atladığımda elinde rasgele bir Ham Yapmalık Kurabiye oluşur.","Ingvar potansiyeli gözünden tanır. Dış görünüşünün sadeliği bir yana, bu sevgili yoldaş milyorlarca poroya liderlik edebilir. Tabii hayal gücü yeterince zenginse. ","Birim",["PORO"],["Runeterra"],"Şampiyon"],"07RU012":["Neeko","Köken: Envai Çeşit Orman Dostu!\nOyna: Köken'imdeki alt tiplere ait 2 manalık üç takipçiden birinin Kılığına Bürünürüm.","Saldır: 6+ farklı alt tipten dost birimle saldırdığında.","Neeko binbir şekle bürünse de kalbi hiç değişmiyor; her zaman ailesinden ve ormandan yana atıyor.","Birim",["ŞEKİL DEĞİŞTİRİCİ"],["Runeterra"],"Şampiyon"],"07BW043":["Dalgaların İmdadı","Bir birime 1 hasar verirsin. Verilen her hasar için 1 Dokunaç Çıkarırsın.","","Yalnızca bilge kimseler elementlere hükmedebilir.","Büyü",["ELEMENTAL"],["Bilgewater"],"ENDER"],"07BW035":["Üçkâğıtçının Mekânı","Elindeki kartlar Geçici alır.\nBir kart oynadığında, 1 kart çekersin.","","''Ya elindeki kartları adın gibi bilip sımsıkı tutacaksın ya da her şeyi kaybetmeyi göze alacaksın.''\n- Twisted Fate","Yer",[],["Bilgewater"],"DESTANSI"],"07BW042":["Güvertenin Avcısı","Oyna: Oyundaki dost birimlerden farklı bir alt tipe sahip bir takipçi Cisimlendirirsin.","","''Bu pasaklı ufaklığın ortalıkta dolanmasına neden izin veriyoruz sanıyorsun? Onun sayesinde yıllardır tek bir rıhtım sıçanı bile görmedik!''\n- Dehşet Yolu tayfası","Birim",["KEDİ"],["Bilgewater"],"YAYGIN"],"07BW039":["Ejder Prens Grinzo","Her tur ilk defa bedeli 1 olan bir dost birim çağırdığında, 1 büyü manası doldurursun.","","''Keytenkele abicik, buyada napıyoyşun? Yoksa sen de mi porocukları çok seviyosun?!''\n- Küçük Ingvar","Birim",["EJDER"],["Bilgewater"],"ENDER"],"07BW033":["Sirenlerin Şarkısı","Rasgele bir Kabuk çağırırsın.\nHer yerdeki bedeli 1 olan dost birimlere +1|+1 kazandırırsın.","","Bilgewater'daki bazı denizciler denizdeki en suskun gecelerde kulaklarına pamuk tıkarlar çünkü dalgaların altında tınlayan müziğin onlara sırılsıklam bir mezardan başka bir şey vaat etmediğini çok iyi bilirler.","Büyü",[],["Bilgewater"],"YAYGIN"],"07IO041":["İyileştiren Meltem","Nexus'unu 3 iyileştirirsin ve 2 büyü çekersin.","","''Gezginin yegâne dostu rüzgârdır.''\n- Yasuo","Büyü",["ELEMENTAL"],["Ionia"],"YAYGIN"],"07IO043":["Her Şeyi Gören Kâhin","Oyna: Rakibin elindeki ya da destesindeki Hızlı veya Yavaş 3 büyüden birini seçersin. O büyüye karşı bir Kehanet Oyması oluşturursun.","","Maddi âlemin ötesine geçebilen göz her şeyi görür. Görmez sanılan kâhin onu kolay hedef sayanların fikirlerini merhamet göstermeden tez değiştirir.","Birim",[],["Ionia"],"ENDER"],"07IO049":["Airis","Nexus Vuruşu: Rasgele bir Kabuk çağırırsın.","","''Sessiz ol bakalım, çok az kaldı. Arkadaşımla tanışmak istediğini söylememiş miydin? İnan bana seni çok sevecek.''","Birim",[],["Ionia"],"ENDER"],"07SH038":["Yavru Pakaa","Sota - 1\nNexus Vuruşu: Bir Pakaa Koruyucusu çağırırsın.","","Şirinlik görünüşten, vahşilikse içgüdülerden gelir. En ufak pakiti bile yeterince zaman ve eğitimin ardından dolu dolu kükreyen, yırtıcı bir yetişkine dönüşür.","Birim",["KEDİ"],["Shurima"],"YAYGIN"],"07SH041":["Çalı Kontrolü","Sotaya yatabilen bir kart Cisimlendirirsin.","","Kimsenin orman keşfine gitmek istememesinin en büyük sebebi, ormanların sürprizlerle dolu olması.","Büyü",[],["Shurima"],"ENDER"],"07SH004":["Kolaçan","Bir dost birime bu tur +2|+0 verirsin. Bu birim bir Çalıdaki Gölge ise bunun yerine +2|+2 verirsin.","","''Sessiz sessiz ilerle, pakiti. Aniden saldır.''\n- Nidalee","Büyü",[],["Shurima"],"YAYGIN"],"07SH013":["Nidalee","Sota - 2","Başka 4 dost birim çağırdığını ya da dönüştürdüğünü gördüğümde.","''Seni daima koruyacağım, kertenkele kız. Avcılara, yaptıklarının bedelini ödeteceğiz. İkimiz, birlikte.''\n- Nidalee","Birim",["KEDİ"],["Shurima"],"Şampiyon"],"07SH009":["İntikamcı Vastaya","Sota - 3\nSotaya Yatmış İntikamcı Vastaya ile dönüştüğümde, tüm Hızlı ve Yavaş düşman büyüleriyle Yeteneklerini durdurursun.","","''Sakın korkmayın ufaklıklar. Ben sizi koruyacağım ve Nidalee'ye olan borcumu ödeyeceğim.''","Birim",[],["Shurima"],"YAYGIN"],"07SH039":["Arazi Azmanı","Sota - 0\nÇağrıldığımda ya da dönüştüğümde, En Güçsüz düşmana Kırılganlık kazandırırsın.","","''Bu bebek, bir acemiyi bile ağaçlara tırmanan ve daldan dala atlayan bir profesyonele dönüştürebilir. Ateş pahasıydı ama birkaç nadir yaratık avladım mıydı derilerini satarak borcumu kapatırım...''","Birim",[],["Shurima"],"ENDER"],"07SH044":["Aurora Hallunatis","Sota - 4\nDönüştüğümde bir Aurora Hallunatis çağırırsın.","","''Dünya gözüyle bir tanesini görmeyi öyle isterdim ki! Çoğu kâşif Aurora Hallunatis'in efsane olduğuna inanıyor. Bir genç adamsa gördüğüne yeminler ediyor. Bu kuşun bedeninde tam bir renk cümbüşü barındırdığını ve kanat açıklığının insan boyuna ulaştığını söylüyor. Ayrıca gözlerinin içine baktığında onun için bir avdan ibaret olduğunun farkına vardığını anlatıyor.''\n- Anura'nın seyir defteri, 21. gün","Birim",["KUŞ"],["Shurima"],"ENDER"],"07SH003":["Balonlu Avcı","Sota - 3\nSotaya Yatmış Balonlu Avcı ile dönüştüğümde, bu tur karşıladığım ya da karşılandığım bir sonraki sefer düşmanımı Zapt Ederim.","","''Hah! Sizi aptal yaratıklar. Hadi şimdi de yakalamaya çalışsanıza beni. Üstün ırk yerçekimine bile boyun eğmez!''","Birim",[],["Shurima"],"DESTANSI"],"07SH011":["Vahşi Pusu Kapanı","Çağrıldığımda ya da her tur bir dost birim ilk defa dönüştüğünde, En Güçsüz düşmana Kırılganlık kazandırırsın.","","''Kan kokusu.''\n- Nidalee","Yer",[],["Shurima"],"YAYGIN"],"07SH046":["Taklit Vadisi","Bir takipçi oynadığında bu tur onun birebir kopyasına dönüşürüm.","","''İiiiişteee tuyumuzun EEEEEEEN AŞIYI GÜZEL yeyine geldiiiik. Şimci heeeeerkeşler benim tuyumu o kaday çok beyenince BÜSBÜYÜK bi Taşkın yaptılay. Ondan sorna da büsbüyük Taşkın sonsuza kaday tuyumuzun eeeeen güzel durmakı oldu. Hadiyin, gidip Taşkın'a 'MEREBA BÜSBÜYÜK TAŞKIN!' diyelim Dev Taşkın HEEEERKEŞLERİ şok seviyo. Ama en en en en çok bu tuyla gezmeye gelenleyi seviyo.''\n- Taşkın'la Maceralar - 6","Yer",[],["Shurima"],"YAYGIN"],"07SH043":["Devasa Ebafil","Sota - 5","","Ormanın en kıdemli sakinleri olan ebafillerin aynı zamanda ormanın hafızası ve kalbi oldukları söylenir. Aslında uysal bir tabiata sahip olsalar da yuvalarını irili ufaklı tüm tehditlere karşı savunmaktan çekinmezler. ","Birim",[],["Shurima"],"DESTANSI"],"07SH040":["Oklu Kirpi","Bir dost birim ilk defa dönüştüğünde +2|+1 kazanırım.","","''Üstü sert kılları andıran dikenlerle kaplı, küçük ve hepçil memeliler. Rahatsız edildiklerinde bu dikenleri jet hızında fırlatabiliyorlar. Muhtemelen savunma aracı olarak kullanılabilen kuyrukları da dikenli ve kıvrak. Deneyimli kâşiflere göre bu yaratıklar, huysuz ve geçimsiz tabiatlarıyla ünlü...''\n- Anura'nın seyir defteri, 3. gün","Birim",[],["Shurima"],"ENDER"],"07SH005":["Büyük Hayvan Taciri","Oyna: Sotaya yatabilen bir kart Cisimlendirirsin.\nBir dost birim dönüştüğünde, Güç ve Can değeri iki katına çıkar.","","''NE DEDİNİZ SİZ? Hepsini kime kaptırdınız? Bir bilim kaçığıyla ucube kertenkelenin tekine ha? Ne diye hâlâ bön bön suratıma bakıyorsunuz? Gidin paramı getirin bana!''","Birim",[],["Shurima"],"ENDER"],"07FR011":["Gerçek Buz Tapınağı","Bir dost birim çağırdığında, Can değerini Güç değerine eşit olacak şekilde arttırırsın.","","Bu tapınak anlamını uzun zaman önce yitirmiş olsa da taş muhafızı, sayısız çığa rağmen yerinden asla kımıldamadan hep dimdik durmuş ve durmaya devam ediyor. Artık her tarafı buz tutmuş bu muhafızdan tuhaf ve gizemli bir ışık saçılıyor.","Yer",[],["Freljord"],"DESTANSI"],"07FR010":["Ak Keskinpençe","Yağma: Bir dost birimin niteliklerini benimkine denk olacak şekilde arttırırsın.","","Freljord'lu bir yırtıcı olan ak keskinpençe genelde küçük memelilerle beslense de pençeleri sayesinde avlayıp midesine indiremeyeceği pek az canlı vardır.","Birim",["KUŞ"],["Freljord"],"YAYGIN"],"07FR015":["Küçük Ingvar","Oyna: Bir dost birim seçersin. Ona ve onunla ortak bir alt tipe sahip diğer tüm dost birimlere +1|+1 kazandırırsın ya da onunla ortak bir alt tipe sahip bir takipçi Cisimlendirirsin.","","Kendini poro danışmanı ve Freljord kâşifi ilan eden Ingvar dışarıda onu müthiş maceraların beklediğinden adı gibi emin ve bu fırsatı kaçırmaya hiç niyeti yok. ","Birim",[],["Freljord"],"DESTANSI"],"07FR017":["Kristal Fırtınagaga","Oyna: TÜM diğer birimlere 2 hasar verirsin.","","Kristal fırtınagaganın ansızın çöken gazabı ayrım gözetmez ve sadece birkaç saniye içinde savaşın tüm gidişatını değiştirebilir. Bu kuş pek çok kişiye göre büyük ve dehşet verici, hatta dünyayı bile yerinden oynatabilecek bir fırtınanın ilk alametidir.","Birim",["KUŞ"],["Freljord"],"ENDER"],"07FR016":["Buzul Binek","Çağrıldığımda destenin en üstündeki 3 birime +1|+1 kazandırırsın. Bir dost birimin benimkinden farklı bir alt tipe sahipse, o birimlerden 1 tanesini çekersin.","","Boynuz ve dişlerle dolu iri cüsselerinin altında koca bir yüreğe sahip bu güvenilir binekler, buz kaplı dağ geçitlerini açmakta büyük rol oynuyor.","Birim",["SÜRÜNGEN"],["Freljord"],"ENDER"],"07SI010":["Ölümcek","Çağrıldığımda 2 Karazehirli Yavru çağırırsın.\nBaşka bir dost birim öldüğünde rakibin Nexus'una 1 Sömürü hasarı verirsin.","","Gölge Adalar'ın yalnızca en karanlık köşelerini mesken tutan bu örümcekler ölümcül bir karazehir salgılar. Bu zehir, bedeni çürütürken bile cildi uyuşuk tutar.","Birim",["ÖRÜMCEK"],["Gölge Adalar"],"DESTANSI"],"07SI012":["Püsküllü Ağsaçan","Oyna: Bir dost birimin benimkinden farklı bir alt tipi varsa, bir düşmana bu tur -2|-0 verirsin.","","Püsküllü ağsaçanlar yuvalarını büyük bir itinayla örerler. Yavrularına son derece sevecen davranırlar ancak bir tehlike sezdiklerinde bir o kadar ölümcül olabilirler.","Birim",["ÖRÜMCEK"],["Gölge Adalar"],"YAYGIN"],"07SI013":["Türeyen Karaifrit","Son Nefes: Destende, destendeki En Güçlü Türeyen Karaifrit kartının birebir kopyası oluşur, ardından destendeki Türeyen Karaifrit kartlarının nitelikleri ikiye katlanır.","","''Sis'ten çok şey öğrendim. En önemlisi de ne zaman kaçmam gerektiğini...''\n- Ixtal'lı Işık Muhafızı","Birim",[],["Gölge Adalar"],"ENDER"],"07SI004":["Kutsal Makas","Saldır: Başka bir dost birim Kutlu olarak Güç aldığında, taşıyıcım da alır.","","''İyi bir makas ve kaliteli bir iplikle dikilmeyecek yara yok!''\n- Gwen","Ekipman",[],["Gölge Adalar"],"ENDER"],"07MT009":["Ejderlerin Çağı","Destenin en üstündeki 9 kart arasından tüm Ejderleri çekersin ve bu tur bedelleri 0 olur. Kalan kartlar destene geri karışır.","","''Bir ejder tanıyan ancak kendinin efendisi olur, çok ejder tanıyansa dünyanın.''\n- Ejder Hizmetkârı Ottrani","Büyü",[],["Targon"],"ENDER"],"07MT013":["Kozmik Çağrı","Bedeli 7 ya da daha fazla olan bir Semavi karta Yakarırsın ya da 8 mana harcayarak her yerdeki Semavi kartlarının bedelini yarıya indirirsin. Sayı üste yuvarlanır.","","Gökler yeryüzünü kutsarken Yargıç ebedi bir nöbet bekler.","Büyü",[],["Targon"],"YAYGIN"],"07MT006":["Bedbaht Âşıklar","Oyna: Bir dost birimi Geri Gönderirsin ve ona niteliklerimi kazandırırsın.","","''Ay ve güneşin buluşması kadar büyüleyici pek az manzara var.''\n- Diana","Birim",[],["Targon"],"YAYGIN"],"07BC020":["Kirli Çıkı","Bir ya da daha fazla tuzağın veya lütfun etkinleştiğinde, ilgili oyuncunun destesine etkinleşen tuzak veya lütuftan 2 tane koyarsın.","","Kirli Çıkı'nın ne kadar zamandır eşya biriktirdiğini ya da nereden geldiğini tam olarak bilen yok. Pek de munis birine benziyor. Arkasında bıraktığı, yürürken insanın ayağına dolanan ıvır zıvırı saymazsanız tabii.","Birim",[],["Bandle Şehri"],"ENDER"],"07BC016":["Hep Sadık Anahtar","Atıldığımda beni ekipmanı olmayan rasgele bir dost birime Kuşatırsın.","","''Ne yalan söyleyeyim, ben aletlerimi sürekli kaybederim. Ama bu var ya, ne zaman ihtiyacım olsa hep yanımda bitiveriyor!''\n- Güvenlik Müfettişi","Ekipman",[],["Bandle Şehri"],"YAYGIN"],"07BC018":["Geçit Bilgini","Çağrıldığımda, destenin en üstündeki 4 kart arasına 1 tane Gizemli Geçit koyarsın.\nOluşturulmuş bir dost birim çağırdığında, ona Ağır Darbe kazandırırsın.","","Her araştırmada muhakkak bir sürpriz çıkar. En azından bu kez kimsenin başı derde girmedi. ","Birim",["PERİ"],["Bandle Şehri"],"DESTANSI"],"07BC011":["Hırçın Yumuşlar","Çağrıldığımda, alt tipi olan diğer dost birimlere +1|+1 ve Ağır Darbe kazandırırsın.","","Ne yazık ki Piltover'lı avcılar bu kuşların zararsız görünüşüne aldandı.","Birim",["KUŞ"],["Bandle Şehri"],"YAYGIN"],"07DE014":["Tetkik Çavuşu","Oyna: Destenin en üstündeki 5 kart arasından bedeli 3 ya da daha az olan bir birim seçersin. Seçtiğin birimi çağırırsın ve kalanları destene geri koyarsın.","","Demacia'lı asker alım çavuşlarının omuzlarında muazzam bir sorumluluk var. Seçtikleri erler pek çok farklı makama yerleşiyor ve hem vazifeleri hem de Demacia'ya duydukları sevgiyle tek yürekte buluşuyor.","Birim",["SEÇKİN"],["Demacia"],"DESTANSI"],"07DE015":["İbikli Aslanşahin","Oyna: Bir dost birimin benimkinden farklı bir alt tipi varsa, bir Demacia büyüsü Cisimlendirirsin.","","''Yaklaşık son elli yıldır görülen ilk aslanşahine tanıklık ediyorum. Göz kamaştıran masmavi ibiği ve zekâ fışkıran gözleriyle karşımda duruyor. Vücudu koruyucu bir tabakayla kaplı ancak hafif kemikleri sayesinde ağaçlara tırmanabiliyor ve hatta havada süzülebiliyor. Kanat yapısı Demacia'lı gümüşkanadı andırıyor. Daha fazla gözlemle geri döneceğim.''\n- Anura'nın seyir defteri, 12. gün","Birim",["KUŞ"],["Demacia"],"ENDER"],"07DE011":["Çaylak Sihir Avcısı","Bedeli 3'ten az olan büyülerin bedeli 3 olur.","","''Kes sesini! Oyunmuş, yemezler! Alçak büyü uğraşını örtbas etmeye çalışmaktan vazgeç. Senin bir düzenbaz ve büyücü olduğunu herkese göstereceğim, aşağılık moruk! Burayı yakıp kül etmek pahasına bile olsa bunu yapacağım!''","Birim",[],["Demacia"],"YAYGIN"],"07DE016":["Özverili Balen","Saldır: Her yerdeki diğer dost Çetin Ceviz birimlere +0|+1 kazandırırsın.","","Uzunca bir zamandır Durand ailesine yoldaşlık eden Balen'in koca cüssesiyle çelişen ince işler çıkarmakta üstüne yok. İşe çırak olarak başlamış olmasına rağmen Balen zanaatındaki üstün yeteneğiyle eşsiz eserler üretiyor ve Durand'lar onu dostları olarak görmekten gurur duyuyor.","Birim",[],["Demacia"],"DESTANSI"],"08SI042":["Mordekaiser","Oyna: 2 taneye kadar dost birim öldürürsün.\nBaşka bir dost birimi katlettiğinde, onu diriltirsin.","15+ dost birim öldüğünde. Güç değeri 5+ olan dost birimler iki kez sayılır.","Ölümsüz Hisar'ın kalbinde sakladığı zırha bağlı olan Mordekaiser, Gri Diyar'daki gaddarlığını yansıtan bir tahtta oturur. Onu yok etmek isteyenler de karşısında Mordekaiser'a yaşamda olduğu kadar ölümde de hizmet eden kalabalık müritleri bulur.","Birim",[],["Gölge Adalar","Noxus"],"Şampiyon"],"08SI040":["Müptezel Erastin","Çağrıldığımda bana Ölümsüz kazandırırsın.\nSaldır: Bu tur düşmanlara -1|-0 verirsin.","","Camavor'un bir zamanlar herkesçe saygı duyulan görkemli ejderleri bile Afet'in her şeyi tüketen çürümesine karşı çaresizdi. Uzun zaman önceki ihtişamlı görünüşünden eser kalmayan ve artık ölümsüzlüğün sapkın ışıltısıyla parlayan Erastin de bu yıkımın kurbanlarından biriydi.","Birim",["EJDER"],["Gölge Adalar"],"DESTANSI"],"08SI007":["Yitenler Birliği","Oyna: Elindeki bir dost birime Ölümsüz kazandırırsın.","","Gri Diyar'da zincirlere vurulmadan önce ruhların nasıl bir biçime sahip olduklarının bir önemi yok. Zira orada bireyselliğin hiçbir değeri yok. Bu yüzden çehresiz ve korkusuz Birlik, Demir Hortlak'a tıpatıp aynı suretlere bürünerek hizmet ediyor.","Birim",[],["Gölge Adalar"],"YAYGIN"],"08SI003":["Zincirlenmiş Hortlaklar","Son Nefes: Bir dost birimi dirilttiğin sonraki seferde, elinde bir kopyam oluşur.","","''Çok uzun zaman önce zincire vurdular bizi. Yakında çektiğimiz bu acıyı sen de tadacaksın ve hepimiz sonsuza dek bu ıstırabı paylaşacağız. Ta ki efendimiz bize yok oluşu bahşedene kadar...''","Birim",[],["Gölge Adalar"],"ENDER"],"08SI021":["Yalnız Tınıbalçığı","Başka bir dost birim öldüğünde ya da Son Nefes: Destene 4 tane Tını koyarsın.","","Tuhaf çınlamayı kafana takma, bizim Tınıbalçığı gevezelik ediyor işte. Yeni birilerini gördü mü öyle bir mutlu oluyor ki... Ama aynı şeyi onu görenler için söylemek zor.","Birim",[],["Gölge Adalar"],"YAYGIN"],"08SI030":["Ölümcül Sular","Rakibin destesinin en altındaki 6 kartın Kökünü Kazırsın.","","Runeterra'nın en derin sularında yaşayan bazı deniz canavarları için jaull gemileri, lezzetli atıştırmalıklardan başka bir şey değil.","Büyü",[],["Gölge Adalar"],"DESTANSI"],"08SI037":["Hayalet Demirtazı","Beni oynamak için bir dost birimi öldürürsün.\nÇağrıldığımda bir Bin Pençeli Ecelgetiren çağırırsın.","","Bu tazılar kaçmaya çalışanların kokusunu asla unutmaz ve kurbanlarını köşeye sıkıştırdıklarında Ecelgetiren'in de ava katılması an meselesidir.","Birim",[],["Gölge Adalar"],"ENDER"],"08SI041":["Ecelin Eli","Bir dost birimi öldürerek bir birime 5 hasar verirsin.","","''Karanlık benim dışımda herkesin yazgısı.''\n- Mordekaiser","Büyü",[],["Gölge Adalar"],"YAYGIN"],"08SI036":["Gri Diyar'ın Eşiği","Oyna: Bir düşmanı Dehşet etkisiyle Lanetlersin.\nDevasa bir dost birim çağırdığında, beni yok edip 2 kart çekersin.","","''Sana adıyoruz bu ruhları. Ayakların altına seriyoruz bu kemikten yolları. Demirin daimiliğini taşıyan ordun için paramparça ediyoruz bu diyarları.''\n- Ecel Eli Tarikatçısı","Yer",[],["Gölge Adalar"],"ENDER"],"08SI004":["Ölüler Âlemi","Bir dost birim En Güçlü rakibi çekerek bir fazladan saldırı başlatır.\nDiğer TÜM birimleri öldürürsün.","","''Ölüm benim diyarım.''\n- Mordekaiser","Büyü",[],["Gölge Adalar"],"DESTANSI"],"08SI026":["Ecel Eli Tarikatçısı","Çağrıldığımda ya da Devasa bir dost birim çağırdığında, En Güçlü düşmanı Dehşet etkisiyle Lanetlersin.","","Hizmetkârlarının gözünde Demir Hortlak, yok oluşu arzulayanların bu emellerine ulaşmak için tek umudu. Bu saplantılı tarikatçılar huzuru hâkimiyetle sağlayabilmek için canlarını bile vermeye hazır.","Birim",[],["Gölge Adalar"],"ENDER"],"08SI018":["Hayalet Araştırmacısı","Oyna: Seçtiğin bir Kâşif büyüsü elinde oluşur.","","''Bu arazide dolaşmak neredeyse imkânsız. Göz gözü görmüyor. Ayrıca her köşede bir düşman yatıyor. Gerçi tuhaf bir şekilde beklenmedik müttefiklerle de karşılaşmadım değil.''\n- Kâşifler Loncası'nın Uzak Diyarlar Bölüğü'ne ait keşif gezisi kayıtlarından bir alıntı. Kayıtta bahsi geçen yer: Gölge Adalar","Birim",[],["Gölge Adalar","Targon"],"ENDER"],"08SI015":["Habis Tayf Ucubesi","Beni oynamak için bir dost birimi öldürürsün.\nSon Nefes: Nexus'unu 2 iyileştirirsin.","","Savaş hayvanları her orduda önemlidir. Gri Diyar'da bu hayvanlar işkence görmüş ruhların korkunç birleşiminden oluşur ve her biri haşin bir vahşetle etrafını yıkıma sürükler. ","Birim",[],["Gölge Adalar"],"DESTANSI"],"08BW008":["Nilah","Saldır: Destenin en üstündeki 6 kart arasında bir Akışkan oluşur.","15+ kart çektiğinde.","Kuzeyde Nilah ve canavar avcısı ekibini Volibear adında, bir zamanlar kendisine tapan Freljord'u dünya üzerinden kazımakla tehdit eden yeni bir tehlike bekliyor. Nilah, başkalarının ilah diye nitelendirdiği bir canavara karşı becerilerini sınama şansı bulmasını kırk yılda bir gelecek bir fırsat olarak görüyor. Avıyla arasına girecek kadar talihsiz canavarcıklarla kıvanç listesini zenginleştirecek olması da cabası. ","Birim",[],["Bilgewater"],"Şampiyon"],"08BW032":["Daimi Mutluluk","Dost birimlere bu tur +1|+0 verirsin ve hasar almış dost birimleri 2 iyileştirirsin.","","''Dolup taşan, daimi bir neşe!''\n- Nilah","Büyü",["ELEMENTAL"],["Bilgewater"],"YAYGIN"],"08BW038":["Çakram Dansçısı","Oyna: Herhangi bir şeye 1 hasar verirsin.\nYeteneklerin Sömürü hasarı verir.","","O su ve çakramın dansıyla hareket eder, fokurdayan dalgalardan ve köpüklerden keskin çelikler çıkarır. Kendi silahlarının akışını görmeye ihtiyacı yoktur. Zira bu silahlar suyun hayat bulmuş halidir ve öyle ya da böyle suya geri döner.","Birim",[],["Bilgewater"],"DESTANSI"],"08BW015":["Dalga Dansçısı","Çağrıldığımda bir Nilah çekersin.\nHer tur üçüncü kez kart oynadığında, diğer dost birimlere bu tur +2|+0 ve Gözü Pek verirsin.\nBana Geçici kazandıracağın zaman, bunun yerine beni açığa çıkarırsın.","","''Duyduğuma göre Bilgewater sularında şu tuhaf şekilli gemiden hızlısına hiç rastlanmamış. Manevra kabiliyetinde de üstüne yokmuş. Kaptanı sıra dışı biriymiş ama bana kalırsa ne istediğini çok iyi biliyor. Belki ondan birkaç şey kapabiliriz.''\n- Bilgewater'lı Barmen","Birim",[],["Bilgewater"],"DESTANSI"],"08BW002":["Şekilsiz Kılıç","Bir birime 2 hasar verirsin. Birimin Can değeri bu hasarla 1'in altına düşemez.","","''Hangi diyarı arşınladığı önemsiz, kendini ilah ilan eden canavarlar yerin dibini boylayacak.''\n- Nilah","Büyü",["ELEMENTAL"],["Bilgewater"],"YAYGIN"],"08BW025":["Erkete Uzmanı","Bu oyunda bir turda 3+ kart çektiğinde, bana +1|+1 ve Gözü Pek kazandırırsın.","","''Şşşt, arkadaş! Nedir bu tantana? Sakin ol bakalım! Bu sularda üstesinden gelemeyeceğimiz hiçbir şey yok!''\n- Kapışma Heveslisi","Birim",[],["Bilgewater"],"YAYGIN"],"08BW026":["Kapışma Heveslisi","Çağrıldığımda, elini Savurursun ve Savurduğun her kart için bana +1|+1 kazandırırsın. 2 kart çekersin.","","''Üff, hadi ama ya. Elinden bu kadarı mı geliyor? Senin yüzünden kendimi ölçülü davranmak zorunda hissediyorum. En nefret ettiğim şey!''","Birim",[],["Bilgewater"],"ENDER"],"08BW028":["Ahtakâşif","Oyna: Seçtiğin bir Kâşif büyüsü elinde oluşur.","","''Tuhaf bir tür. Rengi masmavi. Gözler de pek bir kocaman. Epey cüssesi de var. Daha fazla gözlem için onu yanımıza alacağız.''\n- Kâşifler Loncası'nın Uzak Diyarlar Bölüğü'ne ait keşif gezisi kayıtlarından bir alıntı. Kayıtta bahsi geçen yer: Piltover","Birim",[],["Bilgewater","Piltover ve Zaun"],"ENDER"],"08BW009":["İhtiyar Serdümen","Oyna: Bu oyunda oynadığın iki farklı Elemental büyü Cisimlendirirsin. Bu tur bedelleri 0 olur.","","''Zihin bir nehirdir. Akıntının devamlılığı zaman geçtikçe dağların eteklerini şekillendirir. Tıpkı zihin gibi akıntı da ivme yakaladığında giderek genişler ve yeni kıyılara uzanır.''","Birim",[],["Bilgewater"],"ENDER"],"08BW010":["Tufan","Oyunun geri kalanı boyunca tüm Elemental büyülerin ve yeteneklerin fazladan 1 hasar verir.","","''Su, bilgelerin elinde her şeyi biçimlendiren bir kaynağa dönüşür.''\n- Bilgelik Yolcusu","Büyü",["ELEMENTAL"],["Bilgewater"],"DESTANSI"],"08BW031":["Derinlerin Musibeti Sefirsa","Başka bir birim oynamak için mana harcadığında, elinde bedeli o birimin bedeline denk rasgele bir kart oluşur. Bedeli 0 olur ve Geçici alır.","","Bilgewater'ın kıdemli kaptanları en garip deniz canavarlarını avlamaktan her ne kadar keyif alsa da bu sularda onların bile avlamaktan çekindiği bazı canavarlar yaşamakta. Güvertelerde adı yalnızca fısıltıyla ağza alınan Sefirsa adındaki canavar, insanı etkisi altında bırakan ışığıyla batırdığı sayısız geminin ve boğduğu denizcilerin arasında tüner.","Birim",["DENİZ CANAVARI","EJDER"],["Bilgewater"],"DESTANSI"],"08BW037":["Dürüst Krupiye","Bedeli benim Güç değerime eşit bir kart oynadığında +1|+1 kazanırım.","","''Biraz daha yatır sen, güven bana, harbi diyorum bak! Ne demişler, risk almayan eli boş döner. Bir de benden duymuş olma, bu gece bu masa bi' ayrı ballı. Üstelik bu mekânda kasanın öyle kimseyi dolandırdığı falan da yok, anam babam üzerine yemin ederim bak!''","Birim",[],["Bilgewater"],"ENDER"],"08BW036":["Marai Resif Tepeciği","Bir birim oynamak için mana harcadığında 1 büyü manası doldurursun.","","''Bu resif bize hem bir yuva hem de bir dost oldu. Balçık'ın karanlığına kurban gitmeyelim diye onu koruduğumuz gibi o da bizi koruyup kolluyor.''\n- Marai Büyük Ana","Yer",[],["Bilgewater"],"YAYGIN"],"08BW023":["Coşkun Vikrash","Çağrıldığımda destenin en üstündeki 6 kart arasında bir Akışkan oluşur.","","''Bakın dostlarım, bütün dünya nasıl da bizimle beraber sürükleniyor! Dalgalar gemiyle, rüzgâr yelkenlerle, kuşlar da esintiyle dans ediyor. Bu yüce çağrımızda bana katılın ve neşeyle dolun!''","Birim",[],["Bilgewater"],"DESTANSI"],"08PZ007":["Yelsesi Sürüsü","Bir Yelsesi Kırlangıcı çağırırsın ve bu oyunda oynadığın diğer her Elemental büyü ya da yetenek için ona +1|+1 kazandırırsın.\n1 kart çekersin.","","Yelsesi kırlangıçları sürüyle uçuyorsa fırtına yaklaşıyor demektir.","Büyü",["ELEMENTAL"],["Piltover ve Zaun"],"ENDER"],"08PZ031":["Tuhaf Gözlük","Bir dost takipçi seçersin. Kuşanıldığımda taşıyıcımı onun birebir kopyasına dönüştürürsün.","","Nasıl çalıştıklarını ne sen sor ne ben söyleyeyim.","Ekipman",[],["Piltover ve Zaun"],"ENDER"],"08PZ025":["Prototip Porobot","Son Nefes: Elindeki bedeli 6+ olan rasgele bir büyü ''Oynandığımda bir Prototip Porobot çağırırsın'' alır.","","Yangın laboratuvarın her yerine yayılırken ''O sadece bir prototip ya,'' diye bağırdı çırak, ''Ben onu gördüğü her dişliyi yiyecek şekilde programlamadım ki! Yuttuğu onca metalin nereye gittiğini bile BİLMİYORUM!''","Birim",["PORO"],["Piltover ve Zaun"],"ENDER"],"08PZ005":["Fırtınanın Gözü","Bir dost birime bu tur +2|+0 verirsin.\n2 kart çekersin.","","''Huzurundan ödün verme! Fırtınanın celalini etrafında hissetsen de onun sana zarar vermeyeceğini sakın unutma.''\n- Janna","Büyü",["ELEMENTAL"],["Piltover ve Zaun"],"YAYGIN"],"08PZ019":["İlahi Hortum","Bu tur 3+ kart çektiysen bedelim 2 azalır.\nBir birime 3 hasar ve rakibin Nexus'una 2 hasar verirsin.","","''Rüzgârın tüm gücü emrimde.''\n- Janna","Büyü",["ELEMENTAL"],["Piltover ve Zaun"],"ENDER"],"08PZ028":["Kimya Ejderi","Bir büyü oynadığında 1 kart çekersin. Elin doluyken kart çektiğinde, rakibin Nexus'una 1 hasar verirsin.","","Zaun'da hayatta kalmak için adaptasyon şart. Şehrin tekinsiz bölgelerinde dehşet kusan, yeşil renkli geliştirmelerle tabiatı değişmiş Kimya Ejderi de buranın kurallarına ayak uyduran canlılardan biri. Yozlaşmanın ıstırabından doğan bir hiddetin habercisi olan bu ejder, şehrin sokaklarını yıpranmış kanatlarının gölgesiyle karanlığa gömüyor.","Birim",["EJDER"],["Piltover ve Zaun"],"DESTANSI"],"08PZ001":["Janna","Oyna: 2 kart Savurarak sonraki Tur Başında 2 kart çekersin.\nHer tur, çektiğin ilk 3 kartın bedeli bu tur 1 azalır.","Bedeli azalmış 8 kart oynadığını gördüğümde.","''Janna, Zaun'u sevdiği kadar hiçbir yeri sevmez. Ne de olsa Piltover'ın ölüme terk ettiği zavallıları hep o kurtardı. Yani eğer bir şeylerin yanıtını almak istiyorsam kesinlikle doğru yerdeyim.''\n- Yeldoğan Denizci","Birim",[],["Piltover ve Zaun"],"Şampiyon"],"08PZ026":["Yelsesi Çağrısı","Bir Yelsesi Kırlangıcı çağırırsın.","","''Rüzgârın tüm evlatları çağrıma kulak verir.''\n- Janna","Büyü",["ELEMENTAL"],["Piltover ve Zaun"],"YAYGIN"],"08PZ006":["Derinlerin Başı Iascylla","Bir Elemental büyü ya da yetenek oynadığında, onu aynı hedeflere kopyalarsın.","","''Göster marifetini, Iascylla! Ashlesh bile seni tanıdığına göre gerçekten de kadim bir yaratık olmalısın. Ama kadimmiş, yeniymiş, güzelmiş, çirkinmiş hiç fark etmez. Bir canavar için açık denizin ortasında benim kılıcımla can vermek kadar onurlu hiçbir son yok.''\n- Nilah","Birim",[],["Piltover ve Zaun"],"DESTANSI"],"08PZ018":["Yeldoğan Denizci","Bu tur 3+ kart çektiysen bedelim 2 azalır.","","''Evet, vakti zamanında her şeye sahiptim. Ama sahip olduğum her şeyi başkalarından çalmıştım ve bu insanı kaybolmuşluğa sürüklüyor. Ben de bu yüzden kendimi rüzgârın kılavuzluğuna bıraktım. Gördüğün gibi işte buradayım ve onun beni doğru yola savuracağını umuyorum.''","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"08PZ008":["Tapınağın Koruyucusu Maryam","Oyna: 1 kart Savurarak 1 kart çekersin ya da büyü mananı doldurursun.","","Henüz küçük bir kızken rüzgâr ruhunun onu kurtardığına inanan Maryam, memleketi Shurima'dan Janna'nın erdemlerini insanlara anlata anlata Zaun'a kadar geldi. Şimdiyse Zaun tapınağının baş hanımı olarak günlerini çocuklara ve kimsesizlere Janna'nın lütuflarından bahsederek geçiriyor.","Birim",[],["Piltover ve Zaun"],"DESTANSI"],"08PZ009":["Batık Tapınak","Tur Sonu: Elini Savurursun.\nTur Başı: Destene karışan kartların 1 fazlası kadar kart çekersin.","","Zaun'un Piltover'dan ayrılmasına yol açan çökme faciasında sayısız kayıp yaşandı. Tapınağı dalgaların kurbanı olsa da Janna, orada dua eden herkesi kurtardı.","Yer",[],["Piltover ve Zaun"],"DESTANSI"],"08PZ002":["Uğultulu Kasırga","Bir birime 2 hasar verirsin.\nBu tur oynadığın diğer her kart için verdiğim hasarı en fazla 3 kere olmak üzere 1 arttırırsın.","","''Uğultulu rüzgârda öfkemi hissedin!''\n- Janna","Büyü",["ELEMENTAL"],["Piltover ve Zaun"],"ENDER"],"08PZ024":["Şarlatan Balıkçı","Tur Başı: TÜM oyuncular 1 kart çeker. Ardından rakibin çektiği karta Geçici kazandırırsın.","","''Bugüne özel iki al bir öde, gel vatandaş gel! Derya kuzusu bunlar. Mis gibi balıklar, sudan çıkalı daha... bir ay falan oldu herhalde? İki al bir öde! İkincisini istemiyorum ne demek be? Beleş diyorum beleş!''","Birim",[],["Piltover ve Zaun"],"YAYGIN"],"08PZ020":["Ulu Bulutyeli","Bu tur 3+ kart çektiysen bedelim 2 azalır.\nÇağrıldığımda, sonraki Tur Başında 2 kart çekersin.","","''Benim sevgili Meltem'im. Biraz bulutlarından insen de omzumda durup bana eşlik etsen, olmaz mı?''\n- Janna","Birim",[],["Piltover ve Zaun"],"ENDER"],"08FR012":["Fırtına Ayini","1 kart çekersin.\nBir Fırtına Mührü çağırırsın.","","''Valhir namına, bu adağı sunuyoruz...''\n- Valhir'in Elçisi","Büyü",["ELEMENTAL"],["Freljord"],"YAYGIN"],"08FR033":["Silah Müptelası Savaşçı","Tek bir dost birimi hedef alan Yavaş bir büyü oynadığında, o büyüyü bana kopyalarsın.","","''Birkaç okun beni durduracağını mı sandınız? Hah! Bana karşı doğrulttuğunuz her silah koleksiyonumun müstakbel bir parçası. Ölünce arkada bırakacağınız bütün silahlar elimde buzla yeniden şekil bulacak!''","Birim",[],["Freljord"],"YAYGIN"],"08FR019":["Bulutların Gazabı","Bir dost birime bu tur +1|+3 verirsin.","","Bulutların arasında saklanan ve etrafı yıldırımlarla çevrili ilah ayı, fırtınanın kalbinde tüm dokunulmazlığıyla heybetini konuşturur.","Büyü",["ELEMENTAL"],["Freljord"],"YAYGIN"],"08FR001":["Volibear","Oyna: 3 kere Ebedi Fırtına oynarsın. Her biri farklı rasgele bir düşmanı ya da hiç düşman yoksa rakibin Nexus'unu hedef alır.","Tur Sonu: 50+ hasar verdiğinde.","''Önümde diz çök fani, belki canını o zaman bağışlarım! Bir böcek kadar aciz olsan da belki bana hizmet etmeye layıksındır. Ya diz çök ya da yeryüzünden silinmeye hazır ol!''","Birim",[],["Freljord"],"Şampiyon"],"08FR018":["Devlerin Çarpışması","Rasgele 2 Devasa takipçi çağırırsın.\nBu oyunda oynadığın her Elemental büyü ya da yetenek için bedelim 1 azalır (en fazla 10).","","''Onun pullu bedeniyle dağlara şekil verdim. Gırtlağındaki alevlerle de bin tane fiyort yonttum.''\n- Volibear","Büyü",["ELEMENTAL"],["Freljord"],"DESTANSI"],"08FR011":["Ateşçağıran Kaprin","Bir Elemental büyü ya da yetenek oynadığında, beni İşlersin.","","''Ocağın Efendisi değişimi vaat etti ancak vaadini gerçekleştirmek yerine avarelik zincirlerini dövdü durdu. Böyle zayıf bir ilaha hizmet edenler de hâlâ onun zayıflığını paylaşmaya devam ediyor. Bizi mazinin heybetine ancak Valhir'in kudreti tekrar ulaştırabilir!''","Birim",[],["Freljord"],"ENDER"],"08FR008":["Fırtınaçağıran","Dost Devasa birimler dışındaki TÜM birimlere 4 hasar verirsin.","","''Bu toprakları kızıla boyayalım!''\n- Volibear","Büyü",["ELEMENTAL"],["Freljord"],"ENDER"],"08FR024":["Yadulsk Karköpeği","Saldır: Destenin en üstündeki 2 dost birime +1|+1 kazandırırsın.","","Kökenleri Yadulsk'a dayanıyor olsa da bu yavrular birçok Freljord kabilesi tarafından iz sürmeleri, avlanmaları ve çığ sonrası arama kurtarma görevleri için eğitildi. Hem güçlü cüsseleri hem de sevimli davranışları sayesinde karla kaplı ormanlardan buz gibi tundralara kadar tüm bölgelerdeki kabilelerin zamanla sevilen üyeleri haline geldiler.","Birim",["KÖPEK"],["Freljord"],"YAYGIN"],"08FR015":["Magma Yılanı Rhond","Oyna: 3 Fırtına Mührü çağırırsın.","","Volibear'e hizmet edenlerin sayısı azalsa da tüm Freljord halkı onun Rhond'la olan destansı savaşının hikâyesini bilir. Buz tutmuş kuzeye faniler ayak basmadan çok uzun zaman önce, bu ikilinin yeri göğü sarsan mücadelesi tundrada dere ve tepelerin oluşmasına yol açtı.","Birim",[],["Freljord"],"DESTANSI"],"08FR030":["Kara Buz Canavarı Boadir","Çağrıldığımda 2 Donuk Köle çağırırsın ve onları 2 tur kalıncaya kadar ilerletirsin.","","''Yeminlen öyle vahşiydi ki! Köleleri kapkara buzla yakardı. Pençelerinin arasından çığlar düşer ve kükreyişi dağlardaki tüm karı silip süpürürdü! Anlayacağınız o bi' savaşçı kraliçeydi! Zaten köleleri öldürmek anca savaşçı\nkraliçelere has bi' şey.''\n- Ödü Kopmuş Bjerg","Birim",["EJDER"],["Freljord"],"DESTANSI"],"08FR002":["Valhir'in Elçisi","Çağrıldığımda bir Fırtına Mührü çağırırsın.","","''Kimselerin göremediğini görüyorum; dağı paramparça edecek fırtınayı, yeryüzünün kırılan kemiklerini hissediyorum. Ezeli diyar Freljord'un kanla yeniden şekillenmesi an meselesi.''","Birim",[],["Freljord"],"YAYGIN"],"08FR028":["Sağlam Teçhizat","Bu oyunda çağırdığın her farklı alt tip için +1|+0 alırım.","","''Burada bir çığın bile durduramayacağı canavarlar kol geziyor. İşte böyle durumlarda paraya kıyıp sağlam teçhizatlar almak gerek.''\n- Avarosa Tuzakçısı","Ekipman",[],["Freljord"],"DESTANSI"],"08FR003":["Gözü Dönmüş Ursin","Bir büyü ya da yetenek oynadığında, bir Fırtına Mührü çağırırsın.","","Zaman zaman Volibear'in müritleri kendilerini inançlarında öyle bir kaybederler ki bir anda ayının ta kendisi gibi davranmaya başlarlar. Böylece Ursinlerin bir zamanlar dost saydıkları hemşerilerinin bile Valhir'in iradesi karşısında duramayacağını herkese gösterirler.","Birim",[],["Freljord"],"ENDER"],"08RU014":["Kadim Ejderha","Köken: Ejderha Sureti.\nBu oyunda oynadığın her farklı Ejder Lütfu için bedelim 1 azalır.\nOyna: Her Ejder Lütfunu benim üzerimde oynarsın.","Dost birimlerin toplam 75+ Güç değeriyle saldırdığında.","''Efsaneye göre bu yaratık bütün ejderlerin en yaşlısı ve kanatlı canavarların kralıymış. Bir düşünsene Alatis... onu ehlileştirebilirsek artık karşımızda kimse duramaz. Böylece tüm dünya insanlarla ejderlerin birlikte daha güçlü olduğunu sonunda anlar.''\n- Ejder Dostu Volix","Birim",["EJDER"],["Runeterra"],"Şampiyon"],"08NX003":["Öfkeli Ateşpüskürten","Oyna: Bir düşmana 2 hasar, rakibin Nexus'una 2 hasar verirsin.","","Noxus'luların genişleme politikası imparatorluk sınırlarına bu zamana kadar pek çok farklı halkı, yerleşkeyi ve kültürü kattı. Yabani canlıların hayatıysa çoğu zaman Noxus askerlerinin merhametine kaldı. Tabii söz konusu canlı bu ejder olduğunda durum başka zira Noxus birliklerinin her saldırgan hamlesi kendilerininki kadar haşin bir öfkeyle karşılanıyor.","Birim",["EJDER"],["Noxus"],"DESTANSI"],"08NX024":["Demir Lejyoner","Oyna: Bir dost birime 3 hasar vererek bir düşmana 3 hasar verirsin.","","''Ruhlarını beden dedikleri kafesten söküp atın!''\n- Mordekaiser","Birim",[],["Noxus"],"ENDER"],"08NX011":["Sönmeyen Yangın","Rakibin Nexus'una 1 hasar verirsin. Bu oyunda oynadığın diğer her Sönmeyen Yangın için hasar 1 artar. Destende bir Sönmeyen Yangın oluşur.","","''Annie ateş yaktı...''\n- Annie","Büyü",["ELEMENTAL"],["Noxus"],"YAYGIN"],"08NX028":["Yıkılmaz","Bir dost birime Ölümsüz kazandırırsın.","","''Ebedi demir.''\n- Mordekaiser","Büyü",[],["Noxus"],"YAYGIN"],"08NX019":["Al Dikenli Jiletgürz","Nexus Vuruşu: Rakibini Nezif etkisiyle Lanetlersin.","","Jiletgürz, Noxus taarruzu için önemli olduğu kadar başkentteki dövüş arenalarında da rağbet görüyor. Ama insan ama hayvan, pek az canlı bu canavarla yüzleşebilecek cesarete sahip olduğundan Jiletgürz'ün savaştığı dövüşler çok nadir gerçekleşiyor. Tabii gerçekleştiği zaman da şehrin dört bir yanından tüm halkı arenaya topluyor.","Birim",["SÜRÜNGEN"],["Noxus"],"YAYGIN"],"08NX014":["Müdire Telsi","Dost birimlerin Saldır ve Destekle etkileri fazladan bir kez daha tetiklenir.","","Müdire Telsi'nin kişisel disiplinle ilgili dersi yorucu ödevler, cetvelli dayaklar ve türlü cezalarla geçiyor. İşin kötü tarafı bu ders Ravenbloom Konservatuvarı'ndaki tüm öğrenciler için zorunlu. Zorunlu olmasaydı kimse dersin yüzüne bile bakmazdı.","Birim",[],["Noxus"],"DESTANSI"],"08NX012":["Donanımlı Hazine Avcısı","Oyna: Seçtiğin bir Kâşif büyüsü elinde oluşur.","","''Neymiş efendim, çölde kazı yapmak çok basitmiş. Peh, külahıma anlat! Azıcık zaman geçince kumlar oluyor sana semsert kaya. Bir kez daha düzgün alet edevat için fon talep ediyorum.''\n- Kâşifler Loncası'nın Uzak Diyarlar Bölüğü'ne ait keşif gezisi kayıtlarından bir alıntı. Kayıtta bahsi geçen yer: Shurima","Birim",[],["Noxus","Shurima"],"ENDER"],"08NX029":["Kashuri Pençesi","Bir birim hasar almışsa onu öldürürsün, almamışsa ona 2 hasar verirsin.","","''İnan bana, bu senin iyiliğin için.''\n- Yeleli Lord","Büyü",[],["Noxus"],"DESTANSI"],"08NX009":["Lord Mallat","","","''O korkunç caniyi ancak yüzyıllar süren derin planların ardından hapsedebildik. Sen de gelmiş bana, sen ve dostlarının onu 'neşeyle' yenebileceğini mi söylüyorsun? Seni ahmak kız. Yapmaya çalıştığın şey Hortlak'ı öfkelendirip hepimizi tehlikeye atmaktan başka bir işe yaramayacak.''","Birim",[],["Noxus"],"YAYGIN"],"08NX025":["İhanete Uğramış Hortlak","Bir dost birim dirildiğinde, ona Rakipçeker kazandırırsın.","","''Gülüyorsun ama ben alçak kalbinin derinliklerinde yatan hakikati biliyorum! Daha önce de yüzüme güldüler, gelip soframa bile oturdular. Üstelik bütün bunları beni sırtımdan bıçaklayacaklarını bile bile yaptılar. Artık bir aptal yerine konmayacağım. Sen de diğerleri gibi af çığlıklarınla öleceksin!''","Birim",[],["Noxus"],"ENDER"],"08SH009":["Kadim Bela","Bir düşmanı Dehşet etkisiyle Lanetlersin.","","Bazı şeylerin kumların altında kalması gerekir.","Büyü",[],["Shurima"],"YAYGIN"],"08SH014":["Boynuzlu Sürüçağıran","Oyna: İki düşmana -1|-0 kazandırırsın ve faydalı tesirlerini devre dışı bırakırsın.","","Sürüçağıran, muazzam cüssesine rağmen nadiren saldırgan davranışlar gösterir. Sürüsü bir Shurima köyüne yaklaştığında, köy sakinleri bu davetsiz misafirlerin dikkatini daha önemli mahsullerden uzaklaştırabilmek için civardaki bir çöle çeşitli yemişlerden oluşan adaklar bırakır.","Birim",["EJDER"],["Shurima"],"YAYGIN"],"08SH004":["Kumulların Komutanı","Şafak'ta veya başka bir Şafak etkinleştirdiğinde: En Güçsüz düşmana Kırılganlık kazandırırsın.","","Shurima'nın engin ordusu çölün kudretini kanıtlamak için her daim hazır ve nazır bekler. Emir verildiğindeyse tereddüt etmeden ilerlerler.","Birim",["SEÇKİN"],["Shurima"],"ENDER"],"08SH005":["Güneş Kursu'nun Nöbetçileri","Şafak: Bir Güneş Kursu'nun Nöbetçileri çekersin.","","''Biz uçsuz bucaksız bu çölün koruyucularıyız, tarihin canlı miraslarıyız, aydınlığın yolunda ilerleyenleriz. Biz yalnızca Güneş Kursu'nun karşısında diz çökeriz ve tüm dünyaya da Shurima'nın görkemi karşısında boyun eğdiririz.''\n- Azir","Birim",["SEÇKİN"],["Shurima"],"YAYGIN"],"08SH012":["Mezar Yağmacısı Eflatun","Her tur, ilk defa başka bir dost birim öldüğünde ya da Son Nefes: Elinde bir Şanslı Keşif oluşur.","","''Cepleri doldurmuşsun, Eflatun. Sana güvenebileceğimi biliyordum. Ne... ne dedin? Ne demek seni gördüler?!''\n- Vekaura'lı Kötekçi","Birim",["SÜRÜNGEN"],["Shurima"],"ENDER"],"08SH002":["Kumul Yutan","Beni oynamak için 3 kere bir dost birimi öldürürsün ya da bir mana taşını yok edersin.","","Kumul Yutanlar kendilerinden ufak olan xer'sai hısımlarına göre çok daha derinlerde yaşarlar. Öteki xer'sai avcılarını kolayca midesine indiren bu canlılara ait kayıtlar oldukça az. Tabii bunun sebebi onları bizzat görebilen herkesi kumullarla birlikte tek lokmada yutabilmesi olabilir. ","Birim",[],["Shurima"],"DESTANSI"],"08MT003":["Morgana","Oyna: Bir düşmanı Pranga etkisiyle iki kez Lanetlersin.","Birimleri 10+ kere hedeflediğinde.","''Kapıma yara bere içinde geldin ama ben hayatımda seninki kadar mutlu bir yüz görmedim. Çok tuhaf bir kadınsın gerçekten. Neyse burada güvendesin. Şimdi lütfen dinlen. Kendini daha iyi hissettiğinde hikâyeni dinlemeyi çok isterim.''","Birim",[],["Targon","Demacia"],"Şampiyon"],"08MT005":["Yükselen Suret Mihira","Oyna: 2 düşmanı Pranga etkisiyle iki kez Lanetlersin.","","''Bu kutsal vazifeyi kızlarım adına aldım. Ailem için insanlığımdan feragat ettim ve kendimi bu yanan kılıçla hakikat ve adalet dolu yeni bir dünya kurmaya adadım.''","Birim",[],["Targon"],"DESTANSI"],"08MT042":["Günahkârın Kıskacı","Bir düşmanı Pranga etkisiyle Lanetlersin.\nHer yerdeki düşman Lanetlerinin bedeli 1 artar.","","''Hürriyete kavuşmak için karanlığı kucaklamalısın.''\n- Morgana","Büyü",[],["Targon"],"ENDER"],"08MT024":["Yakut Gözlü Büyücü","Oyna: Elindeki bir dost birime Büyü Kalkanı ya da Aban kazandırırsın.","","''Sakın korkmayın! Devam edin ve asla arkanıza bakmayın! Biz de bu yollardan geçtik. Artık sizi korumak bizim vazifemiz. Oyalanmadan onun sığınağına gidin ki Peçeli Kadın sizi de koruması altına alsın.''","Birim",[],["Targon"],"YAYGIN"],"08MT045":["Prangalı Büyücü","Oyna: Beni Pranga etkisiyle Lanetlersin.","","İnsanların iradesini kırmakta uzman olan Sihir Avcıları onun ellerini bağlayıp sihrini kısıtladılar. Ondan sesini çaldılar. Ancak o, Sihir Avcılarının işkencelerinden daha önce sağ çıkmıştı ve yine çıkacaktı çünkü bu kez Peçeli Kadın onun tarafındaydı.","Birim",[],["Targon"],"ENDER"],"08MT015":["Lisa ve Dolly","Oyna: Bir düşmanı Pranga etkisiyle Lanetlersin.","","''Bak, Dolly! Tıpkı öğrettiğin gibi yapıyorum! Sence annemiz ne kadar öğrendiğimi görebilecek mi? Yoksa zaten biliyor mudur? Oley, gerçekten mi? Umarım haklısındır ya.''\n- Lisa","Birim",[],["Targon"],"YAYGIN"],"08MT030":["Nazik Cevher Ejderi","Hızlı bir büyü, Yavaş bir büyü ya da Yetenek oynadığında, diğer dost Ejderlere +1|+1 kazandırırsın.","","Ejder türleri görünüşlerinde olduğu kadar davranışlarında da çok çeşitliliğe sahipler. Alev Ejderleri gibi her şeyi yakıp yıkan türler olduğu kadar tam aksine hısımlarını ve yaşadığı çevreyi koruyan ağır hareketli ve sevgi dolu Cevher Ejderi\ndiye bir tür de var.","Birim",["EJDER"],["Targon"],"ENDER"],"08MT023":["Karanlık Esaret","Bir düşmanı Sersemletirsin ve Pranga etkisiyle Lanetlersin.","","''Onlara çektirdiğin ıstırabın tadına bak!''\n- Morgana","Büyü",[],["Targon"],"ENDER"],"08MT031":["Ejder Hizmetkârı Ottrani","Çağrıldığımda Nexus'unu 2 iyileştirirsin ve sonraki tur fazladan bir mana taşı alırsın.","","Targon'un en yüksek yamaçlarında hayatını ejderlere adamış yalnız bir Ottrani yaşamaktadır. Onların dökülmüş pullarına ve eski kemiklerine bürünmüş bu yabancı, yazgısını ejderlerin dişleriyle saçtığı yıkımda ve dağın tepesine doğru kıvrılarak yükselen dumanlarda arar.","Birim",[],["Targon"],"DESTANSI"],"08MT009":["Mistik Koruyucu","Çağrıldığımda ya da Devasa bir dost birim çağırdığında, Nexus'un 3 iyileşir.","","Mistik Koruyucu kendisini basit bir hayvandan öteye taşıyan lütfu asla unutmuyor ve minnet borcunu, Targon'a giden basamaklarda sığınak arayan gezginleri sağ salim hedeflerine ulaştırarak ödüyor.","Birim",[],["Targon"],"ENDER"],"08MT006":["Kara Kalkan","Bir dost birime bu tur Büyü Kalkanı verirsin ve onu Pranga etkisiyle Lanetlersin.","","''Kayıtsız nefretten korun!''\n- Morgana","Büyü",[],["Targon"],"ENDER"],"08MT027":["Semavi Akının Habercisi","Oyna: Diğer dost birimlerin Şafak ve Akşam etkilerini devreye sokarsın.\nŞafak: Bana Aban kazandırırsın.\nAkşam: Bana Büyü Kalkanı kazandırırsın.","","''Tepemizde bir ateş çemberi yanar durur. Öngörülen karanlıkta kimse kimseden farklı değildir.'' \n- Lunari Karanlıksöyleyen","Birim",["KUŞ"],["Targon"],"DESTANSI"],"08MT025":["Sismik Parça","Devasa bir birime Tanıklık ettiysen bedelim 3 azalır.\nBir birime 7 hasar verirsin.","","''Haydaa, uff, nemse yaa hiç meyak etmeyin siz, miniminiminnacık bi' taş düşüveydi, öyle kazaylan, babam felan HİÇBİ' ŞEY YAPMADI YANİ! Nemse yaa hadi devam ediyoz!''\n- Taşkın","Büyü",["ELEMENTAL"],["Targon"],"YAYGIN"],"08DE006":["Âlim Kâşif","Oyna: Seçtiğin bir Kâşif büyüsü elinde oluşur.","","''Hava buz gibi. Tir tir titriyorum. Neden her yer hep buz gibi? Bazı bölgeler insanların yaşamasına hiç elverişli değil. Lütfen beni sonraki sefere daha ılıman bir yere gönderin.''\n- Kâşifler Loncası'nın Uzak Diyarlar Bölüğü'ne ait keşif gezisi kayıtlarından bir alıntı. Kayıtta bahsi geçen yer: Freljord","Birim",[],["Demacia","Freljord"],"ENDER"],"08DE020":["Büyülü Zincir","Bir dost birime +0|+2 kazandırırsın. Rakibini Baskı etkisiyle Lanetlersin.","","''Günahlarının ağırlığını hisset!''\n- Morgana","Büyü",[],["Demacia"],"YAYGIN"],"08DE017":["Amir Sihir Avcısı","Çağrıldığımda rakibini Baskı etkisiyle Lanetlersin.","","''Ne pahasına olursa olsun düşmüş kız kardeşin sığınağına ulaşmalarına izin veremeyiz. Zira onun büyüsü o kadar kadim, o kadar sapkındır ki onu ben bile zapt edemem. Çabuk, şu ucubeleri gemiye geri yükleyin ve kalanları da almak için dağa doğru gidin!''","Birim",[],["Demacia"],"ENDER"],"08DE025":["Bulut Ejderi","Çağrıldığımda elindeki tüm dost birimlerin bedeli 1 azalır.","","Soğuğa karşı direnç sağlayan yoğun ve sık bir kürke sahip bu ejder, diğer çoğu türdeşinden çok daha yükseklerde uçabiliyor. Zeki ve bir o kadar da çevik olan bu ejderler, göklerde bulutları fırtınalar ve boralar eşliğinde kanatlarıyla yarıp geçerken görülüyor.","Birim",["EJDER"],["Demacia"],"DESTANSI"],"08DE010":["Centilmen Düellosu","Bir dost birime bu tur +0|+2 verirsin.\nBu dost birim ve bir düşman birim birbirine vurur.","","''Gardını al, dostum! Herhalde bir centilmenin düello teklifini geri çevirecek kadar korkak değilsindir, öyle değil mi?''\n- Züppe Laurent","Büyü",[],["Demacia"],"YAYGIN"],"08DE022":["İskelekuşu","Çağrıldığımda destendeki her şampiyondan 1'er tane çekersin.\nHer tur ilk defa bir şampiyon çağırdığında Silahlanırsın.","","''Unutma oğlum, uğruna mücadele ettiğin her gaye ardında bıraktığın yuvaya hizmet etmek için olmalıdır.''\n- Kral Jarvan III","Birim",[],["Demacia"],"DESTANSI"],"08DE027":["Pençe Saldırısı","Her yerdeki dost Kuşlara +1|+1 kazandırırsın. Dost bir Kuş bir düşmana vurur.","","Gümüşkanadın çığlığı göklerden gelen ölümün habercisidir.","Büyü",[],["Demacia"],"ENDER"],"08DE026":["Cesur Alatis","Ejder Lütufların tüm dost Ejderleri hedefler.","","''Açıkçası her zaman ejderlere bu kadar düşkün değildim. Ta ki Alatis benim hayatımı ilk defa kurtarana kadar. O zamandan bu yana bana çok şey öğretmiş olsa da en önemlisi neydi biliyor musun? Demacia'ya bir ejderin sırtında hizmet etmek gibisi yok.''\n- Ejder Tutkunu","Birim",["EJDER"],["Demacia"],"DESTANSI"],"08DE013":["Ejder Dostu","Çağrıldığımda bir Ejdere Tanıklık ettiysen bir Ejder çekersin.","","''Ben de bu durumdan hoşnut değilim moruk ama onu yalnız başımıza zapt edemiyoruz. Elimizden geleni yaptık zaten. Generale haber veriyorum. Ancak Demacia'nın emsalsiz kudretiyle bu muazzam yaratığı dize getirebiliriz.''","Birim",[],["Demacia"],"YAYGIN"],"08IO012":["Okyanus Ejderi","Hızlı bir büyü, Yavaş bir büyü ya da Yetenek oynadığında, Nexus'unu 1 iyileştirirsin.","","''Ne muazzam bir yaratıksın sen öyle! Pençelerinin yardığı dalgalar âdeta saadet saçıyor. Olur da balıklardan ve martılardan daha fazlasını avlamak istersen seninle yüzleşmekten büyük mutluluk duyarım.''\n- Nilah","Birim",["EJDER"],["Ionia"],"ENDER"],"08IO014":["Dünyanın Kabuğu Heisho","Her tur, oynayacağın ilk kartın bedeli 9 azalır.","","Bu Ionia köyündeki sakinler için Heisho hem saygın bir koruyucu hem de şefkatli bir dost. Köyün tüm sakinleri ezelden beri evlerini sırtlayan bu köyün taşıyıcısının zor zamanlarda huzur dolu kıyılara doğru yol alacağına canı gönülden güveniyor.","Birim",["SÜRÜNGEN"],["Ionia"],"DESTANSI"],"08IO021":["Arşejderinin Dansı","Bir Hızlı ya da Yavaş düşman büyüsünü veya düşman Yeteneğini durdurursun. Bir düşmanı Geri Gönderirsin ve Arşejderi kartını çağırırsın.","","''Bu dansımız bizi baki kılacak.''\n- Irelia","Büyü",[],["Ionia"],"ENDER"],"08IO019":["Güvenilir Adnere","Çağrıldığımda Adnere'in Kuşçuları çağırırsın.","","''Bu diyarın her köşesinde ayrı bir ders yatar. Şunu unutma: Bir mevsime veda ederken mutlu olmak gerekir zira yeni bir başlangıç ancak bir sondan doğar.''","Birim",[],["Ionia"],"ENDER"],"08IO010":["Alabora","Bir düşmanı Geri Göndererek bu tur rakibin oynayacağı bir sonraki birimin bedelini 2 arttırırsın.","","''Bize kötülük edenlerin sonu denizin dibini boylamak olur.''\n- Nehirbüken","Büyü",["ELEMENTAL"],["Ionia"],"YAYGIN"],"08IO023":["Zıpır Deniz Ruhları","Oyna: Benim birebir Hayali bir kopyamı çağırırsın.","","Yılın belirli zamanlarında, denizlerin üstünde yellerin hüküm sürdüğü anlarda bazı Zaun'lular solungaçlı iki yaratığın okyanus dalgaları eşliğinde neşeyle dans ettiğini ısrarla söyler durur.","Birim",[],["Ionia"],"YAYGIN"],"08BC020":["Erkenci Kuş","Rakibin, en yüksek bedelli kartını atar.","","''Düşünsene, bi' solucansın, tamam mı? Ve ölmeden önce son gördüğün şey şu gözler... Ne dedin? Ha, solucanlar göremiyor mu? Eh, o zaman ne mutlu onlara.''\n- Suratsız Gezgin, Elle","Büyü",[],["Bandle Şehri"],"YAYGIN"],"08BC005":["Tıkabasa Dolu Çanta","Bu oyunda oynadığın her Tıkabasa Dolu Çanta için kendi destene 4 tane Tını ve rakibin destesine 4 tane Zehirli Pofkep Mantarı koyarsın. Destende bir Tıkabasa Dolu Çanta oluşur.","","''207. kural: Bir izci yanında asla ihtiyacı olandan fazlasını taşımaz!''\n- Ava Naptınama","Büyü",[],["Bandle Şehri"],"ENDER"],"08BC021":["Gizli Değişim","Bir dost birimi Geri Gönderirsin ve yerine bir Aç Puhukedi çağırırsın.","","''CİYYYK?''\n- Puhukedi","Büyü",[],["Bandle Şehri"],"ENDER"],"08BC002":["Resifin Kralı Koral","Oyna: Rakibin elinden şampiyon olmayan iki karttan birini seçersin. Seçtiğin kartı Zapt Ederim.","","''Doğru bildin. Hem yakışıklıyım hem hızlıyım hem de acayip havalıyım. Hâlâ anlamadın mı moruk? Bu resifin kralı benim ve sen krallığıma izinsiz ayak basıyorsun!''\n''Du-Dur! Derhal buraya gel! Araştırmalarım için o numune bana lazım!''\n- Kabukolog","Birim",[],["Bandle Şehri"],"DESTANSI"],"08BC006":["Geçit Kâşifi","Oyna: Seçtiğin bir Kâşif büyüsü elinde oluşur.","","''Püsküllü beni endişelendiriyor! Bugünlerde hepten stresin kollarına bıraktı kendini. Minnacık bir geçit yolculuğunda bile gerginliğe kapılıyor! Nedenini anlayabilmiş değilim.''\n- Kâşifler Loncası'nın Uzak Diyarlar Bölüğü'ne ait keşif gezisi kayıtlarından bir alıntı. Kayıtta bahsi geçen yer: Bandle Şehri","Birim",["YORDLE"],["Bandle Şehri","Ionia"],"ENDER"],"08BC004":["Garip Geçitaçan","Oyna: Devasa bir takipçi Cisimlendirirsin. Nitelikleri 1|1 ve bedeli 0 olur.","","''Bizim Geçitaçan'ı bilmez miyim! Azıcık kafadan kontak olsa da göz açıp kapayıncaya kadar seni geçitle istediğin yere gönderebilir. Şöyle kuyruğunu salladı mı, bir bakmışsın çoktan başka bir yerdesin!''\n- Geçit Kâşifi","Birim",["EJDER"],["Bandle Şehri"],"DESTANSI"],"08BC018":["Pasta Kapanı","Bir dost birimi destenin en altına koyarak destenin en üstündeki dost birimi çağırırsın.","","''571. kural: Bir izci her daim gözünü dört açmalı. Neticede neyin leziz bir atıştırmalık, neyin tuzak olduğunu\nkim bilebilir ki!''\n- Ava Naptınama","Büyü",[],["Bandle Şehri"],"ENDER"],"09SI015":["Tatlı Felaket","I: Güç ve Can değerleri toplamı 5 ya da daha az olan bir birimi öldürürsün.\nII: Rakibin Nexus'una 2 Sömürü hasarı verirsin.\nIII: Bir dost birimin birebir kopyasını çağırırsın. Kopya Hayali ve 1|1 olur.","","Elinde kırışmış şiiriyle sahnenin basamaklarına tırmanıyordu. Bu gösterisi için hiçbir yere ilan ya da reklam vermemişti zira gelmesini istediği seyirci zaten buradaydı.","Yer",["HİKÂYE"],["Gölge Adalar"],"DESTANSI"],"09SI013":["Demir Fetih","I-II: Bir dost takipçi seçersin. Elinde Hayali bir kopyası oluşur ve kopya +1|+1 alır.\nIII: Ölmüş olan En Güçlü dost takipçiyi diriltirsin ve ona Hayali kazandırırsın.","","Gri Diyar'da ıstırap içindeki varlıklar bir araya gelir ve bir hayalet ordusu meydana getirir. Faniler diyarının kapıları açıldığında bu orduyu hiçbir şey durduramaz.","Yer",["HİKÂYE"],["Gölge Adalar"],"ENDER"],"09SI012":["Varoluşsal Sancılar","Düşmanlara Kasvet kazandırırsın.","","''Hayat ne kadar boş ve sıkıcı.''\n- Vex","Büyü",[],["Gölge Adalar"],"ENDER"],"09SI017":["Kharox","Dokunaç olmayan bir dost birim öldüğünde ya da Son Nefes: 2 Dokunaç Çıkarırsın.","","Pek çok denizcinin Son Tekne adını verdiği hayalet geminin yalnız kürekçisi olan Kharox'un, Gölge Adalar'a ulaşmaya çalışırken harap olan bütün denizcilerin ruhlarıyla konuşabildiği söylenir.","Birim",[],["Gölge Adalar"],"DESTANSI"],"09SI014":["Buhran","Oyna: Bir birime 4 Kasvet kazandırırsın.","","Karanlık bir romantik, melankolik bir şair ve felsefi konuların üstadı olan Buhran biraz kasvet ve bunalımdan asla kaçmıyor. Genelde karamsar ve içedönük kişilerden hoşlanıyor çünkü böylelerinin sevgisini daha çok hak ettiğini düşünüyor.","Birim",["YORDLE"],["Gölge Adalar"],"YAYGIN"],"09DE033":["Yavru Peri","","","''Yavru Periler o kadar muazzam yaratıklar ki... Bu miniklere zaman tanıyıp onları doğru düş sahiplerine yönlendirirsen içlerindeki potansiyeli görebilirsin!''\n- Peri Anne","Birim",[],["Demacia","Ionia"],"YAYGIN"],"09DE039":["Demacia'nın Işığı","I: Bir dost birime Cesaret kazandırırsın.\nII: Bir dost birime 2 Cesaret kazandırırsın.\nIII: Tüm dost birimleri Körüklersin.","","Kendisine bakan yüzler onun ışığıyla aydınlanıyor, kalabalıktan alkışlar yükseliyordu. O her daim halkına umut aşılamaya ve onları desteklemeye çalışmıştı. Şimdiyse halkı onu destekliyordu ve sevgi dolu tezahüratlarla bunu gösteriyordu: ''Luxanna! Luxanna! Luxanna!''","Yer",["HİKÂYE"],["Demacia"],"ENDER"],"09DE034":["Lux: Aydınlık","Destekle: Desteklediğim dost birim Cesaret kazanır ve ben bu tur Bariyer alırım.","Dost birimler toplam 20+ faydalı tesirle saldırdığında ya da saldırırken bu sayıda tesir kazandığında.","Işık huzmeleri Luxanna'nın etrafında dolaşıp oradan oraya sıçrarken şehir halkı ona hayranlıkla bakıyordu. Burada o Demacia'lıların Işığın Hanımı olarak tanıdığı, Crownguard ailesinin genç bir ferdi ve yetenekli bir büyücüydü. Burada Demacia hayallerindeki gibiydi.","Birim",[],["Demacia"],"Şampiyon"],"09DE047":["Unutulmuş Yadigâr","Bir Kumtaşı Savaşçı çağırırsın, ardından dost birimlere bu tur Rakipçeker verirsin.","","Gasp edilen sihirli nesnelerle dolu Sihir Avcısı mahzenlerinin derinliklerinde unutulmaya yüz tutmuş isimsiz bir heykel saklı...","Büyü",[],["Demacia"],"ENDER"],"09DE041":["Petrisit Salon","I: Bir dost birim, bir birimi Zapt Eder.\nII: Rakibini Baskı etkisiyle Lanetlersin.\nIII: Dost birimler tarafından Zapt Edilen tüm kartların Kökünü Kazırsın.","","Salona girdiğinde kalabalığın sesleri iyice azalmıştı. Heykeller sükûnet içinde hareketsiz duruyordu. Onu burada yalnızca karanlık bekliyordu ancak artık geri dönemezdi. Zira Demacia'nın kâbusa sürüklenmesini yalnızca o engelleyebilirdi.","Yer",["HİKÂYE"],["Demacia"],"DESTANSI"],"09DE030":["Akkor","Tüm birimleri Körüklersin.","","''Işığımız kimseye boyun eğmez!''\n- Lux: Aydınlık","Büyü",[],["Demacia"],"YAYGIN"],"09DE043":["Yükselen Işık","Tüm birimleri 3 kere Körüklersin.","","''Işığa kucak açın!''\n- Lux: Aydınlık","Büyü",[],["Demacia"],"ENDER"],"09DE031":["Jarro Lightfeather","Oyna: Elindeki bir dost birime Cesaret kazandırırsın.","","Karşısında çok sayıda gül yaprağı ve parlak canlıların eşliğinde maskeli genç bir adam belirmişti. ''Adım Lightfeather,'' dedi adam, ''Jarro Lightfeather ve duyduğum kadarıyla biraz yardıma ihtiyacınız varmış, leydim?''","Birim",[],["Demacia"],"ENDER"],"09DE046":["Karizmatik Tebessüm","2 dost birimi Körüklersin, ardından bu dost birimler sırayla bir düşmana vurur.","","''Sakin olun, hanımlar. Ben hepinize yeterim.''\n- Jarro Lightfeather","Büyü",[],["Demacia"],"YAYGIN"],"09DE045":["Düş Işığı Alina","Çağrıldığımda 5 Yavru Peri çağırırsın. Tahtaya sığmayan her biri için bunun yerine En Güçsüz dost birimine 2Cesaret kazandırırsın.","","''Senin yaşındayken bu ışıktan çok korkardım. Bana sahip olduğum bu sihrin bir armağan olduğunu ve bir amaçla bana bahşedildiğini söyleyecek kimsem yoktu. Ancak ben sana bunları söylemek için yanındayım. Sakın korkma, Alina. Işığının parlamasına izin ver.''\n- Lux: Aydınlık","Birim",[],["Demacia"],"DESTANSI"],"09DE040":["Tuhaf Sihir Avcısı","Çağrıldığımda diğer dost birimlere Cesaret kazandırırsın.","","''Leydi Crownguard.'' Sihir Avcısı gölgelerin arasında belirmiş, ona doğru elini uzatıyordu. Maske yüzünün yarısını kapatsa da mütevazı gülümsemesi fark ediliyordu. ''Beni takip etmenizi rica edeceğim.''","Birim",[],["Demacia"],"YAYGIN"],"09DE036":["Ağaç Perileri","Oyna: Diğer tüm birimleri Körüklersin.","","''Hadi bakalım, minik periler. Düş sahibine yolu gösterin.''\n- Lillia","Birim",[],["Demacia","Bandle Şehri"],"YAYGIN"],"09DE029":["Işık Perisi","Destekle: Desteklediğim dost birim bu tur tüm faydalı tesirlerimi yükleriyle birlikte alır.","","''Hadi, Peri Amca. Bu ürkütücü gölgeleri birlikte savalım!''\n- Düş Işığı Alina","Birim",[],["Demacia"],"ENDER"],"09SH010":["İmparatorluğun İnşacısı","Oyna: Dost bir Yer kartına ''Yok olduğumda beni diriltirsin'' kazandırırsın.","","İmparator'un yükselişi Shurima'nın dört bir yanında umudun yeşermesini sağladı. Azir'in hayalinin gerçekleşmesini isteyen bu büyücü, kendine ''İmparatorluğun İnşacısı\" diyor ve gömülü harabeleri onarıp eski heybetli günlerine geri döndürmek için çölü karış karış geziyor.","Birim",[],["Shurima"],"YAYGIN"],"09SH009":["İmparatorun Ordusu","I: 2 Kumdan Asker çağırırsın.\nII: Öngörüde bulunursun.\nIII: Bu tur bir dost birim çağırdığında ona bu tur +2|+0 verirsin.","","Azir, Shurima'yı olduğu ve olacağı haliyle bilir. Geleceğe dair vizyonunun bir hayalden fazlası olduğuna inanır zira onun için bu gelecek kaderinde yazılı bir kehanettir.","Yer",["HİKÂYE"],["Shurima"],"DESTANSI"],"09SH012":["Gündoğan Çağrısı","Destende başlamış 3 şampiyondan birini seçerek onu çekersin.","","Kadim Gündoğan askerlerinin pek çok yadigârı tarihin tozlu sayfalarına karıştı. Ancak aynı durum bunların temsil ettiği her ilah savaşçı için geçerli değil.","Büyü",[],["Shurima"],"ENDER"],"09PZ044":["Mum Dileği","I-II: 1 kart Savurarak 1 kart çekersin.\nIII: 1 kart çekersin.","","Janna'ya adanan bu tapınakta pek az duvar vardır zira bu sayede tapınağın ilahının kudretiyle dolup taştığına inanılır. Öyle ki Zaun'un tamamını uğultulu fırtınalar kaplasa dahi tapınaktaki mumlar asla sönmez.","Yer",["HİKÂYE"],["Piltover ve Zaun"],"DESTANSI"],"09PZ045":["Uçan Kartograf","Oyna: 1 kart Savurarak Savrulan karttan daha yüksek veya düşük bedele sahip başka bir kart çekersin.","","''Göklerde süzülünce şu âlemde ne kadar küçük olduğumuzu anlayabiliyorum.''","Birim",[],["Piltover ve Zaun"],"ENDER"],"09PZ046":["Habis Mutasyon","Bir dost takipçi seçersin. 2 Aç Puhukedi çağırırsın, ardından dost birimlerini seçtiğin dost birimin birebir kopyalarına dönüştürürsün.","","''Bir kopya daha... Sonra kusursuz olacak!''\n- Kusurlu Kötü","Büyü",[],["Piltover ve Zaun"],"DESTANSI"],"09IO055":["Yaprak Perisi","Çağrıldığımda Yavru Peri kartını çağırırsın.","","''Lillia'mızın saçı karman çorman olmuş! Rica etsem, düzeltebilir misin? Unutma, bir tutam dilekler için, bir tutam düşler için ve bir tutam da göründüğü gibi olmayan\nher şey için.''\n- Peri Anne","Birim",[],["Ionia"],"ENDER"],"09IO056":["Peri Dansı","Bir dost birimi Geri Göndererek sahip olduğu tüm Cesaret yüklerini başka bir dost birime kazandırırsın.","","''Kalbinde saklı olan düşler bir şekerleme uzağında!''\n- Lillia","Büyü",[],["Ionia"],"ENDER"],"09IO048":["Peri Anne","Çağrıldığımda her yerdeki dost Yavru Peri ve Peri Anne kartlarına Cesaret kazandırırsın.","","Periler yaramaz, kıpır kıpır ve bazen de dikkatsiz olabiliyorlar. Bu yüzden Peri Anne onların doğru düş sahiplerine ulaşmaları için disiplini elden bırakmıyor ve yeri geldiğinde onları uyarmayı ihmal etmiyor.","Birim",[],["Ionia"],"DESTANSI"],"09IO049":["Çiy Tanesi Hasadı","I: Yavru Peri çağırırsın.\nII: Bir dost birimi uyutursun.","","Ağaç Ana'nın her çiy tanesi Runeterra'da bir yerlerde görülen düşleri gösterir ve her tanenin dikkatlice toplanması, özenle bakılması ve korunması gerekir.","Yer",["HİKÂYE"],["Ionia"],"YAYGIN"],"09IO052":["Lillia","Çağrıldığımda ya da Vuruş yaptığımda: Elinde bir Düş Dalı oluşur. Zaten varsa, bedeli 1 azalır.","15+ dost birim ya da Yer kartı çağırdığında.","Unutma Bahçesi'nin kalbinde çiy tanesi hasadı yaklaşıyor. Ancak Lillia ve bahçedeki diğer bakıcıların çiy taneleriyle sevgiyle ilgilenmesine rağmen tanelerde tuhaf bir yozlaşma görülebiliyor. Bu da yetmezmiş gibi tanelerdeki düşler ürkütücü ve karanlık bir hal alıyor...","Birim",[],["Ionia"],"Şampiyon"],"09IO046":["Ophelis Bakıcı","Oyna: Bir dost birimi tamamen iyileştirirsin, ardından uyutursun.","","Düşler Ağacı'nın ve bahçesinin bakıcısı olmak büyük bir onur olsa da bunun için ciddi bir fedakârlık gerekir. Hürmet ve şükran dolu bir törenle bahçenin bakıcısı tüm anılarından vazgeçer ve her gece geçmişinin bir kısmını kaybeder.","Birim",[],["Ionia"],"YAYGIN"],"09IO051":["Köklü Yollar","I-II: 1 kart çekersin.\nIII: Elindeki kartların bedeli bu tur 1 azalır.","","Unutma Bahçesi'nde ama büyük ama küçük her türlü yaratık yaşar ve bunların bazıları istemedikleri kadar bilince sahiptir.","Yer",["HİKÂYE"],["Ionia"],"ENDER"],"09IO053":["Kök Bey","Çağrıldığımda 1 kart çekersin.","","''Vay be, bir gün bu muhteşem varlık da tıpkı bizim gibi ölecek. Umarım ondan önce ben ölürüm. Hehe!''","Birim",[],["Ionia"],"YAYGIN"],"09IO045":["Çiçeklenen Tomurcuk","Bir birimi uyutursun.","","''Düşler mis gibi filizleniyor!''\n- Lillia","Büyü",[],["Ionia"],"ENDER"],"09IO058":["Ağacın Kalbi","I: Nexus'unu 3 iyileştirirsin ve Yavru Peri çağırırsın.\nII: Her yerdeki dost birimlere Cesaret kazandırırsın.\nIII: Bedeli 8 ya da daha fazla olan bir kart Cisimlendirirsin ve kartın bedeli yarıya iner. Sayı üste yuvarlanır.","","Düş perileri bahçenin en kalabalık sakinleridir. Farklı şekillere, boyutlara ve huylara sahip bu varlıkların pek çoğu çiy tanelerinden geçip düş sahiplerini en derin arzularına yönlendirir.","Yer",["HİKÂYE"],["Ionia"],"DESTANSI"],"09IO059":["Çelik Kasırga","Bir düşmanı Sersemletirsin. Onu bir sonraki Tur Başında yine Sersemletirsin.","","''Kılıç her şeyin üstünde.''\n- Rüzgâr Avcısı, Yone","Büyü",[],["Ionia"],"YAYGIN"],"09FR009":["Poro Geçidi","I-II: Oyundaki dost birimlerden farklı bir alt tipe sahip bir takipçi Cisimlendirirsin.\nIII: Bir alt tipe sahip her dost birim için bir dost birime bu tur +1|+1 verirsin.","","Ingvar, Poro Kralı'nın diyarına gittiği günden beri kralın tebaalarıyla çok sıkı bir dostluk kurmayı başardı. Belli ki diplomatik ilişkileri geliştirmenin en iyi yolu birlikte Freljord'un tundralarında macera peşinde koşturmaktan geçiyor.","Yer",["HİKÂYE"],["Freljord"],"DESTANSI"],"09FR014":["Brynhir Gökşarkısı","Oyna: Elindeki bir birimin Kökünü Kazıyarak Geri Sayım'ı en az 1 olmak üzere birimin bedeline denk olan ve bittiğinde birimin birebir kopyasını çağıran bir Fırtına Tepesi çağırırsın.","","''Beni ben yapan dağın ardı arkası kesilmeyen gök gürültüsü ve halkımın şarkısıdır!''","Birim",[],["Freljord"],"DESTANSI"],"09FR010":["Aşırı Yumuşak Poro","Oyna: Bir alt tipe sahip her dost birim için Nexus'unu 1 iyileştirirsin.","","''Hahaha, ne kadar da yumuşak!''\n- Poro Çobanı","Birim",["PORO"],["Freljord"],"YAYGIN"],"09FR012":["Buzul Kuvvet","Bir dost birime Güç değeri kadar Can ve Çetin Ceviz kazandırırsın. Ardından birimin Güç değeri 0 olur.","","Freljord'daki bazı ağaçlar yalnızca kışın dondurucu soğuğu karşısında devrilir.","Büyü",[],["Freljord"],"ENDER"],"09BC020":["Pis Bakış","Bir birime Kasvet kazandırıp 1 kart çekersin.","","''Tebrikler. Senden nefret ediyorum.''\n- Vex","Büyü",[],["Bandle Şehri","Gölge Adalar"],"YAYGIN"],"09BC012":["Aile Buluşması","I: Bir birime Kasvet kazandırırsın.\nII: Bir dost birime Ağır Darbe kazandırırsın.\nIII: 2 birimi Körüklersin.","","Onların yokluğu Vex'in yüreğini sızlatsa da en azından artık aile yemekleri tam istediği gibi sessiz geçiyor.","Yer",["HİKÂYE"],["Bandle Şehri"],"DESTANSI"],"09BC001":["Vex","Saldır: En Güçlü düşmana Kasvet kazandırırsın.","5+ defa Kasvet kazandırdığında.","''Of ya, aptal pembeli kız. Ona partilerden hele ki pastalı partilerden NEFRET ettiğimi defalarca söyledim. İğrenç. O gidince beni uyandırın.''","Birim",["YORDLE"],["Bandle Şehri","Gölge Adalar"],"Şampiyon"],"09BC002":["Milty Amca","Bir Hikâye tamamladığında bana 2 Cesaret kazandırırsın.","","Milty Amca kasvetli yeğeninden çok farklı biri olsa da onunla bağ kurabilmek için elinden geleni yapmaya hazır. Buna mum ışığı altında yeğeninin sevdiği ürkütücü hikâyeleri ona defalarca okumak da dahil...","Birim",["YORDLE"],["Bandle Şehri"],"ENDER"],"09BC013":["Kanat Festivali","I-II: Dost bir takipçi seçersin. Ardından onu bedeli kendisinden 1 fazla olan 3 takipçiden seçtiğin bir tanesine dönüştürürsün.\nIII: Dost bir takipçi seçersin. Ardından onu bedeli kendisinden 2 fazla olan 3 takipçiden seçtiğin bir tanesine dönüştürürsün.","","İhtiyar Trevor Horpiştoto kendini sürekli bir rüyadan başka rüyaya sürüklenirken buluyor. Neyse ki bu rüya epey huzurlu gibi... Ama nedendir bilinmez, bu âlemde karşılaştığı herkes Horpiştoto'nun kanatları gibi kanatlar istiyor...","Yer",["HİKÂYE"],["Bandle Şehri"],"ENDER"],"09BC004":["Allay","Oyna: Bana Cesaret kazandırırsın ya da Bir birime Kasvet kazandırırsın.","","''Veeeeex'ciiiiiim! Dur bi' yaaaa! Sana bir şey vereceğim! Öncelikle işte DOĞUM GÜNÜ PARTİNİN davetiyesi! Bir de henüz erken, biliyorum ama sana hediyeni şimdiden vermek istiyorum! Kusura bakma, BEKLEYEMEDİM! Sen de çok heyecanlı mısın? Ne giyeceğini kararlaştırmamız lazım, bir de PASTA var tabii... Vex'cim?''","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"09BC016":["Sürpriz Canavar","Bir dost birimin Güç ya da Can değerini bu tur 5'e çıkarırsın.","","''Hediyeler tarihinin en kötü hediyesi bu...''\n- Vex","Büyü",[],["Bandle Şehri"],"YAYGIN"],"09BC003":["Ürkütücü Hediye","Bir düşmanın çağrıldığı ilk seferde ona Kasvet kazandırırsın.","","''Hmm, o kadar da kötü bir hediye değilmiş.''\n- Vex","Birim",[],["Bandle Şehri"],"ENDER"],"09BC018":["Gölge","Çağrıldığımda Vex kartını çekersin.\nBu oyunda farklı anlarda kazandırdığın her Kasvet için +1|+0 alırım.","","''İşte böyle Gölge, göster onlara! Tek bir hediye, konfeti ve özellikle de parti şapkası görmek istemiyorum!''\n- Vex","Birim",[],["Bandle Şehri","Gölge Adalar"],"DESTANSI"],"09BC011":["Kasvet Perileri","Vuruş: Bana Ağır Darbe kazandırırsın.","","''Rüyalarda periler çok tuhaf şekillere bürünür. Bu rüyada belli ki... aa, pasta mı o?''\n- Lillia","Birim",[],["Bandle Şehri"],"YAYGIN"],"09BC006":["Kaslı Belediye Başkanı","Tur Başı: Beni Körüklersin.","","İnanılmaz derecede çok katlı pastanın içinden tuhaf ve kaslı belediye başkanı fırladığında zaman yavaşlamıştı. ''MUTLUUU YILLLAAAAR SANAAAAA,'' diyordu belediye başkanı ağzını yayarak, ''Bandle Şehri'nin seçilmiş en iyi ve kaslı memuru olarak doğum gününü kutlarım!''\n\nGördüğü rüyalar arasında Vex en çok bu rüyadan nefret etmişti. ","Birim",["YORDLE"],["Bandle Şehri"],"YAYGIN"],"09BW022":["Çukur Şampiyonu","I: Bir dost birim ve bir düşman birim birbirine vurur. Bu vuruşta iki birimin de Can değeri 1'in altına düşemez.\nII: Bir dost birimi tamamen iyileştirirsin.\nIII: Elinde 3 Sikke oluşur.","","Feneriye tüm dövüşleri bitirecek dövüşü kazanabilmek için yıllarını çalışmaya adadı. Zira her gece rüyasında kendini alın teriyle kazandığı ve Bilgewater Körfezi'ni dolduracak kadar büyük sikke yığınları arasında dolaşırken görürdü.","Yer",["HİKÂYE"],["Bilgewater"],"DESTANSI"],"09BW028":["İstekli Kalfa","Bu tur çektiğin her kart için +1|+0 alırım.","","''Ne demek daha çok çalışmam lazım? Zaten çok çalışıyorum, bak mesela şimdi ne yapacağım!''","Birim",[],["Bilgewater"],"ENDER"],"09BW027":["Paralı Asker Etiği","Rakibin Can değeri 3 ya da daha az olan bir takipçisini bu tur için çalarsın. (Zaten 6 dost birimin ya da Yer kartın varsa oynayamazsın.)","","''Güne bir kese altın için kan dökerek başlamak gibisi yok.''\n- Kiralık Katil","Büyü",[],["Bilgewater"],"YAYGIN"],"09MT002":["Duman Pullu Efendiler","I-II: Etkinleştirmek için 1 kart atarsın. Bedeli 7 ya da daha fazla olan bir Semavi karta Yakarırsın.\nIII: Elindeki rasgele bir kartın bedeli 5 azalır.","","Kendini ejderlere hizmet etmeye ve onları korumaya adayan kimsesiz Ottrani bu amacına o kadar bağlı ki artık bu haşmetli yaratıkları gündüzleri olduğu kadar gece düşlerinde de görüyor.","Yer",["HİKÂYE"],["Targon"],"DESTANSI"],"09MT004":["Peçeli Lütuflar","Bir dost birime 2 Cesaret kazandırırsın.","","''Onların sığınağı olacağım.''\n- Morgana","Büyü",[],["Targon"],"YAYGIN"],"09MT005":["Ejderşarkısı Düş Gezeni","Her tur ilk defa Yakardığında bir Ejder Yavrusu çağırırsın.","","''Ejderler yaklaşıyor. Hissedebiliyorum. Şu anda bile düşlerimde geziyorlar.''","Birim",[],["Targon"],"DESTANSI"],"09NX025":["Arena'nın Şampiyonu","I-II: Bir dost birime bu tur +2|+0 verirsin.\nIII: Bir düşmana bu tur Karşılayamaz verirsin.","","Bu arenada yetenekli olan herkes şöhrete ulaşabiliyor ki bu mekân popülerliğini sunduğu bu fırsata borçlu. Draven'ın bütün dövüşlerini asla kaçırmadan izlemiş bir taraftar, aynı imkânlar sunulursa kendisinin de zirveye yerleşebileceğine adı gibi emin.","Yer",["HİKÂYE"],["Noxus"],"DESTANSI"],"09NX032":["Yeti Terbiyecisi","Beni oynamak için 1 kart atarsın.\nÇağrıldığımda bir Hiddetli Yeti çağırırsın.","","Noxus ordusunun başarısı her koşula ayak uydurabilme becerilerinden geliyor. Zira Noxus askerleri tehlikeli ya da zorlayıcı koşullarda etraflarındaki canlılardan faydalanmaktan çekinmiyor.","Birim",[],["Noxus"],"ENDER"],"09NX033":["Marazlı Savaş Baltası","Tur Sonu: Taşıyıcım bu tur saldırmadıysa, ona Kasvet kazandırırsın.","","Korkaklığın bedeli büyüktür.","Ekipman",[],["Noxus"],"ENDER"]};
